window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["PSA"]={"book":"PSA","editions":{"fin-biblia1776":[[1,1,"Autuas on se, joka ei vaella jumalattomain neuvossa, eikä seiso syntisten tiellä, eikä istu kussa pilkkaajat istuvat;","Autuas on se, joka ei vaella jumalattomain neuvossa, eikä seiso syntisten tiellä, eikä istu kussa pilkkaajat istuvat;"],[1,2,"Vaan rakastaa Herran lakia, ja ajattelee hänen lakiansa päivät ja yöt.","Vaan rakastaa Herran lakia, ja ajattelee hänen lakiansa päivät ja yöt."],[1,3,"Hän on niinkuin istutettu puu vesiojain tykönä, joka hedelmänsä antaa ajallansa, ja hänen lehtensä ei varise, ja kaikki menestyy, mitä hän tekee.","Hän on niinkuin istutettu puu vesiojain tykönä, joka hedelmänsä antaa ajallansa, ja hänen lehtensä ei varise, ja kaikki menestyy, mitä hän tekee."],[1,4,"Mutta jumalattomat ei ole niin, vaan niinkuin akana, jonka tuuli hajoittelee.","Mutta jumalattomat ei ole niin, vaan niinkuin akana, jonka tuuli hajoittelee."],[1,5,"Sentähden ei jumalattomat kestä tuomiota, eikä syntiset vanhurskasten seuraa.","Sentähden ei jumalattomat kestä tuomiota, eikä syntiset vanhurskasten seuraa."],[1,6,"Sillä Herra tietää vanhurskasten tien; mutta jumalattomain tie hukkuu.","Sillä Herra tietää vanhurskasten tien; mutta jumalattomain tie hukkuu."],[2,1,"Miksi pakanat kiukuitsevat, ja kansat turhia ajattelevat?","Miksi pakanat kiukuitsevat, ja kansat turhia ajattelevat?"],[2,2,"Maan kuninkaat hankitsevat itseänsä, ja päämiehet keskenänsä neuvoa pitävät Herraa ja hänen voideltuansa vastaan.","Maan kuninkaat hankitsevat itseänsä, ja päämiehet keskenänsä neuvoa pitävät Herraa ja hänen voideltuansa vastaan."],[2,3,"Katkaiskaamme heidän siteensä, ja heittäkäämme meistä pois heidän köytensä.","Katkaiskaamme heidän siteensä, ja heittäkäämme meistä pois heidän köytensä."],[2,4,"Mutta joka taivaissa asuu, nauraa heitä: Herra pilkkaa heitä.","Mutta joka taivaissa asuu, nauraa heitä: Herra pilkkaa heitä."],[2,5,"Kerran hän puhuu heille vihoissansa, ja hirmuisuudessansa peljättää heitä.","Kerran hän puhuu heille vihoissansa, ja hirmuisuudessansa peljättää heitä."],[2,6,"Mutta minä asetin kuninkaani Zioniin, pyhälle vuorelleni.","Mutta minä asetin kuninkaani Zioniin, pyhälle vuorelleni."],[2,7,"Minä tahdon saarnata senkaltaisesta säädystä, josta Herra minulle sanoi: Sinä olet minun poikani, tänäpänä minä sinun synnytin.","Minä tahdon saarnata senkaltaisesta säädystä, josta Herra minulle sanoi: Sinä olet minun poikani, tänäpänä minä sinun synnytin."],[2,8,"Ano minulta, niin minä annan pakanat perinnökses ja maailman ääret omakses.","Ano minulta, niin minä annan pakanat perinnökses ja maailman ääret omakses."],[2,9,"Sinun pitää särkemän heitä rautaisella valtikalla, ja niinkuin savisen astian heitä murentaman.","Sinun pitää särkemän heitä rautaisella valtikalla, ja niinkuin savisen astian heitä murentaman."],[2,10,"Nyt te kuninkaat, siis ymmärtäkäät, ja te maan tuomarit, antakaat teitänne kurittaa.","Nyt te kuninkaat, siis ymmärtäkäät, ja te maan tuomarit, antakaat teitänne kurittaa."],[2,11,"Palvelkaat Herraa pelvossa, ja iloitkaat vavistuksessa.","Palvelkaat Herraa pelvossa, ja iloitkaat vavistuksessa."],[2,12,"Antakaat suuta pojalle, ettei hän vihastuisi, ja te hukkuisitte tiellä; sillä hänen vihansa syttyy pian. Mutta autuaat ovat kaikki ne, jotka häneen uskaltavat.","Antakaat suuta pojalle, ettei hän vihastuisi, ja te hukkuisitte tiellä; sillä hänen vihansa syttyy pian. Mutta autuaat ovat kaikki ne, jotka häneen uskaltavat."],[3,1,"Davidin Psalmi, kuin hän pakeni poikaansa Absalomia. (H 3:2) Voi Herra! kuinka monta on minulla vihollista, ja niin usiat karkaavat minua vastaan.","Davidin Psalmi, kuin hän pakeni poikaansa Absalomia. (H 3:2) Voi Herra! kuinka monta on minulla vihollista, ja niin usiat karkaavat minua vastaan."],[3,2,"(H 3:3) Moni puhuu minun sielustani: ei ole hänellä apua Jumalan tykönä, Sela!","(H 3:3) Moni puhuu minun sielustani: ei ole hänellä apua Jumalan tykönä, Sela!"],[3,3,"(H 3:4) Mutta sinä, Herra, olet minun kilpeni, joka minun kunniaan saatat, ja minun pääni kohennat.","(H 3:4) Mutta sinä, Herra, olet minun kilpeni, joka minun kunniaan saatat, ja minun pääni kohennat."],[3,4,"(H 3:5) Äänelläni minä huudan Herraa; ja hän kuulee minua pyhästä vuorestansa, Sela!","(H 3:5) Äänelläni minä huudan Herraa; ja hän kuulee minua pyhästä vuorestansa, Sela!"],[3,5,"(H 3:6) Minä makaan ja nukun: minä herään myös; sillä Herra tukee minua.","(H 3:6) Minä makaan ja nukun: minä herään myös; sillä Herra tukee minua."],[3,6,"(H 3:7) En minä pelkää kymmentätuhatta kansoista, jotka minua piirittävät.","(H 3:7) En minä pelkää kymmentätuhatta kansoista, jotka minua piirittävät."],[3,7,"(H 3:8) Nouse, Herra, ja auta minua, minun Jumalani! sillä sinä lyöt kaikkia minun vihollisiani poskelle: sinä murennat jumalattomain hampaat.","(H 3:8) Nouse, Herra, ja auta minua, minun Jumalani! sillä sinä lyöt kaikkia minun vihollisiani poskelle: sinä murennat jumalattomain hampaat."],[3,8,"(H 3:9) Herran tykönä apu löydetään: sinun kansas päällä on sinun siunaukses, Sela!","(H 3:9) Herran tykönä apu löydetään: sinun kansas päällä on sinun siunaukses, Sela!"],[4,1,"Davidin Psalmi, edelläveisaajalle, kanteleilla. (H 4:2) Rukoillessani kuule minua, vanhurskauteni Jumala, joka minua lohdutat ahdistuksessani: ole minulle armollinen, ja kuule rukoukseni.","Davidin Psalmi, edelläveisaajalle, kanteleilla. (H 4:2) Rukoillessani kuule minua, vanhurskauteni Jumala, joka minua lohdutat ahdistuksessani: ole minulle armollinen, ja kuule rukoukseni."],[4,2,"(H 4:3) Te uljaat miehet, kuinka kauvan pitää minun kunniani pilkattaman? miksi te rakastatte turhuutta ja kysytte valhetta? Sela!","(H 4:3) Te uljaat miehet, kuinka kauvan pitää minun kunniani pilkattaman? miksi te rakastatte turhuutta ja kysytte valhetta? Sela!"],[4,3,"(H 4:4) Niin tuntekaat, että Herra vie pyhänsä ihmeellisesti: Herra kuulee, kuin minä häntä rukoilen.","(H 4:4) Niin tuntekaat, että Herra vie pyhänsä ihmeellisesti: Herra kuulee, kuin minä häntä rukoilen."],[4,4,"(H 4:5) Jos te vihastutte, niin älkäät syntiä tehkö: puhukaat sydämissänne, teidän vuoteissanne, ja odottakaat, Sela!","(H 4:5) Jos te vihastutte, niin älkäät syntiä tehkö: puhukaat sydämissänne, teidän vuoteissanne, ja odottakaat, Sela!"],[4,5,"(H 4:6) Uhratkaat vanhurskauden uhria, ja toivokaat Herran päälle.","(H 4:6) Uhratkaat vanhurskauden uhria, ja toivokaat Herran päälle."],[4,6,"(H 4:7) Moni sanoo: kuka osoittais meille hyvää? Mutta nosta sinä Herra meidän päällemme sinun kasvois paiste.","(H 4:7) Moni sanoo: kuka osoittais meille hyvää? Mutta nosta sinä Herra meidän päällemme sinun kasvois paiste."],[4,7,"(H 4:8) Sinä ilahutat minun sydämeni; ehkä muilla on jyviä ja viinaa kyllä.","(H 4:8) Sinä ilahutat minun sydämeni; ehkä muilla on jyviä ja viinaa kyllä."],[4,8,"(H 4:9) Minä makaan ja lepään juuri rauhassa; sillä sinä Herra yksinäs autat minua turvassa asumaan.","(H 4:9) Minä makaan ja lepään juuri rauhassa; sillä sinä Herra yksinäs autat minua turvassa asumaan."],[5,1,"Davidin Psalmi, edelläveisaajalle, perimisestä. (H 5:2) Herra, ota minun sanani korviis, havaitse minun puheeni.","Davidin Psalmi, edelläveisaajalle, perimisestä. (H 5:2) Herra, ota minun sanani korviis, havaitse minun puheeni."],[5,2,"(H 5:3) Ota vaari minun huudostani, minun Kuninkaani ja minun Jumalani; sillä sinua minä rukoilen.","(H 5:3) Ota vaari minun huudostani, minun Kuninkaani ja minun Jumalani; sillä sinua minä rukoilen."],[5,3,"(H 5:4) Herra kuultele varhain minun ääntäni: varhain hankitsen minä itseni sinun tykös, ja siitä otan vaarin.","(H 5:4) Herra kuultele varhain minun ääntäni: varhain hankitsen minä itseni sinun tykös, ja siitä otan vaarin."],[5,4,"(H 5:5) Sillä et sinä ole se Jumala, jolle jumalatoin meno kelpaa: joka paha on, ei se pysy edessäs.","(H 5:5) Sillä et sinä ole se Jumala, jolle jumalatoin meno kelpaa: joka paha on, ei se pysy edessäs."],[5,5,"(H 5:6) Öykkärit ei pysy sinun silmäis edessä: kaikkia pahantekiöitä sinä vihaat.","(H 5:6) Öykkärit ei pysy sinun silmäis edessä: kaikkia pahantekiöitä sinä vihaat."],[5,6,"(H 5:7) Sinä kadotat valhetteliat: Herra kauhistuu murhaajia ja viekkaita.","(H 5:7) Sinä kadotat valhetteliat: Herra kauhistuu murhaajia ja viekkaita."],[5,7,"(H 5:8) Mutta minä menen sinun huoneeses sinun suuressa laupiudessas, ja kumarran sinun pyhään templiis päin sinun pelvossas.","(H 5:8) Mutta minä menen sinun huoneeses sinun suuressa laupiudessas, ja kumarran sinun pyhään templiis päin sinun pelvossas."],[5,8,"(H 5:9) Herra saata minua vanhurskaudessas, minun vihollisteni tähden: ojenna ties minun eteeni.","(H 5:9) Herra saata minua vanhurskaudessas, minun vihollisteni tähden: ojenna ties minun eteeni."],[5,9,"(H 5:10) Sillä heidän suussansa ei ole mitään totuutta, heidän sisällyksensä on sydämen kipu; heidän kitansa on avoin hauta, ja kielellänsä he liehakoitsevat.","(H 5:10) Sillä heidän suussansa ei ole mitään totuutta, heidän sisällyksensä on sydämen kipu; heidän kitansa on avoin hauta, ja kielellänsä he liehakoitsevat."],[5,10,"(H 5:11) Nuhtele heitä Jumala, että he lankeisivat ajatuksistansa: syökse heitä ulos heidän suurten ylitsekäymistensä tähden; sillä he ovat sinulle vastahakoiset.","(H 5:11) Nuhtele heitä Jumala, että he lankeisivat ajatuksistansa: syökse heitä ulos heidän suurten ylitsekäymistensä tähden; sillä he ovat sinulle vastahakoiset."],[5,11,"(H 5:12) Iloitkaan kaikki, jotka sinuun uskaltavat, anna heidän riemuita ijankaikkisesti; sillä sinä varjelet heitä: iloitkaan sinussa ne, jotka sinun nimeäs rakastavat.","(H 5:12) Iloitkaan kaikki, jotka sinuun uskaltavat, anna heidän riemuita ijankaikkisesti; sillä sinä varjelet heitä: iloitkaan sinussa ne, jotka sinun nimeäs rakastavat."],[5,12,"(H 5:13) Sillä sinä Herra siunaat vanhurskaita: sinä kaunistat heitä armollas niinkuin kilvellä.","(H 5:13) Sillä sinä Herra siunaat vanhurskaita: sinä kaunistat heitä armollas niinkuin kilvellä."],[6,1,"Davidin Psalmi, edelläveisaajalle, kahdeksalla kielellä. (H 6:2) Oi Herra, älä rankaise minua vihassas, ja älä minua julmuudessas kurita.","Davidin Psalmi, edelläveisaajalle, kahdeksalla kielellä. (H 6:2) Oi Herra, älä rankaise minua vihassas, ja älä minua julmuudessas kurita."],[6,2,"(H 6:3) Herra, ole minulle armollinen, sillä minä olen heikko: paranna Herra minua, sillä minun luuni ovat peljästyneet.","(H 6:3) Herra, ole minulle armollinen, sillä minä olen heikko: paranna Herra minua, sillä minun luuni ovat peljästyneet."],[6,3,"(H 6:4) Ja minun sieluni on sangen kovin hämmästynyt, voi Herra, kuinka kauvan!","(H 6:4) Ja minun sieluni on sangen kovin hämmästynyt, voi Herra, kuinka kauvan!"],[6,4,"(H 6:5) Käännä sinuas, Herra, ja pelasta sieluni; auta minua sinun hyvyytes tähden.","(H 6:5) Käännä sinuas, Herra, ja pelasta sieluni; auta minua sinun hyvyytes tähden."],[6,5,"(H 6:6) Sillä ei kuolemassa kenkään muista sinua, kuka kiittää sinua tuonelassa?","(H 6:6) Sillä ei kuolemassa kenkään muista sinua, kuka kiittää sinua tuonelassa?"],[6,6,"(H 6:7) Minä olen niin väsynyt huokauksista: minä uitan vuoteeni yli yötä, ja kastan leposiani kyynelilläni.","(H 6:7) Minä olen niin väsynyt huokauksista: minä uitan vuoteeni yli yötä, ja kastan leposiani kyynelilläni."],[6,7,"(H 6:8) Minun muotoni on muuttunut murheesta, ja on vanhentunut; sillä minä ahdistetaan kaikilta puolilta.","(H 6:8) Minun muotoni on muuttunut murheesta, ja on vanhentunut; sillä minä ahdistetaan kaikilta puolilta."],[6,8,"(H 6:9) Eritkäät minusta, kaikki pahointekiät; sillä Herra kuulee minun itkuni.","(H 6:9) Eritkäät minusta, kaikki pahointekiät; sillä Herra kuulee minun itkuni."],[6,9,"(H 6:10) Herra kuulee minun rukoukseni: anomiseni Herra ottaa vastaan.","(H 6:10) Herra kuulee minun rukoukseni: anomiseni Herra ottaa vastaan."],[6,10,"(H 6:11) Kaikki minun viholliseni saakoon häpiän, ja suuresti peljättäköön; kääntyköön takaperin, ja nopiasti häväistäköön.","(H 6:11) Kaikki minun viholliseni saakoon häpiän, ja suuresti peljättäköön; kääntyköön takaperin, ja nopiasti häväistäköön."],[7,1,"Davidin viattomuus, josta hän Herralle veisasi, Kuusin Jeminin pojan sanan tähden: (H 7:2) Sinuun, Herra minun Jumalani, minä uskallan: auta minua kaikista minun vainollisistani, ja pelasta minua;","Davidin viattomuus, josta hän Herralle veisasi, Kuusin Jeminin pojan sanan tähden: (H 7:2) Sinuun, Herra minun Jumalani, minä uskallan: auta minua kaikista minun vainollisistani, ja pelasta minua;"],[7,2,"(H 7:3) Ettei he repisi minun sieluani niinkuin jalopeura, ja sätkisi ilman holhojaa.","(H 7:3) Ettei he repisi minun sieluani niinkuin jalopeura, ja sätkisi ilman holhojaa."],[7,3,"(H 7:4) Herra minun Jumalani, jos minä sen tein ja jos vääryys on minun käsissäni;","(H 7:4) Herra minun Jumalani, jos minä sen tein ja jos vääryys on minun käsissäni;"],[7,4,"(H 7:5) Jos minä pahalla kostanut olen niille, jotka minun kanssani rauhassa elivät; vaan minä olen niitä pelastanut, jotka ilman syytä minua vihasivat;","(H 7:5) Jos minä pahalla kostanut olen niille, jotka minun kanssani rauhassa elivät; vaan minä olen niitä pelastanut, jotka ilman syytä minua vihasivat;"],[7,5,"(H 7:6) Niin vainotkaan viholliseni minun sieluani ja käsittäköön sen, ja poljeskelkaan maahan elämäni, ja painakaan kunniani tomuun, Sela!","(H 7:6) Niin vainotkaan viholliseni minun sieluani ja käsittäköön sen, ja poljeskelkaan maahan elämäni, ja painakaan kunniani tomuun, Sela!"],[7,6,"(H 7:7) Nouse Herra vihassas, korota sinuas ylitse vihollisteni hirmuisuuden, heräjä minun puoleeni; sillä sinä olet käskenyt oikeuden,","(H 7:7) Nouse Herra vihassas, korota sinuas ylitse vihollisteni hirmuisuuden, heräjä minun puoleeni; sillä sinä olet käskenyt oikeuden,"],[7,7,"(H 7:8) Että kansat kokoontuisivat jälleen sinun tykös; ja tule heidän tähtensä taas ylös,","(H 7:8) Että kansat kokoontuisivat jälleen sinun tykös; ja tule heidän tähtensä taas ylös,"],[7,8,"(H 7:9) Herra on kansain tuomari: tuomitse Herra minua vanhurskauteni ja vakuuteni jälkeen.","(H 7:9) Herra on kansain tuomari: tuomitse Herra minua vanhurskauteni ja vakuuteni jälkeen."],[7,9,"(H 7:10) Loppukoon jumalattomain pahuus, ja holho vanhurskaita; sillä sinä, vanhurskas Jumala, tutkit sydämet ja munaskuut.","(H 7:10) Loppukoon jumalattomain pahuus, ja holho vanhurskaita; sillä sinä, vanhurskas Jumala, tutkit sydämet ja munaskuut."],[7,10,"(H 7:11) Minun kilpeni on Jumalan tykönä, joka vaat sydämet auttaa.","(H 7:11) Minun kilpeni on Jumalan tykönä, joka vaat sydämet auttaa."],[7,11,"(H 7:12) Jumala on oikia tuomari; ja Jumala, joka joka päivä uhkaa.","(H 7:12) Jumala on oikia tuomari; ja Jumala, joka joka päivä uhkaa."],[7,12,"(H 7:13) Ellei he palaja, niin hän on miekkansa teroittanut, joutsensa jännittänyt, ja tarkoittaa,","(H 7:13) Ellei he palaja, niin hän on miekkansa teroittanut, joutsensa jännittänyt, ja tarkoittaa,"],[7,13,"(H 7:14) Ja on pannut sen päälle surmannuolet; hän on valmistanut vasamansa kadottamaan.","(H 7:14) Ja on pannut sen päälle surmannuolet; hän on valmistanut vasamansa kadottamaan."],[7,14,"(H 7:15) Katso, hänellä on pahaa mielessä: hän on onnettomuutta raskas, mutta hän synnyttää puuttumisen.","(H 7:15) Katso, hänellä on pahaa mielessä: hän on onnettomuutta raskas, mutta hän synnyttää puuttumisen."],[7,15,"(H 7:16) Hän kaivoi haudan ja valmisti, ja on kaatunut siihen kuoppaan, jonka hän oli tehnyt.","(H 7:16) Hän kaivoi haudan ja valmisti, ja on kaatunut siihen kuoppaan, jonka hän oli tehnyt."],[7,16,"(H 7:17) Hänen onnettomuutensa pitää hänen päänsä päälle tuleman, ja hänen vääryytensä pitää hänen päänsä laelle lankeeman.","(H 7:17) Hänen onnettomuutensa pitää hänen päänsä päälle tuleman, ja hänen vääryytensä pitää hänen päänsä laelle lankeeman."],[7,17,"(H 7:18) Minä kiitän Herraa hänen vanhurskautensa tähden, ja kunnioitan ylimmäisen Herran nimeä.","(H 7:18) Minä kiitän Herraa hänen vanhurskautensa tähden, ja kunnioitan ylimmäisen Herran nimeä."],[8,1,"Davidin Psalmi, edelläveisaajalle, Gittitin päällä. (H 8:2) Herra meidän Herramme! kuinka ihmeellinen on sinun nimes kaikessa maassa, joka panit kunnias taivasten ylitse.","Davidin Psalmi, edelläveisaajalle, Gittitin päällä. (H 8:2) Herra meidän Herramme! kuinka ihmeellinen on sinun nimes kaikessa maassa, joka panit kunnias taivasten ylitse."],[8,2,"Nuorten lasten ja imeväisten suusta perustit sinä voiman, vihollistes tähden, ettäs vihollisen ja kostajan murentaisit.","Nuorten lasten ja imeväisten suusta perustit sinä voiman, vihollistes tähden, ettäs vihollisen ja kostajan murentaisit."],[8,3,"Sillä minä näen taivaat, sinun sormeis teot, kuun ja tähdet, jotka valmistit.","Sillä minä näen taivaat, sinun sormeis teot, kuun ja tähdet, jotka valmistit."],[8,4,"Mikä on ihminen, ettäs häntä muistat? eli ihmisen poika, ettäs häntä etsiskelet?","Mikä on ihminen, ettäs häntä muistat? eli ihmisen poika, ettäs häntä etsiskelet?"],[8,5,"Sinä teit hänen vähää vähemmäksi enkeleitä; vaan sinä kaunistat hänen kunnialla ja kaunistuksella.","Sinä teit hänen vähää vähemmäksi enkeleitä; vaan sinä kaunistat hänen kunnialla ja kaunistuksella."],[8,6,"Sinä asetat hänen sinun käsitekois herraksi: kaikki olet sinä hänen jalkainsa alle heittänyt:","Sinä asetat hänen sinun käsitekois herraksi: kaikki olet sinä hänen jalkainsa alle heittänyt:"],[8,7,"Lampaat ja kaikki karjat, ja myös metsän eläimet,","Lampaat ja kaikki karjat, ja myös metsän eläimet,"],[8,8,"Linnut taivaan alla ja kalat meressä ja mitä meressä vaeltaa.","Linnut taivaan alla ja kalat meressä ja mitä meressä vaeltaa."],[8,9,"Herra meidän Herramme, kuinka ihmeellinen on sinun nimes kaikessa maassa!","Herra meidän Herramme, kuinka ihmeellinen on sinun nimes kaikessa maassa!"],[9,1,"Davidin Psalmi, kauniista nuoruudesta, edelläveisaajalle. (H 9:2) Minä kiitän Herraa kaikesta sydämestäni, ja luettelen kaikki sinun ihmees.","Davidin Psalmi, kauniista nuoruudesta, edelläveisaajalle. (H 9:2) Minä kiitän Herraa kaikesta sydämestäni, ja luettelen kaikki sinun ihmees."],[9,2,"Minä iloitsen ja riemuitsen sinussa, ja veisaan kiitosta sinun nimelles, sinä kaikkein ylimmäinen,","Minä iloitsen ja riemuitsen sinussa, ja veisaan kiitosta sinun nimelles, sinä kaikkein ylimmäinen,"],[9,3,"Ettäs minun viholliseni olet ajanut takaperin: he lankesivat ja hukkuivat sinun etees.","Ettäs minun viholliseni olet ajanut takaperin: he lankesivat ja hukkuivat sinun etees."],[9,4,"Sillä sinä saatat minun oikeuteni ja asiani toimeen: sinä istuit istuimelle, vanhurskauden tuomari.","Sillä sinä saatat minun oikeuteni ja asiani toimeen: sinä istuit istuimelle, vanhurskauden tuomari."],[9,5,"Sinä nuhtelet pakanoita, ja kadotat jumalattomat: sinä pyyhit heidän nimensä pois aina ja ijankaikkisesti.","Sinä nuhtelet pakanoita, ja kadotat jumalattomat: sinä pyyhit heidän nimensä pois aina ja ijankaikkisesti."],[9,6,"Vihollisten hävitykset ovat lopetetut ijäisesti, ja kaupungit sinä kukistit heidän muistonsa on heidän kanssansa kadonnut.","Vihollisten hävitykset ovat lopetetut ijäisesti, ja kaupungit sinä kukistit heidän muistonsa on heidän kanssansa kadonnut."],[9,7,"Mutta Herra pysyy ijankaikkisesti: hän on valmistanut istuimensa tuomioon.","Mutta Herra pysyy ijankaikkisesti: hän on valmistanut istuimensa tuomioon."],[9,8,"Ja hän tuomitsee maan piirin vanhurskaudessa, ja hallitsee kansat oikein.","Ja hän tuomitsee maan piirin vanhurskaudessa, ja hallitsee kansat oikein."],[9,9,"Ja Herra on köyhän turva: hän on turva hädän aikana.","Ja Herra on köyhän turva: hän on turva hädän aikana."],[9,10,"Sentähden he sinuun toivovat, jotka sinun nimes tuntevat; sillä et sinä niitä hylkää, jotka sinua, Herra, etsivät.","Sentähden he sinuun toivovat, jotka sinun nimes tuntevat; sillä et sinä niitä hylkää, jotka sinua, Herra, etsivät."],[9,11,"Veisatkaat Herralle, joka Zionissa asuu: julistakaat kansoissa hänen tekonsa.","Veisatkaat Herralle, joka Zionissa asuu: julistakaat kansoissa hänen tekonsa."],[9,12,"Sillä se joka kostaa verenvikoja, muistaa heitä, eikä unohda köyhäin parkumista.","Sillä se joka kostaa verenvikoja, muistaa heitä, eikä unohda köyhäin parkumista."],[9,13,"Herra ole minulle armollinen, katso minun ahdistustani niiltä, jotka minua vihaavat, sinä joka ylennät minun surman porteista;","Herra ole minulle armollinen, katso minun ahdistustani niiltä, jotka minua vihaavat, sinä joka ylennät minun surman porteista;"],[9,14,"Että minä luettelisin kaikki sinun kiitokses Zionin tytärten porteissa, ja iloitsisin sinun avustas.","Että minä luettelisin kaikki sinun kiitokses Zionin tytärten porteissa, ja iloitsisin sinun avustas."],[9,15,"Pakanat ovat vajonneet siihen hautaan, jonka he valmistivat: heidän jalkansa on käsitetty siinä verkossa, jonka he virittivät.","Pakanat ovat vajonneet siihen hautaan, jonka he valmistivat: heidän jalkansa on käsitetty siinä verkossa, jonka he virittivät."],[9,16,"Niin ymmärretään Herran tekevän oikeuden, koska jumalatoin juuri omissa kättensä töissä käsitetään; se on tutkisteltava asia, Sela!","Niin ymmärretään Herran tekevän oikeuden, koska jumalatoin juuri omissa kättensä töissä käsitetään; se on tutkisteltava asia, Sela!"],[9,17,"Jospa jumalattomat palajaisivat helvettiin, ja kaikki pakanat, jotka Jumalan unohtavat.","Jospa jumalattomat palajaisivat helvettiin, ja kaikki pakanat, jotka Jumalan unohtavat."],[9,18,"Sillä ei hän köyhää peräti unohda, ja raadollisten toivo ei huku ijankaikkisesti.","Sillä ei hän köyhää peräti unohda, ja raadollisten toivo ei huku ijankaikkisesti."],[9,19,"Nouse, Herra, ettei ihminen saisi valtaa: anna kaikki pakanat edessäs tuomittaa.","Nouse, Herra, ettei ihminen saisi valtaa: anna kaikki pakanat edessäs tuomittaa."],[9,20,"Herra, anna heille opettaja, että pakanat tuntisivat itsensä ihmisiksi, Sela!","Herra, anna heille opettaja, että pakanat tuntisivat itsensä ihmisiksi, Sela!"],[10,1,"Miksis Herra niin kaukana seisot, ja tuskan ajalla sinus peität?","Miksis Herra niin kaukana seisot, ja tuskan ajalla sinus peität?"],[10,2,"Ylpeydessänsä jumalatoin vainoo köyhää: käsitettäköön he heidän juonissansa, joita he ajattelevat.","Ylpeydessänsä jumalatoin vainoo köyhää: käsitettäköön he heidän juonissansa, joita he ajattelevat."],[10,3,"Sillä jumalatoin itse kerskaa omaa mielivaltaansa: ahne siunailee itsiänsä, ja vihoittaa Herran.","Sillä jumalatoin itse kerskaa omaa mielivaltaansa: ahne siunailee itsiänsä, ja vihoittaa Herran."],[10,4,"Jumalatoin on koria ja vihainen, ettei hän ketään tottele: ei hän Jumalaa olevankaan luule.","Jumalatoin on koria ja vihainen, ettei hän ketään tottele: ei hän Jumalaa olevankaan luule."],[10,5,"Hänen tiensä menestyvät joka aika, sinun tuomios on kaukana hänestä: hän ylpeilee kaikkein vihollistensa edessä.","Hänen tiensä menestyvät joka aika, sinun tuomios on kaukana hänestä: hän ylpeilee kaikkein vihollistensa edessä."],[10,6,"Sillä hän puhuu sydämessänsä: en minä ikänä kukisteta, ei sukukunnasta sukukuntaan hätää ole.","Sillä hän puhuu sydämessänsä: en minä ikänä kukisteta, ei sukukunnasta sukukuntaan hätää ole."],[10,7,"Jonka suu on täynnä kirouksia, kavaluutta ja viettelystä, hänen kielensä saattaa vaivan ja työn.","Jonka suu on täynnä kirouksia, kavaluutta ja viettelystä, hänen kielensä saattaa vaivan ja työn."],[10,8,"Hän istuu ja väijyy kartanoissa, murhataksensa salaa viatointa; hänen silmänsä palaa köyhän puoleen.","Hän istuu ja väijyy kartanoissa, murhataksensa salaa viatointa; hänen silmänsä palaa köyhän puoleen."],[10,9,"Hän väijyy salaa niinkuin jalopeura luolassansa, hän väijyy raadollista käsittääksensä, ja hän käsittää hänen, kuin hän tempaa sen verkkoihinsa.","Hän väijyy salaa niinkuin jalopeura luolassansa, hän väijyy raadollista käsittääksensä, ja hän käsittää hänen, kuin hän tempaa sen verkkoihinsa."],[10,10,"Hän paiskaa ja polkee alas, ja sysää köyhän väkivallalla maahan.","Hän paiskaa ja polkee alas, ja sysää köyhän väkivallalla maahan."],[10,11,"Hän sanoo sydämessänsä: Jumala on hänen unhottanut, ja verhonnut kasvonsa, ei hän ikänä näe.","Hän sanoo sydämessänsä: Jumala on hänen unhottanut, ja verhonnut kasvonsa, ei hän ikänä näe."],[10,12,"Nouse, Herra! Jumala, ylennä kätes ja älä köyhää unohda.","Nouse, Herra! Jumala, ylennä kätes ja älä köyhää unohda."],[10,13,"Miksi jumalatoin pilkkaa Jumalaa ja sanoo sydämessänsä: et sinä sitä tottele?","Miksi jumalatoin pilkkaa Jumalaa ja sanoo sydämessänsä: et sinä sitä tottele?"],[10,14,"Katso siis; sillä sinä näet tuskat ja surut, se on sinun käsissäs: sinuun köyhä itsensä luottaa, ja sinä olet orpolasten holhoja.","Katso siis; sillä sinä näet tuskat ja surut, se on sinun käsissäs: sinuun köyhä itsensä luottaa, ja sinä olet orpolasten holhoja."],[10,15,"Särje jumalattoman käsivarsi, ja etsi pahan jumalattomuutta, niin ettei sitä enää löydettäisi.","Särje jumalattoman käsivarsi, ja etsi pahan jumalattomuutta, niin ettei sitä enää löydettäisi."],[10,16,"Herra on kuningas aina ja ijankaikkisesti: pakanain pitää häviämän hänen maastansa.","Herra on kuningas aina ja ijankaikkisesti: pakanain pitää häviämän hänen maastansa."],[10,17,"Köyhäin halauksen sinä, Herra, kuulet: heidän sydämensä sinä vahvistat, että sinun korvas siitä ottaa vaarin;","Köyhäin halauksen sinä, Herra, kuulet: heidän sydämensä sinä vahvistat, että sinun korvas siitä ottaa vaarin;"],[10,18,"Ettäs oikeuden saatat orvoille ja köyhille, ettei ihminen enää ylpeile heitä vastaan maan päällä.","Ettäs oikeuden saatat orvoille ja köyhille, ettei ihminen enää ylpeile heitä vastaan maan päällä."],[11,1,"Davidin Psalmi, edelläveisaajalle. Herraan minä uskallan: kuinka te sanotte sielulleni, että hän lentäis niinkuin lintu teidän vuoreltanne?","Davidin Psalmi, edelläveisaajalle. Herraan minä uskallan: kuinka te sanotte sielulleni, että hän lentäis niinkuin lintu teidän vuoreltanne?"],[11,2,"Sillä katsos, jumalattomat jännittävät joutsen ja panevat nuolensa jänteelle, salaisesti ampuaksensa hurskaita.","Sillä katsos, jumalattomat jännittävät joutsen ja panevat nuolensa jänteelle, salaisesti ampuaksensa hurskaita."],[11,3,"Sillä he rikkoivat perustuksen: mitä vanhurskas taitaa toimittaa?","Sillä he rikkoivat perustuksen: mitä vanhurskas taitaa toimittaa?"],[11,4,"Herra on pyhässä templissänsä, Herran istuin on taivaissa; hänen silmänsä ottavat vaarin, ja hänen silmänsä laudat koettelevat ihmisten lapsia.","Herra on pyhässä templissänsä, Herran istuin on taivaissa; hänen silmänsä ottavat vaarin, ja hänen silmänsä laudat koettelevat ihmisten lapsia."],[11,5,"Herra koettelee vanhurskasta; hänen sielunsa vihaa jumalatointa, ja jotka vääryyttä rakastavat.","Herra koettelee vanhurskasta; hänen sielunsa vihaa jumalatointa, ja jotka vääryyttä rakastavat."],[11,6,"Hän antaa sataa jumalattomain päälle pitkäisen leimauksia, tulta ja tulikiveä, ja antaa heille tuulispäät palkaksi.","Hän antaa sataa jumalattomain päälle pitkäisen leimauksia, tulta ja tulikiveä, ja antaa heille tuulispäät palkaksi."],[11,7,"Sillä Herra on vanhurskas ja rakastaa vanhurskautta, että hänen kasvonsa katsovat oikeutta.","Sillä Herra on vanhurskas ja rakastaa vanhurskautta, että hänen kasvonsa katsovat oikeutta."],[12,1,"Davidin Psalmi, edelläveisaajalle, kahdeksalla kielellä. (H 12:2) Auta, Herra; sillä pyhät ovat vähentyneet, ja uskolliset ovat harvat ihmisten lasten seassa.","Davidin Psalmi, edelläveisaajalle, kahdeksalla kielellä. (H 12:2) Auta, Herra; sillä pyhät ovat vähentyneet, ja uskolliset ovat harvat ihmisten lasten seassa."],[12,2,"Jokainen puhuu lähimmäisensä kanssa valhetta: he liehakoitsevat ja opettavat eripuraisuutta sydämistä.","Jokainen puhuu lähimmäisensä kanssa valhetta: he liehakoitsevat ja opettavat eripuraisuutta sydämistä."],[12,3,"Katkokoon Herra kaikki ulkokullaiset huulet ja ylpiästi puhuvaiset kielet,","Katkokoon Herra kaikki ulkokullaiset huulet ja ylpiästi puhuvaiset kielet,"],[12,4,"Jotka sanovat: meidän kielemme pitää voittaman, meidän tulee puhua: kuka meidän herramme on?","Jotka sanovat: meidän kielemme pitää voittaman, meidän tulee puhua: kuka meidän herramme on?"],[12,5,"Että köyhät hävitetään ja vaivaiset huokaavat, niin minä nyt nousen, sanoo Herra: minä saatan avun, että rohkiasti pitää opetettaman.","Että köyhät hävitetään ja vaivaiset huokaavat, niin minä nyt nousen, sanoo Herra: minä saatan avun, että rohkiasti pitää opetettaman."],[12,6,"Herran puheet ovat kirkkaat, niinkuin selitetty hopia saviastioissa, seitsemän kertaa koeteltu.","Herran puheet ovat kirkkaat, niinkuin selitetty hopia saviastioissa, seitsemän kertaa koeteltu."],[12,7,"Sinä Herra, kätke ne, ja varjele meitä tästä suvusta ijankaikkisesti.","Sinä Herra, kätke ne, ja varjele meitä tästä suvusta ijankaikkisesti."],[12,8,"Sillä joka paikka on jumalattomia täynnä, koska huonot ihmisten lasten seassa korotetaan.","Sillä joka paikka on jumalattomia täynnä, koska huonot ihmisten lasten seassa korotetaan."],[13,1,"Davidin Psalmi, edelläveisaajalle.","Davidin Psalmi, edelläveisaajalle."],[13,2,"Kuinka kauvan sinä Herra peräti tahdot minua unhottaa? kuinka kauvan sinä peität kasvos minusta?","Kuinka kauvan sinä Herra peräti tahdot minua unhottaa? kuinka kauvan sinä peität kasvos minusta?"],[13,3,"Kuinka kauvan minä neuvoa pidän sielussani? ja ahdistetaan sydämessäni joka päivä? kuinka kauvan minun viholliseni yltyy minua vastaan?","Kuinka kauvan minä neuvoa pidän sielussani? ja ahdistetaan sydämessäni joka päivä? kuinka kauvan minun viholliseni yltyy minua vastaan?"],[13,4,"Katso siis ja kuule minua, Herra minun Jumalani: valista silmäni etten minä koskaan kuolemaan nukkuisi;","Katso siis ja kuule minua, Herra minun Jumalani: valista silmäni etten minä koskaan kuolemaan nukkuisi;"],[13,5,"Ettei viholliseni sanoisi: minä voitin hänen, ja minun sortajani iloitsisi, koska minä kompastun.","Ettei viholliseni sanoisi: minä voitin hänen, ja minun sortajani iloitsisi, koska minä kompastun."],[13,6,"Mutta minä turvaan sinun armoos: minun sydämeni riemuitsee, ettäs niin mielelläs autat: minä veisaan Herralle, että hän minulle niin hyvästi tekee.","Mutta minä turvaan sinun armoos: minun sydämeni riemuitsee, ettäs niin mielelläs autat: minä veisaan Herralle, että hän minulle niin hyvästi tekee."],[14,1,"Davidin Psalmi, edelläveisaajalle. Tyhmät sanovat sydämessänsä: ei Jumalaa olekaan; ei he mitään kelpaa, ja ovat ilkiät menoissansa; ei ole joka hyvää tekee.","Davidin Psalmi, edelläveisaajalle. Tyhmät sanovat sydämessänsä: ei Jumalaa olekaan; ei he mitään kelpaa, ja ovat ilkiät menoissansa; ei ole joka hyvää tekee."],[14,2,"Herra katsoi taivaasta ihmisten lapsia, nähdäksensä, jos joku ymmärtäis eli etsis Jumalaa.","Herra katsoi taivaasta ihmisten lapsia, nähdäksensä, jos joku ymmärtäis eli etsis Jumalaa."],[14,3,"Mutta he ovat kaikki poikenneet pois, ja kaikki ovat kelvottomat: ei ole yksikään, joka hyvää tekee, ei ainoakaan.","Mutta he ovat kaikki poikenneet pois, ja kaikki ovat kelvottomat: ei ole yksikään, joka hyvää tekee, ei ainoakaan."],[14,4,"Eikö siis kenkään pahointekiöistä sitä havaitse? jotka minun kansaani syövät niinkuin he söisivät leipää; vaan ei he rukoile Herraa.","Eikö siis kenkään pahointekiöistä sitä havaitse? jotka minun kansaani syövät niinkuin he söisivät leipää; vaan ei he rukoile Herraa."],[14,5,"Siellä he kovin pelkäsivät; sillä Jumala on läsnä vanhurskasten sukua.","Siellä he kovin pelkäsivät; sillä Jumala on läsnä vanhurskasten sukua."],[14,6,"Te häpäisette köyhän neuvon; mutta Jumala on hänen turvansa.","Te häpäisette köyhän neuvon; mutta Jumala on hänen turvansa."],[14,7,"Oi jos apu tulis Israelille Zionista! sillä koska Herra päästää vangitun kansansa, niin Jakob iloitsee ja Israel riemuitsee.","Oi jos apu tulis Israelille Zionista! sillä koska Herra päästää vangitun kansansa, niin Jakob iloitsee ja Israel riemuitsee."],[15,1,"Davidin Psalmi. Herra, kuka asuu sinun majassas? eli kuka on pysyväinen sinun pyhällä vuorellas?","Davidin Psalmi. Herra, kuka asuu sinun majassas? eli kuka on pysyväinen sinun pyhällä vuorellas?"],[15,2,"Joka vaeltaa ja tekee oikeuden, ja puhuu totuuden sydämestänsä;","Joka vaeltaa ja tekee oikeuden, ja puhuu totuuden sydämestänsä;"],[15,3,"Joka ei kielellänsä panettele, eikä lähimmäisellensä mitään pahaa tee, ja ei häpäise lähimmäistänsä;","Joka ei kielellänsä panettele, eikä lähimmäisellensä mitään pahaa tee, ja ei häpäise lähimmäistänsä;"],[15,4,"Joka jumalattomat katsoo ylön, vaan kunnioittaa Jumalaa pelkääväisiä; joka lähimmäisellensä vannoo ja pitää.","Joka jumalattomat katsoo ylön, vaan kunnioittaa Jumalaa pelkääväisiä; joka lähimmäisellensä vannoo ja pitää."],[15,5,"Joka ei anna rahaansa korolle, eikä ota lahjoja viatointa vastaan. Joka näin tekee, ei hän horjahda ijankaikkisesti.","Joka ei anna rahaansa korolle, eikä ota lahjoja viatointa vastaan. Joka näin tekee, ei hän horjahda ijankaikkisesti."],[16,1,"Davidin kultainen kappale. Kätke minua Jumala; sillä minä uskallan sinuun.","Davidin kultainen kappale. Kätke minua Jumala; sillä minä uskallan sinuun."],[16,2,"Sinä olet Herralle sanonut: sinä olet minun Herrani: minun hyvätyöni ei ole sinun tähtes,","Sinä olet Herralle sanonut: sinä olet minun Herrani: minun hyvätyöni ei ole sinun tähtes,"],[16,3,"Vaan pyhäin tähden, jotka maan päällä ovat, ja kunniallisten tähden, joissa kaikki minun mielisuosioni on.","Vaan pyhäin tähden, jotka maan päällä ovat, ja kunniallisten tähden, joissa kaikki minun mielisuosioni on."],[16,4,"Mutta jotka toisen jälkeen rientävät, niillä pitää suuri sydämen kipu oleman: en minä uhraa heidän juomauhriansa verestä, enkä mainitse heidän nimiänsä suussani.","Mutta jotka toisen jälkeen rientävät, niillä pitää suuri sydämen kipu oleman: en minä uhraa heidän juomauhriansa verestä, enkä mainitse heidän nimiänsä suussani."],[16,5,"Mutta Herra on minun tavarani ja osani: sinä tähteelle panet minun perimiseni.","Mutta Herra on minun tavarani ja osani: sinä tähteelle panet minun perimiseni."],[16,6,"Arpa lankesi minulle kauniimmissa: minä olen jalon perimisen saanut.","Arpa lankesi minulle kauniimmissa: minä olen jalon perimisen saanut."],[16,7,"Minä kiitän Herraa, joka minua on neuvonut: niin myös minun munaskuuni ovat yöllä kurittaneet.","Minä kiitän Herraa, joka minua on neuvonut: niin myös minun munaskuuni ovat yöllä kurittaneet."],[16,8,"Minä pidän aina Herran kasvoini edessä, sillä hän on minun oikialla puolellani, sentähden en minä horju.","Minä pidän aina Herran kasvoini edessä, sillä hän on minun oikialla puolellani, sentähden en minä horju."],[16,9,"Sentähden minun sydämeni reimuitsee ja minun kunniani on iloinen, ja minun lihani lepää toivossa.","Sentähden minun sydämeni reimuitsee ja minun kunniani on iloinen, ja minun lihani lepää toivossa."],[16,10,"Sillä et sinä hyljää sieluani helvetissä, etkä salli sinun pyhäs näkevän turmelusta.","Sillä et sinä hyljää sieluani helvetissä, etkä salli sinun pyhäs näkevän turmelusta."],[16,11,"Sinä osoitat minulle elämän tien, sinun kasvois edessä on täydellinen ilo, ja riemullinen meno oikialla kädelläs ijankaikkisesti.","Sinä osoitat minulle elämän tien, sinun kasvois edessä on täydellinen ilo, ja riemullinen meno oikialla kädelläs ijankaikkisesti."],[17,1,"Davidin rukous. Kuule, Herra, oikeutta, havaitse minun huutoni, ota vaari minun rukouksestani, joka ei viekkaasta suusta lähde.","Davidin rukous. Kuule, Herra, oikeutta, havaitse minun huutoni, ota vaari minun rukouksestani, joka ei viekkaasta suusta lähde."],[17,2,"Puhu sinä minun asiassani, ja sinun silmäs katsokaan oikeutta.","Puhu sinä minun asiassani, ja sinun silmäs katsokaan oikeutta."],[17,3,"Sinä koettelet minun sydämeni, ja etsiskelet sitä yöllä, ja tutkit minua, ja et mitään löydä; minä olen aikonut, ettei minun suuni missäkään riko.","Sinä koettelet minun sydämeni, ja etsiskelet sitä yöllä, ja tutkit minua, ja et mitään löydä; minä olen aikonut, ettei minun suuni missäkään riko."],[17,4,"Minä varjelen minuni sinun huultes sanoissa, ihmisten töistä, murhaajan tiellä.","Minä varjelen minuni sinun huultes sanoissa, ihmisten töistä, murhaajan tiellä."],[17,5,"Hallitse minun käyntöni poluillas, ettei minun askeleeni liukahtaisi.","Hallitse minun käyntöni poluillas, ettei minun askeleeni liukahtaisi."],[17,6,"Minä huudan sinua, ettäs, Jumala, minua kuulisit: kallista korvas minun puoleeni, kuule minun puheeni.","Minä huudan sinua, ettäs, Jumala, minua kuulisit: kallista korvas minun puoleeni, kuule minun puheeni."],[17,7,"Osoita ihmeellinen hyvyytes, sinä niiden vapahtaja, jotka sinuun uskaltavat, niitä vastaan, jotka sinun oikiaa kättäs vastaan ovat.","Osoita ihmeellinen hyvyytes, sinä niiden vapahtaja, jotka sinuun uskaltavat, niitä vastaan, jotka sinun oikiaa kättäs vastaan ovat."],[17,8,"Varjele minua niinkuin silmäterää: suojele minua siipeis varjon alla.","Varjele minua niinkuin silmäterää: suojele minua siipeis varjon alla."],[17,9,"Jumalattomista, jotka minua hävittävät, vihollisistani, jotka minun sieluuni piirittävät.","Jumalattomista, jotka minua hävittävät, vihollisistani, jotka minun sieluuni piirittävät."],[17,10,"Heidän lihavansa yhtä pitävät: he puhuvat suullansa ylpiästi.","Heidän lihavansa yhtä pitävät: he puhuvat suullansa ylpiästi."],[17,11,"Kuhunka me menemme, niin he meitä piirittävät: siihen he silmänsä tarkoittavat meitä kukistaaksensa maahan,","Kuhunka me menemme, niin he meitä piirittävät: siihen he silmänsä tarkoittavat meitä kukistaaksensa maahan,"],[17,12,"Niinkuin jalopeura saalista himoitsee, niinkuin nuori jalopeura, joka luolasta väijyy.","Niinkuin jalopeura saalista himoitsee, niinkuin nuori jalopeura, joka luolasta väijyy."],[17,13,"Nouse, Herra, ennätä hänen kasvonsa, ja polje häntä; vapahda minun sieluni miekallas jumalattomista,","Nouse, Herra, ennätä hänen kasvonsa, ja polje häntä; vapahda minun sieluni miekallas jumalattomista,"],[17,14,"Sinun kädelläs ihmisistä, Herra, tämän maailman ihmisistä, joiden osa on tässä elämässä, ja joiden vatsan sinä täytät tavarallas: heidän lapsensa ravitaan, ja he jättävät tähteensä lapsukaisillensa.","Sinun kädelläs ihmisistä, Herra, tämän maailman ihmisistä, joiden osa on tässä elämässä, ja joiden vatsan sinä täytät tavarallas: heidän lapsensa ravitaan, ja he jättävät tähteensä lapsukaisillensa."],[17,15,"Mutta minä saan nähdä sinun kasvos vanhurskaudessa: minä ravitaan herättyäni sinun kuvas jälkeen.","Mutta minä saan nähdä sinun kasvos vanhurskaudessa: minä ravitaan herättyäni sinun kuvas jälkeen."],[18,1,"Edelläveisaajalle, Davidin Herran palvelian Psalmi, joka Herralle nämät veisun sanat puhui sinä päivänä, jona Herra hänen vapahti kaikkein vihollistensa käsistä ja Saulin käsistä. (H18:2) Ja hän sanoi: minä rakastan sydämestäni sinua, Herra, minun voimani.","Edelläveisaajalle, Davidin Herran palvelian Psalmi, joka Herralle nämät veisun sanat puhui sinä päivänä, jona Herra hänen vapahti kaikkein vihollistensa käsistä ja Saulin käsistä. (H18:2) Ja hän sanoi: minä rakastan sydämestäni sinua, Herra, minun voimani."],[18,2,"Herra, minun kallioni, minun linnani ja minun vapahtajani; minun Jumalani on minun vahani, johon minä turvaan: minun kilpeni, ja minun autuuteni sarvi, ja minun varjelukseni.","Herra, minun kallioni, minun linnani ja minun vapahtajani; minun Jumalani on minun vahani, johon minä turvaan: minun kilpeni, ja minun autuuteni sarvi, ja minun varjelukseni."],[18,3,"Minä kiitän ja avukseni huudan Herraa, niin minä vapahdetaan vihollisistani.","Minä kiitän ja avukseni huudan Herraa, niin minä vapahdetaan vihollisistani."],[18,4,"Sillä kuoleman siteet olivat käärineet minun ympäri, ja Belialin ojat peljättivät minun.","Sillä kuoleman siteet olivat käärineet minun ympäri, ja Belialin ojat peljättivät minun."],[18,5,"Helvetin siteet kietoivat minun: kuoleman paulat ennättivät minun.","Helvetin siteet kietoivat minun: kuoleman paulat ennättivät minun."],[18,6,"Ahdistuksessani minä avukseni huudan Herraa, ja minun Jumalani tykö minä huudan: niin hän kuulee ääneni templistänsä, ja minun huutoni hänen edessänsä tulee hänen korviinsa.","Ahdistuksessani minä avukseni huudan Herraa, ja minun Jumalani tykö minä huudan: niin hän kuulee ääneni templistänsä, ja minun huutoni hänen edessänsä tulee hänen korviinsa."],[18,7,"Maa liikkui ja vapisi, ja vuorten perustukset liikkuivat: he värisivät, koska hän vihastui.","Maa liikkui ja vapisi, ja vuorten perustukset liikkuivat: he värisivät, koska hän vihastui."],[18,8,"Savu suitsi hänen sieraimistansa ja kuluttava tuli hänen suustansa, niin että hiilet siitä syttyivät.","Savu suitsi hänen sieraimistansa ja kuluttava tuli hänen suustansa, niin että hiilet siitä syttyivät."],[18,9,"Hän notkisti taivaat ja astui alas, ja synkiä pimeys oli hänen jalkainsa alla.","Hän notkisti taivaat ja astui alas, ja synkiä pimeys oli hänen jalkainsa alla."],[18,10,"Hän astui Kerubimin päälle ja lensi, ja hän lensi tuulen sulkain päällä.","Hän astui Kerubimin päälle ja lensi, ja hän lensi tuulen sulkain päällä."],[18,11,"Hän pani pimeyden majansa ympärille, ja mustat paksut pilvet, jossa hän lymyssä oli.","Hän pani pimeyden majansa ympärille, ja mustat paksut pilvet, jossa hän lymyssä oli."],[18,12,"Kirkkaudesta hänen edessänsä hajosivat pilvet rakeilla ja leimauksilla.","Kirkkaudesta hänen edessänsä hajosivat pilvet rakeilla ja leimauksilla."],[18,13,"Ja Herra jylisti taivaissa, Ylimmäinen antoi pauhinansa, rakeilla ja leimauksilla.","Ja Herra jylisti taivaissa, Ylimmäinen antoi pauhinansa, rakeilla ja leimauksilla."],[18,14,"Hän ampui nuolensa ja hajoitti heitä: hän iski kovat leimaukset, ja peljätti heitä,","Hän ampui nuolensa ja hajoitti heitä: hän iski kovat leimaukset, ja peljätti heitä,"],[18,15,"Ja niin ilmestyivät vetten kuljut, ja maan perustukset ilmaantuivat, Herra, sinun kovasta nuhtelemisestas ja sinun sieraimies hengen puhalluksesta.","Ja niin ilmestyivät vetten kuljut, ja maan perustukset ilmaantuivat, Herra, sinun kovasta nuhtelemisestas ja sinun sieraimies hengen puhalluksesta."],[18,16,"Hän lähetti korkeudesta ja otti minun, ja veti minun ulos suurista vesistä.","Hän lähetti korkeudesta ja otti minun, ja veti minun ulos suurista vesistä."],[18,17,"Hän vapahti minun voimallisista vihollisistani, jotka minua väkevämmät olivat.","Hän vapahti minun voimallisista vihollisistani, jotka minua väkevämmät olivat."],[18,18,"Ne ennättivät minun tuskapäivänäni; mutta Herra tuli minun turvakseni.","Ne ennättivät minun tuskapäivänäni; mutta Herra tuli minun turvakseni."],[18,19,"Ja hän vei minun lakialle: hän tempasi minun ulos; sillä hän mielistyi minuun.","Ja hän vei minun lakialle: hän tempasi minun ulos; sillä hän mielistyi minuun."],[18,20,"Herra maksoi minulle minun vanhurskauteni jälkeen: hän antoi minulle kätteni puhtauden jälkeen.","Herra maksoi minulle minun vanhurskauteni jälkeen: hän antoi minulle kätteni puhtauden jälkeen."],[18,21,"Sillä minä pidän Herran tiet, ja en ole Jumalaani vastaan.","Sillä minä pidän Herran tiet, ja en ole Jumalaani vastaan."],[18,22,"Sillä kaikki hänen oikeutensa ovat silmäini edessä, ja hänen käskyjänsä en minä tyköäni hylkää.","Sillä kaikki hänen oikeutensa ovat silmäini edessä, ja hänen käskyjänsä en minä tyköäni hylkää."],[18,23,"Vaan olen vakaa hänen edessänsä ja vältän vääryyttä.","Vaan olen vakaa hänen edessänsä ja vältän vääryyttä."],[18,24,"Sentähden Herra kostaa minulle vanhurskauteni perästä, kätteni puhtauden jälkeen, silmäinsä edessä.","Sentähden Herra kostaa minulle vanhurskauteni perästä, kätteni puhtauden jälkeen, silmäinsä edessä."],[18,25,"Pyhäin kanssa sinä pyhä olet, ja toimellisten kanssa toimellinen.","Pyhäin kanssa sinä pyhä olet, ja toimellisten kanssa toimellinen."],[18,26,"Puhdasten kanssa sinä puhdas olet, ja nurjain kanssa sinä nurja olet.","Puhdasten kanssa sinä puhdas olet, ja nurjain kanssa sinä nurja olet."],[18,27,"Sillä sinä vapahdat ahdistetun kansan, ja korkiat silmät sinä alennat.","Sillä sinä vapahdat ahdistetun kansan, ja korkiat silmät sinä alennat."],[18,28,"Sillä minun kynttiläni sinä valaiset; Herra minun Jumalani valaisee minun pimeyteni.","Sillä minun kynttiläni sinä valaiset; Herra minun Jumalani valaisee minun pimeyteni."],[18,29,"Sillä sinun kauttas minä sotaväen murran, ja minun Jumalassani karkaan muurin ylitse.","Sillä sinun kauttas minä sotaväen murran, ja minun Jumalassani karkaan muurin ylitse."],[18,30,"Jumalan tie on täydellinen. Herran puheet tulella koetellut: hän on kaikkein kilpi, jotka häneen uskaltavat.","Jumalan tie on täydellinen. Herran puheet tulella koetellut: hän on kaikkein kilpi, jotka häneen uskaltavat."],[18,31,"Sillä kuka on Jumala, paitsi Herraa? ja kuka on kallio, paitsi Jumalaamme?","Sillä kuka on Jumala, paitsi Herraa? ja kuka on kallio, paitsi Jumalaamme?"],[18,32,"Jumala vyöttää minun voimalla, ja panee minun tieni viattomaksi.","Jumala vyöttää minun voimalla, ja panee minun tieni viattomaksi."],[18,33,"Hän tekee jalkani niinkuin peurain jalat, ja asettaa minun korkeudelle.","Hän tekee jalkani niinkuin peurain jalat, ja asettaa minun korkeudelle."],[18,34,"Hän opettaa käteni sotimaan, ja käsivarteni vaskijoutsea vetämään.","Hän opettaa käteni sotimaan, ja käsivarteni vaskijoutsea vetämään."],[18,35,"Ja sinä annoit minulle autuutes kilven, ja sinun oikia kätes vahvistaa minun: ja koskas minun alennat, niin sinä teet minun suureksi.","Ja sinä annoit minulle autuutes kilven, ja sinun oikia kätes vahvistaa minun: ja koskas minun alennat, niin sinä teet minun suureksi."],[18,36,"Sinä levitit minun askeleeni minun allani, ettei minun kantapääni livistyneet.","Sinä levitit minun askeleeni minun allani, ettei minun kantapääni livistyneet."],[18,37,"Minä ajan vihollisiani takaa ja käsitän heitä, ja en palaja, ennenkuin minä heidät hukutan.","Minä ajan vihollisiani takaa ja käsitän heitä, ja en palaja, ennenkuin minä heidät hukutan."],[18,38,"Minä runtelen heitä, ettei he taida nousta: heidän täytyy kaatua jalkaini alla.","Minä runtelen heitä, ettei he taida nousta: heidän täytyy kaatua jalkaini alla."],[18,39,"Sinä valmistat minun voimalla sotaan: sinä taivutat minun alleni ne, jotka nousevat minua vastaan.","Sinä valmistat minun voimalla sotaan: sinä taivutat minun alleni ne, jotka nousevat minua vastaan."],[18,40,"Sinä annat minulle viholliseni kaulan, ja minä kadotan vainoojani.","Sinä annat minulle viholliseni kaulan, ja minä kadotan vainoojani."],[18,41,"He huutavat, vaan ei ole auttajaa: Herran tykö, mutta ei hän vastaa heitä.","He huutavat, vaan ei ole auttajaa: Herran tykö, mutta ei hän vastaa heitä."],[18,42,"Minä survon heitä niinkuin maan tomun tuulen edessä, ja heitän pois niinkuin loan kaduilta.","Minä survon heitä niinkuin maan tomun tuulen edessä, ja heitän pois niinkuin loan kaduilta."],[18,43,"Sinä pelastat minua riitaisesta kansasta: sinä asetat minun pakanain pääksi; se kansa, jota en minä tuntenut, palvelee minua.","Sinä pelastat minua riitaisesta kansasta: sinä asetat minun pakanain pääksi; se kansa, jota en minä tuntenut, palvelee minua."],[18,44,"Se kuultelee minua kuuliaisilla korvilla: muukalaiset lapset kieltävät minun.","Se kuultelee minua kuuliaisilla korvilla: muukalaiset lapset kieltävät minun."],[18,45,"Muukalaiset lapset vaipuvat ja vapisevat siteissänsä.","Muukalaiset lapset vaipuvat ja vapisevat siteissänsä."],[18,46,"Herra elää, ja kiitetty olkoon minun kallioni, ja minun autuuteni Jumala olkoon ylistetty!","Herra elää, ja kiitetty olkoon minun kallioni, ja minun autuuteni Jumala olkoon ylistetty!"],[18,47,"Jumala, joka minulle koston antaa, ja vaatii kansat minun alleni;","Jumala, joka minulle koston antaa, ja vaatii kansat minun alleni;"],[18,48,"Joka minua auttaa vihollisistani: sinä korotat myös minun niistä, jotka karkaavat minua vastaan: sinä pelastat minua väkivaltaisesta miehestä.","Joka minua auttaa vihollisistani: sinä korotat myös minun niistä, jotka karkaavat minua vastaan: sinä pelastat minua väkivaltaisesta miehestä."],[18,49,"Sentähden minä kiitän sinua, Herra, pakanain seassa, ja veisaan nimelles kiitoksen,","Sentähden minä kiitän sinua, Herra, pakanain seassa, ja veisaan nimelles kiitoksen,"],[18,50,"Joka suuren autuuden kuninkaallensa osoittaa, ja tekee hyvästi voidellullensa, Davidille, ja hänen siemenellensä ijankaikkisesti.","Joka suuren autuuden kuninkaallensa osoittaa, ja tekee hyvästi voidellullensa, Davidille, ja hänen siemenellensä ijankaikkisesti."],[19,1,"Davidin Psalmi, edelläveisaajalle. (H19:2) Taivaat ilmoittavat Jumalan kunnian, ja vahvuus julistaa hänen kättensä teot.","Davidin Psalmi, edelläveisaajalle. (H19:2) Taivaat ilmoittavat Jumalan kunnian, ja vahvuus julistaa hänen kättensä teot."],[19,2,"Päivä sanoo päivälle, ja yö ilmoittaa yölle tiedon.","Päivä sanoo päivälle, ja yö ilmoittaa yölle tiedon."],[19,3,"Ei ole kieltä eikä puhetta, kussa ei heidän äänensä kuulu.","Ei ole kieltä eikä puhetta, kussa ei heidän äänensä kuulu."],[19,4,"Heidän nuoransa käy ulos kaikkiin maihin, ja heidän puheensa maailman ääreen asti: auringolle hän pani majan heissä.","Heidän nuoransa käy ulos kaikkiin maihin, ja heidän puheensa maailman ääreen asti: auringolle hän pani majan heissä."],[19,5,"Ja hän käy ulos kammiostansa niinkuin ylkä, ja riemuitsee niinkuin sankari tietä juostaksensa.","Ja hän käy ulos kammiostansa niinkuin ylkä, ja riemuitsee niinkuin sankari tietä juostaksensa."],[19,6,"Hän käy ylös taivasten lopulta ja juoksee ympäri hamaan niiden loppuun jälleen; ja ei ole mitään peitetty hänen lämpimänsä edestä.","Hän käy ylös taivasten lopulta ja juoksee ympäri hamaan niiden loppuun jälleen; ja ei ole mitään peitetty hänen lämpimänsä edestä."],[19,7,"Herran laki on täydellinen ja virvoittaa sielut: Herran todistus on vahva ja tekee yksinkertaiset taitaviksi.","Herran laki on täydellinen ja virvoittaa sielut: Herran todistus on vahva ja tekee yksinkertaiset taitaviksi."],[19,8,"Herran käskyt ovat oikiat ja ilahuttavat sydämet: Herran käskyt ovat kirkkaat ja valistavat silmät.","Herran käskyt ovat oikiat ja ilahuttavat sydämet: Herran käskyt ovat kirkkaat ja valistavat silmät."],[19,9,"Herran pelko on puhdas ja pysyy ijankaikkisesti: Herran oikeudet ovat todet, kaikki tyynni vanhurskaat,","Herran pelko on puhdas ja pysyy ijankaikkisesti: Herran oikeudet ovat todet, kaikki tyynni vanhurskaat,"],[19,10,"Ne ovat kalliimmat kultaa ja kaikkein parasta kultaa, ja makeammat hunajaa ja mesileipiä.","Ne ovat kalliimmat kultaa ja kaikkein parasta kultaa, ja makeammat hunajaa ja mesileipiä."],[19,11,"Sinun palvelias myös niissä opetetaan: ja joka niitä pitää, hänellä on suuri palkka.","Sinun palvelias myös niissä opetetaan: ja joka niitä pitää, hänellä on suuri palkka."],[19,12,"Erhetykset kuka ymmärtää? anna minulle anteeksi salaiset rikokset.","Erhetykset kuka ymmärtää? anna minulle anteeksi salaiset rikokset."],[19,13,"Varjele myös palvelias ylpeistä, ettei he minua hallitsisi; niin minä olen viatoin ja nuhteetoin suuresta pahasta teosta.","Varjele myös palvelias ylpeistä, ettei he minua hallitsisi; niin minä olen viatoin ja nuhteetoin suuresta pahasta teosta."],[19,14,"Kelvatkoon sinulle minun suuni puheet, ja minun sydämeni ajatukset sinun edessäs, Herra, minun vahani ja minun Lunastajani!","Kelvatkoon sinulle minun suuni puheet, ja minun sydämeni ajatukset sinun edessäs, Herra, minun vahani ja minun Lunastajani!"],[20,1,"Davidin Psalmi, edelläveisaajalle. (H20:2) Herra kuulkoon sinua hädässäs, Jakobin Jumalan nimi sinua varjelkoon!","Davidin Psalmi, edelläveisaajalle. (H20:2) Herra kuulkoon sinua hädässäs, Jakobin Jumalan nimi sinua varjelkoon!"],[20,2,"Hän lähettäköön sinulle apua pyhästä ja Zionista sinua vahvistakoon!","Hän lähettäköön sinulle apua pyhästä ja Zionista sinua vahvistakoon!"],[20,3,"Hän muistakoon kaikki ruokauhris, ja sinun polttouhris olkoon lihavat, Sela!","Hän muistakoon kaikki ruokauhris, ja sinun polttouhris olkoon lihavat, Sela!"],[20,4,"Hän antakoon sinulle, mitä sinun sydämes anoo, ja päättäköön kaikki aivoitukses!","Hän antakoon sinulle, mitä sinun sydämes anoo, ja päättäköön kaikki aivoitukses!"],[20,5,"Me kerskaamme sinun avustas, ja meidän Jumalamme nimessä me ylennämme lippumme: Herra täyttäköön kaikki sinun rukoukses!","Me kerskaamme sinun avustas, ja meidän Jumalamme nimessä me ylennämme lippumme: Herra täyttäköön kaikki sinun rukoukses!"],[20,6,"Nyt minä tunnen Herran voideltuansa auttavan, ja häntä kuulevan pyhästä taivaastansa: hänen oikia kätensä auttaa voimallisesti.","Nyt minä tunnen Herran voideltuansa auttavan, ja häntä kuulevan pyhästä taivaastansa: hänen oikia kätensä auttaa voimallisesti."],[20,7,"Nämät uskaltavat rattaisiin ja oreihin; mutta me muistamme Herran Jumalamme nimeä.","Nämät uskaltavat rattaisiin ja oreihin; mutta me muistamme Herran Jumalamme nimeä."],[20,8,"He ovat kukistetut ja langenneet; mutta me nousemme ja pystyällä seisomme.","He ovat kukistetut ja langenneet; mutta me nousemme ja pystyällä seisomme."],[20,9,"Auta Herra! Kuningas meitä kuulkaan, kuin me huudamme.","Auta Herra! Kuningas meitä kuulkaan, kuin me huudamme."],[21,1,"Davidin Psalmi, edelläveisaajalle. (H21:2) Herra, Kuningas riemuitsee sinun voimassas: ja kuinka suuresti hän iloitsee avustas!","Davidin Psalmi, edelläveisaajalle. (H21:2) Herra, Kuningas riemuitsee sinun voimassas: ja kuinka suuresti hän iloitsee avustas!"],[21,2,"Hänen sydämensä halun sinä annat hänelle, etkä kiellä, mitä hänen suunsa anoo, Sela!","Hänen sydämensä halun sinä annat hänelle, etkä kiellä, mitä hänen suunsa anoo, Sela!"],[21,3,"Sillä sinä ennätät hänen hyvällä siunauksella: sinä panet kultaisen kruunun hänen päähänsä.","Sillä sinä ennätät hänen hyvällä siunauksella: sinä panet kultaisen kruunun hänen päähänsä."],[21,4,"Hän anoi elämää sinulta, niin sinä annoit hänelle pitkän ijän aina ja ijankaikkisesti.","Hän anoi elämää sinulta, niin sinä annoit hänelle pitkän ijän aina ja ijankaikkisesti."],[21,5,"Hänellä on suuri kunnia sinun avustas: sinä panet ylistyksen ja kaunistuksen hänen päällensä.","Hänellä on suuri kunnia sinun avustas: sinä panet ylistyksen ja kaunistuksen hänen päällensä."],[21,6,"Sillä sinä asetat hänen siunaukseksi ijankaikkisesti: sinä ilahutat hänen kasvois edessä ilolla.","Sillä sinä asetat hänen siunaukseksi ijankaikkisesti: sinä ilahutat hänen kasvois edessä ilolla."],[21,7,"Sillä Kuningas turvaa Herraan: ja Ylimmäisen laupiudessa ei hän horju.","Sillä Kuningas turvaa Herraan: ja Ylimmäisen laupiudessa ei hän horju."],[21,8,"Sinun kätes löytää kaikki vihollises: sinun oikia kätes löytää ne, jotka sinua kadehtivat.","Sinun kätes löytää kaikki vihollises: sinun oikia kätes löytää ne, jotka sinua kadehtivat."],[21,9,"Sinä panet heitä niinkuin kuumaan pätsiin sinun vihas aikana: Herra nielee heitä vihassansa, ja tuli syö heitä.","Sinä panet heitä niinkuin kuumaan pätsiin sinun vihas aikana: Herra nielee heitä vihassansa, ja tuli syö heitä."],[21,10,"Heidän hedelmänsä sinä kadotat maan päältä, ja heidän siemenensä ihmisten lapsista.","Heidän hedelmänsä sinä kadotat maan päältä, ja heidän siemenensä ihmisten lapsista."],[21,11,"Sillä he ajattelivat tehdä sinulle pahaa: he pitivät neuvoa, jota ei he voineet täyttää.","Sillä he ajattelivat tehdä sinulle pahaa: he pitivät neuvoa, jota ei he voineet täyttää."],[21,12,"Sillä sinä teet heitä olkapääksi: sinä tarkoitat jänteelläs heidän kasvojansa vastaan.","Sillä sinä teet heitä olkapääksi: sinä tarkoitat jänteelläs heidän kasvojansa vastaan."],[21,13,"Herra, ylennä sinuas väkevyydessäs; niin me veisaamme ja kiitämme sinun voimaas.","Herra, ylennä sinuas väkevyydessäs; niin me veisaamme ja kiitämme sinun voimaas."],[22,1,"Davidin Psalmi, edelläveisaajalle, peurasta, jota varhain väijytään. (H22:2) Minun Jumalani, minun Jumalani! miksis minun hylkäsit? minä parun, vaan minun apuni on kaukana.","Davidin Psalmi, edelläveisaajalle, peurasta, jota varhain väijytään. (H22:2) Minun Jumalani, minun Jumalani! miksis minun hylkäsit? minä parun, vaan minun apuni on kaukana."],[22,2,"Minun Jumalani! päivällä minä huudan, ja et sinä vastaa, ja en yölläkään vaikene.","Minun Jumalani! päivällä minä huudan, ja et sinä vastaa, ja en yölläkään vaikene."],[22,3,"Sinä olet pyhä, joka asut Israelin kiitoksessa.","Sinä olet pyhä, joka asut Israelin kiitoksessa."],[22,4,"Meidän isämme toivoivat sinuun: ja kuin he toivoivat, niin sinä vapahdit heitä.","Meidän isämme toivoivat sinuun: ja kuin he toivoivat, niin sinä vapahdit heitä."],[22,5,"Sinua he huusivat, ja vapahdettiin: sinuun he turvasivat, ja ei tulleet häpiään.","Sinua he huusivat, ja vapahdettiin: sinuun he turvasivat, ja ei tulleet häpiään."],[22,6,"Mutta minä olen mato ja en ihminen, ihmisten pilkka ja kansan ylönkatse.","Mutta minä olen mato ja en ihminen, ihmisten pilkka ja kansan ylönkatse."],[22,7,"Kaikki, jotka minun näkevät, häpäisevät minua: he vääristelevät huuliansa ja päätänsä vääntelevät.","Kaikki, jotka minun näkevät, häpäisevät minua: he vääristelevät huuliansa ja päätänsä vääntelevät."],[22,8,"Hän valittaa Herralle, hän vapahtakoon hänen: hän auttakoon häntä, jos hän mielistyy häneen.","Hän valittaa Herralle, hän vapahtakoon hänen: hän auttakoon häntä, jos hän mielistyy häneen."],[22,9,"Sillä sinä olet minun vetänyt ulos äitini kohdusta: sinä olit minun turvani, ollessani vielä äitini rinnalla.","Sillä sinä olet minun vetänyt ulos äitini kohdusta: sinä olit minun turvani, ollessani vielä äitini rinnalla."],[22,10,"Sinun päälles minä olen heitetty äitini kohdusta: sinä olet minun Jumalani hamasta äitini kohdusta.","Sinun päälles minä olen heitetty äitini kohdusta: sinä olet minun Jumalani hamasta äitini kohdusta."],[22,11,"Älä ole kaukana minusta; sillä ahdistus on läsnä, ja ei ole auttajaa,","Älä ole kaukana minusta; sillä ahdistus on läsnä, ja ei ole auttajaa,"],[22,12,"Suuret mullit ovat minun piirittäneet, lihavat härjät kiertäneet minun ympäri.","Suuret mullit ovat minun piirittäneet, lihavat härjät kiertäneet minun ympäri."],[22,13,"Kitansa avasivat he minua vastaan, niinkuin raateleva ja kiljuva jalopeura.","Kitansa avasivat he minua vastaan, niinkuin raateleva ja kiljuva jalopeura."],[22,14,"Minä olen kaadettu ulos niinkuin vesi, ja luuni ovat kaikki hajoitetut: minun sydämeni on niinkuin salattu vedenvaha ruumiissani.","Minä olen kaadettu ulos niinkuin vesi, ja luuni ovat kaikki hajoitetut: minun sydämeni on niinkuin salattu vedenvaha ruumiissani."],[22,15,"Minun voimani on kuivettunut niinkuin kruusin muru, ja minun kieleni tarttuu suuni lakeen; ja sinä panet minun kuoleman tomuun.","Minun voimani on kuivettunut niinkuin kruusin muru, ja minun kieleni tarttuu suuni lakeen; ja sinä panet minun kuoleman tomuun."],[22,16,"Sillä koirat ovat minun piirittäneet: julmain parvi saartain lävistänyt kuin jalopeura käteni ja jalkani.","Sillä koirat ovat minun piirittäneet: julmain parvi saartain lävistänyt kuin jalopeura käteni ja jalkani."],[22,17,"Minä lukisin kaikki minun luuni; mutta he katselivat ja näkivät ihastuksensa minusta.","Minä lukisin kaikki minun luuni; mutta he katselivat ja näkivät ihastuksensa minusta."],[22,18,"He jakavat itsellensä minun vaatteeni ja heittävät hameestani arpaa.","He jakavat itsellensä minun vaatteeni ja heittävät hameestani arpaa."],[22,19,"Mutta sinä, Herra, älä ole kaukana! minun väkevyyteni, riennä avukseni!","Mutta sinä, Herra, älä ole kaukana! minun väkevyyteni, riennä avukseni!"],[22,20,"Pelasta minun sieluni miekasta, ja ainokaiseni koirilta.","Pelasta minun sieluni miekasta, ja ainokaiseni koirilta."],[22,21,"Vapahda minua jalopeuran suusta, ja päästä minua yksisarvillisista.","Vapahda minua jalopeuran suusta, ja päästä minua yksisarvillisista."],[22,22,"Minä saarnaan sinun nimeäs veljilleni: minä ylistän sinua seurakunnassa.","Minä saarnaan sinun nimeäs veljilleni: minä ylistän sinua seurakunnassa."],[22,23,"Ylistäkäät Herraa te, jotka häntä pelkäätte: koko Jakobin siemen kunnioittakoon häntä, ja kavahtakoon häntä kaikki Israelin siemen!","Ylistäkäät Herraa te, jotka häntä pelkäätte: koko Jakobin siemen kunnioittakoon häntä, ja kavahtakoon häntä kaikki Israelin siemen!"],[22,24,"Sillä ei hän hyljännyt eikä katsonut ylön köyhän raadollisuutta, eikä kääntänyt kasvojansa hänestä pois; vaan kuin se häntä huusi, kuuli hän sitä.","Sillä ei hän hyljännyt eikä katsonut ylön köyhän raadollisuutta, eikä kääntänyt kasvojansa hänestä pois; vaan kuin se häntä huusi, kuuli hän sitä."],[22,25,"Sinua minä ylistän suuressa seurakunnassa: minä maksan lupaukseni heidän edessänsä, jotka häntä pelkäävät.","Sinua minä ylistän suuressa seurakunnassa: minä maksan lupaukseni heidän edessänsä, jotka häntä pelkäävät."],[22,26,"Raadolliset syövät ja ravitaan, ja jotka Herraa etsivät, pitää häntä ylistämän: teidän sydämenne pitää elämän ijankaikkisesti.","Raadolliset syövät ja ravitaan, ja jotka Herraa etsivät, pitää häntä ylistämän: teidän sydämenne pitää elämän ijankaikkisesti."],[22,27,"Kaikki maailman ääret muistakaan ja kääntykään Herran tykö, ja kumartakaan sinun edessäs kaikki pakanain sukukunnat.","Kaikki maailman ääret muistakaan ja kääntykään Herran tykö, ja kumartakaan sinun edessäs kaikki pakanain sukukunnat."],[22,28,"Sillä Herralta on valtakunta, ja hän vallitsee pakanoita.","Sillä Herralta on valtakunta, ja hän vallitsee pakanoita."],[22,29,"Kaikki lihavat maan päällä pitää syömän ja kumartaman, hänen edessänsä polviansa notkistaman kaikki, jotka tomussa makaavat ja jotka surussansa elävät.","Kaikki lihavat maan päällä pitää syömän ja kumartaman, hänen edessänsä polviansa notkistaman kaikki, jotka tomussa makaavat ja jotka surussansa elävät."],[22,30,"Hänen pitää saaman siemenen, joka häntä palvelee: Herrasta pitää ilmoitettaman lasten lapsiin.","Hänen pitää saaman siemenen, joka häntä palvelee: Herrasta pitää ilmoitettaman lasten lapsiin."],[22,31,"He tulevat ja hänen vanhurskauttansa saarnaavat syntyvälle kansalle, että hän sen tekee.","He tulevat ja hänen vanhurskauttansa saarnaavat syntyvälle kansalle, että hän sen tekee."],[23,1,"Davidin Psalmi. Herra on minun paimeneni: ei minulta mitään puutu.","Davidin Psalmi. Herra on minun paimeneni: ei minulta mitään puutu."],[23,2,"Hän kaitsee minua viheriäisessä niityssä, ja vie minua virvoittavan veden tykö.","Hän kaitsee minua viheriäisessä niityssä, ja vie minua virvoittavan veden tykö."],[23,3,"Minun sieluni hän virvoittaa: hän vie minun oikialle tielle, nimensä tähden.","Minun sieluni hän virvoittaa: hän vie minun oikialle tielle, nimensä tähden."],[23,4,"Ja vaikka minä vaeltaisin pimiässä laaksossa, en minä pelkäisi mitään pahuutta, ettäs olet kanssani: sinun vitsas ja sauvas minun tukevat.","Ja vaikka minä vaeltaisin pimiässä laaksossa, en minä pelkäisi mitään pahuutta, ettäs olet kanssani: sinun vitsas ja sauvas minun tukevat."],[23,5,"Sinä valmistat minulle pöydän vihollisteni kohdalle: sinä voitelet minun pääni öljyllä, ja minun maljani on ylitsevuotavainen.","Sinä valmistat minulle pöydän vihollisteni kohdalle: sinä voitelet minun pääni öljyllä, ja minun maljani on ylitsevuotavainen."],[23,6,"Hyvyys ja laupius noudattavat minua kaiken elinaikani, ja minä saan asua Herran huoneessa ijankaikkisesti.","Hyvyys ja laupius noudattavat minua kaiken elinaikani, ja minä saan asua Herran huoneessa ijankaikkisesti."],[24,1,"Davidin Psalmi. Herran on maa, ja kaikki mitkä siinä ovat, maan piiri ja ne jotka sen päällä asuvat.","Davidin Psalmi. Herran on maa, ja kaikki mitkä siinä ovat, maan piiri ja ne jotka sen päällä asuvat."],[24,2,"Sillä hän on perustanut sen merten päälle, ja virtain päälle sen vahvistanut.","Sillä hän on perustanut sen merten päälle, ja virtain päälle sen vahvistanut."],[24,3,"Kuka astuu Herran vuorelle? ja kuka taitaa seisoa hänen pyhässä siassansa?","Kuka astuu Herran vuorelle? ja kuka taitaa seisoa hänen pyhässä siassansa?"],[24,4,"Jolla viattomat kädet ovat ja on puhdas sydämestä, joka ei halaja turhuutta eikä vanno väärin,","Jolla viattomat kädet ovat ja on puhdas sydämestä, joka ei halaja turhuutta eikä vanno väärin,"],[24,5,"Se saa siunauksen Herralta, ja vanhurskauden autuutensa Jumalalta.","Se saa siunauksen Herralta, ja vanhurskauden autuutensa Jumalalta."],[24,6,"Tämä on se sukukunta, joka häntä etsii, joka kysyy sinun kasvojas, Jakob, Sela!","Tämä on se sukukunta, joka häntä etsii, joka kysyy sinun kasvojas, Jakob, Sela!"],[24,7,"Tehkäät portit avaraksi ja ovet maailmassa korkiaksi, kunnian Kuninkaan mennä sisälle.","Tehkäät portit avaraksi ja ovet maailmassa korkiaksi, kunnian Kuninkaan mennä sisälle."],[24,8,"Kuka on kunnian Kuningas? se on Herra, väkevä ja voimallinen, Herra voimallinen sodassa.","Kuka on kunnian Kuningas? se on Herra, väkevä ja voimallinen, Herra voimallinen sodassa."],[24,9,"Tehkäät portit avaraksi ja ovet maailmassa korkiaksi, kunnian Kuninkaan mennä sisälle!","Tehkäät portit avaraksi ja ovet maailmassa korkiaksi, kunnian Kuninkaan mennä sisälle!"],[24,10,"Kuka on kunnian Kuningas? se on Herra Zebaot, hän on kunnian Kuningas, Sela!","Kuka on kunnian Kuningas? se on Herra Zebaot, hän on kunnian Kuningas, Sela!"],[25,1,"Davidin Psalmi. Sinun tykös, Herra, ylennän minä sieluni.","Davidin Psalmi. Sinun tykös, Herra, ylennän minä sieluni."],[25,2,"Minun Jumalani! sinuun minä turvaan, älä salli minua häväistä, ettei minun viholliseni iloitsisi minusta.","Minun Jumalani! sinuun minä turvaan, älä salli minua häväistä, ettei minun viholliseni iloitsisi minusta."],[25,3,"Sillä ei yksikään tule häpiään, joka sinua odottaa; mutta irralliset pilkkaajat saavat häpiän.","Sillä ei yksikään tule häpiään, joka sinua odottaa; mutta irralliset pilkkaajat saavat häpiän."],[25,4,"Herra, osoita minulle sinun ties, ja opeta minulle sinun polkus.","Herra, osoita minulle sinun ties, ja opeta minulle sinun polkus."],[25,5,"Johdata minua totuudessas, ja opeta minua; sillä sinä olet Jumala, joka minua autat, yli päivää minä odotan sinua.","Johdata minua totuudessas, ja opeta minua; sillä sinä olet Jumala, joka minua autat, yli päivää minä odotan sinua."],[25,6,"Muista, Herra, laupiuttas ja hyvyyttäs, joka maailman alusta on ollut.","Muista, Herra, laupiuttas ja hyvyyttäs, joka maailman alusta on ollut."],[25,7,"Älä muista nuoruuteni syntejä ja ylitsekäymistäni; mutta muista minua sinun laupiutes jälkeen, sinun hyvyytes tähden, Herra!","Älä muista nuoruuteni syntejä ja ylitsekäymistäni; mutta muista minua sinun laupiutes jälkeen, sinun hyvyytes tähden, Herra!"],[25,8,"Herra on hyvä ja vakaa, sentähden saattaa hän syntiset tielle.","Herra on hyvä ja vakaa, sentähden saattaa hän syntiset tielle."],[25,9,"Hän johdattaa oikeudella raadollisen, ja opettaa siveille hänen tiensä.","Hän johdattaa oikeudella raadollisen, ja opettaa siveille hänen tiensä."],[25,10,"Kaikki Herran tiet ovat hyvyys ja totuus niille, jotka hänen liittonsa ja todistuksensa pitävät.","Kaikki Herran tiet ovat hyvyys ja totuus niille, jotka hänen liittonsa ja todistuksensa pitävät."],[25,11,"Sinun nimes tähden, Herra, ole armollinen minun pahalle teolleni, joka suuri on.","Sinun nimes tähden, Herra, ole armollinen minun pahalle teolleni, joka suuri on."],[25,12,"Kuka on se mies, joka Herraa pelkää? sillä hän opettaa parhaan tien.","Kuka on se mies, joka Herraa pelkää? sillä hän opettaa parhaan tien."],[25,13,"Hänen sielunsa asuu hyvyydessä, ja hänen sikiänsä omistaa maan.","Hänen sielunsa asuu hyvyydessä, ja hänen sikiänsä omistaa maan."],[25,14,"Herran salaisuus on niillä, jotka häntä pelkäävät, ja liittonsa ilmoittaa hän heille.","Herran salaisuus on niillä, jotka häntä pelkäävät, ja liittonsa ilmoittaa hän heille."],[25,15,"Minun silmäni katsovat alati Herraa, sillä hän kirvoittaa minun jalkani verkosta.","Minun silmäni katsovat alati Herraa, sillä hän kirvoittaa minun jalkani verkosta."],[25,16,"Käännä sinuas minun puoleeni, ja ole minulle armollinen; sillä minä olen yksinäinen ja raadollinen.","Käännä sinuas minun puoleeni, ja ole minulle armollinen; sillä minä olen yksinäinen ja raadollinen."],[25,17,"Minun sydämeni murheet ovat moninaiset: vie siis minua ulos tuskistani.","Minun sydämeni murheet ovat moninaiset: vie siis minua ulos tuskistani."],[25,18,"Katsos minun vaivaisuuteni ja raadollisuuteni puoleen, ja anna kaikki minun syntini anteeksi.","Katsos minun vaivaisuuteni ja raadollisuuteni puoleen, ja anna kaikki minun syntini anteeksi."],[25,19,"Katsos, kuinka monta vihollista minulla on? ja sulasta kateudesta he minua vihaavat.","Katsos, kuinka monta vihollista minulla on? ja sulasta kateudesta he minua vihaavat."],[25,20,"Varjele minun sieluni ja vapahda minua, älä laske minua häpiään; sillä sinuun minä turvaan.","Varjele minun sieluni ja vapahda minua, älä laske minua häpiään; sillä sinuun minä turvaan."],[25,21,"Vakuus ja oikeus varjelkoon minua; sillä minä odotan sinua.","Vakuus ja oikeus varjelkoon minua; sillä minä odotan sinua."],[25,22,"Jumala, vapahda Israel kaikista tuskistansa.","Jumala, vapahda Israel kaikista tuskistansa."],[26,1,"Davidin Psalmi. Tuomitse minua, Herra; sillä minä olen vakuudessani vaeltanut: ja minä toivon Herraan, sentähden en minä livistele.","Davidin Psalmi. Tuomitse minua, Herra; sillä minä olen vakuudessani vaeltanut: ja minä toivon Herraan, sentähden en minä livistele."],[26,2,"Koettele minua, Herra, ja kiusaa minua: puhdista minun munaskuuni ja sydämeni.","Koettele minua, Herra, ja kiusaa minua: puhdista minun munaskuuni ja sydämeni."],[26,3,"Sillä sinun hyvyytes on silmäini edessä, ja minä vaellan sinun totuudessas.","Sillä sinun hyvyytes on silmäini edessä, ja minä vaellan sinun totuudessas."],[26,4,"En minä istu turhain ihmisten seassa, enkä seuraa petollisia.","En minä istu turhain ihmisten seassa, enkä seuraa petollisia."],[26,5,"Minä vihaan pahain seurakuntaa, enkä istu jumalattomain tykönä.","Minä vihaan pahain seurakuntaa, enkä istu jumalattomain tykönä."],[26,6,"Minä pesen käteni viattomuudessa, ja oleskelen, Herra, alttaris tykönä,","Minä pesen käteni viattomuudessa, ja oleskelen, Herra, alttaris tykönä,"],[26,7,"Kussa kiitossanan ääni kuullaan, ja kaikki sinun ihmees saarnataan.","Kussa kiitossanan ääni kuullaan, ja kaikki sinun ihmees saarnataan."],[26,8,"Herra, minä rakastin sinun huonees asuinsiaa ja sitä siaa, jossa sinun kunnias asuu.","Herra, minä rakastin sinun huonees asuinsiaa ja sitä siaa, jossa sinun kunnias asuu."],[26,9,"Älä tempaa minun sieluani pois syntisten kanssa ja henkeäni verikoirain kanssa,","Älä tempaa minun sieluani pois syntisten kanssa ja henkeäni verikoirain kanssa,"],[26,10,"Jotka pahanjuoniset ovat ja mielellänsä lahjoja ottavat.","Jotka pahanjuoniset ovat ja mielellänsä lahjoja ottavat."],[26,11,"Mutta minä vaellan viattomuudessani: vapahda minua ja ole minulle armollinen!","Mutta minä vaellan viattomuudessani: vapahda minua ja ole minulle armollinen!"],[26,12,"Minun jalkani käy oikiasti: minä kiitän Herraa seurakunnissa.","Minun jalkani käy oikiasti: minä kiitän Herraa seurakunnissa."],[27,1,"Davidin Psalmi. Herra on minun valistukseni ja autuuteni, ketä minä pelkään? Herra on henkeni väkevyys, ketä minä vapisen?","Davidin Psalmi. Herra on minun valistukseni ja autuuteni, ketä minä pelkään? Herra on henkeni väkevyys, ketä minä vapisen?"],[27,2,"Sentähden, vaikka pahat, vainolliseni ja viholliseni, lähestyvät minun lihaani syömään, täytyy heidän kuintenkin itseänsä loukata ja langeta.","Sentähden, vaikka pahat, vainolliseni ja viholliseni, lähestyvät minun lihaani syömään, täytyy heidän kuintenkin itseänsä loukata ja langeta."],[27,3,"Ja vaikka sotaväki saartais minua, niin ei sydämeni sentähden pelkäisi; ja jos sota nousis minua vastaan, minä turvaan sittekin häneen.","Ja vaikka sotaväki saartais minua, niin ei sydämeni sentähden pelkäisi; ja jos sota nousis minua vastaan, minä turvaan sittekin häneen."],[27,4,"Yhtä minä Herralta anon, sitä minä pyydän, asuakseni Herran huoneessa kaiken elinaikani: että minä näkisin Herran kauniin jumalanpalveluksen, ja hänen templiänsä etsisin.","Yhtä minä Herralta anon, sitä minä pyydän, asuakseni Herran huoneessa kaiken elinaikani: että minä näkisin Herran kauniin jumalanpalveluksen, ja hänen templiänsä etsisin."],[27,5,"Sillä hän peittää minua majassansa pahana aikana: hän kätkee minun salaiseen majaansa, ja korottaa minun kalliolle.","Sillä hän peittää minua majassansa pahana aikana: hän kätkee minun salaiseen majaansa, ja korottaa minun kalliolle."],[27,6,"Ja hän korottaa nytkin minun pääni vihollisteni ylitse, jotka ympärilläni ovat; niin minä uhraan hänen majassansa kiitosuhria: minä veisaan ja laulan Herralle.","Ja hän korottaa nytkin minun pääni vihollisteni ylitse, jotka ympärilläni ovat; niin minä uhraan hänen majassansa kiitosuhria: minä veisaan ja laulan Herralle."],[27,7,"Herra, kuule minun ääneni, koska minä huudan: ole minulle armollinen, ja kuultele minua.","Herra, kuule minun ääneni, koska minä huudan: ole minulle armollinen, ja kuultele minua."],[27,8,"Minun sydämeni sanoo sinulle tämän sinun sanas: etsikäät minun kasvojani! sentähden minä etsin, Herra, sinun kasvojas.","Minun sydämeni sanoo sinulle tämän sinun sanas: etsikäät minun kasvojani! sentähden minä etsin, Herra, sinun kasvojas."],[27,9,"Älä peitä kasvojas minulta, ja älä sysää pois palveliaas vihassas; sillä sinä olet minun apuni: älä minua hylkää, älä myös minua anna ylön, minun autuuteni Jumala.","Älä peitä kasvojas minulta, ja älä sysää pois palveliaas vihassas; sillä sinä olet minun apuni: älä minua hylkää, älä myös minua anna ylön, minun autuuteni Jumala."],[27,10,"Sillä minun isäni ja äitini hylkäsivät minun; mutta Herra korjasi minun.","Sillä minun isäni ja äitini hylkäsivät minun; mutta Herra korjasi minun."],[27,11,"Herra, osoita minulle sinun ties, ja johdata minua oikiaa polkua, minun vihollisteni tähden.","Herra, osoita minulle sinun ties, ja johdata minua oikiaa polkua, minun vihollisteni tähden."],[27,12,"Älä anna minua vihollisteni tahtoon; sillä väärät todistukset seisovat minua vastaan ja tekevät häpeemättä vääryyttä.","Älä anna minua vihollisteni tahtoon; sillä väärät todistukset seisovat minua vastaan ja tekevät häpeemättä vääryyttä."],[27,13,"Mutta minä uskon kuitenkin näkeväni Herran hyvyyttä eläväin maalla,","Mutta minä uskon kuitenkin näkeväni Herran hyvyyttä eläväin maalla,"],[27,14,"Odota Herraa, ole hyvässä turvassa, ja hän vahvistaa sinun sydämes: ja odota Herraa.","Odota Herraa, ole hyvässä turvassa, ja hän vahvistaa sinun sydämes: ja odota Herraa."],[28,1,"Davidin Psalmi. Koska minä huudan sinua, Herra, uskallukseni, niin älä vaikene minulle; etten, koska sinä vaikenisit minulle, minä tulisi niiden kaltaiseksi, jotka hautaan menevät.","Davidin Psalmi. Koska minä huudan sinua, Herra, uskallukseni, niin älä vaikene minulle; etten, koska sinä vaikenisit minulle, minä tulisi niiden kaltaiseksi, jotka hautaan menevät."],[28,2,"Kuule minun rukoukseni ääni, koska minä huudan sinua, kuin minä nostan käteni sinun pyhää kuorias päin.","Kuule minun rukoukseni ääni, koska minä huudan sinua, kuin minä nostan käteni sinun pyhää kuorias päin."],[28,3,"Älä anna minun tulla jumalattomain ja pahointekiäin sekaan, jotka lähimmäistensä kanssa puhuvat ystävällisesti, vaan pahuutta on heidän sydämissänsä,","Älä anna minun tulla jumalattomain ja pahointekiäin sekaan, jotka lähimmäistensä kanssa puhuvat ystävällisesti, vaan pahuutta on heidän sydämissänsä,"],[28,4,"Anna heille heidän työnsä jälkeen ja heidän pahan menonsa perään: anna heille heidän kättensä töiden perään, maksa heille heidän ansionsa perästä.","Anna heille heidän työnsä jälkeen ja heidän pahan menonsa perään: anna heille heidän kättensä töiden perään, maksa heille heidän ansionsa perästä."],[28,5,"Sillä ei he ota vaaria Herran töistä, eikä hänen käsi-aloistansa; sentähden rikkoo hän heitä ja ei rakenna heitä.","Sillä ei he ota vaaria Herran töistä, eikä hänen käsi-aloistansa; sentähden rikkoo hän heitä ja ei rakenna heitä."],[28,6,"Kiitetty olkoon Herra; sillä hän on kuullut minun rukoukseni äänen.","Kiitetty olkoon Herra; sillä hän on kuullut minun rukoukseni äänen."],[28,7,"Herra on minun väkevyyteni ja kilpeni, häneen minun sydämeni toivoo, ja minä olen autettu; ja minun sydämeni riemuitsee, ja minä kiitän häntä veisullani.","Herra on minun väkevyyteni ja kilpeni, häneen minun sydämeni toivoo, ja minä olen autettu; ja minun sydämeni riemuitsee, ja minä kiitän häntä veisullani."],[28,8,"Herra on heidän väkevyytensä; hän on väkevä, joka voideltuansa auttaa.","Herra on heidän väkevyytensä; hän on väkevä, joka voideltuansa auttaa."],[28,9,"Auta kansaas ja siunaa perimistäs, ja ravitse heitä ja korota heitä ijankaikkisesti.","Auta kansaas ja siunaa perimistäs, ja ravitse heitä ja korota heitä ijankaikkisesti."],[29,1,"Davidin Psalmi. Tuokaat Herralle, te väkevät, tuokaat Herralle kunnia ja väkevyys.","Davidin Psalmi. Tuokaat Herralle, te väkevät, tuokaat Herralle kunnia ja väkevyys."],[29,2,"Tuokaat Herralle hänen nimensä kunnia: kumartakaat Herraa pyhässä kaunistuksessa.","Tuokaat Herralle hänen nimensä kunnia: kumartakaat Herraa pyhässä kaunistuksessa."],[29,3,"Herran ääni käy vetten päällä: kunnian Jumala pauhaa, suurten vetten päällä.","Herran ääni käy vetten päällä: kunnian Jumala pauhaa, suurten vetten päällä."],[29,4,"Herran ääni käy voimassa: Herran ääni käy suuressa kunniassa.","Herran ääni käy voimassa: Herran ääni käy suuressa kunniassa."],[29,5,"Herran ääni särkee sedripuut, ja Herra särkee sedripuut Libanonissa.","Herran ääni särkee sedripuut, ja Herra särkee sedripuut Libanonissa."],[29,6,"Hän hyppäyttää heitä niinkuin vasikan, sekä Libanonin että Sirionin, niinkuin nuoren yksisarvisen.","Hän hyppäyttää heitä niinkuin vasikan, sekä Libanonin että Sirionin, niinkuin nuoren yksisarvisen."],[29,7,"Herran ääni leikkaa niinkuin tulen liekki.","Herran ääni leikkaa niinkuin tulen liekki."],[29,8,"Herran ääni häälyttää korven, ja Herra liikuttaa Kadeksen korven.","Herran ääni häälyttää korven, ja Herra liikuttaa Kadeksen korven."],[29,9,"Herran ääni saattaa peurat poikimaan, ja paljastaa metsät: ja hänen templissänsä pitää koko hänen joukkonsa sanoman hänelle kunnian.","Herran ääni saattaa peurat poikimaan, ja paljastaa metsät: ja hänen templissänsä pitää koko hänen joukkonsa sanoman hänelle kunnian."],[29,10,"Herra istuu vedenpaisumisen päällä: Herra pysyy Kuninkaana ijankaikkisesti.","Herra istuu vedenpaisumisen päällä: Herra pysyy Kuninkaana ijankaikkisesti."],[29,11,"Herra antaa kansallensa väkevyyden: Herra siunaa kansaansa rauhalla.","Herra antaa kansallensa väkevyyden: Herra siunaa kansaansa rauhalla."],[30,1,"Psalmi, veisattava Davidin huoneen vihkimisessä. (H30:2) Minä ylistän sinua, Herra, sillä sinä olet korottanut minua: et myös salli viholliseni iloita minusta.","Psalmi, veisattava Davidin huoneen vihkimisessä. (H30:2) Minä ylistän sinua, Herra, sillä sinä olet korottanut minua: et myös salli viholliseni iloita minusta."],[30,2,"Herra minun Jumalani, kuin minä huusin sinua, niin sinä teit minun terveeksi.","Herra minun Jumalani, kuin minä huusin sinua, niin sinä teit minun terveeksi."],[30,3,"Herra, sinä veit sieluni ulos helvetistä: sinä olet minun elävänä pitänyt niiden mennessä kuoppaan.","Herra, sinä veit sieluni ulos helvetistä: sinä olet minun elävänä pitänyt niiden mennessä kuoppaan."],[30,4,"Pyhät, veisatkaat kiitosta Herralle, ja kiittäkäät hänen pyhyytensä muistoksi.","Pyhät, veisatkaat kiitosta Herralle, ja kiittäkäät hänen pyhyytensä muistoksi."],[30,5,"Sillä hänen vihansa viipyy silmänräpäyksen, ja hän ihastuu elämästä: ehtoona on itku, mutta aamulla ilo.","Sillä hänen vihansa viipyy silmänräpäyksen, ja hän ihastuu elämästä: ehtoona on itku, mutta aamulla ilo."],[30,6,"Mutta minä sanoin myötäkäymisessäni: en minä ikänä kukistu.","Mutta minä sanoin myötäkäymisessäni: en minä ikänä kukistu."],[30,7,"Sillä sinä, Herra, olet hyvässä tahdossas vuoreni vahvistanut; mutta kuin sinä kasvos peitit, niin minä hämmästyin.","Sillä sinä, Herra, olet hyvässä tahdossas vuoreni vahvistanut; mutta kuin sinä kasvos peitit, niin minä hämmästyin."],[30,8,"Sinua, Herra, minä huudan, ja Herraa minä rukoilen.","Sinua, Herra, minä huudan, ja Herraa minä rukoilen."],[30,9,"Mitä hyvää minun veressäni on, kuin minä hautaan alas menen? kiittäneekö tomukin sinua, ja ilmoittaneeko se sinun totuuttas?","Mitä hyvää minun veressäni on, kuin minä hautaan alas menen? kiittäneekö tomukin sinua, ja ilmoittaneeko se sinun totuuttas?"],[30,10,"Herra, kuule, ja ole minulle armollinen: Herra, ole minun auttajani.","Herra, kuule, ja ole minulle armollinen: Herra, ole minun auttajani."],[30,11,"Sinä olet muuttanut minun valitukseni iloksi: sinä olet riisunut minun säkkini, ja vyötit minun riemulla,","Sinä olet muuttanut minun valitukseni iloksi: sinä olet riisunut minun säkkini, ja vyötit minun riemulla,"],[30,12,"Että minun kunniani veisais sinulle kiitosta ja ei vaikenisi, Herra minun Jumalani, minä kiitän sinua ijankaikkisesti!","Että minun kunniani veisais sinulle kiitosta ja ei vaikenisi, Herra minun Jumalani, minä kiitän sinua ijankaikkisesti!"],[31,1,"Davidin Psalmi edelläveisaajalle. (H31:2) Herra, sinuun minä uskallan, etten minä ikänä häpiään tulisi: vapahda minua sinun vanhurskautes kautta.","Davidin Psalmi edelläveisaajalle. (H31:2) Herra, sinuun minä uskallan, etten minä ikänä häpiään tulisi: vapahda minua sinun vanhurskautes kautta."],[31,2,"Kallista korvas minun puoleeni, auta minua äkisti: ole minulle vahva kallio ja linna minua auttamaan;","Kallista korvas minun puoleeni, auta minua äkisti: ole minulle vahva kallio ja linna minua auttamaan;"],[31,3,"Sillä sinä olet minun kallioni ja minun linnani, ettäs siis sinun nimes tähden minua taluttaisit ja veisit;","Sillä sinä olet minun kallioni ja minun linnani, ettäs siis sinun nimes tähden minua taluttaisit ja veisit;"],[31,4,"Ettäs minun kirvottaisit verkosta, jonka he minun eteeni virittivät; sillä sinä olet minun väkevyyteni.","Ettäs minun kirvottaisit verkosta, jonka he minun eteeni virittivät; sillä sinä olet minun väkevyyteni."],[31,5,"Sinun käsiis annan minä henkeni, sinä olet minun lunastanut, Herra, sinä totinen Jumala.","Sinun käsiis annan minä henkeni, sinä olet minun lunastanut, Herra, sinä totinen Jumala."],[31,6,"Minä vihaan niitä, jotka pitävät väärää oppia; mutta minä uskallan Herraan.","Minä vihaan niitä, jotka pitävät väärää oppia; mutta minä uskallan Herraan."],[31,7,"Minä ihastun ja riemuitsen sinun hyvyytes tähden, ettäs katsot minun raadollisuuttani, ja tunnet minun sieluni tuskassa.","Minä ihastun ja riemuitsen sinun hyvyytes tähden, ettäs katsot minun raadollisuuttani, ja tunnet minun sieluni tuskassa."],[31,8,"Ja et sinä sulje minua vihollisteni käsiin: sinä asetat minun avaraan paikkaan.","Ja et sinä sulje minua vihollisteni käsiin: sinä asetat minun avaraan paikkaan."],[31,9,"Herra, ole minulle armollinen, sillä minä ahdistetaan; minun kasvoni ovat muuttuneet murheesta, niin myös minun sieluni ja vatsani.","Herra, ole minulle armollinen, sillä minä ahdistetaan; minun kasvoni ovat muuttuneet murheesta, niin myös minun sieluni ja vatsani."],[31,10,"Sillä minun elämäni on kulutettu murheesta, ja minun vuoteni huokauksesta: minun voimani on rauvennut pahain tekoin kautta, ja minun luuni ovat muserretut.","Sillä minun elämäni on kulutettu murheesta, ja minun vuoteni huokauksesta: minun voimani on rauvennut pahain tekoin kautta, ja minun luuni ovat muserretut."],[31,11,"Minä olen pilkaksi tullut kaikille vihamiehilleni ja kylällisilleni ylönpalttisesti, ja hämmästykseksi tuttavilleni: jotka minun ulkona näkevät, pakenevat minua.","Minä olen pilkaksi tullut kaikille vihamiehilleni ja kylällisilleni ylönpalttisesti, ja hämmästykseksi tuttavilleni: jotka minun ulkona näkevät, pakenevat minua."],[31,12,"Minä olen sydämestä unhotettu niinkuin kuollut: minä olen niinkuin rikottu astia.","Minä olen sydämestä unhotettu niinkuin kuollut: minä olen niinkuin rikottu astia."],[31,13,"Sillä minä kuulen monen häväistyksen, että jokainen karttaa minua: he pitävät keskenänsä neuvoa minusta, ja tahtovat ottaa minun henkeni.","Sillä minä kuulen monen häväistyksen, että jokainen karttaa minua: he pitävät keskenänsä neuvoa minusta, ja tahtovat ottaa minun henkeni."],[31,14,"Mutta minä toivon sinuun, Herra, ja sanon: sinä olet minun Jumalani!","Mutta minä toivon sinuun, Herra, ja sanon: sinä olet minun Jumalani!"],[31,15,"Minun aikani ovat sinun käsissäs: pelasta minua vihollisteni kädestä ja niistä, jotka minua vainoovat.","Minun aikani ovat sinun käsissäs: pelasta minua vihollisteni kädestä ja niistä, jotka minua vainoovat."],[31,16,"Anna kasvos paistaa palvelias päälle: auta minua laupiutes kautta.","Anna kasvos paistaa palvelias päälle: auta minua laupiutes kautta."],[31,17,"Herra, älä minun anna häpiään tulla; sillä sinua minä avuksi huudan: jumalattomat tulkoon häpiään, vaijetkoon helvetissä.","Herra, älä minun anna häpiään tulla; sillä sinua minä avuksi huudan: jumalattomat tulkoon häpiään, vaijetkoon helvetissä."],[31,18,"Tulkoon mykäksi väärät suut, jotka puhuvat vanhurskasta vastaan kovasti ylpeydestä ja ylönkatseesta.","Tulkoon mykäksi väärät suut, jotka puhuvat vanhurskasta vastaan kovasti ylpeydestä ja ylönkatseesta."],[31,19,"Kuinka suuri on sinun hyvyytes, jonka panit tallelle niille, jotka sinua pelkäävät! ja jonka niille osoitat, jotka sinuun uskaltavat, ihmisten lasten edessä!","Kuinka suuri on sinun hyvyytes, jonka panit tallelle niille, jotka sinua pelkäävät! ja jonka niille osoitat, jotka sinuun uskaltavat, ihmisten lasten edessä!"],[31,20,"Sinä kätket heitä tykönäs salaisesti jokaisen haastosta: sinä peität heitä majassas riiteleväisistä kielistä.","Sinä kätket heitä tykönäs salaisesti jokaisen haastosta: sinä peität heitä majassas riiteleväisistä kielistä."],[31,21,"Herra olkoon kiitetty, että hän on minulle osoittanut ihmeellisen hyvyyden, vahvassa kaupungissa.","Herra olkoon kiitetty, että hän on minulle osoittanut ihmeellisen hyvyyden, vahvassa kaupungissa."],[31,22,"Sillä minä sanoin pikaisuudessani: minä olen sinun silmäis edestä sysätty pois: kuitenkin kuulit sinä rukoukseni äänen, koska minä sinun tykös huusin.","Sillä minä sanoin pikaisuudessani: minä olen sinun silmäis edestä sysätty pois: kuitenkin kuulit sinä rukoukseni äänen, koska minä sinun tykös huusin."],[31,23,"Rakastakaat Herraa, kaikki hänen pyhänsä; Herra varjelee uskollisia ja runsaasti kostaa niille, jotka ylpeyttä harjoittelevat.","Rakastakaat Herraa, kaikki hänen pyhänsä; Herra varjelee uskollisia ja runsaasti kostaa niille, jotka ylpeyttä harjoittelevat."],[31,24,"Olkaat hyvässä turvassa, ja hän vahvistaa teidän sydämenne, kaikki jotka Herraa odotatte.","Olkaat hyvässä turvassa, ja hän vahvistaa teidän sydämenne, kaikki jotka Herraa odotatte."],[32,1,"Davidin opetus. Autuas on se, jonka pahat teot ovat annetut anteeksi ja jonka synnit peitetyt ovat.","Davidin opetus. Autuas on se, jonka pahat teot ovat annetut anteeksi ja jonka synnit peitetyt ovat."],[32,2,"Autuas on se ihminen, jolle Herra ei soimaa vääryyttä, jonka hengessä ei vilppiä ole.","Autuas on se ihminen, jolle Herra ei soimaa vääryyttä, jonka hengessä ei vilppiä ole."],[32,3,"Sillä koska minä tahdoin sitä vaieta, musertuivat minun luuni jokapäiväisestä itkustani,","Sillä koska minä tahdoin sitä vaieta, musertuivat minun luuni jokapäiväisestä itkustani,"],[32,4,"Sillä sinun kätes oli yöllä ja päivällä raskas minun päälläni, niin että nesteeni kuivui: niinkuin kesällä kuivuu, Sela!","Sillä sinun kätes oli yöllä ja päivällä raskas minun päälläni, niin että nesteeni kuivui: niinkuin kesällä kuivuu, Sela!"],[32,5,"Sentähden minä tunnustan sinun edessäs syntini, ja en peitä pahoja tekojani. Minä sanoin: minä tunnustan Herralle pahat tekoni; niin sinä annoit anteeksi syntini vääryyden, Sela!","Sentähden minä tunnustan sinun edessäs syntini, ja en peitä pahoja tekojani. Minä sanoin: minä tunnustan Herralle pahat tekoni; niin sinä annoit anteeksi syntini vääryyden, Sela!"],[32,6,"Tämän tähden pitää kaikkein pyhäin sinua rukoileman oikialla ajalla: sentähden kuin suuret vedenpaisumiset tulevat, ei he niihin ulotu.","Tämän tähden pitää kaikkein pyhäin sinua rukoileman oikialla ajalla: sentähden kuin suuret vedenpaisumiset tulevat, ei he niihin ulotu."],[32,7,"Sinä olet minun varjelukseni, kätke minua murheesta, että minä pelastettuna sangen riemuisesti kerskaisin, Sela!","Sinä olet minun varjelukseni, kätke minua murheesta, että minä pelastettuna sangen riemuisesti kerskaisin, Sela!"],[32,8,"Minä neuvon sinua ja osoitan sinulle tien, jotas vaellat: minä johdatan sinun silmilläni.","Minä neuvon sinua ja osoitan sinulle tien, jotas vaellat: minä johdatan sinun silmilläni."],[32,9,"Älkäät olko niinkuin orhiit ja muulit, joilla ei ymmärrystä ole, joille pitää suitset ja ohjat suuhun pantaman, ellei he lähene sinua.","Älkäät olko niinkuin orhiit ja muulit, joilla ei ymmärrystä ole, joille pitää suitset ja ohjat suuhun pantaman, ellei he lähene sinua."],[32,10,"Jumalattomalla on monta vitsausta; mutta joka Herraan toivoo, hänen hyvyys ympäri piirittää.","Jumalattomalla on monta vitsausta; mutta joka Herraan toivoo, hänen hyvyys ympäri piirittää."],[32,11,"Riemuitkaat teitänne Herrassa, ja olkaat iloiset, te vanhurskaat, ja kerskatkaat, kaikki te yksivakaiset.","Riemuitkaat teitänne Herrassa, ja olkaat iloiset, te vanhurskaat, ja kerskatkaat, kaikki te yksivakaiset."],[33,1,"Riemuitkaat, te vanhurskaat, Herrassa; vakain pitää häntä kauniisti kiittämän.","Riemuitkaat, te vanhurskaat, Herrassa; vakain pitää häntä kauniisti kiittämän."],[33,2,"Kiittäkäät Herraa kanteleilla, veisatkaat hänelle kiitosta kymmenkielisellä psaltarilla.","Kiittäkäät Herraa kanteleilla, veisatkaat hänelle kiitosta kymmenkielisellä psaltarilla."],[33,3,"Veisatkaat hänelle uusi virsi: veisatkaat jalosti kielten leikissä, helisemisellä.","Veisatkaat hänelle uusi virsi: veisatkaat jalosti kielten leikissä, helisemisellä."],[33,4,"Sillä Herran sana on totinen, ja mitä hän lupaa, sen hän vahvana pitää.","Sillä Herran sana on totinen, ja mitä hän lupaa, sen hän vahvana pitää."],[33,5,"Hän rakastaa vanhurskautta ja tuomiota; maa on täynnänsä Herran laupiutta.","Hän rakastaa vanhurskautta ja tuomiota; maa on täynnänsä Herran laupiutta."],[33,6,"Herran sanalla ovat taivaat tehdyt, ja kaikki heidän joukkonsa hänen suunsa hengellä.","Herran sanalla ovat taivaat tehdyt, ja kaikki heidän joukkonsa hänen suunsa hengellä."],[33,7,"Hän pitää koossa veden meressä niinkuin roukkiossa, ja kätkee syvyydet.","Hän pitää koossa veden meressä niinkuin roukkiossa, ja kätkee syvyydet."],[33,8,"Peljätköön Herraa kaikki maa; häntä peljätköön kaikki maan piirin asuvaiset.","Peljätköön Herraa kaikki maa; häntä peljätköön kaikki maan piirin asuvaiset."],[33,9,"Sillä koska hän sanoo, niin se tapahtuu; jos hän käskee, niin se on tehty.","Sillä koska hän sanoo, niin se tapahtuu; jos hän käskee, niin se on tehty."],[33,10,"Herra tekee pakanain neuvot tyhjäksi; hän saattaa kansain ajatukset turhaksi.","Herra tekee pakanain neuvot tyhjäksi; hän saattaa kansain ajatukset turhaksi."],[33,11,"Mutta Herran neuvo pysyy ijankaikkisesti, hänen sydämensä ajatukset sukukunnasta sukukuntaan.","Mutta Herran neuvo pysyy ijankaikkisesti, hänen sydämensä ajatukset sukukunnasta sukukuntaan."],[33,12,"Autuas on se kansa, jonka Herra on Jumala, se kansa, jonka hän itsellensä on perinnöksi valinnut.","Autuas on se kansa, jonka Herra on Jumala, se kansa, jonka hän itsellensä on perinnöksi valinnut."],[33,13,"Herra katsoi taivaasta alas, ja näki kaikki ihmisten lapset.","Herra katsoi taivaasta alas, ja näki kaikki ihmisten lapset."],[33,14,"Vahvalta istuimeltansa katsoi hän kaikkia, jotka maan päällä asuvat.","Vahvalta istuimeltansa katsoi hän kaikkia, jotka maan päällä asuvat."],[33,15,"Hän valmistaa kaikkein heidän sydämensä: hän ymmärtää kaikki heidän työnsä.","Hän valmistaa kaikkein heidän sydämensä: hän ymmärtää kaikki heidän työnsä."],[33,16,"Ei kuningasta auta hänen suuri väkensä, eikä sankari vapahdeta suurella voimallansa.","Ei kuningasta auta hänen suuri väkensä, eikä sankari vapahdeta suurella voimallansa."],[33,17,"Orhiit ei myös auta; ja heidän suuri väkevyytensä ei pelasta.","Orhiit ei myös auta; ja heidän suuri väkevyytensä ei pelasta."],[33,18,"Katso, Herran silmät katsovat niitä, jotka häntä pelkäävät, jotka hänen laupiuteensa toivovat,","Katso, Herran silmät katsovat niitä, jotka häntä pelkäävät, jotka hänen laupiuteensa toivovat,"],[33,19,"Että hän pelastais heidän sielunsa kuolemasta, ja elättäis heitä nälän aikana.","Että hän pelastais heidän sielunsa kuolemasta, ja elättäis heitä nälän aikana."],[33,20,"Meidän sielumme odottaa Herraa, joka on meidän apumme ja kilpemme!","Meidän sielumme odottaa Herraa, joka on meidän apumme ja kilpemme!"],[33,21,"Sillä meidän sydämemme iloitsee hänessä, ja me toivomme hänen pyhään nimeensä.","Sillä meidän sydämemme iloitsee hänessä, ja me toivomme hänen pyhään nimeensä."],[33,22,"Olkoon sinun laupiutes, Herra, meidän päällämme, niinkuin me sinuun uskallamme!","Olkoon sinun laupiutes, Herra, meidän päällämme, niinkuin me sinuun uskallamme!"],[34,1,"Davidin Psalmi, koska hän muotonsa muutti Abimelekin edessä, joka hänen ajoi pois tyköänsä ja hän meni pois. (H34:2) Minä kiitän Herraa aina: hänen kiitoksensa on alati minun suussani.","Davidin Psalmi, koska hän muotonsa muutti Abimelekin edessä, joka hänen ajoi pois tyköänsä ja hän meni pois. (H34:2) Minä kiitän Herraa aina: hänen kiitoksensa on alati minun suussani."],[34,2,"Minun sieluni kerskaa Herrassa, että raadolliset sen kuulevat ja iloitsevat.","Minun sieluni kerskaa Herrassa, että raadolliset sen kuulevat ja iloitsevat."],[34,3,"Ylistäkäät Herraa minun kanssani, ja korottakaamme ynnä hänen nimeänsä.","Ylistäkäät Herraa minun kanssani, ja korottakaamme ynnä hänen nimeänsä."],[34,4,"Kuin minä Herraa etsin, kuuli hän minun rukoukseni, ja pelasti minun kaikista vavistuksistani.","Kuin minä Herraa etsin, kuuli hän minun rukoukseni, ja pelasti minun kaikista vavistuksistani."],[34,5,"Jotka häntä katsovat, ne valaistaan: heidän kasvonsa ei tule häpiään.","Jotka häntä katsovat, ne valaistaan: heidän kasvonsa ei tule häpiään."],[34,6,"Kuin raadollinen huusi, kuuli Herra häntä, ja autti hänen kaikista tuskistansa.","Kuin raadollinen huusi, kuuli Herra häntä, ja autti hänen kaikista tuskistansa."],[34,7,"Herran enkeli piirittää niitä, jotka häntä pelkäävät, ja pelastaa heitä.","Herran enkeli piirittää niitä, jotka häntä pelkäävät, ja pelastaa heitä."],[34,8,"Maistakaat ja katsokaat, kuinka Herra on suloinen: autuas on se, joka häneen turvaa.","Maistakaat ja katsokaat, kuinka Herra on suloinen: autuas on se, joka häneen turvaa."],[34,9,"Peljätkään Herraa kaikki hänen pyhänsä; sillä jotka häntä pelkäävät, ei niiltä mitään puutu.","Peljätkään Herraa kaikki hänen pyhänsä; sillä jotka häntä pelkäävät, ei niiltä mitään puutu."],[34,10,"Nuorten jalopeurain pitää tarvitseman ja isooman; mutta jotka Herraa etsivät, ei heiltä mitään hyvää puutu.","Nuorten jalopeurain pitää tarvitseman ja isooman; mutta jotka Herraa etsivät, ei heiltä mitään hyvää puutu."],[34,11,"Tulkaat tänne, lapset, kuulkaat minua: Herran pelvon minä teille opetan.","Tulkaat tänne, lapset, kuulkaat minua: Herran pelvon minä teille opetan."],[34,12,"Kuka on, joka (hyvää) elämää pyytää? ja pitäis mielellänsä hyviä päiviä?","Kuka on, joka (hyvää) elämää pyytää? ja pitäis mielellänsä hyviä päiviä?"],[34,13,"Varjele kieles pahuudesta, ja huules vilppiä puhumasta.","Varjele kieles pahuudesta, ja huules vilppiä puhumasta."],[34,14,"Lakkaa pahasta ja tee hyvää: etsi rauhaa ja noutele häntä.","Lakkaa pahasta ja tee hyvää: etsi rauhaa ja noutele häntä."],[34,15,"Herran silmät katsovat vanhurskaita, ja hänen korvansa heidän huutoansa.","Herran silmät katsovat vanhurskaita, ja hänen korvansa heidän huutoansa."],[34,16,"Mutta Herran kasvot ovat pahointekiöitä vastaan, hukuttamaan maasta heidän muistoansa.","Mutta Herran kasvot ovat pahointekiöitä vastaan, hukuttamaan maasta heidän muistoansa."],[34,17,"Kuin (vanhurskaat) huutavat, niin Herra kuulee, ja pelastaa heitä kaikista heidän tuskistansa.","Kuin (vanhurskaat) huutavat, niin Herra kuulee, ja pelastaa heitä kaikista heidän tuskistansa."],[34,18,"Herra on juuri läsnä niitä, joilla on murheellinen sydän, ja auttaa niitä, joilla on surkia mieli.","Herra on juuri läsnä niitä, joilla on murheellinen sydän, ja auttaa niitä, joilla on surkia mieli."],[34,19,"Vanhurskaalle tapahtuu paljo pahaa; mutta Herra hänen niistä kaikista päästää.","Vanhurskaalle tapahtuu paljo pahaa; mutta Herra hänen niistä kaikista päästää."],[34,20,"Hän kätkee kaikki hänen luunsa, ettei yhtäkään niistä murreta.","Hän kätkee kaikki hänen luunsa, ettei yhtäkään niistä murreta."],[34,21,"Pahuus tappaa jumalattoman, ja jotka vanhurskasta vihaavat, ne hukutetaan.","Pahuus tappaa jumalattoman, ja jotka vanhurskasta vihaavat, ne hukutetaan."],[34,22,"Herra lunastaa palveliansa sielut; ja kaikki, jotka häneen toivovat, ei pidä hukkuman.","Herra lunastaa palveliansa sielut; ja kaikki, jotka häneen toivovat, ei pidä hukkuman."],[35,1,"Davidin Psalmi. Riitele, Herra, riitaveljeini kanssa: sodi vihollisiani vastaan.","Davidin Psalmi. Riitele, Herra, riitaveljeini kanssa: sodi vihollisiani vastaan."],[35,2,"Tempaa kilpi ja keihäs, ja nouse minua auttamaan.","Tempaa kilpi ja keihäs, ja nouse minua auttamaan."],[35,3,"Sivalla ase ja suojele minua sortajiani vastaan: sano sielulleni: minä olen apus.","Sivalla ase ja suojele minua sortajiani vastaan: sano sielulleni: minä olen apus."],[35,4,"Häpiään ja pilkkaan tulkoon kaikki, jotka sieluani väijyvät: palatkoon takaperin ja nauruksi tulkoon, jotka minulle pahaa suovat.","Häpiään ja pilkkaan tulkoon kaikki, jotka sieluani väijyvät: palatkoon takaperin ja nauruksi tulkoon, jotka minulle pahaa suovat."],[35,5,"Olkoon he niinkuin akanat tuulessa; ja Herran enkeli sysätköön heitä pois.","Olkoon he niinkuin akanat tuulessa; ja Herran enkeli sysätköön heitä pois."],[35,6,"Heidän tiensä olkaan pimiä ja niljakas; ja Herran enkeli vainotkoon heitä.","Heidän tiensä olkaan pimiä ja niljakas; ja Herran enkeli vainotkoon heitä."],[35,7,"Sillä he ovat ilman syytä verkkonsa virittäneet minua kadottaaksensa, ja ilman syytä ovat sielulleni kaivaneet haudan.","Sillä he ovat ilman syytä verkkonsa virittäneet minua kadottaaksensa, ja ilman syytä ovat sielulleni kaivaneet haudan."],[35,8,"Tulkoon hänelle vaiva, jota ei hän tiedä, ja verkko, jonka hän viritti, käsittäköön hänen: siihen hän langetkoon.","Tulkoon hänelle vaiva, jota ei hän tiedä, ja verkko, jonka hän viritti, käsittäköön hänen: siihen hän langetkoon."],[35,9,"Mutta minun sieluni iloitkoon Herrassa ja riemuitkaan hänen avustansa.","Mutta minun sieluni iloitkoon Herrassa ja riemuitkaan hänen avustansa."],[35,10,"Kaikki minun luuni sanokaan: Herra, kuka on sinun vertaises? sinä joka päästät nöyrän väkevämmän käsistä, raadollisen ja köyhän raatelialtansa.","Kaikki minun luuni sanokaan: Herra, kuka on sinun vertaises? sinä joka päästät nöyrän väkevämmän käsistä, raadollisen ja köyhän raatelialtansa."],[35,11,"Väärät todistajat astuvat edes, jotka minua niihin soimaavat, joista en mitään tiedä.","Väärät todistajat astuvat edes, jotka minua niihin soimaavat, joista en mitään tiedä."],[35,12,"He tekevät minulle pahaa hyvästä, minulle mielikarvaudeksi.","He tekevät minulle pahaa hyvästä, minulle mielikarvaudeksi."],[35,13,"Mutta minä, kuin he sairastivat, puin säkin päälleni, vaivasin itsiäni paastolla, ja rukoilin sydämestäni;","Mutta minä, kuin he sairastivat, puin säkin päälleni, vaivasin itsiäni paastolla, ja rukoilin sydämestäni;"],[35,14,"Minä käytin itseni kuin he olisivat olleet minun ystäväni ja veljeni: niinkuin se joka äitiänsä murehtii, kävin minä kumarruksissa murhevaatteissa.","Minä käytin itseni kuin he olisivat olleet minun ystäväni ja veljeni: niinkuin se joka äitiänsä murehtii, kävin minä kumarruksissa murhevaatteissa."],[35,15,"Mutta he iloitsevat minun vahingostani ja kokoontuvat: ontuvat myös kokoovat heitänsä havaitsematta minua vastaan, he repivät ja ei lakkaa.","Mutta he iloitsevat minun vahingostani ja kokoontuvat: ontuvat myös kokoovat heitänsä havaitsematta minua vastaan, he repivät ja ei lakkaa."],[35,16,"Ulkokullattuin seassa, jotka leipäkyrsänkin tähden pilkkaavat, kiristävät he hampaitansa minun päälleni.","Ulkokullattuin seassa, jotka leipäkyrsänkin tähden pilkkaavat, kiristävät he hampaitansa minun päälleni."],[35,17,"Herra, kuinka kauvan sinä tätä katselet? Päästä siis sieluni heidän hävityksestänsä, ja yksinäiseni nuorista jalopeuroista.","Herra, kuinka kauvan sinä tätä katselet? Päästä siis sieluni heidän hävityksestänsä, ja yksinäiseni nuorista jalopeuroista."],[35,18,"Minä kiitän sinua suuressa seurakunnassa; paljon kansan keskellä minä sinua ylistän.","Minä kiitän sinua suuressa seurakunnassa; paljon kansan keskellä minä sinua ylistän."],[35,19,"Älä salli niiden iloita minusta, jotka syyttömästi minun viholliseni ovat, eli silmää iskeä, jotka minua ilman syytä vihaavat.","Älä salli niiden iloita minusta, jotka syyttömästi minun viholliseni ovat, eli silmää iskeä, jotka minua ilman syytä vihaavat."],[35,20,"Sillä ei he puhu ystävällisesti, vaan etsivät vääriä syitä hiljaisia vastaan maan päällä,","Sillä ei he puhu ystävällisesti, vaan etsivät vääriä syitä hiljaisia vastaan maan päällä,"],[35,21,"Ja levittävät kitansa avaralta minua vastaan, ja sanovat: niin, niin: sen me mielellämme näemme.","Ja levittävät kitansa avaralta minua vastaan, ja sanovat: niin, niin: sen me mielellämme näemme."],[35,22,"Herra, sinä sen myös näet, älä siis vaiti ole: Herra, älä kaukana ole minusta.","Herra, sinä sen myös näet, älä siis vaiti ole: Herra, älä kaukana ole minusta."],[35,23,"Herää ja nouse katsomaan minun oikeuttani ja asiatani, minun Jumalani ja Herrani.","Herää ja nouse katsomaan minun oikeuttani ja asiatani, minun Jumalani ja Herrani."],[35,24,"Herra minun Jumalani, tuomitse minua vanhurskautes jälkeen, ettei he riemuitsisi minusta.","Herra minun Jumalani, tuomitse minua vanhurskautes jälkeen, ettei he riemuitsisi minusta."],[35,25,"Älä salli heidän sydämissänsä sanoa: niin, niin me tahdomme; ja älä anna heidän sanoa: me olemme hänen nielleet.","Älä salli heidän sydämissänsä sanoa: niin, niin me tahdomme; ja älä anna heidän sanoa: me olemme hänen nielleet."],[35,26,"Häväistäköön ja nauruksi joutukoon kaikki, jotka onnettomuudestani iloitsevat: puetettakoon häpiällä ja pilkalla, jotka itsiänsä minusta kerskaavat.","Häväistäköön ja nauruksi joutukoon kaikki, jotka onnettomuudestani iloitsevat: puetettakoon häpiällä ja pilkalla, jotka itsiänsä minusta kerskaavat."],[35,27,"Iloitkaan ja riemuitkaan, jotka minun vanhurskauttani rakastavat, ja sanokaan aina: Herra olkoon suuresti kiitetty, joka suo palveliallensa rauhan.","Iloitkaan ja riemuitkaan, jotka minun vanhurskauttani rakastavat, ja sanokaan aina: Herra olkoon suuresti kiitetty, joka suo palveliallensa rauhan."],[35,28,"Ja minun kieleni puhuu sinun vanhurskauttas, ja kiittää sinua joka päivä.","Ja minun kieleni puhuu sinun vanhurskauttas, ja kiittää sinua joka päivä."],[36,1,"Davidin, Herran palvelian Psalmi, edelläveisaajalle. (H36:2) Se on sydämestäni sanottu jumalattomain menosta: ei he ensinkään Jumalaa pelkää.","Davidin, Herran palvelian Psalmi, edelläveisaajalle. (H36:2) Se on sydämestäni sanottu jumalattomain menosta: ei he ensinkään Jumalaa pelkää."],[36,2,"Sillä hän suosittelee itsiänsä silmäinsä edessä, niinkauvan kuin hän löytää pahuutensa, saattaaksensa vihaa matkaan.","Sillä hän suosittelee itsiänsä silmäinsä edessä, niinkauvan kuin hän löytää pahuutensa, saattaaksensa vihaa matkaan."],[36,3,"Hänen suunsa sanat ovat vääryys ja petos; ei hän tahdo enempää ymmärtää, että hän jotakin hyvää tekis,","Hänen suunsa sanat ovat vääryys ja petos; ei hän tahdo enempää ymmärtää, että hän jotakin hyvää tekis,"],[36,4,"Mutta ajattelee vuoteessansa vahinkoa, ja pysyy vahvasti pahalla tiellä; ja ei he mitään pahaa hylkää.","Mutta ajattelee vuoteessansa vahinkoa, ja pysyy vahvasti pahalla tiellä; ja ei he mitään pahaa hylkää."],[36,5,"Herra, sinun laupiutes ulottuu niin leviältä kuin taivas on, ja sinun totuutes niin avaralta kuin pilvet juoksevat.","Herra, sinun laupiutes ulottuu niin leviältä kuin taivas on, ja sinun totuutes niin avaralta kuin pilvet juoksevat."],[36,6,"Sinun vanhurskautes on niinkuin Jumalan vuoret, ja sinun oikeutes niinkuin suuri syvyys: Herra, sinä autat sekä ihmiset että eläimet.","Sinun vanhurskautes on niinkuin Jumalan vuoret, ja sinun oikeutes niinkuin suuri syvyys: Herra, sinä autat sekä ihmiset että eläimet."],[36,7,"Kuinka kallis on sinun hyvyytes, Jumala! että ihmisten lapset sinun siipeis varjon alle uskaltavat.","Kuinka kallis on sinun hyvyytes, Jumala! että ihmisten lapset sinun siipeis varjon alle uskaltavat."],[36,8,"He juopuvat sinun huonees runsaasta tavarasta, ja sinä juotat heitä hekumallas niinkuin virralla.","He juopuvat sinun huonees runsaasta tavarasta, ja sinä juotat heitä hekumallas niinkuin virralla."],[36,9,"Sillä sinun tykönäs on elävä lähde, ja sinun valkeudessas me näemme valkeuden.","Sillä sinun tykönäs on elävä lähde, ja sinun valkeudessas me näemme valkeuden."],[36,10,"Levitä laupiutes niille, jotka sinun tuntevat, ja sinun vanhurskautes toimellisille.","Levitä laupiutes niille, jotka sinun tuntevat, ja sinun vanhurskautes toimellisille."],[36,11,"Älä salli minua tallattaa ylpeiltä; ja jumalattomain käsi älköön minua kukistako.","Älä salli minua tallattaa ylpeiltä; ja jumalattomain käsi älköön minua kukistako."],[36,12,"Vaan anna pahointekiät siihen langeta, että he syöstäisiin pois, ja ei seisoalla pysyisi.","Vaan anna pahointekiät siihen langeta, että he syöstäisiin pois, ja ei seisoalla pysyisi."],[37,1,"Davidin Psalmi. Älä vihastu pahain tähden, ja älä kadehdi pahantekiöitä.","Davidin Psalmi. Älä vihastu pahain tähden, ja älä kadehdi pahantekiöitä."],[37,2,"Sillä niinkuin heinä he pian hakataan pois, ja lakastuvat niinkuin vihoittava ruoho.","Sillä niinkuin heinä he pian hakataan pois, ja lakastuvat niinkuin vihoittava ruoho."],[37,3,"Toivo Herraan ja tee hyvää: asu maassa ja elätä itses vakuudella.","Toivo Herraan ja tee hyvää: asu maassa ja elätä itses vakuudella."],[37,4,"Iloitse Herrassa, ja hän antaa sinulle, mitä sinun sydämes halajaa.","Iloitse Herrassa, ja hän antaa sinulle, mitä sinun sydämes halajaa."],[37,5,"Anna ties Herran haltuun, ja toivo hänen päällensä; kyllä hän sen tekee.","Anna ties Herran haltuun, ja toivo hänen päällensä; kyllä hän sen tekee."],[37,6,"Ja hän tuo edes vanhurskautes niinkuin valkeuden, ja oikeutes niinkuin puolipäivän.","Ja hän tuo edes vanhurskautes niinkuin valkeuden, ja oikeutes niinkuin puolipäivän."],[37,7,"Tyydy Herraan, ja odota häntä: älä kiivoittele sitä, jonka tie menestyy ja sitä ihmistä, joka vääryyttä tekee.","Tyydy Herraan, ja odota häntä: älä kiivoittele sitä, jonka tie menestyy ja sitä ihmistä, joka vääryyttä tekee."],[37,8,"Lakkaa vihasta ja hylkää tuimuus: älä niin vihastu, ettäs itsekin pahaa teet.","Lakkaa vihasta ja hylkää tuimuus: älä niin vihastu, ettäs itsekin pahaa teet."],[37,9,"Sillä pahat hävitetään; mutta Herraa odottavaiset perivät maan.","Sillä pahat hävitetään; mutta Herraa odottavaiset perivät maan."],[37,10,"Vielä vähä hetki on, niin ei jumalatoin olekaan; ja kuin sinä katsot hänen siaansa, niin hän on poissa.","Vielä vähä hetki on, niin ei jumalatoin olekaan; ja kuin sinä katsot hänen siaansa, niin hän on poissa."],[37,11,"Mutta siviät perivät maan, ja iloitsevat suuressa rauhassa.","Mutta siviät perivät maan, ja iloitsevat suuressa rauhassa."],[37,12,"Jumalatoin uhkaa vanhurskasta, ja kiristelee hampaitansa hänen päällensä.","Jumalatoin uhkaa vanhurskasta, ja kiristelee hampaitansa hänen päällensä."],[37,13,"Mutta Herra nauraa häntä; sillä hän näkee hänen päivänsä joutuvan.","Mutta Herra nauraa häntä; sillä hän näkee hänen päivänsä joutuvan."],[37,14,"Jumalattomat vetävät miekkansa ja jännittävät joutsensa, kukistaaksensa raadollista ja köyhää, ja teurastaaksensa hurskaita heidän teissänsä.","Jumalattomat vetävät miekkansa ja jännittävät joutsensa, kukistaaksensa raadollista ja köyhää, ja teurastaaksensa hurskaita heidän teissänsä."],[37,15,"Mutta heidän miekkansa pitää käymän heidän sydämeensä; ja heidän joutsensa pitää särkymän.","Mutta heidän miekkansa pitää käymän heidän sydämeensä; ja heidän joutsensa pitää särkymän."],[37,16,"Se vähä, mikä vanhurskaalla on, on parempi kuin monen jumalattoman suuret tavarat.","Se vähä, mikä vanhurskaalla on, on parempi kuin monen jumalattoman suuret tavarat."],[37,17,"Sillä jumalattoman käsivarsi pitää rikottaman; mutta Herra vahvistaa vanhurskaat.","Sillä jumalattoman käsivarsi pitää rikottaman; mutta Herra vahvistaa vanhurskaat."],[37,18,"Herra tietää hurskasten päivät, ja heidän perimisensä pysyy ijankaikkisesti.","Herra tietää hurskasten päivät, ja heidän perimisensä pysyy ijankaikkisesti."],[37,19,"Ei he tule häpiään pahalla ajalla; ja nälkävuosina pitää heillä kyllä oleman.","Ei he tule häpiään pahalla ajalla; ja nälkävuosina pitää heillä kyllä oleman."],[37,20,"Sillä jumalattomat hukkuvat, ja Herran viholliset, ehkä he olisivat niinkuin ihana niitty, niin heidän pitää kuitenkin niinkuin savu katooman.","Sillä jumalattomat hukkuvat, ja Herran viholliset, ehkä he olisivat niinkuin ihana niitty, niin heidän pitää kuitenkin niinkuin savu katooman."],[37,21,"Jumalatoin ottaa lainan ja ei maksa; mutta hurskas on laupias ja runsas.","Jumalatoin ottaa lainan ja ei maksa; mutta hurskas on laupias ja runsas."],[37,22,"Sillä hänen siunattunsa perivät maan; mutta hänen kirottunsa pitää hävitettämän.","Sillä hänen siunattunsa perivät maan; mutta hänen kirottunsa pitää hävitettämän."],[37,23,"Herralta senkaltaisen miehen vaellus hallitaan; ja hänen tiensä kelpaa hänelle.","Herralta senkaltaisen miehen vaellus hallitaan; ja hänen tiensä kelpaa hänelle."],[37,24,"Jos hän lankee, niin ei häntä hyljätä; sillä Herra tukee hänen kätensä.","Jos hän lankee, niin ei häntä hyljätä; sillä Herra tukee hänen kätensä."],[37,25,"Minä olin nuori, ja vanhennuin, ja en ikänä nähnyt vanhurskasta hyljätyksi, enkä hänen siemenensä kerjäävän leipää.","Minä olin nuori, ja vanhennuin, ja en ikänä nähnyt vanhurskasta hyljätyksi, enkä hänen siemenensä kerjäävän leipää."],[37,26,"Hän on aina laupias, ja lainaa mielellänsä; ja hänen siemenensä on siunattu.","Hän on aina laupias, ja lainaa mielellänsä; ja hänen siemenensä on siunattu."],[37,27,"Vältä pahaa, ja tee hyvää, ja pysy ijankaikkisesti.","Vältä pahaa, ja tee hyvää, ja pysy ijankaikkisesti."],[37,28,"Sillä Herra rakastaa oikeutta, ja ei hylkää pyhiänsä: ne kätketään ijankaikkisesti; mutta jumalattomain siemen pitää hävitettämän.","Sillä Herra rakastaa oikeutta, ja ei hylkää pyhiänsä: ne kätketään ijankaikkisesti; mutta jumalattomain siemen pitää hävitettämän."],[37,29,"Hurskaat perivät maan, ja asuvat siinä ijankaikkisesti.","Hurskaat perivät maan, ja asuvat siinä ijankaikkisesti."],[37,30,"Vanhurskaan suu puhuu viisautta, ja hänen kielensä opettaa oikeutta.","Vanhurskaan suu puhuu viisautta, ja hänen kielensä opettaa oikeutta."],[37,31,"Hänen Jumalansa laki on hänen sydämessänsä; ja ei hänen askeleensa livisty.","Hänen Jumalansa laki on hänen sydämessänsä; ja ei hänen askeleensa livisty."],[37,32,"Jumalatoin väijyy vanhurskasta, ja etsii häntä tappaaksensa;","Jumalatoin väijyy vanhurskasta, ja etsii häntä tappaaksensa;"],[37,33,"Mutta ei Herra jätä häntä hänen käsiinsä, ja ei tuomitse häntä, koska hän tuomitaan.","Mutta ei Herra jätä häntä hänen käsiinsä, ja ei tuomitse häntä, koska hän tuomitaan."],[37,34,"Odota Herraa, ja kätke hänen tiensä, niin hän sinun korottaa, ettäs perit maan: ja sinä saat nähdä jumalattomat hävitettävän.","Odota Herraa, ja kätke hänen tiensä, niin hän sinun korottaa, ettäs perit maan: ja sinä saat nähdä jumalattomat hävitettävän."],[37,35,"Minä näin jumalattoman, sangen jalon ja valtiaan, joka levitti itsensä, ja vihotti niinkuin viheriäinen laakeripuu.","Minä näin jumalattoman, sangen jalon ja valtiaan, joka levitti itsensä, ja vihotti niinkuin viheriäinen laakeripuu."],[37,36,"Ja hän meni pois, ja katso ei hän enää ollut; ja minä kysyin häntä, ja ei häntä mistään löydetty.","Ja hän meni pois, ja katso ei hän enää ollut; ja minä kysyin häntä, ja ei häntä mistään löydetty."],[37,37,"Ole viatoin, ja pidä sinus oikein; sillä senkaltaiset viimein menestyvät;","Ole viatoin, ja pidä sinus oikein; sillä senkaltaiset viimein menestyvät;"],[37,38,"Mutta väärät pitää ynnä hukkuman, ja jumalattomat pitää viimein hävitettämän.","Mutta väärät pitää ynnä hukkuman, ja jumalattomat pitää viimein hävitettämän."],[37,39,"Mutta Herra auttaa vanhurskaita: hän on heidän väkevyytensä tuskan ajalla.","Mutta Herra auttaa vanhurskaita: hän on heidän väkevyytensä tuskan ajalla."],[37,40,"Ja Herra auttaa heitä ja päästää heitä: hän pelastaa heitä jumalattomista ja vapahtaa heitä; sillä he uskalsivat häneen.","Ja Herra auttaa heitä ja päästää heitä: hän pelastaa heitä jumalattomista ja vapahtaa heitä; sillä he uskalsivat häneen."],[38,1,"Davidin Psalmi muistoksi. (H38:2) Herra, älä rankaise minua vihassas, ja älä kurita minua hirmuisuudessas!","Davidin Psalmi muistoksi. (H38:2) Herra, älä rankaise minua vihassas, ja älä kurita minua hirmuisuudessas!"],[38,2,"Sillä sinun nuoles ovat minuun kiinnitetyt, ja sinun kätes painaa minua.","Sillä sinun nuoles ovat minuun kiinnitetyt, ja sinun kätes painaa minua."],[38,3,"Ei ole terveys minun ruumiissani, sinun uhkauksestas: ja ei ole rauhaa minun luissani, minun synteini tähden.","Ei ole terveys minun ruumiissani, sinun uhkauksestas: ja ei ole rauhaa minun luissani, minun synteini tähden."],[38,4,"Sillä minun syntini käyvät pääni ylitse; niinkuin raskas kuorma ovat he ylen raskaaksi tulleet.","Sillä minun syntini käyvät pääni ylitse; niinkuin raskas kuorma ovat he ylen raskaaksi tulleet."],[38,5,"Minun haavani haisevat ja mätänevät minun hulluuteni tähden.","Minun haavani haisevat ja mätänevät minun hulluuteni tähden."],[38,6,"Minä käyn kymärässä ja kumarruksissa: yli päivää minä käyn murheissani.","Minä käyn kymärässä ja kumarruksissa: yli päivää minä käyn murheissani."],[38,7,"Sillä minun kupeeni peräti kuivettuvat, ja ei ole mitään tervettä minun ruumiissani.","Sillä minun kupeeni peräti kuivettuvat, ja ei ole mitään tervettä minun ruumiissani."],[38,8,"Minä olen ylen paljon runneltu ja lyöty rikki: minä myrisen minun sydämeni kivusta.","Minä olen ylen paljon runneltu ja lyöty rikki: minä myrisen minun sydämeni kivusta."],[38,9,"Herra, sinun edessäs on kaikki minun haluni, ja minun huokaukseni ei ole sinulta salattu.","Herra, sinun edessäs on kaikki minun haluni, ja minun huokaukseni ei ole sinulta salattu."],[38,10,"Minun sydämeni värisee, minun voimani on minusta luopunut, ja minun silmäini valkeus ei ole minun tykönäni.","Minun sydämeni värisee, minun voimani on minusta luopunut, ja minun silmäini valkeus ei ole minun tykönäni."],[38,11,"Minun ystäväni ja lähimmäiseni ovat kohdastansa minua vastaan, ja minun omaiseni seisovat kaukana.","Minun ystäväni ja lähimmäiseni ovat kohdastansa minua vastaan, ja minun omaiseni seisovat kaukana."],[38,12,"Jotka minun sieluani etsivät, ne virittelevät paulat minun eteeni, ja jotka minulle pahaa suovat, ne puhuvat sulaa pahuutta, ja petosta joka päivä ajattelevat.","Jotka minun sieluani etsivät, ne virittelevät paulat minun eteeni, ja jotka minulle pahaa suovat, ne puhuvat sulaa pahuutta, ja petosta joka päivä ajattelevat."],[38,13,"Mutta minun täytyy olla niinkuin kuuron, ja ei mitään kuuleman, ja niinkuin mykän, joka ei avaja suutansa,","Mutta minun täytyy olla niinkuin kuuron, ja ei mitään kuuleman, ja niinkuin mykän, joka ei avaja suutansa,"],[38,14,"Ja minun täytyy olla niinkuin se, joka ei mitään kuule, ja jonka suussa ei ole vastausta.","Ja minun täytyy olla niinkuin se, joka ei mitään kuule, ja jonka suussa ei ole vastausta."],[38,15,"Mutta minä odotan sinua, Herra; sinä, Herra, minun Jumalani, kuultelet minua.","Mutta minä odotan sinua, Herra; sinä, Herra, minun Jumalani, kuultelet minua."],[38,16,"Sillä minä ajattelen, ettei heidän suinkaan pidä minusta iloitseman: jos minun jalkani kompastuis, niin he kerskaisivat sangen paljon minusta.","Sillä minä ajattelen, ettei heidän suinkaan pidä minusta iloitseman: jos minun jalkani kompastuis, niin he kerskaisivat sangen paljon minusta."],[38,17,"Sillä minä olen tehty kärsimään, ja minun kipuni on alati minun edessäni.","Sillä minä olen tehty kärsimään, ja minun kipuni on alati minun edessäni."],[38,18,"Sillä minä julistan pahan tekoni, ja murehdin syntini tähden.","Sillä minä julistan pahan tekoni, ja murehdin syntini tähden."],[38,19,"Mutta minun viholliseni elävät ja ovat väkevät: ne ovat suuret, jotka minua syyttömästi vihaavat.","Mutta minun viholliseni elävät ja ovat väkevät: ne ovat suuret, jotka minua syyttömästi vihaavat."],[38,20,"Ja ne, jotka minulle maksavat pahalla hyvän, asettavat heitänsä minua vastaan, että minä hyvää noudatan.","Ja ne, jotka minulle maksavat pahalla hyvän, asettavat heitänsä minua vastaan, että minä hyvää noudatan."],[38,21,"Älä hylkää minua, Herra: minun Jumalani, älä ole kaukana minusta!","Älä hylkää minua, Herra: minun Jumalani, älä ole kaukana minusta!"],[38,22,"Riennä minua auttamaan, Herra, minun autuuteni!","Riennä minua auttamaan, Herra, minun autuuteni!"],[39,1,"Davidin Psalmi, Jedutunilta, edelläveisaajalle. (H39:2) Minä olen sanonut: minä tahdon pitää vaarin teistäni, etten minä tekisi syntiä kielelläni: minä hallitsen suuni niinkuin suitsilla, niin kauvan kuin minä näen jumalattoman edessäni.","Davidin Psalmi, Jedutunilta, edelläveisaajalle. (H39:2) Minä olen sanonut: minä tahdon pitää vaarin teistäni, etten minä tekisi syntiä kielelläni: minä hallitsen suuni niinkuin suitsilla, niin kauvan kuin minä näen jumalattoman edessäni."],[39,2,"Minä tulin mykäksi, vaikenemisella vaikenin hyvästä; mutta minun murheeni lisääntyi.","Minä tulin mykäksi, vaikenemisella vaikenin hyvästä; mutta minun murheeni lisääntyi."],[39,3,"Minun sydämeni on palava minussa, ja kuin minä sitä ajattelen, niin minä sytyn: minä puhun kielelläni.","Minun sydämeni on palava minussa, ja kuin minä sitä ajattelen, niin minä sytyn: minä puhun kielelläni."],[39,4,"Herra, opeta minua ajattelemaan minun loppuani, ja mikä mitta minun elämälläni on, tietääkseni, että minä erkanen täältä.","Herra, opeta minua ajattelemaan minun loppuani, ja mikä mitta minun elämälläni on, tietääkseni, että minä erkanen täältä."],[39,5,"Katso, minun päiväni ovat kämmenen leveys tykönäs, ja minun elämäni on niinkuin ei mitään sinun edessäs: kuinka aivan turhat ovat kaikki ihmiset, jotka kuitenkin niin suruttomasti elävät Sela!","Katso, minun päiväni ovat kämmenen leveys tykönäs, ja minun elämäni on niinkuin ei mitään sinun edessäs: kuinka aivan turhat ovat kaikki ihmiset, jotka kuitenkin niin suruttomasti elävät Sela!"],[39,6,"Vaan he menevät pois niinkuin varjo, ja tekevät itsellensä hukkaan suuren murheen: he kokoovat ja ei tiedä, kuka sen saa.","Vaan he menevät pois niinkuin varjo, ja tekevät itsellensä hukkaan suuren murheen: he kokoovat ja ei tiedä, kuka sen saa."],[39,7,"Ja nyt Herra, mihinkä minä luotan? sinuun minä toivon.","Ja nyt Herra, mihinkä minä luotan? sinuun minä toivon."],[39,8,"Vapahda minua kaikista synneistäni, ja älä anna minun tulla hulluin pilkaksi.","Vapahda minua kaikista synneistäni, ja älä anna minun tulla hulluin pilkaksi."],[39,9,"Minä vaikenen ja en avaa suutani; kyllä sinä sen teet.","Minä vaikenen ja en avaa suutani; kyllä sinä sen teet."],[39,10,"Käännä sinun rangaistukses pois minusta; sillä minä olen nääntynyt sinun kätes pieksämisestä.","Käännä sinun rangaistukses pois minusta; sillä minä olen nääntynyt sinun kätes pieksämisestä."],[39,11,"Koskas jonkun rankaiset synnin tähden, niin hänen kaunistuksensa kulutetaan niinkuin koilta; tosin aivan turhat ovat kaikki ihmiset, Sela!","Koskas jonkun rankaiset synnin tähden, niin hänen kaunistuksensa kulutetaan niinkuin koilta; tosin aivan turhat ovat kaikki ihmiset, Sela!"],[39,12,"Kuule minun rukoukseni, Herra, ja ota minun huutoni korviis, ja älä vaikene minun kyynelteni tähden; sillä minä olen muukalainen sinun tykönäs ja vieras, niinkuin kaikki minun isäni.","Kuule minun rukoukseni, Herra, ja ota minun huutoni korviis, ja älä vaikene minun kyynelteni tähden; sillä minä olen muukalainen sinun tykönäs ja vieras, niinkuin kaikki minun isäni."],[39,13,"Luovu minusta, että minä virkoaisin, ennenkuin minä menen pois, ja en silleen tässä ole.","Luovu minusta, että minä virkoaisin, ennenkuin minä menen pois, ja en silleen tässä ole."],[40,1,"Davidin Psalmi, edelläveisaajalle. (H40:2) Minä hartaasti odotin Herraa: ja hän kallisti itsensä minun tyköni, ja hän kuuli minun huutoni.","Davidin Psalmi, edelläveisaajalle. (H40:2) Minä hartaasti odotin Herraa: ja hän kallisti itsensä minun tyköni, ja hän kuuli minun huutoni."],[40,2,"Ja hän veti minun ylös hirmuisesta haudasta ja sontaisesta loasta, ja asetti minun jalkani kalliolle, ja hallitsi minun käymiseni.","Ja hän veti minun ylös hirmuisesta haudasta ja sontaisesta loasta, ja asetti minun jalkani kalliolle, ja hallitsi minun käymiseni."],[40,3,"Ja hän antoi minun suuhuni uuden veisun, kiittämään meidän Jumalaamme. Sen pitää monen näkemän, ja pelkäämän Herraa, ja toivoman häneen.","Ja hän antoi minun suuhuni uuden veisun, kiittämään meidän Jumalaamme. Sen pitää monen näkemän, ja pelkäämän Herraa, ja toivoman häneen."],[40,4,"Autuas on se ihminen, joka panee uskalluksensa Herraan, ja ei käänny ylpeiden tykö ja niiden, jotka valheella vaeltavat.","Autuas on se ihminen, joka panee uskalluksensa Herraan, ja ei käänny ylpeiden tykö ja niiden, jotka valheella vaeltavat."],[40,5,"Herra, minun Jumalani, suuret ovat sinun ihmees ja ajatukses, jotka sinä meille osoitat: ei ole mitään sinun vertaas; minä ilmoitan niitä ja sanon, vaikka ne ovat epälukuiset.","Herra, minun Jumalani, suuret ovat sinun ihmees ja ajatukses, jotka sinä meille osoitat: ei ole mitään sinun vertaas; minä ilmoitan niitä ja sanon, vaikka ne ovat epälukuiset."],[40,6,"Uhri ja ruokauhri ei sinulle kelpaa, vaan korvat sinä minulle avasit: et sinä tahdo polttouhria eli syntiuhria.","Uhri ja ruokauhri ei sinulle kelpaa, vaan korvat sinä minulle avasit: et sinä tahdo polttouhria eli syntiuhria."],[40,7,"Silloin minä sanoin: katso, minä tulen: Raamatussa on minusta kirjoitettu.","Silloin minä sanoin: katso, minä tulen: Raamatussa on minusta kirjoitettu."],[40,8,"Sinun tahtos, minun Jumalani, teen minä mielelläni; ja sinun lakis on minun sydämessäni.","Sinun tahtos, minun Jumalani, teen minä mielelläni; ja sinun lakis on minun sydämessäni."],[40,9,"Minä saarnaan sinun vanhurskauttas suuressa seurakunnassa: katso, en minä anna tukita suutani; Herra, sinä sen tiedät.","Minä saarnaan sinun vanhurskauttas suuressa seurakunnassa: katso, en minä anna tukita suutani; Herra, sinä sen tiedät."],[40,10,"En minä salaa vanhurskauttas sydämessäni: minä puhun sinun totuudestas ja autuudestas: en minä peitä laupiuttas ja vakuuttas suuressa seurakunnassa.","En minä salaa vanhurskauttas sydämessäni: minä puhun sinun totuudestas ja autuudestas: en minä peitä laupiuttas ja vakuuttas suuressa seurakunnassa."],[40,11,"Mutta sinä, Herra, älä käännä laupiuttas minusta pois: sinun laupiutes ja vakuutes aina minua varjelkoon.","Mutta sinä, Herra, älä käännä laupiuttas minusta pois: sinun laupiutes ja vakuutes aina minua varjelkoon."],[40,12,"Sillä lukemattomat vaivat ovat minun piirittäneet: minun syntini ovat minun ottaneet kiinni, niin etten minä nähdä taida: ne ovat usiammat kuin hiukset päässäni, ja minun sydämeni on minussa vaipunut.","Sillä lukemattomat vaivat ovat minun piirittäneet: minun syntini ovat minun ottaneet kiinni, niin etten minä nähdä taida: ne ovat usiammat kuin hiukset päässäni, ja minun sydämeni on minussa vaipunut."],[40,13,"Kelvatkoon se sinulle, Herra, ettäs minun vapahdat: riennä, Herra, minua auttamaan!","Kelvatkoon se sinulle, Herra, ettäs minun vapahdat: riennä, Herra, minua auttamaan!"],[40,14,"Hävetköön ja kaikki pilkaksi tulkoon, jotka minun sieluani väijyvät hukataksensa sitä: palatkoon takaperin ja häpiään tulkoon, jotka minulle pahaa suovat.","Hävetköön ja kaikki pilkaksi tulkoon, jotka minun sieluani väijyvät hukataksensa sitä: palatkoon takaperin ja häpiään tulkoon, jotka minulle pahaa suovat."],[40,15,"Hämmästyköön häpiässänsä, jotka minulle sanovat: niin, niin.","Hämmästyköön häpiässänsä, jotka minulle sanovat: niin, niin."],[40,16,"Iloitkaan ja riemuitkaan kaikki sinussa, jotka sinua etsivät, ja jotka sinun autuuttas rakastavat, sanokaan aina: Herra olkoon korkiasti ylistetty!","Iloitkaan ja riemuitkaan kaikki sinussa, jotka sinua etsivät, ja jotka sinun autuuttas rakastavat, sanokaan aina: Herra olkoon korkiasti ylistetty!"],[40,17,"Minä olen köyhä ja vaivainen, mutta Herra pitää minusta murheen: sinä olet minun auttajani ja vapahtajani: minun Jumalani, älä viivy.","Minä olen köyhä ja vaivainen, mutta Herra pitää minusta murheen: sinä olet minun auttajani ja vapahtajani: minun Jumalani, älä viivy."],[41,1,"Davidin Psalmi, edelläveisaajalle. (H41:2) Autuas on, joka köyhää holhoo: häntä Herra auttaa pahana päivänä.","Davidin Psalmi, edelläveisaajalle. (H41:2) Autuas on, joka köyhää holhoo: häntä Herra auttaa pahana päivänä."],[41,2,"Herra kätkee hänen ja pitää hänen elävänä, että hän menestyy maan päällä, ja ei hylkää häntä vihollistensa tahtoon.","Herra kätkee hänen ja pitää hänen elävänä, että hän menestyy maan päällä, ja ei hylkää häntä vihollistensa tahtoon."],[41,3,"Herra virvoittaa häntä tautivuoteessansa: sinä autat hänen kaikesta hänen sairaudestansa.","Herra virvoittaa häntä tautivuoteessansa: sinä autat hänen kaikesta hänen sairaudestansa."],[41,4,"Minä sanoin: Herra, ole minulle armollinen, paranna minun sieluni; sillä minä tein syntiä sinua vastaan.","Minä sanoin: Herra, ole minulle armollinen, paranna minun sieluni; sillä minä tein syntiä sinua vastaan."],[41,5,"Minun viholliseni puhuivat pahaa minua vastaan: koska hän kuollee ja hänen nimensä kadonnee?","Minun viholliseni puhuivat pahaa minua vastaan: koska hän kuollee ja hänen nimensä kadonnee?"],[41,6,"Ja kuin he tulevat katselemaan, niin he puhuvat valhetta: heidän sydämensä kokoo vääryyttä; niin he menevät pois ja sitä panettelevat.","Ja kuin he tulevat katselemaan, niin he puhuvat valhetta: heidän sydämensä kokoo vääryyttä; niin he menevät pois ja sitä panettelevat."],[41,7,"Kaikki, jotka minua vihaavat, kuiskuttelevat keskenänsä minua vastaan, ja ajattelevat pahaa minua vastaan.","Kaikki, jotka minua vihaavat, kuiskuttelevat keskenänsä minua vastaan, ja ajattelevat pahaa minua vastaan."],[41,8,"Paha asia on hänen päällensä tullut; ja koska hän makaa, niin ei hän nouse jälleen.","Paha asia on hänen päällensä tullut; ja koska hän makaa, niin ei hän nouse jälleen."],[41,9,"Niin myös minun ystäväni, johon minä uskalsin, joka sai minun leipääni, se tallasi minun jalkainsa alle.","Niin myös minun ystäväni, johon minä uskalsin, joka sai minun leipääni, se tallasi minun jalkainsa alle."],[41,10,"Mutta sinä, Herra, ole minulle armollinen ja auta minua, niin minä sen heille kostan.","Mutta sinä, Herra, ole minulle armollinen ja auta minua, niin minä sen heille kostan."],[41,11,"Siitä minä ymmärrän, ettäs suot minulle hyvää, ettei viholliseni saa kerskata minusta.","Siitä minä ymmärrän, ettäs suot minulle hyvää, ettei viholliseni saa kerskata minusta."],[41,12,"Mutta minua sinä holhot viattomuuteni tähden, ja asetat minun kasvois eteen ijankaikkisesti.","Mutta minua sinä holhot viattomuuteni tähden, ja asetat minun kasvois eteen ijankaikkisesti."],[41,13,"Kiitetty olkoon Herra Israelin Jumala, ijankaikkisesta ijankaikkiseen! Amen, amen.","Kiitetty olkoon Herra Israelin Jumala, ijankaikkisesta ijankaikkiseen! Amen, amen."],[42,1,"Koran lasten opetus, edelläveisaajalle. (H42:2) Niinkuin peura himoitsee tuoretta vettä, niin minun sieluni himoitsee sinua, Jumala.","Koran lasten opetus, edelläveisaajalle. (H42:2) Niinkuin peura himoitsee tuoretta vettä, niin minun sieluni himoitsee sinua, Jumala."],[42,2,"Minun sieluni janoo Jumalaa, elävää Jumalaa: koska minä tulen Jumalan kasvoja näkemään?","Minun sieluni janoo Jumalaa, elävää Jumalaa: koska minä tulen Jumalan kasvoja näkemään?"],[42,3,"Minun kyyneleeni ovat minun ruokani päivällä ja yöllä, että joka päivä minulle sanotaan: kussa nyt on Jumalas?","Minun kyyneleeni ovat minun ruokani päivällä ja yöllä, että joka päivä minulle sanotaan: kussa nyt on Jumalas?"],[42,4,"Koska minä näitä muistelen, niin minä vuodatan ulos sydämeni itsessäni; sillä minä menisin mielelläni joukon kanssa, ja vaeltaisin heidän kanssansa Jumalan huoneeseen: ihastuksella ja kiitoksella joukon seassa, jotka juhlaa pitävät.","Koska minä näitä muistelen, niin minä vuodatan ulos sydämeni itsessäni; sillä minä menisin mielelläni joukon kanssa, ja vaeltaisin heidän kanssansa Jumalan huoneeseen: ihastuksella ja kiitoksella joukon seassa, jotka juhlaa pitävät."],[42,5,"Mitäs murehdit, sieluni, ja olet niin levotoin minussa? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän minua auttaa kasvoillansa.","Mitäs murehdit, sieluni, ja olet niin levotoin minussa? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän minua auttaa kasvoillansa."],[42,6,"Minun Jumalani! sieluni on murheissansa minussa; sentähden minä muistan sinua Jordanin ja Hermonin maalla, sillä vähällä vuorella.","Minun Jumalani! sieluni on murheissansa minussa; sentähden minä muistan sinua Jordanin ja Hermonin maalla, sillä vähällä vuorella."],[42,7,"Sinun virtas pauhaavat kovin, niin että yksi syvyys pauhaa tässä ja toinen syvyys siellä: kaikki sinun vesilainees ja aaltos käyvät minun ylitseni.","Sinun virtas pauhaavat kovin, niin että yksi syvyys pauhaa tässä ja toinen syvyys siellä: kaikki sinun vesilainees ja aaltos käyvät minun ylitseni."],[42,8,"Päivällä on Herra luvannut hyvyytensä, ja yöllä minä hänelle veisaan, ja rukoilen elämäni Jumalaa.","Päivällä on Herra luvannut hyvyytensä, ja yöllä minä hänelle veisaan, ja rukoilen elämäni Jumalaa."],[42,9,"Minä sanon Jumalalle minun kalliolleni: miksi sinä olet minun unohtanut? miksi minä käyn niin murheissani, koska minun viholliseni minua ahdistaa?","Minä sanon Jumalalle minun kalliolleni: miksi sinä olet minun unohtanut? miksi minä käyn niin murheissani, koska minun viholliseni minua ahdistaa?"],[42,10,"Se on niinkuin murha minun luissani, että minun viholliseni häpäisevät minua, koska he jokapäivä sanovat minulle: kussa nyt on Jumalas?","Se on niinkuin murha minun luissani, että minun viholliseni häpäisevät minua, koska he jokapäivä sanovat minulle: kussa nyt on Jumalas?"],[42,11,"Mitäs murehdit, sieluni, ja olet minussa niin levotoin? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän on minun kasvoini apu ja minun Jumalani.","Mitäs murehdit, sieluni, ja olet minussa niin levotoin? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän on minun kasvoini apu ja minun Jumalani."],[43,1,"Tuomitse minua, Jumala, ja ratkaise minun asiani armotointa kansaa vastaan, ja päästä minua kavaloista ja vääristä ihmisistä.","Tuomitse minua, Jumala, ja ratkaise minun asiani armotointa kansaa vastaan, ja päästä minua kavaloista ja vääristä ihmisistä."],[43,2,"Sillä sinä olet minun väkevyyteni Jumala, miksis syökset minun pois? miksis minun annat murheissani käydä, koska vihollinen minua ahdistaa?","Sillä sinä olet minun väkevyyteni Jumala, miksis syökset minun pois? miksis minun annat murheissani käydä, koska vihollinen minua ahdistaa?"],[43,3,"Lähetä valkeutes ja totuutes minua saattamaan, ja tuomaan sinun pyhän vuores tykö ja sinun asumises tykö.","Lähetä valkeutes ja totuutes minua saattamaan, ja tuomaan sinun pyhän vuores tykö ja sinun asumises tykö."],[43,4,"Ja minä kävisin sisälle Jumalan alttarin tykö, sen Jumalan tykö, joka minun iloni ja riemuni on, ja kiittäisin sinua kanteleilla, Jumalani, minun Jumalani.","Ja minä kävisin sisälle Jumalan alttarin tykö, sen Jumalan tykö, joka minun iloni ja riemuni on, ja kiittäisin sinua kanteleilla, Jumalani, minun Jumalani."],[43,5,"Mitäs murehdit, sieluni, ja olet minussa niin levotoin? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän on minun kasvoini apu ja minun Jumalani.","Mitäs murehdit, sieluni, ja olet minussa niin levotoin? Turvaa Jumalaan; sillä minä vielä nytkin häntä kiitän, että hän on minun kasvoini apu ja minun Jumalani."],[44,1,"Koran lasten opetus, edelläveisaajalle. (H44:2) Jumala! me olemme korvillamme kuulleet, meidän isämme ovat meille luetelleet, mitäs heidän aikanansa ja muinen tehnyt olet.","Koran lasten opetus, edelläveisaajalle. (H44:2) Jumala! me olemme korvillamme kuulleet, meidän isämme ovat meille luetelleet, mitäs heidän aikanansa ja muinen tehnyt olet."],[44,2,"Sinä olet ajanut pakanat pois kädelläs; mutta heidät sinä olet istuttanut siaan: sinä olet kansat kadottanut, mutta heitä sinä olet levittänyt.","Sinä olet ajanut pakanat pois kädelläs; mutta heidät sinä olet istuttanut siaan: sinä olet kansat kadottanut, mutta heitä sinä olet levittänyt."],[44,3,"Sillä ei he ole miekallansa maata omistaneet, ja heidän käsivartensa ei auttaneet heitä, vaan sinun oikia kätes ja sinun käsivartes, ja sinun kasvois valkeus; sillä sinä mielistyit heihin.","Sillä ei he ole miekallansa maata omistaneet, ja heidän käsivartensa ei auttaneet heitä, vaan sinun oikia kätes ja sinun käsivartes, ja sinun kasvois valkeus; sillä sinä mielistyit heihin."],[44,4,"Jumala, sinä olet minun kuninkaani, joka autuuden Jakobille lupaat.","Jumala, sinä olet minun kuninkaani, joka autuuden Jakobille lupaat."],[44,5,"Sinun kauttas me vihollisemme paiskaamme maahan; sinun nimessäs me tallaamme vastaankarkaajamme.","Sinun kauttas me vihollisemme paiskaamme maahan; sinun nimessäs me tallaamme vastaankarkaajamme."],[44,6,"Sillä en minä luota joutseeni, eikä miekkani auta minua.","Sillä en minä luota joutseeni, eikä miekkani auta minua."],[44,7,"Mutta sinä autat meitä vihollisistamme, ja saatat niitä häpiään, jotka meitä vihaavat.","Mutta sinä autat meitä vihollisistamme, ja saatat niitä häpiään, jotka meitä vihaavat."],[44,8,"Jumalasta me kerskaamme joka päivä, ja kiitämme sinun nimeäs ijankaikkisesti, Sela!","Jumalasta me kerskaamme joka päivä, ja kiitämme sinun nimeäs ijankaikkisesti, Sela!"],[44,9,"Miksi sinä nyt sysäät meitä pois, ja annat meidän häpiään tulla, etkä lähde meidän sotajoukkomme kanssa?","Miksi sinä nyt sysäät meitä pois, ja annat meidän häpiään tulla, etkä lähde meidän sotajoukkomme kanssa?"],[44,10,"Sinä annat meidän paeta vihollistemme edessä, että ne raatelisivat meitä, jotka meitä vihaavat.","Sinä annat meidän paeta vihollistemme edessä, että ne raatelisivat meitä, jotka meitä vihaavat."],[44,11,"Sinä annat meitä syötäviksi niinkuin lampaita, ja hajoitat pakanain sekaan.","Sinä annat meitä syötäviksi niinkuin lampaita, ja hajoitat pakanain sekaan."],[44,12,"Sinä myit kansas ilman hintaa, ja et mitään siitä ottanut.","Sinä myit kansas ilman hintaa, ja et mitään siitä ottanut."],[44,13,"Sinä panet meitä häpiäksi läsnä-asuvaisillemme, pilkaksi ja nauruksi niille, jotka meidän ympärillämme ovat.","Sinä panet meitä häpiäksi läsnä-asuvaisillemme, pilkaksi ja nauruksi niille, jotka meidän ympärillämme ovat."],[44,14,"Sinä teet meitä sananlaskuksi pakanain seassa, ja että kansat vääntelevät päätänsä meidän tähtemme.","Sinä teet meitä sananlaskuksi pakanain seassa, ja että kansat vääntelevät päätänsä meidän tähtemme."],[44,15,"Joka päivä on minun häväistykseni minun edessäni; ja minun kasvoini häpiä peittää minun,","Joka päivä on minun häväistykseni minun edessäni; ja minun kasvoini häpiä peittää minun,"],[44,16,"Että minun pitää pilkkaajia ja laittajia kuuleman, ja viholliset ja tylyt kostajat näkemän.","Että minun pitää pilkkaajia ja laittajia kuuleman, ja viholliset ja tylyt kostajat näkemän."],[44,17,"Nämät kaikki ovat tulleet meidän päällemme; ja emme sentähden ole sinua unhottaneet, emmekä petollisesti sinun liittoas vastaan tehneet.","Nämät kaikki ovat tulleet meidän päällemme; ja emme sentähden ole sinua unhottaneet, emmekä petollisesti sinun liittoas vastaan tehneet."],[44,18,"Ja ei meidän sydämemme takaperin kääntynyt, eikä meidän käymisemme poikennut sinun tiestäs;","Ja ei meidän sydämemme takaperin kääntynyt, eikä meidän käymisemme poikennut sinun tiestäs;"],[44,19,"Ettäs meitä niin löit rikki lohikärmeiden seassa ja peitit meitä kuoleman varjolla.","Ettäs meitä niin löit rikki lohikärmeiden seassa ja peitit meitä kuoleman varjolla."],[44,20,"Jos me olisimme meidän Jumalamme nimen unhottaneet, ja meidän kätemme nostaneet vieraalle Jumalalle,","Jos me olisimme meidän Jumalamme nimen unhottaneet, ja meidän kätemme nostaneet vieraalle Jumalalle,"],[44,21,"Eikö Jumala sitä etsisi? vaan hän itse tietää meidän sydämemme pohjan.","Eikö Jumala sitä etsisi? vaan hän itse tietää meidän sydämemme pohjan."],[44,22,"Sillä sinun tähtes me surmataan joka päivä: ja me luetaan teuraslampaiksi.","Sillä sinun tähtes me surmataan joka päivä: ja me luetaan teuraslampaiksi."],[44,23,"Herää, Herra, miksis makaat? valvo, ja älä meitä sysää pois kaiketikaan.","Herää, Herra, miksis makaat? valvo, ja älä meitä sysää pois kaiketikaan."],[44,24,"Miksis peität kasvos, ja unohdat meidän raadollisuutemme ja ahdistuksemme?","Miksis peität kasvos, ja unohdat meidän raadollisuutemme ja ahdistuksemme?"],[44,25,"Sillä meidän sielumme on painettu alas maahan asti: meidän vatsamme riippuu maassa.","Sillä meidän sielumme on painettu alas maahan asti: meidän vatsamme riippuu maassa."],[44,26,"Nouse, auta meitä, ja lunasta meitä laupiutes tähden!","Nouse, auta meitä, ja lunasta meitä laupiutes tähden!"],[45,1,"Morsiamen opetusvirsi kukkasesta Koran lapsilta edelläveisaajalle. (H45:2) Minun sydämeni ajattelee kauniin laulun: minä veisaan kuninkaasta, minun kieleni on jalon kirjoittajan kynä.","Morsiamen opetusvirsi kukkasesta Koran lapsilta edelläveisaajalle. (H45:2) Minun sydämeni ajattelee kauniin laulun: minä veisaan kuninkaasta, minun kieleni on jalon kirjoittajan kynä."],[45,2,"Sinä olet kaikkein kaunein ihmisten lasten seassa: armo on vuodatettu sinun huulissas; sentähden siunaa Jumala sinua ijankaikkisesti.","Sinä olet kaikkein kaunein ihmisten lasten seassa: armo on vuodatettu sinun huulissas; sentähden siunaa Jumala sinua ijankaikkisesti."],[45,3,"Pane miekkas vyölles, sinä sankari, ja kaunista itses kunniallisesti.","Pane miekkas vyölles, sinä sankari, ja kaunista itses kunniallisesti."],[45,4,"Menesty sinun kauneudessas, kiiruhda sinus sanan totuuden, siveyden ja vanhurskauden tähden, niin sinun oikia kätes ihmeellisiä osoittaa.","Menesty sinun kauneudessas, kiiruhda sinus sanan totuuden, siveyden ja vanhurskauden tähden, niin sinun oikia kätes ihmeellisiä osoittaa."],[45,5,"Terävät ovat sinun nuoles, että kansat lankeevat etees maahan, jotka sydämestänsä kuninkaan viholliset ovat.","Terävät ovat sinun nuoles, että kansat lankeevat etees maahan, jotka sydämestänsä kuninkaan viholliset ovat."],[45,6,"Jumala, sinun istuimes pysyy aina ja ijankaikkisesti; sinun valtakuntas valtikka on oikeuden valtikka.","Jumala, sinun istuimes pysyy aina ja ijankaikkisesti; sinun valtakuntas valtikka on oikeuden valtikka."],[45,7,"Sinä rakastit vanhurskautta, ja vihasit jumalatointa menoa: sentähden, oi Jumala, on sinun Jumalas voidellut sinua ilo-öljyllä enempi kuin sinun osaveljes.","Sinä rakastit vanhurskautta, ja vihasit jumalatointa menoa: sentähden, oi Jumala, on sinun Jumalas voidellut sinua ilo-öljyllä enempi kuin sinun osaveljes."],[45,8,"Kaikki sinun vaattees ovat sula Mirrham, Aloe ja Ketsia. Kuin sinä elephantin luisesta tuvastas lähdet, niin he ilahuttavat sinun.","Kaikki sinun vaattees ovat sula Mirrham, Aloe ja Ketsia. Kuin sinä elephantin luisesta tuvastas lähdet, niin he ilahuttavat sinun."],[45,9,"Sinun kaunistuksessas käyvät kuningasten tyttäret: morsian seisoo oikialla kädelläs sulassa kalliimmassa kullassa.","Sinun kaunistuksessas käyvät kuningasten tyttäret: morsian seisoo oikialla kädelläs sulassa kalliimmassa kullassa."],[45,10,"Kuule,tytär, katso, ja kallista korvas: unohda kansas ja isäs huone,","Kuule,tytär, katso, ja kallista korvas: unohda kansas ja isäs huone,"],[45,11,"Niin kuningas saa halun kauneutees; sillä hän on sinun herras, ja sinun pitää häntä kumartaman.","Niin kuningas saa halun kauneutees; sillä hän on sinun herras, ja sinun pitää häntä kumartaman."],[45,12,"Tyron tytär lahjoinensa, rikkaat kansan seassa sinua imartelevat.","Tyron tytär lahjoinensa, rikkaat kansan seassa sinua imartelevat."],[45,13,"Kuninkaan tytär on kokonansa kunniallinen sisältä: hän on kultaisessa vaatteessa puetettu.","Kuninkaan tytär on kokonansa kunniallinen sisältä: hän on kultaisessa vaatteessa puetettu."],[45,14,"Hän viedään monella tavalla kudotuissa vaatteissa kuninkaan tykö: neitseet, hänen ystävänsä, jotka häntä seuraavat, tuodaan sinun tykös.","Hän viedään monella tavalla kudotuissa vaatteissa kuninkaan tykö: neitseet, hänen ystävänsä, jotka häntä seuraavat, tuodaan sinun tykös."],[45,15,"Ne viedään ilolla ja riemulla, ja he menevät kuninkaan tupaan.","Ne viedään ilolla ja riemulla, ja he menevät kuninkaan tupaan."],[45,16,"Sinun isäis siaan pitää sinun lapsia saaman, jotka asetat päämiehiksi kaikkeen maailmaan.","Sinun isäis siaan pitää sinun lapsia saaman, jotka asetat päämiehiksi kaikkeen maailmaan."],[45,17,"Minä tahdon muistaa sinun nimeäs sukukunnasta niin sukukuntaan: sentähden pitää kansat sinua kiittämän aina ja ijankaikkisesti.","Minä tahdon muistaa sinun nimeäs sukukunnasta niin sukukuntaan: sentähden pitää kansat sinua kiittämän aina ja ijankaikkisesti."],[46,1,"Koran lasten veisu nuoruudesta, edelläveisaajalle. (H46:2) Jumala on meidän turvamme ja väkevyytemme, joka on sangen sovelias apu tuskissa.","Koran lasten veisu nuoruudesta, edelläveisaajalle. (H46:2) Jumala on meidän turvamme ja väkevyytemme, joka on sangen sovelias apu tuskissa."],[46,2,"Sentähden emme pelkää, jos vielä maailma hukkuis, ja vuoret keskelle merta vajoisivat,","Sentähden emme pelkää, jos vielä maailma hukkuis, ja vuoret keskelle merta vajoisivat,"],[46,3,"Vaikka vielä meri pauhais ja lainehtis, niin että siitä pauhinasta mäet kukistuisivat, Sela!","Vaikka vielä meri pauhais ja lainehtis, niin että siitä pauhinasta mäet kukistuisivat, Sela!"],[46,4,"Kuitenkin on Jumalan kaupunki ihana virtoinensa, jossa Korkeimman pyhät asumiset ovat.","Kuitenkin on Jumalan kaupunki ihana virtoinensa, jossa Korkeimman pyhät asumiset ovat."],[46,5,"Jumala on hänen keskellänsä, sentähden se kyllä pysyy: Jumala auttaa häntä varhain.","Jumala on hänen keskellänsä, sentähden se kyllä pysyy: Jumala auttaa häntä varhain."],[46,6,"Pakanain pitää hämmästymän ja valtakunnat lankeeman; ja maa hukkuu, kuin hän äänensä antaa.","Pakanain pitää hämmästymän ja valtakunnat lankeeman; ja maa hukkuu, kuin hän äänensä antaa."],[46,7,"Herra Zebaot on meidän kanssamme, Jakobin Jumala on meidän tukemme, Sela!","Herra Zebaot on meidän kanssamme, Jakobin Jumala on meidän tukemme, Sela!"],[46,8,"Tulkaat ja katsokaat Herran tekoja, joka maan päällä senkaltaiset hävitykset tekee,","Tulkaat ja katsokaat Herran tekoja, joka maan päällä senkaltaiset hävitykset tekee,"],[46,9,"Joka hallitsee sodat kaikessa maailmassa, joka joutsen särkee ja rikkoo keihään, ja rattaat tulessa polttaa.","Joka hallitsee sodat kaikessa maailmassa, joka joutsen särkee ja rikkoo keihään, ja rattaat tulessa polttaa."],[46,10,"Lakatkaat ja tietäkäät, että minä olen Jumala: minä olen voittava kunnian pakanain seassa ja minä ylennetään maan päällä.","Lakatkaat ja tietäkäät, että minä olen Jumala: minä olen voittava kunnian pakanain seassa ja minä ylennetään maan päällä."],[46,11,"Herra Zebaot on meidän kanssamme: Jakobin Jumala on meidän tukemme, Sela!","Herra Zebaot on meidän kanssamme: Jakobin Jumala on meidän tukemme, Sela!"],[47,1,"Koran lasten Psalmi, edelläveisaajalle. (H47:2) Kaikki kansat, paukuttakaat käsiänne, ja ihastukaat Jumalalle iloisella äänellä.","Koran lasten Psalmi, edelläveisaajalle. (H47:2) Kaikki kansat, paukuttakaat käsiänne, ja ihastukaat Jumalalle iloisella äänellä."],[47,2,"Sillä Herra kaikkein korkein on hirmuinen, suuri kuningas koko maan päällä.","Sillä Herra kaikkein korkein on hirmuinen, suuri kuningas koko maan päällä."],[47,3,"Hän vaatii kansat allemme, ja pakanat meidän jalkaimme alle.","Hän vaatii kansat allemme, ja pakanat meidän jalkaimme alle."],[47,4,"Hän valitsee meille perimisemme, Jakobin kunnian, jota hän rakastaa, Sela!","Hän valitsee meille perimisemme, Jakobin kunnian, jota hän rakastaa, Sela!"],[47,5,"Jumala astui ylös riemulla, ja Herra helisevällä basunalla.","Jumala astui ylös riemulla, ja Herra helisevällä basunalla."],[47,6,"Veisatkaat, veisatkaat Jumalalle: veisatkaat, veisatkaat kuninkaallemme.","Veisatkaat, veisatkaat Jumalalle: veisatkaat, veisatkaat kuninkaallemme."],[47,7,"Sillä Jumala on koko maan kuningas: veisatkaat hänelle taitavasti.","Sillä Jumala on koko maan kuningas: veisatkaat hänelle taitavasti."],[47,8,"Jumala on pakanain kuningas: Jumala istuu pyhällä istuimellansa.","Jumala on pakanain kuningas: Jumala istuu pyhällä istuimellansa."],[47,9,"Kansain päämiehet ovat kokoontuneet Abrahamin Jumalan kansan tykö; sillä maan edesvastaajat ovat Jumalan: hän on sangen suuresti ylennetty.","Kansain päämiehet ovat kokoontuneet Abrahamin Jumalan kansan tykö; sillä maan edesvastaajat ovat Jumalan: hän on sangen suuresti ylennetty."],[48,1,"Koran lasten Veisu-Psalmi. (H48:2) Suuri on Herra, ja sangen kiitettävä, meidän Jumalamme kaupungissa, pyhällä vuorellansa.","Koran lasten Veisu-Psalmi. (H48:2) Suuri on Herra, ja sangen kiitettävä, meidän Jumalamme kaupungissa, pyhällä vuorellansa."],[48,2,"Zionin vuori on kauniilla paikalla, koko maan ilo, pohjan puolella, suuren kuninkaan kaupunki.","Zionin vuori on kauniilla paikalla, koko maan ilo, pohjan puolella, suuren kuninkaan kaupunki."],[48,3,"Jumala on tunnettu huoneessansa, että hän sen varjelia on.","Jumala on tunnettu huoneessansa, että hän sen varjelia on."],[48,4,"Sillä katso, kuninkaat olivat kokoontuneet, ja ynnä menivät ohitse.","Sillä katso, kuninkaat olivat kokoontuneet, ja ynnä menivät ohitse."],[48,5,"He ihmettelivät, kuin he tämän näkivät: he hämmästyivät, ja kiiruhtivat pois,","He ihmettelivät, kuin he tämän näkivät: he hämmästyivät, ja kiiruhtivat pois,"],[48,6,"Vavistus on heidät siellä käsittänyt, ahdistus niinkuin synnyttäväisen.","Vavistus on heidät siellä käsittänyt, ahdistus niinkuin synnyttäväisen."],[48,7,"Sinä särjet haahdet meressä itätuulella.","Sinä särjet haahdet meressä itätuulella."],[48,8,"Niinkuin me kuulimme, niin me sen näemme Herran Zebaotin kaupungissa, meidän Jumalamme kaupungissa: Jumala sen vahvistaa ijankaikkisesti, Sela!","Niinkuin me kuulimme, niin me sen näemme Herran Zebaotin kaupungissa, meidän Jumalamme kaupungissa: Jumala sen vahvistaa ijankaikkisesti, Sela!"],[48,9,"Jumala! me odotamme sinun hyvyyttäs sinun templissäs.","Jumala! me odotamme sinun hyvyyttäs sinun templissäs."],[48,10,"Jumala! niinkuin sinun nimes on, niin myös on sinun kiitokses hamaan maailman ääreen: sinun oikia kätes on täynnä vanhurskautta.","Jumala! niinkuin sinun nimes on, niin myös on sinun kiitokses hamaan maailman ääreen: sinun oikia kätes on täynnä vanhurskautta."],[48,11,"Riemuitkaan Zionin vuori, ja Juudan tyttäret iloitkaan sinun oikeuttes tähden.","Riemuitkaan Zionin vuori, ja Juudan tyttäret iloitkaan sinun oikeuttes tähden."],[48,12,"Menkäät Zionin ympäri ja piirittäkäät häntä: lukekaat hänen torninsa.","Menkäät Zionin ympäri ja piirittäkäät häntä: lukekaat hänen torninsa."],[48,13,"Turvatkaat hänen muurinsa, vahvistakaat hänen salinsa, että te sitä juttelisitte tulevaisille sukukunnille.","Turvatkaat hänen muurinsa, vahvistakaat hänen salinsa, että te sitä juttelisitte tulevaisille sukukunnille."],[48,14,"Sillä tämä Jumala on meidän Jumalamme aina ja ijankaikkisesti: hän johdattaa meitä kuolemaan asti.","Sillä tämä Jumala on meidän Jumalamme aina ja ijankaikkisesti: hän johdattaa meitä kuolemaan asti."],[49,1,"Koran lasten Psalmi, edelläveisaajalle. (H49:2) Kuulkaat tätä, kaikki kansat, ottakaat korviinne, kaikki maan asuvaiset,","Koran lasten Psalmi, edelläveisaajalle. (H49:2) Kuulkaat tätä, kaikki kansat, ottakaat korviinne, kaikki maan asuvaiset,"],[49,2,"Sekä yhteinen kansa että herrat, niin rikkaat kuin köyhät.","Sekä yhteinen kansa että herrat, niin rikkaat kuin köyhät."],[49,3,"Minun suuni puhuu viisautta, ja minun sydämeni sanoo ymmärryksen.","Minun suuni puhuu viisautta, ja minun sydämeni sanoo ymmärryksen."],[49,4,"Minä tahdon kallistaa korvani vertauksiin, ja minun tapaukseni kanteleella soittaa.","Minä tahdon kallistaa korvani vertauksiin, ja minun tapaukseni kanteleella soittaa."],[49,5,"Miksi minun pitäis pelkäämän pahoina päivinä, kuin minun sortajani vääryys käy minua ympäri?","Miksi minun pitäis pelkäämän pahoina päivinä, kuin minun sortajani vääryys käy minua ympäri?"],[49,6,"Jotka luottavat tavaroihinsa, ja suuresti kerskaavat paljosta rikkaudestansa.","Jotka luottavat tavaroihinsa, ja suuresti kerskaavat paljosta rikkaudestansa."],[49,7,"Ei velikään taida ketään lunastaa, eikä Jumalalle ketään sovittaa.","Ei velikään taida ketään lunastaa, eikä Jumalalle ketään sovittaa."],[49,8,"Sillä heidän sielunsa lunastus on ylen kallis, niin että se jää tekemättä ijankaikkisesti,","Sillä heidän sielunsa lunastus on ylen kallis, niin että se jää tekemättä ijankaikkisesti,"],[49,9,"Vaikka hän vielä kauvankin eläis ja ei näkisi hautaa.","Vaikka hän vielä kauvankin eläis ja ei näkisi hautaa."],[49,10,"Sillä hänen täytyy nähdä, että viisasten pitää kuoleman, niin myös tyhmän ja taitamattoman pitää hukkuman, ja pitää vieraille tavaransa jättämän.","Sillä hänen täytyy nähdä, että viisasten pitää kuoleman, niin myös tyhmän ja taitamattoman pitää hukkuman, ja pitää vieraille tavaransa jättämän."],[49,11,"Heidän sydämensä ajatus on, että heidän huoneensa pitää ijankaikkisesti pysymän, ja heidän majansa suvusta sukuun, ja heidän nimensä kuuluisaksi tulemaan maan päällä.","Heidän sydämensä ajatus on, että heidän huoneensa pitää ijankaikkisesti pysymän, ja heidän majansa suvusta sukuun, ja heidän nimensä kuuluisaksi tulemaan maan päällä."],[49,12,"Mutta ei ihminen taida pysyä kunniassa, vaan verrataan eläimiin, jotka hukkuvat.","Mutta ei ihminen taida pysyä kunniassa, vaan verrataan eläimiin, jotka hukkuvat."],[49,13,"Tämä heidän tiensä on sula hulluus; kuitenkin, heidän jälkeentulevaisensa sitä suullansa kiittävät, Sela!","Tämä heidän tiensä on sula hulluus; kuitenkin, heidän jälkeentulevaisensa sitä suullansa kiittävät, Sela!"],[49,14,"He makaavat helvetissä niinkuin lampaat, kuolema heitä kalvaa; mutta hurskasten pitää varhain heitä hallitseman, ja heidän öykkäyksensä pitää hukkuman, ja heidän täytyy jäädä helvettiin.","He makaavat helvetissä niinkuin lampaat, kuolema heitä kalvaa; mutta hurskasten pitää varhain heitä hallitseman, ja heidän öykkäyksensä pitää hukkuman, ja heidän täytyy jäädä helvettiin."],[49,15,"Kuitenkin vapahtaa Jumala minun sieluni helvetin vallasta; sillä hän korjasi minun, Sela!","Kuitenkin vapahtaa Jumala minun sieluni helvetin vallasta; sillä hän korjasi minun, Sela!"],[49,16,"Älä sitä tottele, koska joku rikastuu, eli jos hänen huoneensa kunnia suureksi tulee.","Älä sitä tottele, koska joku rikastuu, eli jos hänen huoneensa kunnia suureksi tulee."],[49,17,"Sillä kuin hän kuolee, niin ei hän mitään myötänsä vie, eikä hänen kunniansa mene alas hänen kanssansa.","Sillä kuin hän kuolee, niin ei hän mitään myötänsä vie, eikä hänen kunniansa mene alas hänen kanssansa."],[49,18,"Sillä hän kiittää sieluansa elämästänsä: ja he ylistävät sinua, jos sinä itselles hyvää teet.","Sillä hän kiittää sieluansa elämästänsä: ja he ylistävät sinua, jos sinä itselles hyvää teet."],[49,19,"Niin he menevät isäinsä perästä, ja ei saa nähdä ikänä valkeutta.","Niin he menevät isäinsä perästä, ja ei saa nähdä ikänä valkeutta."],[49,20,"Koska ihminen on kunniassa, ja ei ole ymmärrystä, niin hän on verrattu eläimiin, jotka hukkuvat.","Koska ihminen on kunniassa, ja ei ole ymmärrystä, niin hän on verrattu eläimiin, jotka hukkuvat."],[50,1,"Asaphin Psalmi. Herra, väkevä Jumala, puhuu, ja kutsuu maailman hamasta auringon koitosta niin laskemiseen asti.","Asaphin Psalmi. Herra, väkevä Jumala, puhuu, ja kutsuu maailman hamasta auringon koitosta niin laskemiseen asti."],[50,2,"Zionista antaa Jumala täydellisen kirkkauden paistaa.","Zionista antaa Jumala täydellisen kirkkauden paistaa."],[50,3,"Meidän Jumalamme tulee, ja ei vaikene: kuluttavainen tuli käy hänen edellänsä, ja hänen ympärillänsä väkevä ilma.","Meidän Jumalamme tulee, ja ei vaikene: kuluttavainen tuli käy hänen edellänsä, ja hänen ympärillänsä väkevä ilma."],[50,4,"Hän kutsuu taivaat ylhäältä ja maan, tuomitaksensa kansaansa.","Hän kutsuu taivaat ylhäältä ja maan, tuomitaksensa kansaansa."],[50,5,"Kootkaat minulle minun pyhäni, jotka liitostani enemmän pitävät kuin uhrista.","Kootkaat minulle minun pyhäni, jotka liitostani enemmän pitävät kuin uhrista."],[50,6,"Ja taivaat pitää hänen vanhurskauttansa ilmoittaman; sillä Jumala on tuomari, Sela!","Ja taivaat pitää hänen vanhurskauttansa ilmoittaman; sillä Jumala on tuomari, Sela!"],[50,7,"Kuule, kansani! minä tahdon puhua, ja sinun seassas, Israel, todistaa: minä Jumala olen sinun Jumalas,","Kuule, kansani! minä tahdon puhua, ja sinun seassas, Israel, todistaa: minä Jumala olen sinun Jumalas,"],[50,8,"Uhreistas en minä sinua nuhtele; sillä sinun polttouhris ovat alati minun edessäni.","Uhreistas en minä sinua nuhtele; sillä sinun polttouhris ovat alati minun edessäni."],[50,9,"En minä ota härkiä sinun huoneestas, enkä kauriita navetastas;","En minä ota härkiä sinun huoneestas, enkä kauriita navetastas;"],[50,10,"Sillä kaikki metsän eläimet ovat minun, ja eläimet vuorilla tuhansin.","Sillä kaikki metsän eläimet ovat minun, ja eläimet vuorilla tuhansin."],[50,11,"Minä tunnen kaikki linnut vuorten päällä, ja metsän pedot ovat minun edessäni.","Minä tunnen kaikki linnut vuorten päällä, ja metsän pedot ovat minun edessäni."],[50,12,"Jos minä isoon, en minä sitä sano sinulle; sillä maan piiri on minun, ja kaikki mitä siinä on.","Jos minä isoon, en minä sitä sano sinulle; sillä maan piiri on minun, ja kaikki mitä siinä on."],[50,13,"Luuletkos minun syövän härjän lihaa? ja kauristen verta juovan?","Luuletkos minun syövän härjän lihaa? ja kauristen verta juovan?"],[50,14,"Uhraa Jumalalle kiitosuhri, ja maksa Ylimmäiselle lupaukses;","Uhraa Jumalalle kiitosuhri, ja maksa Ylimmäiselle lupaukses;"],[50,15,"Ja avukses huuda minua hädässäs, niin minä tahdon auttaa sinua, ja sinun pitää kunnioittaman minua.","Ja avukses huuda minua hädässäs, niin minä tahdon auttaa sinua, ja sinun pitää kunnioittaman minua."],[50,16,"Mutta jumalattomalle sanoo Jumala: miksi sinä ilmoitat minun säätyjäni? ja otat minun liittoni suulles?","Mutta jumalattomalle sanoo Jumala: miksi sinä ilmoitat minun säätyjäni? ja otat minun liittoni suulles?"],[50,17,"Ettäs kuritusta vihaat, ja heität minun sanani taakses.","Ettäs kuritusta vihaat, ja heität minun sanani taakses."],[50,18,"Koskas varkaan näet, niin sinä juokset hänen kanssansa, ja pidät yhtä huorintekiäin kanssa.","Koskas varkaan näet, niin sinä juokset hänen kanssansa, ja pidät yhtä huorintekiäin kanssa."],[50,19,"Sinun suus sallit sinä pahaa puhua, ja kieles saattaa petosta matkaan.","Sinun suus sallit sinä pahaa puhua, ja kieles saattaa petosta matkaan."],[50,20,"Sinä istut ja puhut veljeäs vastaan, äitis poikaa sinä pilkkaat.","Sinä istut ja puhut veljeäs vastaan, äitis poikaa sinä pilkkaat."],[50,21,"Näitä teet, ja minä olen vaiti; niin sinä luulet, että minä olen sinun kaltaises; mutta minä nuhtelen sinua ja asetan näitä silmäis eteen.","Näitä teet, ja minä olen vaiti; niin sinä luulet, että minä olen sinun kaltaises; mutta minä nuhtelen sinua ja asetan näitä silmäis eteen."],[50,22,"Ymmärtäkäät siis näitä te, jotka Jumalan unhotatte; etten minä tempaisi joskus pois, ja ei olisi vapahtajaa.","Ymmärtäkäät siis näitä te, jotka Jumalan unhotatte; etten minä tempaisi joskus pois, ja ei olisi vapahtajaa."],[50,23,"Joka kiitosta uhraa, se ylistää minua, ja siinä on se tie, että minä osoitan hänelle Jumalan autuuden.","Joka kiitosta uhraa, se ylistää minua, ja siinä on se tie, että minä osoitan hänelle Jumalan autuuden."],[51,1,"Davidin Psalmi, edelläveisaajalle, (H51:2) Kuin propheta Natan tuli hänen tykönsä, sittekuin hän Batseban tykönä käynyt oli. (H51:3) Jumala, ole minulle armollinen sinun hyvyytes tähden: pyyhi pois minun syntini suuren laupiutes tähden.","Davidin Psalmi, edelläveisaajalle, (H51:2) Kuin propheta Natan tuli hänen tykönsä, sittekuin hän Batseban tykönä käynyt oli. (H51:3) Jumala, ole minulle armollinen sinun hyvyytes tähden: pyyhi pois minun syntini suuren laupiutes tähden."],[51,2,"Pese minua hyvin vääryydestäni, ja puhdista minua synnistäni.","Pese minua hyvin vääryydestäni, ja puhdista minua synnistäni."],[51,3,"Sillä minä tunnen pahat tekoni, ja minun syntini on aina edessäni.","Sillä minä tunnen pahat tekoni, ja minun syntini on aina edessäni."],[51,4,"Sinua, sinua ainoaa vastaan minä syntiä tein, ja pahasti tein sinun edessäs, ettäs olisit oikia sanoissas ja puhdas tuomitessas.","Sinua, sinua ainoaa vastaan minä syntiä tein, ja pahasti tein sinun edessäs, ettäs olisit oikia sanoissas ja puhdas tuomitessas."],[51,5,"Katso, minä olen synnissä syntynyt, ja minun äitini on synnissä minun siittänyt.","Katso, minä olen synnissä syntynyt, ja minun äitini on synnissä minun siittänyt."],[51,6,"Katso, sinä halajat totuutta, joka salaudessa on, ja ilmoitat salatun viisauden minulle.","Katso, sinä halajat totuutta, joka salaudessa on, ja ilmoitat salatun viisauden minulle."],[51,7,"Puhdista minua isopilla, että minä puhdistuisin: pese minua, että minä lumivalkiaksi tulisin.","Puhdista minua isopilla, että minä puhdistuisin: pese minua, että minä lumivalkiaksi tulisin."],[51,8,"Anna minun kuulla iloa ja riemua, että ne luut ihastuisivat, jotka särkenyt olet.","Anna minun kuulla iloa ja riemua, että ne luut ihastuisivat, jotka särkenyt olet."],[51,9,"Peitä kasvos minun synneistäni, ja pyyhi pois kaikki pahat tekoni.","Peitä kasvos minun synneistäni, ja pyyhi pois kaikki pahat tekoni."],[51,10,"Jumala, luo minuun puhdas sydän, ja anna minulle uusi vahva henki.","Jumala, luo minuun puhdas sydän, ja anna minulle uusi vahva henki."],[51,11,"Älä heitä minua pois kasvois edestä, ja älä minulta ota pois sinun Pyhää Henkeäs.","Älä heitä minua pois kasvois edestä, ja älä minulta ota pois sinun Pyhää Henkeäs."],[51,12,"Anna minulle taas sinun autuutes ilo, ja sillä hyvällä hengelläs tue minua.","Anna minulle taas sinun autuutes ilo, ja sillä hyvällä hengelläs tue minua."],[51,13,"Minä tahdon väärille opettaa sinun ties, että syntiset tykös palajaisivat.","Minä tahdon väärille opettaa sinun ties, että syntiset tykös palajaisivat."],[51,14,"Päästä minua veren vioista, Jumala, minun autuuteni Jumala, että minun kieleni ylistäis sinun vanhurskauttas.","Päästä minua veren vioista, Jumala, minun autuuteni Jumala, että minun kieleni ylistäis sinun vanhurskauttas."],[51,15,"Avaa, Herra, minun huuleni, että minun suuni ilmoittais sinun kiitokses.","Avaa, Herra, minun huuleni, että minun suuni ilmoittais sinun kiitokses."],[51,16,"Sillä ei sinulle kelpaa uhri, että minä sen antaisin; ja ei polttouhri sinulle ensinkään kelpaa.","Sillä ei sinulle kelpaa uhri, että minä sen antaisin; ja ei polttouhri sinulle ensinkään kelpaa."],[51,17,"Ne uhrit, jotka Jumalalle kelpaavat, ovat murheellinen henki: ahdistettua ja särjettyä sydäntä et sinä, Jumala, hylkää.","Ne uhrit, jotka Jumalalle kelpaavat, ovat murheellinen henki: ahdistettua ja särjettyä sydäntä et sinä, Jumala, hylkää."],[51,18,"Tee Zionille hyvästi sinun armos jälkeen; rakenna Jerusalemin muurit.","Tee Zionille hyvästi sinun armos jälkeen; rakenna Jerusalemin muurit."],[51,19,"Silloin sinulle kelpaavat vanhurskauden uhrit, polttouhrit ja muut uhrit: silloin sinun alttarillas härkiä uhrataan.","Silloin sinulle kelpaavat vanhurskauden uhrit, polttouhrit ja muut uhrit: silloin sinun alttarillas härkiä uhrataan."],[52,1,"Davidin opetus, edelläveisaajalle, (H52:2) Kuin Edomilainen Doeg tuli ja ilmoitti Saulille, ja sanoi hänelle: David on tullut Ahimelekin huoneeseen. (H52:3) Mitäs kerskaat pahuudessas, sinä väkevä? Jumalan laupius pysyy joka päivä.","Davidin opetus, edelläveisaajalle, (H52:2) Kuin Edomilainen Doeg tuli ja ilmoitti Saulille, ja sanoi hänelle: David on tullut Ahimelekin huoneeseen. (H52:3) Mitäs kerskaat pahuudessas, sinä väkevä? Jumalan laupius pysyy joka päivä."],[52,2,"Sinun kieles ajattelee vahinkoa ja leikkaa valheellansa niinkuin terävä partaveitsi.","Sinun kieles ajattelee vahinkoa ja leikkaa valheellansa niinkuin terävä partaveitsi."],[52,3,"Sinä rakastat enempi pahaa kuin hyvää, ja puhut valhetta pikemmin kuin oikeutta, Sela!","Sinä rakastat enempi pahaa kuin hyvää, ja puhut valhetta pikemmin kuin oikeutta, Sela!"],[52,4,"Sinä puhut mielelläs kaikkia murhasanoja väärällä kielellä.","Sinä puhut mielelläs kaikkia murhasanoja väärällä kielellä."],[52,5,"Niin Jumala myös kukistaa sinun ijankaikkisesti: hän murentaa sinun, ja majasta tempaa sinun ulos, ja juurittaa sinun ulos eläväin maalta, Sela!","Niin Jumala myös kukistaa sinun ijankaikkisesti: hän murentaa sinun, ja majasta tempaa sinun ulos, ja juurittaa sinun ulos eläväin maalta, Sela!"],[52,6,"Ja vanhurskasten pitää sen näkemän ja pelkäämän; ja he nauravat häntä.","Ja vanhurskasten pitää sen näkemän ja pelkäämän; ja he nauravat häntä."],[52,7,"Katso, tämä on se mies, joka ei pitänyt Jumalaa turvanansa, vaan uskalsi suureen rikkauteensa: hän on vahvistunut pahuudessansa.","Katso, tämä on se mies, joka ei pitänyt Jumalaa turvanansa, vaan uskalsi suureen rikkauteensa: hän on vahvistunut pahuudessansa."],[52,8,"Mutta minä olen niinkuin viheriäinen öljypuu Herran huoneessa: minä uskallan Jumalan laupiuteen aina ja ijankaikkisesti.","Mutta minä olen niinkuin viheriäinen öljypuu Herran huoneessa: minä uskallan Jumalan laupiuteen aina ja ijankaikkisesti."],[52,9,"Minä tahdon sinua kiittää ijankaikkisesti, ettäs sen teit, ja odottaa sinun nimeäs; sillä se on hyvä sinun pyhäis edessä.","Minä tahdon sinua kiittää ijankaikkisesti, ettäs sen teit, ja odottaa sinun nimeäs; sillä se on hyvä sinun pyhäis edessä."],[53,1,"Davidin opetus, edelläveisaajalle, Mahelatin päällä. (H53:2) Tyhmät sanovat sydämessänsä: ei Jumalaa olekaan; ei he mitään kelpaa, ja ovat ilkiät menoissansa: ei ole joka hyvää tekee.","Davidin opetus, edelläveisaajalle, Mahelatin päällä. (H53:2) Tyhmät sanovat sydämessänsä: ei Jumalaa olekaan; ei he mitään kelpaa, ja ovat ilkiät menoissansa: ei ole joka hyvää tekee."],[53,2,"Jumala katsoi taivaasta ihmisten lapsia, nähdäksensä, jos joku ymmärtäis, joku Jumalaa etsis.","Jumala katsoi taivaasta ihmisten lapsia, nähdäksensä, jos joku ymmärtäis, joku Jumalaa etsis."],[53,3,"Mutta he ovat kaikki vilpistelleet, ja kaikki ovat kelvottomiksi tulleet: ei ole yksikään, joka hyvää tekee, ei ainoakaan.","Mutta he ovat kaikki vilpistelleet, ja kaikki ovat kelvottomiksi tulleet: ei ole yksikään, joka hyvää tekee, ei ainoakaan."],[53,4,"Eivätkö pahantekiät sitä huomaitse? jotka minun kansaani syövät, niinkuin he söisivät leipää; vaan ei he Jumalaa avuksensa huuda.","Eivätkö pahantekiät sitä huomaitse? jotka minun kansaani syövät, niinkuin he söisivät leipää; vaan ei he Jumalaa avuksensa huuda."],[53,5,"Siellä he kovin pelkäsivät, kussa ei mitään peljättävää ollut; sillä Jumala hajoittaa niiden luut, jotka sinua ahdistavat: sinä saatat heitä häpiään, sillä Jumala hylkää heidät.","Siellä he kovin pelkäsivät, kussa ei mitään peljättävää ollut; sillä Jumala hajoittaa niiden luut, jotka sinua ahdistavat: sinä saatat heitä häpiään, sillä Jumala hylkää heidät."],[53,6,"Oi, jos apu tulis Zionista Israelille! Kuin Jumala vangitun kansansa päästää, niin Jakob iloitsee ja Israel riemuitsee.","Oi, jos apu tulis Zionista Israelille! Kuin Jumala vangitun kansansa päästää, niin Jakob iloitsee ja Israel riemuitsee."],[54,1,"Davidin opetus, edelläveisaajalle, kanteleilla, (H54:2) Kuin Siphiläiset tulivat ja sanoivat Saulille: David on lymyttänyt itsensä meidän tykönämme. (H52:3) Auta minua Jumala sinun nimelläs, ja saata minulle oikeus sinun väkevyydelläs.","Davidin opetus, edelläveisaajalle, kanteleilla, (H54:2) Kuin Siphiläiset tulivat ja sanoivat Saulille: David on lymyttänyt itsensä meidän tykönämme. (H52:3) Auta minua Jumala sinun nimelläs, ja saata minulle oikeus sinun väkevyydelläs."],[54,2,"Jumala, kuule minun rukoukseni, ota korviis minun suuni sanat.","Jumala, kuule minun rukoukseni, ota korviis minun suuni sanat."],[54,3,"Sillä muukalaiset karkasivat minua vastaan, ja väkivaltaiset väijyivät minun sieluani: ei he pitäneet Jumalaa silmäinsä edessä, Sela!","Sillä muukalaiset karkasivat minua vastaan, ja väkivaltaiset väijyivät minun sieluani: ei he pitäneet Jumalaa silmäinsä edessä, Sela!"],[54,4,"Katso, Jumala auttaa minua: Herra tukee minun sieluani.","Katso, Jumala auttaa minua: Herra tukee minun sieluani."],[54,5,"Hän kostaa minun vihollisteni pahuuden: hajoita ne totuudessas.","Hän kostaa minun vihollisteni pahuuden: hajoita ne totuudessas."],[54,6,"Niin minä mielelläni sinulle uhraan: minä kiitän, Herra, sinun nimeäs, sillä se on hyvä.","Niin minä mielelläni sinulle uhraan: minä kiitän, Herra, sinun nimeäs, sillä se on hyvä."],[54,7,"Sillä hän on pelastanut minun kaikesta hädästä; ja minun silmäni ovat nähneet minun viholiseni.","Sillä hän on pelastanut minun kaikesta hädästä; ja minun silmäni ovat nähneet minun viholiseni."],[55,1,"Davidin opetus, edelläveisaajalle, kanteleilla. (H55:2) Jumala, kuule minun rukoukseni, ja älä peitä sinuas minun rukoukseni edestä.","Davidin opetus, edelläveisaajalle, kanteleilla. (H55:2) Jumala, kuule minun rukoukseni, ja älä peitä sinuas minun rukoukseni edestä."],[55,2,"Ota minusta vaari ja kuule minua; että minä surkeasti valitan rukouksissani ja parun;","Ota minusta vaari ja kuule minua; että minä surkeasti valitan rukouksissani ja parun;"],[55,3,"Että vihamies niin huutaa, ja jumalatoin ahdistaa; sillä he kääntävät valheen minun päälleni, ja asettavat itsensä vihassansa minua vastaan.","Että vihamies niin huutaa, ja jumalatoin ahdistaa; sillä he kääntävät valheen minun päälleni, ja asettavat itsensä vihassansa minua vastaan."],[55,4,"Minun sydämeni vapisee minussa, ja kuoleman pelko lankesi minun päälleni.","Minun sydämeni vapisee minussa, ja kuoleman pelko lankesi minun päälleni."],[55,5,"Pelko ja vavistus tulivat minun päälleni, ja kauhistus peitti minun.","Pelko ja vavistus tulivat minun päälleni, ja kauhistus peitti minun."],[55,6,"Ja minä sanoin: jospa minulla olisi siivet niinkuin mettisellä, että minä lentäisin, ja (joskus) lepäisin!","Ja minä sanoin: jospa minulla olisi siivet niinkuin mettisellä, että minä lentäisin, ja (joskus) lepäisin!"],[55,7,"Katso, niin minä kauvas pakenisin, ja oleskelisin korvessa, Sela!","Katso, niin minä kauvas pakenisin, ja oleskelisin korvessa, Sela!"],[55,8,"Minä rientäisin, että minä pääsisin tuulen puuskasta ja tuulispäästä.","Minä rientäisin, että minä pääsisin tuulen puuskasta ja tuulispäästä."],[55,9,"Turmele, Herra, ja sekoita heidän kielensä; sillä minä näin väkivallan ja riidan kaupungissa.","Turmele, Herra, ja sekoita heidän kielensä; sillä minä näin väkivallan ja riidan kaupungissa."],[55,10,"He käyvät sen ympäri päivällä ja yöllä hänen muurinsa päällä: vääryys ja vaiva on sen keskellä.","He käyvät sen ympäri päivällä ja yöllä hänen muurinsa päällä: vääryys ja vaiva on sen keskellä."],[55,11,"Vääryys on sen keskellä: valhe ja petos ei luovu hänen kaduiltansa.","Vääryys on sen keskellä: valhe ja petos ei luovu hänen kaduiltansa."],[55,12,"Sillä jos minun vihamieheni häpäisis minua, sen minä kärsisin: ja jos minun vainoojani nousis minua vastaan, niin minä kätkisin itseni hänen edestänsä.","Sillä jos minun vihamieheni häpäisis minua, sen minä kärsisin: ja jos minun vainoojani nousis minua vastaan, niin minä kätkisin itseni hänen edestänsä."],[55,13,"Vaan sinä olet minun kumppanini, minun johdattajani ja minun tuttavani:","Vaan sinä olet minun kumppanini, minun johdattajani ja minun tuttavani:"],[55,14,"Me jotka ystävällisesti keskenämme neuvoa pidimme, ja vaelsimme Jumalan huoneesen joukossa.","Me jotka ystävällisesti keskenämme neuvoa pidimme, ja vaelsimme Jumalan huoneesen joukossa."],[55,15,"Langetkoon kuolema heidän päällensä, ja he menkään elävänä alas helvettiin; sillä sula pahuus on heidän asuinsioissansa heidän keskellänsä.","Langetkoon kuolema heidän päällensä, ja he menkään elävänä alas helvettiin; sillä sula pahuus on heidän asuinsioissansa heidän keskellänsä."],[55,16,"Mutta minä huudan Jumalan tykö; ja Herra auttaa minua.","Mutta minä huudan Jumalan tykö; ja Herra auttaa minua."],[55,17,"Ehtoona, aamulla ja puolipäivänä minä valitan ja itken; ja hän kuulee minun ääneni.","Ehtoona, aamulla ja puolipäivänä minä valitan ja itken; ja hän kuulee minun ääneni."],[55,18,"Hän lunastaa minun sieluni niistä, jotka sotivat minua vastaan, ja saattaa hänelle rauhan; sillä monta on minua vastaan.","Hän lunastaa minun sieluni niistä, jotka sotivat minua vastaan, ja saattaa hänelle rauhan; sillä monta on minua vastaan."],[55,19,"Jumala kuulkoon, ja heitä nöyryyttäköön, joka alusta ollut on, Sela! jotka ei paranna heitänsä, eikä pelkää Jumalaa.","Jumala kuulkoon, ja heitä nöyryyttäköön, joka alusta ollut on, Sela! jotka ei paranna heitänsä, eikä pelkää Jumalaa."],[55,20,"He laskevat kätensä hänen rauhallistensa päälle, ja turmelevat hänen liittonsa.","He laskevat kätensä hänen rauhallistensa päälle, ja turmelevat hänen liittonsa."],[55,21,"Heidän suunsa on liukkaampi kuin voi, ja sota on heidän sydämessänsä: heidän sanansa ovat sileämmät kuin öljy, ja ne ovat paljaat miekat.","Heidän suunsa on liukkaampi kuin voi, ja sota on heidän sydämessänsä: heidän sanansa ovat sileämmät kuin öljy, ja ne ovat paljaat miekat."],[55,22,"Heitä surus Herran päälle, hän sinusta murheen pitää, ja ei salli vanhurskaan olla kulkiana ijankaikkisesti.","Heitä surus Herran päälle, hän sinusta murheen pitää, ja ei salli vanhurskaan olla kulkiana ijankaikkisesti."],[55,23,"Mutta sinä, Jumala, syökset heitä syvään kuoppaan: murhamiehet ja pettäjät ei pidä tuleman puoli-ikäänsä; vaan minä toivon sinuun.","Mutta sinä, Jumala, syökset heitä syvään kuoppaan: murhamiehet ja pettäjät ei pidä tuleman puoli-ikäänsä; vaan minä toivon sinuun."],[56,1,"Davidin kultainen kappale mykästä mettisestä muukalaisten seassa, kuin Philistealaiset käsittivät hänen Gatissa. (H56:2) Jumala, ole minulle armollinen; sillä ihmiset tahtovat minua niellä ylös: joka päivä he sotivat ja ahdistavat minua.","Davidin kultainen kappale mykästä mettisestä muukalaisten seassa, kuin Philistealaiset käsittivät hänen Gatissa. (H56:2) Jumala, ole minulle armollinen; sillä ihmiset tahtovat minua niellä ylös: joka päivä he sotivat ja ahdistavat minua."],[56,2,"Minun kadehtiani tahtovat joka päivä minua niellä ylös; sillä moni sotii ylpiästi minua vastaan.","Minun kadehtiani tahtovat joka päivä minua niellä ylös; sillä moni sotii ylpiästi minua vastaan."],[56,3,"Kuin minä pelkään, niin minä toivon sinuun.","Kuin minä pelkään, niin minä toivon sinuun."],[56,4,"Jumalassa minä kerskaan hänen sanaansa: Jumalaan minä toivon, en minä pelkää: mitä liha minun tekis?","Jumalassa minä kerskaan hänen sanaansa: Jumalaan minä toivon, en minä pelkää: mitä liha minun tekis?"],[56,5,"Joka päivä he minun sanojani kääntelevät; kaikki heidän ajatuksensa ovat pahuuteen minua vastaan.","Joka päivä he minun sanojani kääntelevät; kaikki heidän ajatuksensa ovat pahuuteen minua vastaan."],[56,6,"He pitävät yhtä, ja väijyvät, ja ottavat minun askeleistani vaarin, kuinka he minun sieluni käsittäisivät.","He pitävät yhtä, ja väijyvät, ja ottavat minun askeleistani vaarin, kuinka he minun sieluni käsittäisivät."],[56,7,"Pitäiskö heidän vääryydestänsä pääsemän? Syökse, Jumala, se kansa alas vihassas.","Pitäiskö heidän vääryydestänsä pääsemän? Syökse, Jumala, se kansa alas vihassas."],[56,8,"Sinä olet lukenut minun kulkemukseni: sinä panet minun kyyneleeni leiliis: eikö ne ole sinun kirjassas?","Sinä olet lukenut minun kulkemukseni: sinä panet minun kyyneleeni leiliis: eikö ne ole sinun kirjassas?"],[56,9,"Silloin pitää viholliseni kääntämän heitänsä takaperin, sinä päivänä, kuin minä huudan: sen minä tiedän, ettäs minun Jumalani olet.","Silloin pitää viholliseni kääntämän heitänsä takaperin, sinä päivänä, kuin minä huudan: sen minä tiedän, ettäs minun Jumalani olet."],[56,10,"Jumalassa minä kerskaan hänen sanaansa: Herrassa minä kerskaan hänen sanaansa.","Jumalassa minä kerskaan hänen sanaansa: Herrassa minä kerskaan hänen sanaansa."],[56,11,"Jumalaan minä toivon, en minä pelkää: mitä ihminen tekis?","Jumalaan minä toivon, en minä pelkää: mitä ihminen tekis?"],[56,12,"Minä olen sinulle, Jumala, luvannut, minä tahdon sinua kiittää.","Minä olen sinulle, Jumala, luvannut, minä tahdon sinua kiittää."],[56,13,"Sillä sinä olet pelastanut minun sieluni kuolemasta, minun jalkani lankeemisesta; että minä vaeltaisin Jumalan edessä eläväin valkeudessa.","Sillä sinä olet pelastanut minun sieluni kuolemasta, minun jalkani lankeemisesta; että minä vaeltaisin Jumalan edessä eläväin valkeudessa."],[57,1,"Davidin kultainen kappale, edelläveisaajalle, ettei hän hukkunut, kuin hän Saulin edestä pakeni luolaan. (H57:2) Jumala, ole minulle armollinen, ole minulle armollinen; sillä sinuun minun sieluni uskaltaa, ja sinun siipeis varjon alle minä turvaan siihenasti, että ahdistukset ohitse käyvät.","Davidin kultainen kappale, edelläveisaajalle, ettei hän hukkunut, kuin hän Saulin edestä pakeni luolaan. (H57:2) Jumala, ole minulle armollinen, ole minulle armollinen; sillä sinuun minun sieluni uskaltaa, ja sinun siipeis varjon alle minä turvaan siihenasti, että ahdistukset ohitse käyvät."],[57,2,"Minä huudan korkeimman Jumalan tykö, sen Jumalan tykö, joka minun vaivani päälle lopun tekee.","Minä huudan korkeimman Jumalan tykö, sen Jumalan tykö, joka minun vaivani päälle lopun tekee."],[57,3,"Hän lähettää taivaasta, ja varjelee minua, ja antaa ne häpiään tulla, jotka minua tahtovat niellä ylös, Sela! lähettäköön Jumala armonsa ja totuutensa.","Hän lähettää taivaasta, ja varjelee minua, ja antaa ne häpiään tulla, jotka minua tahtovat niellä ylös, Sela! lähettäköön Jumala armonsa ja totuutensa."],[57,4,"Minun sieluni makaa jalopeurain keskellä, jotka ovat niinkuin tulen liekki; ihmisten lapset, joiden hampaat ovat keihäs ja nuolet, ja heidän kielensä terävä miekka.","Minun sieluni makaa jalopeurain keskellä, jotka ovat niinkuin tulen liekki; ihmisten lapset, joiden hampaat ovat keihäs ja nuolet, ja heidän kielensä terävä miekka."],[57,5,"Korota itses, Jumala, taivasten ylitse ja sinun kunnias ylitse kaiken maan.","Korota itses, Jumala, taivasten ylitse ja sinun kunnias ylitse kaiken maan."],[57,6,"Verkon he virittivät minun käymiseni eteen, ja minun sieluni vältti: kuopan he kaivoivat minun eteeni, ja siihen he itse lankesivat, Sela!","Verkon he virittivät minun käymiseni eteen, ja minun sieluni vältti: kuopan he kaivoivat minun eteeni, ja siihen he itse lankesivat, Sela!"],[57,7,"Valmis on sydämeni, Jumala, valmis on sydämeni veisaamaan ja kiittämään.","Valmis on sydämeni, Jumala, valmis on sydämeni veisaamaan ja kiittämään."],[57,8,"Herää kunniani, herää psaltari ja kantele, varhain minä tahdon herätä.","Herää kunniani, herää psaltari ja kantele, varhain minä tahdon herätä."],[57,9,"Herra, sinua minä tahdon kiittää kansain seassa, ja veisata pakanain seassa.","Herra, sinua minä tahdon kiittää kansain seassa, ja veisata pakanain seassa."],[57,10,"Sillä sinun armos on suuri hamaan taivaisiin asti, ja sinun totuutes pilviin asti.","Sillä sinun armos on suuri hamaan taivaisiin asti, ja sinun totuutes pilviin asti."],[57,11,"Korota itses, Jumala, taivasten ylitse, ja sinun kunnias ylitse kaiken maan.","Korota itses, Jumala, taivasten ylitse, ja sinun kunnias ylitse kaiken maan."],[58,1,"Davidin kultainen kappale, edelläveisaajalle, ettei hän hukkunut. (H58:2) Oletteko te juuri niin mykät, ettette puhu sitä mikä oikeus on, ettekä tuomitse, mikä kohtuus on, te ihmisten lapset?","Davidin kultainen kappale, edelläveisaajalle, ettei hän hukkunut. (H58:2) Oletteko te juuri niin mykät, ettette puhu sitä mikä oikeus on, ettekä tuomitse, mikä kohtuus on, te ihmisten lapset?"],[58,2,"Sydämestänne te myös vääryyttä teette, ja maakunnassa käsillänne väkivaltaa toimitatte.","Sydämestänne te myös vääryyttä teette, ja maakunnassa käsillänne väkivaltaa toimitatte."],[58,3,"Jumalattomat ovat kääntyneet pois jo äitinsä kohdusta, valhetteliat ovat eksyneet hamasta äitinsä kohdusta.","Jumalattomat ovat kääntyneet pois jo äitinsä kohdusta, valhetteliat ovat eksyneet hamasta äitinsä kohdusta."],[58,4,"Heidän kiukkunsa on niinkuin kärmeen kiukku, niinkuin kuuron kyykärmeen, joka korvansa tukitsee,","Heidän kiukkunsa on niinkuin kärmeen kiukku, niinkuin kuuron kyykärmeen, joka korvansa tukitsee,"],[58,5,"Ettei hän kuulisi lumojain ääntä, sen joka viisaasti lumota taitaa.","Ettei hän kuulisi lumojain ääntä, sen joka viisaasti lumota taitaa."],[58,6,"Jumala, särje heidän hampaansa heidän suuhunsa: murenna, Herra, nuorten jalopeurain syömähampaat.","Jumala, särje heidän hampaansa heidän suuhunsa: murenna, Herra, nuorten jalopeurain syömähampaat."],[58,7,"Heidän pitää sulaman niinkuin vesi: he ampuvat nuolillansa, mutta ne käyvät rikki.","Heidän pitää sulaman niinkuin vesi: he ampuvat nuolillansa, mutta ne käyvät rikki."],[58,8,"He hukkuvat, niinkuin näkin kota raukee, niinkuin vaimon keskeneräinen, eikä saa nähdä aurinkoa.","He hukkuvat, niinkuin näkin kota raukee, niinkuin vaimon keskeneräinen, eikä saa nähdä aurinkoa."],[58,9,"Ennenkuin teidän orjantappuranne puuksi kasvavat, niin pitää vihan heitä elävänä repäisemän pois.","Ennenkuin teidän orjantappuranne puuksi kasvavat, niin pitää vihan heitä elävänä repäisemän pois."],[58,10,"Vanhurskaan pitää iloitseman, koska hän koston näkee, ja pesemän jalkansa jumalattoman veressä,","Vanhurskaan pitää iloitseman, koska hän koston näkee, ja pesemän jalkansa jumalattoman veressä,"],[58,11,"Että jokaisen pitää sanoman: vanhurskaalla on kuitenkin hedelmä; Jumala on kuitenkin se, joka tuomitsee maan päällä.","Että jokaisen pitää sanoman: vanhurskaalla on kuitenkin hedelmä; Jumala on kuitenkin se, joka tuomitsee maan päällä."],[59,1,"Davidin kultainen kappale, ettei hän hukkunut, kuin Saul lähetti hänen huonettansa piirittämään, saadaksensa häntä tappaa. (H59:2) Pelasta minua vihollisistani, Jumala, ja varjele minua niistä, jotka itseänsä asettavat minua vastaan.","Davidin kultainen kappale, ettei hän hukkunut, kuin Saul lähetti hänen huonettansa piirittämään, saadaksensa häntä tappaa. (H59:2) Pelasta minua vihollisistani, Jumala, ja varjele minua niistä, jotka itseänsä asettavat minua vastaan."],[59,2,"Pelasta minua pahointekiöistä, ja auta minua murhamiehistä;","Pelasta minua pahointekiöistä, ja auta minua murhamiehistä;"],[59,3,"Sillä katso, Herra, he väijyvät sieluani: väkevät kokoontuvat minua vastaan, ilman minun syytäni ja rikostani.","Sillä katso, Herra, he väijyvät sieluani: väkevät kokoontuvat minua vastaan, ilman minun syytäni ja rikostani."],[59,4,"He juoksevat ilman syytä, ja valmistavat itseänsä: nouse tulemaan minua vastaan ja katsomaan.","He juoksevat ilman syytä, ja valmistavat itseänsä: nouse tulemaan minua vastaan ja katsomaan."],[59,5,"Ja sinä, Herra Jumala Zebaot, Israelin Jumala, herää etsimään kaikkia pakanoita: älä ketään heistä armahda, jotka niin väkivaltaisesti vääryyttä tekevät, Sela!","Ja sinä, Herra Jumala Zebaot, Israelin Jumala, herää etsimään kaikkia pakanoita: älä ketään heistä armahda, jotka niin väkivaltaisesti vääryyttä tekevät, Sela!"],[59,6,"He tulkoon taas ehtoona, ja ulvokaan niinkuin koira, ja samotkaan ympäri kaupungin.","He tulkoon taas ehtoona, ja ulvokaan niinkuin koira, ja samotkaan ympäri kaupungin."],[59,7,"Katso, he puhuvat suullansa: miekat ovat heidän huulissansa, kuka sen kuulis.","Katso, he puhuvat suullansa: miekat ovat heidän huulissansa, kuka sen kuulis."],[59,8,"Mutta sinä, Herra, naurat heitä, ja pilkkaat kaikkia pakanoita.","Mutta sinä, Herra, naurat heitä, ja pilkkaat kaikkia pakanoita."],[59,9,"Heidän väkevyytensä edestä minä turvaan sinun tykös; sillä Jumala on minun varjelukseni.","Heidän väkevyytensä edestä minä turvaan sinun tykös; sillä Jumala on minun varjelukseni."],[59,10,"Jumala osoittaa minulle runsaasti laupiutensa, Jumala antaa minun nähdä koston vihollisistani.","Jumala osoittaa minulle runsaasti laupiutensa, Jumala antaa minun nähdä koston vihollisistani."],[59,11,"Älä heitä tapa, ettei minun kansani sitä unohtaisi: hajoita heitä voimallas, ja lyö heitä maahan, Herra meidän kilpemme.","Älä heitä tapa, ettei minun kansani sitä unohtaisi: hajoita heitä voimallas, ja lyö heitä maahan, Herra meidän kilpemme."],[59,12,"Heidän huultensa puhe on heidän suunsa synti: ja he käsitetään ylpeydessänsä: ja he juttelevat kirouksia ja valhetta.","Heidän huultensa puhe on heidän suunsa synti: ja he käsitetään ylpeydessänsä: ja he juttelevat kirouksia ja valhetta."],[59,13,"Pyyhi heitä pois vihassas, pyyhi heitä pois, ettei he olisikaan; että he ymmärtäisivät sen, että Jumala hallitsee Jakobissa, hamaan maailman ääriin asti, Sela!","Pyyhi heitä pois vihassas, pyyhi heitä pois, ettei he olisikaan; että he ymmärtäisivät sen, että Jumala hallitsee Jakobissa, hamaan maailman ääriin asti, Sela!"],[59,14,"He tulkoon taas ehtoona, ja ulvokaan niinkuin koira, ja samotkaan ympäri kaupungin.","He tulkoon taas ehtoona, ja ulvokaan niinkuin koira, ja samotkaan ympäri kaupungin."],[59,15,"Anna heidän juosta sinne ja tänne ruoan tähden; ja ulvokaan, koska ei he ravituksi tule.","Anna heidän juosta sinne ja tänne ruoan tähden; ja ulvokaan, koska ei he ravituksi tule."],[59,16,"Mutta minä veisaan sinun väkevyyttäs, ja varhain kerskaan sinun laupiuttas; sillä sinä olet minun varjelukseni ja turvani minun hädässäni.","Mutta minä veisaan sinun väkevyyttäs, ja varhain kerskaan sinun laupiuttas; sillä sinä olet minun varjelukseni ja turvani minun hädässäni."],[59,17,"Sinä olet minun väkevyyteni, sinulle minä kiitosta veisaan; sillä sinä Jumala olet minun varjelukseni ja minun armollinen Jumalani.","Sinä olet minun väkevyyteni, sinulle minä kiitosta veisaan; sillä sinä Jumala olet minun varjelukseni ja minun armollinen Jumalani."],[60,1,"Davidin kultainen kappale, edelläveisaajalle, kultaisesta seppeleen kukkaisesta opettamaan, (H60:2) Kuin hän oli sotinut Syrialaisten kanssa Mesopotamiasta, ja Zoban Syrialaisten kanssa; kuin Joab palasi, ja löi Suolalaaksossa kaksitoistakymmentä tuhatta Edomilaista. (H60:3) Jumala, sinä joka olet meitä lykännyt pois, hajoittanut meitä ja ollut vihainen, palaja taas meidän tykömme.","Davidin kultainen kappale, edelläveisaajalle, kultaisesta seppeleen kukkaisesta opettamaan, (H60:2) Kuin hän oli sotinut Syrialaisten kanssa Mesopotamiasta, ja Zoban Syrialaisten kanssa; kuin Joab palasi, ja löi Suolalaaksossa kaksitoistakymmentä tuhatta Edomilaista. (H60:3) Jumala, sinä joka olet meitä lykännyt pois, hajoittanut meitä ja ollut vihainen, palaja taas meidän tykömme."],[60,2,"Sinä joka maan liikuttanut ja halaissut olet, paranna hänen rakonsa, joka niin haljennut on.","Sinä joka maan liikuttanut ja halaissut olet, paranna hänen rakonsa, joka niin haljennut on."],[60,3,"Sinä olet kansalles kovuutta osoittanut, ja meitä kompastuksen viinalla juottanut.","Sinä olet kansalles kovuutta osoittanut, ja meitä kompastuksen viinalla juottanut."],[60,4,"Sinä annoit lipun niille, jotka sinua pelkäävät, jolla he itsensä ojensivat ylös, totuuden tähden, Sela!","Sinä annoit lipun niille, jotka sinua pelkäävät, jolla he itsensä ojensivat ylös, totuuden tähden, Sela!"],[60,5,"Että sinun ystäväs vapahdetuksi tulisivat: niin auta nyt oikialla kädelläs, ja kuule meidän rukouksemme.","Että sinun ystäväs vapahdetuksi tulisivat: niin auta nyt oikialla kädelläs, ja kuule meidän rukouksemme."],[60,6,"Jumala on puhunut pyhässänsä, siitä minä iloitsen: minä tahdon jakaa Sikemin ja mitata Sukkotin laakson.","Jumala on puhunut pyhässänsä, siitä minä iloitsen: minä tahdon jakaa Sikemin ja mitata Sukkotin laakson."],[60,7,"Gilead on minun, minun on Manasse, Ephrain on minun pääni voima: Juuda on minulle lainopettaja.","Gilead on minun, minun on Manasse, Ephrain on minun pääni voima: Juuda on minulle lainopettaja."],[60,8,"Moab on minun pesinpatani, Edomin ylitse heitän minä kenkäni: sinä Philistea, iloitse minusta.","Moab on minun pesinpatani, Edomin ylitse heitän minä kenkäni: sinä Philistea, iloitse minusta."],[60,9,"Kuka vie minun vahvaan kaupunkiin? kuka johdattaa minun Edomiin?","Kuka vie minun vahvaan kaupunkiin? kuka johdattaa minun Edomiin?"],[60,10,"Etkös sinä, Jumala, joka meitä lykkäsit pois? ja etkö sinä, Jumala, lähde ulos meidän sotaväkemme kanssa?","Etkös sinä, Jumala, joka meitä lykkäsit pois? ja etkö sinä, Jumala, lähde ulos meidän sotaväkemme kanssa?"],[60,11,"Saata meille apu tuskasta; sillä ihmisten apu on turha.","Saata meille apu tuskasta; sillä ihmisten apu on turha."],[60,12,"Jumalassa tahdomme me voimalliset työt tehdä: ja hän tallaa alas meidän vihollisemme.","Jumalassa tahdomme me voimalliset työt tehdä: ja hän tallaa alas meidän vihollisemme."],[61,1,"Davidin Psalmi, edelläveisaajalle, kanteleilla. (H61:2) Kuule, Jumala, minun huutoni: ota vaari minun rukouksestani.","Davidin Psalmi, edelläveisaajalle, kanteleilla. (H61:2) Kuule, Jumala, minun huutoni: ota vaari minun rukouksestani."],[61,2,"Maan äärestä minä huudan sinun tykös, koska minun sydämeni näännyksissä on: vie minua siis korkialle kalliolle.","Maan äärestä minä huudan sinun tykös, koska minun sydämeni näännyksissä on: vie minua siis korkialle kalliolle."],[61,3,"Sillä sinä olet minun turvani, vahva torni vihollisten edessä.","Sillä sinä olet minun turvani, vahva torni vihollisten edessä."],[61,4,"Minä tahdon asua sinun majassas ijankaikkisesti, ja uskaltaa sinun siipeis varjon alle, Sela!","Minä tahdon asua sinun majassas ijankaikkisesti, ja uskaltaa sinun siipeis varjon alle, Sela!"],[61,5,"Sillä sinä, Jumala, kuulet minun lupaukseni, ja annat perinnön niille, jotka sinun nimeäs pelkäävät.","Sillä sinä, Jumala, kuulet minun lupaukseni, ja annat perinnön niille, jotka sinun nimeäs pelkäävät."],[61,6,"Sinä annat kuninkaalle pitkän ijän, että hänen vuotensa olisivat suvusta sukuun.","Sinä annat kuninkaalle pitkän ijän, että hänen vuotensa olisivat suvusta sukuun."],[61,7,"Että hän alati pysyis Jumalan edessä: osoita hänelle laupiutta ja totuutta, jotka häntä varjelisivat.","Että hän alati pysyis Jumalan edessä: osoita hänelle laupiutta ja totuutta, jotka häntä varjelisivat."],[61,8,"Niin minä veisaan kiitosta sinun nimelles ijankaikkisesti, maksaakseni minun lupaustani päivä päivältä.","Niin minä veisaan kiitosta sinun nimelles ijankaikkisesti, maksaakseni minun lupaustani päivä päivältä."],[62,1,"Davidin Psalmi Jedutunin edestä, edelläveisaajalle. (H62:2) Minun sieluni odottaa ainoastaan Jumalaa, joka minua auttaa.","Davidin Psalmi Jedutunin edestä, edelläveisaajalle. (H62:2) Minun sieluni odottaa ainoastaan Jumalaa, joka minua auttaa."],[62,2,"Hän ainoastaan on kallioni, minun autuuteni, minun varjelukseni, etten minä kovin kompastuisi.","Hän ainoastaan on kallioni, minun autuuteni, minun varjelukseni, etten minä kovin kompastuisi."],[62,3,"Kuinka kauvan te yhtä väijytte, että te kaikin häntä surmaatte, niinkuin kallistuvaa seinää ja raukeevaa muuria?","Kuinka kauvan te yhtä väijytte, että te kaikin häntä surmaatte, niinkuin kallistuvaa seinää ja raukeevaa muuria?"],[62,4,"Kuitenkin he neuvoa pitävät, kukistaaksensa häntä korkeudestansa; he rakastavat valhetta: suullansa he siunaavat, ja sydämessänsä kiroilevat, Sela!","Kuitenkin he neuvoa pitävät, kukistaaksensa häntä korkeudestansa; he rakastavat valhetta: suullansa he siunaavat, ja sydämessänsä kiroilevat, Sela!"],[62,5,"Minun sieluni odottaa ainoastaan Jumalaa; sillä hän on minun toivoni.","Minun sieluni odottaa ainoastaan Jumalaa; sillä hän on minun toivoni."],[62,6,"Hän ainoastaan on kallioni ja autuuteni, hän varjelukseni, en minä kaadu.","Hän ainoastaan on kallioni ja autuuteni, hän varjelukseni, en minä kaadu."],[62,7,"Jumalassa on minun autuuteni, minun kunniani, minun väkevyyteni kallio, minun turvani on Jumalassa.","Jumalassa on minun autuuteni, minun kunniani, minun väkevyyteni kallio, minun turvani on Jumalassa."],[62,8,"Te kansat, toivokaat häneen joka aika, vuodattakaat teidän sydämenne hänen eteensä: Jumala on meidän turvamme, Sela!","Te kansat, toivokaat häneen joka aika, vuodattakaat teidän sydämenne hänen eteensä: Jumala on meidän turvamme, Sela!"],[62,9,"Mutta ihmiset ovat kuitenkin turhat, voimalliset myös puuttuvat: he painavat vähemmän kuin ei mitään, niin monta kuin heitä on.","Mutta ihmiset ovat kuitenkin turhat, voimalliset myös puuttuvat: he painavat vähemmän kuin ei mitään, niin monta kuin heitä on."],[62,10,"Älkäät luottako vääryyteen ja väkivaltaan; älkäät turvatko niihin, mitkä ei mitään ole; jos rikkaudet teidän tykönne lankeevat, niin älkäät panko sydäntänne niiden päälle.","Älkäät luottako vääryyteen ja väkivaltaan; älkäät turvatko niihin, mitkä ei mitään ole; jos rikkaudet teidän tykönne lankeevat, niin älkäät panko sydäntänne niiden päälle."],[62,11,"Jumala on kerran puhunut, sen olen minä kahdesti kuullut: että Jumala (yksinänsä) väkevä on.","Jumala on kerran puhunut, sen olen minä kahdesti kuullut: että Jumala (yksinänsä) väkevä on."],[62,12,"Ja sinä Jumala olet armollinen; sillä sinä maksat jokaiselle työnsä jälkeen.","Ja sinä Jumala olet armollinen; sillä sinä maksat jokaiselle työnsä jälkeen."],[63,1,"Davidin Psalmi, kuin hän oli Juudan korvessa. (H63:2) Jumala, sinä olet minun Jumalani! Varhain minä sinua etsin: sinua minun sieluni janoo, minun lihani halaa sinua karkiassa ja kuivassa maassa, joka vedetöin on.","Davidin Psalmi, kuin hän oli Juudan korvessa. (H63:2) Jumala, sinä olet minun Jumalani! Varhain minä sinua etsin: sinua minun sieluni janoo, minun lihani halaa sinua karkiassa ja kuivassa maassa, joka vedetöin on."],[63,2,"Niinkuin minä näin sinun pyhässä, katsellakseni sinun voimaas ja kunniaas;","Niinkuin minä näin sinun pyhässä, katsellakseni sinun voimaas ja kunniaas;"],[63,3,"Sillä sinun laupiutes on parempi kuin elämä: minun huuleni pitää sinua kiittämän.","Sillä sinun laupiutes on parempi kuin elämä: minun huuleni pitää sinua kiittämän."],[63,4,"Niin minä tahdon kunnioittaa sinua minun elinaikanani, ja minun käteni nostaa ylös sinun nimees.","Niin minä tahdon kunnioittaa sinua minun elinaikanani, ja minun käteni nostaa ylös sinun nimees."],[63,5,"Niinkuin lihavuudella ja rasvalla pitää minun sieluni ravittaman: ja minun suuni pitää kiittämän iloisilla huulilla.","Niinkuin lihavuudella ja rasvalla pitää minun sieluni ravittaman: ja minun suuni pitää kiittämän iloisilla huulilla."],[63,6,"Kuin minä vuoteeseni lasken, niin minä muistan sinua:kuin minä herään, niin minä puhun sinusta.","Kuin minä vuoteeseni lasken, niin minä muistan sinua:kuin minä herään, niin minä puhun sinusta."],[63,7,"Sillä sinä olet minun apuni, ja sinun siipeis varjon alla minä kerskaan.","Sillä sinä olet minun apuni, ja sinun siipeis varjon alla minä kerskaan."],[63,8,"Minun sieluni riippuu sinussa: sinun oikia kätes minun tukee.","Minun sieluni riippuu sinussa: sinun oikia kätes minun tukee."],[63,9,"Mutta he etsivät kadottaaksensa minun sieluni: heidän täytyy maan alle mennä.","Mutta he etsivät kadottaaksensa minun sieluni: heidän täytyy maan alle mennä."],[63,10,"Heidän pitää miekkaan lankeeman, ketuille osaksi tuleman.","Heidän pitää miekkaan lankeeman, ketuille osaksi tuleman."],[63,11,"Mutta kuninkaan pitää iloitseman Jumalassa: joka hänen kauttansa vannoo, se kunnioitetaan; sillä valhetteliain suu pitää tukittaman.","Mutta kuninkaan pitää iloitseman Jumalassa: joka hänen kauttansa vannoo, se kunnioitetaan; sillä valhetteliain suu pitää tukittaman."],[64,1,"Davidin Psalmi, edelläveisaajalle. (H64:2) Kuule, Jumala, ääntäni, minun valituksessani: varjele elämäni vihollisen pelvosta.","Davidin Psalmi, edelläveisaajalle. (H64:2) Kuule, Jumala, ääntäni, minun valituksessani: varjele elämäni vihollisen pelvosta."],[64,2,"Peitä minua pahain neuvosta, väärintekiäin metelistä,","Peitä minua pahain neuvosta, väärintekiäin metelistä,"],[64,3,"Jotka kielensä hiovat niinkuin miekan: he ampuvat myrkyllisillä sanoillansa niinkuin nuolilla;","Jotka kielensä hiovat niinkuin miekan: he ampuvat myrkyllisillä sanoillansa niinkuin nuolilla;"],[64,4,"Että he salaisesti ampuisivat viatointa: he ampuvat häntä äkisti ilman pelvota.","Että he salaisesti ampuisivat viatointa: he ampuvat häntä äkisti ilman pelvota."],[64,5,"He vahvistavat itsensä pahoissa juonissansa ja puhuvat, kuinka he paulat virittäisivät, ja sanovat: kuka taitaa ne nähdä?","He vahvistavat itsensä pahoissa juonissansa ja puhuvat, kuinka he paulat virittäisivät, ja sanovat: kuka taitaa ne nähdä?"],[64,6,"He ajattelevat vääryyttä, ja täyttävät sen minkä he ajatelleet ovat; viekkaat ihmiset ja salakavalat sydämet.","He ajattelevat vääryyttä, ja täyttävät sen minkä he ajatelleet ovat; viekkaat ihmiset ja salakavalat sydämet."],[64,7,"Mutta Jumala ampuu heitä; äkillinen nuoli on heidän rangaistuksensa.","Mutta Jumala ampuu heitä; äkillinen nuoli on heidän rangaistuksensa."],[64,8,"Heidän oma kielensä pitää heitä langettaman, että jokainen, joka heidät näkee, pakenee heitä.","Heidän oma kielensä pitää heitä langettaman, että jokainen, joka heidät näkee, pakenee heitä."],[64,9,"Ja kaikkein ihmisten pitää pelkäämän, ja Jumalan työtä ilmoittaman, ja hänen työnsä ymmärtämän.","Ja kaikkein ihmisten pitää pelkäämän, ja Jumalan työtä ilmoittaman, ja hänen työnsä ymmärtämän."],[64,10,"Vanhurskaat pitää Herrassa riemuitseman, ja häneen uskaltaman; ja kaikki vaat sydämet kerskatkoon siitä.","Vanhurskaat pitää Herrassa riemuitseman, ja häneen uskaltaman; ja kaikki vaat sydämet kerskatkoon siitä."],[65,1,"Davidin Psalmi ja veisu, edelläveisaajalle. (H65:2) Jumala, sinua kiitetään Zionissa hiljaisuudessa; ja sinulle maksetaan lupaus.","Davidin Psalmi ja veisu, edelläveisaajalle. (H65:2) Jumala, sinua kiitetään Zionissa hiljaisuudessa; ja sinulle maksetaan lupaus."],[65,2,"Sinä kuulet rukouksen; sentähden tulee kaikki liha sinun tykös.","Sinä kuulet rukouksen; sentähden tulee kaikki liha sinun tykös."],[65,3,"Meidän pahat tekomme meitä kovin raskauttavat; mutta anna sinä meille synnit anteeksi.","Meidän pahat tekomme meitä kovin raskauttavat; mutta anna sinä meille synnit anteeksi."],[65,4,"Autuas on se, jonkas valitset ja otat tykös, asumaan kartanoissas: hän ravitaan sinun huonees ja pyhän templis hyvyydestä.","Autuas on se, jonkas valitset ja otat tykös, asumaan kartanoissas: hän ravitaan sinun huonees ja pyhän templis hyvyydestä."],[65,5,"Kuule meitä ihmeellisestä vanhurskaudesta, meidän autuutemme Jumala, kaikkein turva maan päällä ja kaukana meressä,","Kuule meitä ihmeellisestä vanhurskaudesta, meidän autuutemme Jumala, kaikkein turva maan päällä ja kaukana meressä,"],[65,6,"Joka vuoret vahvistat voimallas, ja olet hankittu väkevyydellä,","Joka vuoret vahvistat voimallas, ja olet hankittu väkevyydellä,"],[65,7,"Sinä joka asetat meren pauhinan ja hänen aaltoinsa pauhinan, ja kansain metelin;","Sinä joka asetat meren pauhinan ja hänen aaltoinsa pauhinan, ja kansain metelin;"],[65,8,"Että ne hämmästyisivät, jotka niissä maan äärissä asuvat, sinun ihmeitäs. Sinä iloitat kaikki liikkuvaiset aamulla ja ehtoona.","Että ne hämmästyisivät, jotka niissä maan äärissä asuvat, sinun ihmeitäs. Sinä iloitat kaikki liikkuvaiset aamulla ja ehtoona."],[65,9,"Sinä etsiskelet maan ja liotat sen ja teet sen ylen rikkaaksi: Jumalan virta on vettä täynnä: sinä kasvatat heidän jyvänsä, ettäs näin maan valmistat.","Sinä etsiskelet maan ja liotat sen ja teet sen ylen rikkaaksi: Jumalan virta on vettä täynnä: sinä kasvatat heidän jyvänsä, ettäs näin maan valmistat."],[65,10,"Sinä juotat hänen vakonsa ja kastat hänen kyntönsä: sateella sinä ne pehmität, ja siunaat hänen laihonsa.","Sinä juotat hänen vakonsa ja kastat hänen kyntönsä: sateella sinä ne pehmität, ja siunaat hänen laihonsa."],[65,11,"Sinä kaunistat vuoden hyvyydelläs, ja sinun askelees tiukkuvat rasvasta.","Sinä kaunistat vuoden hyvyydelläs, ja sinun askelees tiukkuvat rasvasta."],[65,12,"Korven laitumet myös tiukkuvat, ja kukkulat ovat ympäri iloissansa.","Korven laitumet myös tiukkuvat, ja kukkulat ovat ympäri iloissansa."],[65,13,"Kedot ovat laumaa täynnä, ja laaksossa on tihkiältä jyviä, niin että siitä ihastutaan ja myös lauletaan.","Kedot ovat laumaa täynnä, ja laaksossa on tihkiältä jyviä, niin että siitä ihastutaan ja myös lauletaan."],[66,1,"Davidin Psalmi ja veisu, edelläveisaajalle. Ihastukaa Jumalalle, kaikki maa.","Davidin Psalmi ja veisu, edelläveisaajalle. Ihastukaa Jumalalle, kaikki maa."],[66,2,"Veisatkaat kiitosta hänen nimensä kunniaksi, ylistäkäät häntä suuresti.","Veisatkaat kiitosta hänen nimensä kunniaksi, ylistäkäät häntä suuresti."],[66,3,"Sanokaat Jumalalle: kuinka ihmeelliset ovat sinun työs! sinun vihollisiltas pitää puuttuman, sinun suuren väkes tähden.","Sanokaat Jumalalle: kuinka ihmeelliset ovat sinun työs! sinun vihollisiltas pitää puuttuman, sinun suuren väkes tähden."],[66,4,"Kaikki maa kumartakoon sinua, ja veisatkaan kiitosta sinun nimelles, Sela!","Kaikki maa kumartakoon sinua, ja veisatkaan kiitosta sinun nimelles, Sela!"],[66,5,"Tulkaat ja katsokaat Jumalan tekoja, joka niin ihmeellinen on töissänsä ihmisten lasten seassa.","Tulkaat ja katsokaat Jumalan tekoja, joka niin ihmeellinen on töissänsä ihmisten lasten seassa."],[66,6,"Hän muuttaa meren kuivaksi, niin että jalkaisin käydään veden ylitse: siitä me hänessä iloitsemme.","Hän muuttaa meren kuivaksi, niin että jalkaisin käydään veden ylitse: siitä me hänessä iloitsemme."],[66,7,"Hän hallitsee voimansa kautta ijankaikkisesti, hänen silmänsä katselevat kansoja: eripuraiset ei pidä voiman korottaa itseänsä, Sela!","Hän hallitsee voimansa kautta ijankaikkisesti, hänen silmänsä katselevat kansoja: eripuraiset ei pidä voiman korottaa itseänsä, Sela!"],[66,8,"Kiittäkäät te pakanat, meidän Jumalaamme: kajahtakaan hänen kiitoksensa ääni kauvas,","Kiittäkäät te pakanat, meidän Jumalaamme: kajahtakaan hänen kiitoksensa ääni kauvas,"],[66,9,"Joka meidän sielumme elättää, eikä salli jalkamme liukastella.","Joka meidän sielumme elättää, eikä salli jalkamme liukastella."],[66,10,"Sillä sinä, Jumala, olet meitä koetellut, ja valanut meitä niinkuin hopia valetaan.","Sillä sinä, Jumala, olet meitä koetellut, ja valanut meitä niinkuin hopia valetaan."],[66,11,"Sinä veit meitä vankeuteen, ja panit kuorman meidän lanteillemme.","Sinä veit meitä vankeuteen, ja panit kuorman meidän lanteillemme."],[66,12,"Sinä olet antanut ihmiset meidän päämme päällitse mennä: me olemme tuleen ja veteen tulleet, mutta sinä veit meitä ulos, ja virvoitit.","Sinä olet antanut ihmiset meidän päämme päällitse mennä: me olemme tuleen ja veteen tulleet, mutta sinä veit meitä ulos, ja virvoitit."],[66,13,"Sentähden minä menen polttouhrilla sinun huoneeses, ja maksan sinulle lupaukseni,","Sentähden minä menen polttouhrilla sinun huoneeses, ja maksan sinulle lupaukseni,"],[66,14,"Joita minun huuleni lupasivat, ja minun suuni puhunut on tuskassani.","Joita minun huuleni lupasivat, ja minun suuni puhunut on tuskassani."],[66,15,"Lihavat polttouhrit minä teen sinulle oinasten suitsutuksella: minä uhraan sinulle naudat kauristen kanssa, Sela!","Lihavat polttouhrit minä teen sinulle oinasten suitsutuksella: minä uhraan sinulle naudat kauristen kanssa, Sela!"],[66,16,"Tulkaat, kuulkaat te kaikki, jotka Jumalaa pelkäätte: minä ilmoitan, mitä hän minun sielulleni on tehnyt.","Tulkaat, kuulkaat te kaikki, jotka Jumalaa pelkäätte: minä ilmoitan, mitä hän minun sielulleni on tehnyt."],[66,17,"Häntä minä suullani huusin, ja ylistin kielelläni.","Häntä minä suullani huusin, ja ylistin kielelläni."],[66,18,"Jos minä jotakin vääryyttä pitäisin sydämessäni, niin ei Herra minua kuulisi.","Jos minä jotakin vääryyttä pitäisin sydämessäni, niin ei Herra minua kuulisi."],[66,19,"Sentähden Jumala on minua kuullut, ja ottanut vaarin minun rukoukseni äänestä.","Sentähden Jumala on minua kuullut, ja ottanut vaarin minun rukoukseni äänestä."],[66,20,"Kiitetty olkoon Jumala, joka ei hylkää rukoustani, eikä käännä laupiuttansa pois minusta!","Kiitetty olkoon Jumala, joka ei hylkää rukoustani, eikä käännä laupiuttansa pois minusta!"],[67,1,"Psalmi ja veisu, edelläveisaajalle, kanteleilla. (H67:2) Jumala olkoon meille armollinen, ja siunatkoon meitä! hän valistakoon kasvonsa aina meidän päällemme, Sela!","Psalmi ja veisu, edelläveisaajalle, kanteleilla. (H67:2) Jumala olkoon meille armollinen, ja siunatkoon meitä! hän valistakoon kasvonsa aina meidän päällemme, Sela!"],[67,2,"Että me maan päällä tuntisimme sinun ties, ja kaikkein pakanain seassa sinun autuutes.","Että me maan päällä tuntisimme sinun ties, ja kaikkein pakanain seassa sinun autuutes."],[67,3,"Sinua, Jumala, kansat kiittäköön: sinua kaikki kansat kiittäköön.","Sinua, Jumala, kansat kiittäköön: sinua kaikki kansat kiittäköön."],[67,4,"Kansat iloitkaan ja riemuitkaan, ettäs kansat oikein tuomitset, ja hallitset kansat maan päällä, Sela!","Kansat iloitkaan ja riemuitkaan, ettäs kansat oikein tuomitset, ja hallitset kansat maan päällä, Sela!"],[67,5,"Sinua, Jumala, kansat kiittäköön: sinua kaikki kansat kiittäköön.","Sinua, Jumala, kansat kiittäköön: sinua kaikki kansat kiittäköön."],[67,6,"Maa antaa hedelmänsä; siunatkoon meitä Jumala, meidän Jumalamme.","Maa antaa hedelmänsä; siunatkoon meitä Jumala, meidän Jumalamme."],[67,7,"Siunatkoon meitä Jumala, ja kaikki maailma peljätköön häntä.","Siunatkoon meitä Jumala, ja kaikki maailma peljätköön häntä."],[68,1,"Davidin Psalmi ja veisu, edelläveisaajalle. (H68:2) Nouskaan Jumala, että hänen vihollisensa hajoitettaisiin; ja jotka häntä vihaavat, paetkaat hänen edestänsä.","Davidin Psalmi ja veisu, edelläveisaajalle. (H68:2) Nouskaan Jumala, että hänen vihollisensa hajoitettaisiin; ja jotka häntä vihaavat, paetkaat hänen edestänsä."],[68,2,"Aja heitä pois, niinkuin savu ajetaan pois; niinkuin vedenvaha sulaa tulen edessä, niin hukkukaan jumalattomat Jumalan kasvoin edessä.","Aja heitä pois, niinkuin savu ajetaan pois; niinkuin vedenvaha sulaa tulen edessä, niin hukkukaan jumalattomat Jumalan kasvoin edessä."],[68,3,"Mutta vanhurskaat riemuitkaan ja iloitkaan Jumalan edessä, ja riemuitkaan ilossa.","Mutta vanhurskaat riemuitkaan ja iloitkaan Jumalan edessä, ja riemuitkaan ilossa."],[68,4,"Veisatkaan Jumalalle, veisatkaat kiitosta hänen nimellensä; tehkäät hänelle tietä, joka istuu ylimmäisten taivasten päällä; hänen nimensä on Herra, ja iloitkaat hänen edessänsä.","Veisatkaan Jumalalle, veisatkaat kiitosta hänen nimellensä; tehkäät hänelle tietä, joka istuu ylimmäisten taivasten päällä; hänen nimensä on Herra, ja iloitkaat hänen edessänsä."],[68,5,"Joka on orpoin isä ja leskein tuomari: hän on Jumala pyhässä asumisessansa.","Joka on orpoin isä ja leskein tuomari: hän on Jumala pyhässä asumisessansa."],[68,6,"Jumala, joka yksinäisten antaa asua huoneessa, ja vie vangit ulos oikeudella; mutta vastahakoiset asuvat kuivassa.","Jumala, joka yksinäisten antaa asua huoneessa, ja vie vangit ulos oikeudella; mutta vastahakoiset asuvat kuivassa."],[68,7,"Jumala, koskas kävit kansas edellä, koskas vaelsit korvessa, Sela,","Jumala, koskas kävit kansas edellä, koskas vaelsit korvessa, Sela,"],[68,8,"Niin maa vapisi ja taivaat tiukkuivat Jumalan edessä: tämä Sinai, Jumalan edessä, joka Israelin Jumala on.","Niin maa vapisi ja taivaat tiukkuivat Jumalan edessä: tämä Sinai, Jumalan edessä, joka Israelin Jumala on."],[68,9,"Mutta nyt sinä, Jumala, annat armollisen sateen, ja virvoitat perimises, joka väsynyt on.","Mutta nyt sinä, Jumala, annat armollisen sateen, ja virvoitat perimises, joka väsynyt on."],[68,10,"Että sinun laumas siinä asuis: Jumala, sinä virvoitat hyvyydelläs raadolliset.","Että sinun laumas siinä asuis: Jumala, sinä virvoitat hyvyydelläs raadolliset."],[68,11,"Herra antaa sanan suurella evankelistain joukolla.","Herra antaa sanan suurella evankelistain joukolla."],[68,12,"Sotaväen kuninkaat pakenevat, he pakenevat; ja kotona asuva jakaa saaliit.","Sotaväen kuninkaat pakenevat, he pakenevat; ja kotona asuva jakaa saaliit."],[68,13,"Kuin te tarhain välissä makaatte, niin mettisen sulat ovat silatut hopialla, ja hänen siipensä ruskialla kullalla.","Kuin te tarhain välissä makaatte, niin mettisen sulat ovat silatut hopialla, ja hänen siipensä ruskialla kullalla."],[68,14,"Kuin Kaikkivaltias siinä joka paikassa kuninkaat levittää, niin Zalmonissa valaisee kuin lumi.","Kuin Kaikkivaltias siinä joka paikassa kuninkaat levittää, niin Zalmonissa valaisee kuin lumi."],[68,15,"Jumalan vuori on hedelmällinen vuori: korkia vuori on se hedelmällinen vuori.","Jumalan vuori on hedelmällinen vuori: korkia vuori on se hedelmällinen vuori."],[68,16,"Miksi te, suuret vuoret, kippaatte? Tämä on Jumalan vuori, jossa hän mielistyy asumaan; ja Herra asuu siellä ijankaikkisesti.","Miksi te, suuret vuoret, kippaatte? Tämä on Jumalan vuori, jossa hän mielistyy asumaan; ja Herra asuu siellä ijankaikkisesti."],[68,17,"Jumalan rattaita on monta tuhatta kertaa tuhatta: Herra on heissä, pyhässä Sinaissa.","Jumalan rattaita on monta tuhatta kertaa tuhatta: Herra on heissä, pyhässä Sinaissa."],[68,18,"Sinä astuit ylös korkeuteen, ja olet vangiksi ottanut vankeuden. Sinä olet lahjoja saanut ihmisille: vastahakoiset myös, että Herra Jumala siellä kumminkin asuu.","Sinä astuit ylös korkeuteen, ja olet vangiksi ottanut vankeuden. Sinä olet lahjoja saanut ihmisille: vastahakoiset myös, että Herra Jumala siellä kumminkin asuu."],[68,19,"Kiitetty olkoon Herra joka päivä! Jumala panee kuorman meidän päällemme; mutta hän myös auttaa meitä, Sela!","Kiitetty olkoon Herra joka päivä! Jumala panee kuorman meidän päällemme; mutta hän myös auttaa meitä, Sela!"],[68,20,"Meillä on Jumala, Jumala, joka auttaa, ja Herra, Herra, joka kuolemasta vapahtaa.","Meillä on Jumala, Jumala, joka auttaa, ja Herra, Herra, joka kuolemasta vapahtaa."],[68,21,"Mutta Jumala särkee vihollistensa pään heidän päänlakeinsa kanssa, jotka pysyvät heidän synneissänsä.","Mutta Jumala särkee vihollistensa pään heidän päänlakeinsa kanssa, jotka pysyvät heidän synneissänsä."],[68,22,"Herra sanoo: minä palautan (muutamat) lihavista; meren syvyydestä minä heitä palautan,","Herra sanoo: minä palautan (muutamat) lihavista; meren syvyydestä minä heitä palautan,"],[68,23,"Että sinun jalkas tulis painetuksi veressä, ja koirais kieli sinun vihollisistas.","Että sinun jalkas tulis painetuksi veressä, ja koirais kieli sinun vihollisistas."],[68,24,"He näkivät, Jumala, kuinkas vaellat; kuinkas, minun Jumalani ja kuninkaani, pyhässä vaellat:","He näkivät, Jumala, kuinkas vaellat; kuinkas, minun Jumalani ja kuninkaani, pyhässä vaellat:"],[68,25,"Laulajat käyvät edellä, ja sitte leikarit piikain seassa, jotka kanteleita soittavat.","Laulajat käyvät edellä, ja sitte leikarit piikain seassa, jotka kanteleita soittavat."],[68,26,"Kiittäkäät Herraa Jumalaa seurakunnissa, te Israelin lähteestä.","Kiittäkäät Herraa Jumalaa seurakunnissa, te Israelin lähteestä."],[68,27,"Siellä hallitsee heitä vähä Benjamin, Juudan päämiehet joukkoinensa, Zebulonin päämiehet, Naphtalin päämiehet.","Siellä hallitsee heitä vähä Benjamin, Juudan päämiehet joukkoinensa, Zebulonin päämiehet, Naphtalin päämiehet."],[68,28,"Sinun Jumalas on käskenyt sinun olla väkevän: vahvista Jumala se, minkä sinä meissä tehnyt olet.","Sinun Jumalas on käskenyt sinun olla väkevän: vahvista Jumala se, minkä sinä meissä tehnyt olet."],[68,29,"Sinun templis tähden, joka on Jerusalemissa, pitää kuninkaat sinulle lahjoja viemän.","Sinun templis tähden, joka on Jerusalemissa, pitää kuninkaat sinulle lahjoja viemän."],[68,30,"Nuhtele ruovon petoa, härkäin laumaa kansain vasikkain kanssa, jotka kumartaen tuovat hopeakankeja: hajoittanut on hän kansat, jotka mielellänsä sotivat.","Nuhtele ruovon petoa, härkäin laumaa kansain vasikkain kanssa, jotka kumartaen tuovat hopeakankeja: hajoittanut on hän kansat, jotka mielellänsä sotivat."],[68,31,"Egyptin päämiehet tulevat: Etiopia ojentaa käsiänsä Jumalalle.","Egyptin päämiehet tulevat: Etiopia ojentaa käsiänsä Jumalalle."],[68,32,"Te maan valtakunnat, veisatkaat Jumalalle, veisatkaat kiitosta Herralle, Sela!","Te maan valtakunnat, veisatkaat Jumalalle, veisatkaat kiitosta Herralle, Sela!"],[68,33,"Sille joka asuu taivaissa joka paikassa, hamasta alusta: katso, hän antaa jylinälle voiman.","Sille joka asuu taivaissa joka paikassa, hamasta alusta: katso, hän antaa jylinälle voiman."],[68,34,"Antakaat Jumalalle voima: hänen herrautensa on Israelissa, ja hänen voimansa pilvissä.","Antakaat Jumalalle voima: hänen herrautensa on Israelissa, ja hänen voimansa pilvissä."],[68,35,"Jumala on ihmeellinen pyhässänsä, hän on Israelin Jumala: hän antaa kansalle väen ja voiman: kiitetty olkoon Jumala!","Jumala on ihmeellinen pyhässänsä, hän on Israelin Jumala: hän antaa kansalle väen ja voiman: kiitetty olkoon Jumala!"],[69,1,"Davidin Psalmi kukkasista, edelläveisaajalle. (H69:2) Jumala,auta minua; sillä vedet käyvät hamaan minun sieluuni asti.","Davidin Psalmi kukkasista, edelläveisaajalle. (H69:2) Jumala,auta minua; sillä vedet käyvät hamaan minun sieluuni asti."],[69,2,"Minä vajoon syvään mutaan, jossa ei pohjaa ole: minä olen tullut syviin vesiin, ja virta upottaa minun.","Minä vajoon syvään mutaan, jossa ei pohjaa ole: minä olen tullut syviin vesiin, ja virta upottaa minun."],[69,3,"Minä väsyn huutamisesta: minun kurkkuni kuivettuu: minun näkyni vaipuu, toivoissani minun Jumalani päälle.","Minä väsyn huutamisesta: minun kurkkuni kuivettuu: minun näkyni vaipuu, toivoissani minun Jumalani päälle."],[69,4,"Niitä on enempi kuin päässäni hiuksia, jotka ilman syytä minua vihaavat, jotka syyttömästi minun viholliseni ovat, ja minua hukuttavat, ovat väkevät: niitä täytyy minun maksaa, joita en minä ryövännyt.","Niitä on enempi kuin päässäni hiuksia, jotka ilman syytä minua vihaavat, jotka syyttömästi minun viholliseni ovat, ja minua hukuttavat, ovat väkevät: niitä täytyy minun maksaa, joita en minä ryövännyt."],[69,5,"Jumala, sinäpä tiedät minun tyhmyyteni, ja minun rikokseni ei ole sinulta salatut.","Jumala, sinäpä tiedät minun tyhmyyteni, ja minun rikokseni ei ole sinulta salatut."],[69,6,"Älä salli heitä häpiään tulla minun tähteni, jotka sinua odottavat, Herra, Herra Zebaot: älä anna heitä häväistä minun tähteni, jotka sinua etsivät, Israelin Jumala.","Älä salli heitä häpiään tulla minun tähteni, jotka sinua odottavat, Herra, Herra Zebaot: älä anna heitä häväistä minun tähteni, jotka sinua etsivät, Israelin Jumala."],[69,7,"Sillä sinun tähtes minä pilkkaa kärsin; minun kasvoni ovat täynnä häpiää.","Sillä sinun tähtes minä pilkkaa kärsin; minun kasvoni ovat täynnä häpiää."],[69,8,"Minä olen muukalaiseksi veljilleni tullut, ja oudoksi äitini lapsille.","Minä olen muukalaiseksi veljilleni tullut, ja oudoksi äitini lapsille."],[69,9,"Sillä sinun huonees kiivaus syö minua: ja heidän pilkkansa, jotka sinua pilkkasivat, lankesi minun päälleni.","Sillä sinun huonees kiivaus syö minua: ja heidän pilkkansa, jotka sinua pilkkasivat, lankesi minun päälleni."],[69,10,"Minä itkin ja paastosin hartaasti, ja minä pilkattiin päälliseksi.","Minä itkin ja paastosin hartaasti, ja minä pilkattiin päälliseksi."],[69,11,"Ja minä puin säkin ylleni, ja olin heille sananlaskuksi.","Ja minä puin säkin ylleni, ja olin heille sananlaskuksi."],[69,12,"Jotka portissa istuvat, ne minusta jaarittelevat, ja juodessansa he minusta lauleskelevat.","Jotka portissa istuvat, ne minusta jaarittelevat, ja juodessansa he minusta lauleskelevat."],[69,13,"Mutta minä rukoilen sinua, Herra, otollisella ajalla, Jumala, sinun suuren laupiutes puolesta: kuule minua sinun autuutes totuuden tähden.","Mutta minä rukoilen sinua, Herra, otollisella ajalla, Jumala, sinun suuren laupiutes puolesta: kuule minua sinun autuutes totuuden tähden."],[69,14,"Pelasta minua loasta, etten minä vajoaisi; että minä pelastettaisiin vihollisistani ja syvistä vesistä.","Pelasta minua loasta, etten minä vajoaisi; että minä pelastettaisiin vihollisistani ja syvistä vesistä."],[69,15,"Ettei vuo minua upottaisi ja syvyydet minua lainoaisi, eikä kaivon suu suljettaisi minun päälleni.","Ettei vuo minua upottaisi ja syvyydet minua lainoaisi, eikä kaivon suu suljettaisi minun päälleni."],[69,16,"Kuule minua, Herra; sillä sinun laupiutes on hyvä: käännä sinuas minun puoleeni, sinun suuren laupiutes tähden.","Kuule minua, Herra; sillä sinun laupiutes on hyvä: käännä sinuas minun puoleeni, sinun suuren laupiutes tähden."],[69,17,"Ja älä peitä kasvojas palvelialtas; sillä minä ahdistetaan: kuultele minua nopiasti.","Ja älä peitä kasvojas palvelialtas; sillä minä ahdistetaan: kuultele minua nopiasti."],[69,18,"Lähene minun sieluani, ja lunasta häntä: minun vihollisteni tähden pelasta minua.","Lähene minun sieluani, ja lunasta häntä: minun vihollisteni tähden pelasta minua."],[69,19,"Sinäpä tiedät pilkkani, häpiäni ja häväistykseni: kaikki minun viholliseni ovat edessäs.","Sinäpä tiedät pilkkani, häpiäni ja häväistykseni: kaikki minun viholliseni ovat edessäs."],[69,20,"Pilkka särkee minun sydämeni ja vaivaa minua: minä odotan, jos joku armahtais, ja ei ole kenkään, ja lohduttajia, vaan en ketään löydä.","Pilkka särkee minun sydämeni ja vaivaa minua: minä odotan, jos joku armahtais, ja ei ole kenkään, ja lohduttajia, vaan en ketään löydä."],[69,21,"Ja he antoivat minulle sappea syödäkseni, ja etikkaa juodakseni minun janossani.","Ja he antoivat minulle sappea syödäkseni, ja etikkaa juodakseni minun janossani."],[69,22,"Heidän pöytänsä olkoon heille paulaksi, sekä kostoksi että lankeemiseksi.","Heidän pöytänsä olkoon heille paulaksi, sekä kostoksi että lankeemiseksi."],[69,23,"Tulkoon heidän silmänsä pimiäksi, ettei he näkisi, ja salli heidän lanteensa aina horjua.","Tulkoon heidän silmänsä pimiäksi, ettei he näkisi, ja salli heidän lanteensa aina horjua."],[69,24,"Vuodata närkästykses heidän päällensä, ja hirmuinen vihas käsittäköön heitä,","Vuodata närkästykses heidän päällensä, ja hirmuinen vihas käsittäköön heitä,"],[69,25,"Olkoon heidän huoneensa kylmillä; ja ei kenkään olko, joka heidän majassansa asuis.","Olkoon heidän huoneensa kylmillä; ja ei kenkään olko, joka heidän majassansa asuis."],[69,26,"Sillä he vainoovat sitä, jota lyönyt olet, ja juttelevat niiden kipua, joita haavoittanut olet.","Sillä he vainoovat sitä, jota lyönyt olet, ja juttelevat niiden kipua, joita haavoittanut olet."],[69,27,"Salli heitä langeta synnistä syntiin, ettei he tulisi sinun vanhurskautees.","Salli heitä langeta synnistä syntiin, ettei he tulisi sinun vanhurskautees."],[69,28,"Pyyhi heitä eläväin kirjasta, ettei he kirjoitettaisi vanhurskasten kanssa.","Pyyhi heitä eläväin kirjasta, ettei he kirjoitettaisi vanhurskasten kanssa."],[69,29,"Mutta minä olen raadollinen ja murheellinen: Jumala, sinun autuutes suojelkoon minua!","Mutta minä olen raadollinen ja murheellinen: Jumala, sinun autuutes suojelkoon minua!"],[69,30,"Minä kiitän Jumalan nimeä veisuulla, ja suuresti ylistän häntä kiitoksella.","Minä kiitän Jumalan nimeä veisuulla, ja suuresti ylistän häntä kiitoksella."],[69,31,"Se kelpaa paremmin Herralle kuin härkä taikka mulli, jolla ovat sarvet ja sorkat.","Se kelpaa paremmin Herralle kuin härkä taikka mulli, jolla ovat sarvet ja sorkat."],[69,32,"Raadolliset näkevät sen ja iloitsevat, ja jotka Jumalaa etsivät, heidän sydämensä pitää elämän.","Raadolliset näkevät sen ja iloitsevat, ja jotka Jumalaa etsivät, heidän sydämensä pitää elämän."],[69,33,"Sillä Herra kuulee köyhiä, ja ei hän vankiansa katso ylön.","Sillä Herra kuulee köyhiä, ja ei hän vankiansa katso ylön."],[69,34,"Kiittäkään häntä taivaat ja maa, meri, ja kaikki kuin niissä liikkuvat.","Kiittäkään häntä taivaat ja maa, meri, ja kaikki kuin niissä liikkuvat."],[69,35,"Sillä Jumala auttaa Zionia ja rakentaa Juudan kaupungit, että siellä asutaan, ja se perinnöllä omistetaan.","Sillä Jumala auttaa Zionia ja rakentaa Juudan kaupungit, että siellä asutaan, ja se perinnöllä omistetaan."],[69,36,"Ja hänen palveliainsa siemen sen perii: ja ne, jotka hänen nimeänsä rakastavat, pitää asuman siinä.","Ja hänen palveliainsa siemen sen perii: ja ne, jotka hänen nimeänsä rakastavat, pitää asuman siinä."],[70,1,"Davidin Psalmi edelläveisaajalle, muistoksi. (H70:2) Riennä, Jumala, minua vapahtamaan: kiiruhda, Herra, minua auttamaan.","Davidin Psalmi edelläveisaajalle, muistoksi. (H70:2) Riennä, Jumala, minua vapahtamaan: kiiruhda, Herra, minua auttamaan."],[70,2,"Häpiään tulkoon ja hävetköön, jotka minun sieluani väijyvät: ajettakoon takaperin ja tulkoon häväistyksi, jotka minulle pahaa suovat;","Häpiään tulkoon ja hävetköön, jotka minun sieluani väijyvät: ajettakoon takaperin ja tulkoon häväistyksi, jotka minulle pahaa suovat;"],[70,3,"Että he jälleen häpiään tulisivat, jotka minua pitittävät.","Että he jälleen häpiään tulisivat, jotka minua pitittävät."],[70,4,"Iloitkaan ja riemuitkaan sinussa kaikki, jotka sinua etsivät; ja jotka sinun autuuttas rakastavat, sanokaan aina: Jumala olkoon suuresti ylistetty!","Iloitkaan ja riemuitkaan sinussa kaikki, jotka sinua etsivät; ja jotka sinun autuuttas rakastavat, sanokaan aina: Jumala olkoon suuresti ylistetty!"],[70,5,"Mutta minä olen raadollinen ja köyhä, riennä, Jumala, minun tyköni; sillä sinä olet minun auttajani ja pelastajani, Herra, älä viivyttele.","Mutta minä olen raadollinen ja köyhä, riennä, Jumala, minun tyköni; sillä sinä olet minun auttajani ja pelastajani, Herra, älä viivyttele."],[71,1,"Sinuun, Herra, minä uskallan: älä anna minua ikänä häväistä.","Sinuun, Herra, minä uskallan: älä anna minua ikänä häväistä."],[71,2,"Vapahda minua vanhurskaudessa ja pelasta minua: kallista korvas minun puoleeni ja auta minua.","Vapahda minua vanhurskaudessa ja pelasta minua: kallista korvas minun puoleeni ja auta minua."],[71,3,"Ole minulle vahva turva, johon minä aina pakenisin: sinä olet luvannut minua auttaa; sillä sinä olet minun kallioni ja linnani.","Ole minulle vahva turva, johon minä aina pakenisin: sinä olet luvannut minua auttaa; sillä sinä olet minun kallioni ja linnani."],[71,4,"Minun Jumalani, auta minua jumalattoman kädestä, väärän ja väkivaltaisen kädestä.","Minun Jumalani, auta minua jumalattoman kädestä, väärän ja väkivaltaisen kädestä."],[71,5,"Sillä sinä olet minun turvani, Herra, Herra: minun toivoni hamasta minun nuoruudestani.","Sillä sinä olet minun turvani, Herra, Herra: minun toivoni hamasta minun nuoruudestani."],[71,6,"Sinuun minä olen luottanut hamasta äitini kohdusta, sinä minun vedit ulos äitini kohdusta: sinusta on aina minun kerskaukseni.","Sinuun minä olen luottanut hamasta äitini kohdusta, sinä minun vedit ulos äitini kohdusta: sinusta on aina minun kerskaukseni."],[71,7,"Minä olen monelle ihmeeksi tullut; mutta sinä olet minun vahva turvani.","Minä olen monelle ihmeeksi tullut; mutta sinä olet minun vahva turvani."],[71,8,"Täytä minun suuni sinun kiitoksestas ja sinun kunniastas joka päivä.","Täytä minun suuni sinun kiitoksestas ja sinun kunniastas joka päivä."],[71,9,"Älä minua heitä pois minun vanhuudessani: älä minua hylkää, kuin minä heikoksi tulen.","Älä minua heitä pois minun vanhuudessani: älä minua hylkää, kuin minä heikoksi tulen."],[71,10,"Sillä minun viholliseni puhuvat minua vastaan: ja jotka minun sieluani väijyvät, he keskenänsä neuvoa pitävät,","Sillä minun viholliseni puhuvat minua vastaan: ja jotka minun sieluani väijyvät, he keskenänsä neuvoa pitävät,"],[71,11,"Ja sanovat: Jumala hylkäsi hänen; ajakaat takaa ja käsittäkäät häntä, sillä ei ole vapahtajaa.","Ja sanovat: Jumala hylkäsi hänen; ajakaat takaa ja käsittäkäät häntä, sillä ei ole vapahtajaa."],[71,12,"Jumala, älä erkane kauvas minusta: minun Jumalani, riennä minua auttamaan.","Jumala, älä erkane kauvas minusta: minun Jumalani, riennä minua auttamaan."],[71,13,"Hävetköön ja hukkukoon, jotka minun sieluani vastaan ovat: häpiän ja häväistyksen alle tulkoon, jotka minulle pahaa suovat.","Hävetköön ja hukkukoon, jotka minun sieluani vastaan ovat: häpiän ja häväistyksen alle tulkoon, jotka minulle pahaa suovat."],[71,14,"Mutta minä odotan aina, ja korotan aina sinun kiitokses.","Mutta minä odotan aina, ja korotan aina sinun kiitokses."],[71,15,"Minun suuni pitää ilmoittaman sinun vanhurskauttas, joka päivä sinun autuuttas, joita en minä voi kaikkia lukea.","Minun suuni pitää ilmoittaman sinun vanhurskauttas, joka päivä sinun autuuttas, joita en minä voi kaikkia lukea."],[71,16,"Minä vaellan Herran, Herran väkevyydessä: minä tahdon muistaa ainoastaan sinun vanhurskauttas.","Minä vaellan Herran, Herran väkevyydessä: minä tahdon muistaa ainoastaan sinun vanhurskauttas."],[71,17,"Jumala, sinä olet minua nuoruudestani opettanut, sentähden minä julistan sinun ihmeitäs.","Jumala, sinä olet minua nuoruudestani opettanut, sentähden minä julistan sinun ihmeitäs."],[71,18,"Ja minun vanhuudessani ja harmaaksi tultuani älä, Jumala, minua hylkää, siihenasti kuin minä ilmoitan sinun käsivartes lasten lapsille, ja sinun väkevyytes kaikille tulevaisille.","Ja minun vanhuudessani ja harmaaksi tultuani älä, Jumala, minua hylkää, siihenasti kuin minä ilmoitan sinun käsivartes lasten lapsille, ja sinun väkevyytes kaikille tulevaisille."],[71,19,"Ja tosin, Jumala, sinun vanhurskautes on sangen korkia, sinä teet suuria: Jumala, kuka on sinun vertaises?","Ja tosin, Jumala, sinun vanhurskautes on sangen korkia, sinä teet suuria: Jumala, kuka on sinun vertaises?"],[71,20,"Sillä sinä annat minun nähdä paljon ja suuria ahdistuksia, ja virvoitat minua jälleen; ja taas sinä haet minua ulos maan syvyydestä.","Sillä sinä annat minun nähdä paljon ja suuria ahdistuksia, ja virvoitat minua jälleen; ja taas sinä haet minua ulos maan syvyydestä."],[71,21,"Sinä teet minun sangen suureksi, ja lohdutat minua jälleen.","Sinä teet minun sangen suureksi, ja lohdutat minua jälleen."],[71,22,"Niin minäkin kiitän sinua psaltarilla, sinun totuuttas, minun Jumalani: minä veisaan kiitosta sinulle kanteleilla, sinä pyhä Israelissa.","Niin minäkin kiitän sinua psaltarilla, sinun totuuttas, minun Jumalani: minä veisaan kiitosta sinulle kanteleilla, sinä pyhä Israelissa."],[71,23,"Minun huuleni pitää kiittämän, koska minä sinulle veisaan, ja minun sieluni, jonkas lunastit.","Minun huuleni pitää kiittämän, koska minä sinulle veisaan, ja minun sieluni, jonkas lunastit."],[71,24,"Ja minun kieleni puhuu myös joka päivä sinun vanhurskaudestas; sentähden hävetkään he ja häpiään tulkoon, jotka minulle pahaa suovat.","Ja minun kieleni puhuu myös joka päivä sinun vanhurskaudestas; sentähden hävetkään he ja häpiään tulkoon, jotka minulle pahaa suovat."],[72,1,"Salomon. Jumala, anna tuomios kuninkaalle, ja vanhurskautes kuninkaan pojalle,","Salomon. Jumala, anna tuomios kuninkaalle, ja vanhurskautes kuninkaan pojalle,"],[72,2,"Että hän veis sinun kansas vanhurskauteen, ja auttais sinun raadollistas.","Että hän veis sinun kansas vanhurskauteen, ja auttais sinun raadollistas."],[72,3,"Vuoret tuokaan rauhan kansalle, ja kukulat vanhurskauden.","Vuoret tuokaan rauhan kansalle, ja kukulat vanhurskauden."],[72,4,"Hänen pitää raadollisen kansan oikeudessa pitämän, ja köyhäin lapsia auttaman ja särkemän pilkkaajat.","Hänen pitää raadollisen kansan oikeudessa pitämän, ja köyhäin lapsia auttaman ja särkemän pilkkaajat."],[72,5,"Sinua peljätään, niinkauvan kuin aurinko ja kuu ovat, lapsista niin lasten lapsiin.","Sinua peljätään, niinkauvan kuin aurinko ja kuu ovat, lapsista niin lasten lapsiin."],[72,6,"Hän laskee alas niinkuin sade heinän sängelle, niinkuin pisarat, jotka maan lioittavat.","Hän laskee alas niinkuin sade heinän sängelle, niinkuin pisarat, jotka maan lioittavat."],[72,7,"Hänen aikanansa vanhurskas kukoistaa, ja on suuri rauha siihen asti, ettei kuuta enää olekaan.","Hänen aikanansa vanhurskas kukoistaa, ja on suuri rauha siihen asti, ettei kuuta enää olekaan."],[72,8,"Hän hallitsee merestä mereen ja virrasta maailman ääriin.","Hän hallitsee merestä mereen ja virrasta maailman ääriin."],[72,9,"Häntä pitää korven asuvaiset kumartaman, ja hänen vihollisensa pitää tomun nuoleman.","Häntä pitää korven asuvaiset kumartaman, ja hänen vihollisensa pitää tomun nuoleman."],[72,10,"Kuninkaat meren tyköä ja luodoista pitää lahjoja kantaman: kuninkaat rikkaasta Arabiasta ja Sebasta pitää annot tuoman.","Kuninkaat meren tyköä ja luodoista pitää lahjoja kantaman: kuninkaat rikkaasta Arabiasta ja Sebasta pitää annot tuoman."],[72,11,"Kaikki kuninkaat pitää häntä kumartaman, ja kaikki pakanat pitää häntä palveleman.","Kaikki kuninkaat pitää häntä kumartaman, ja kaikki pakanat pitää häntä palveleman."],[72,12,"Sillä hän vapahtaa huutavaisen köyhän, ja raadollisen, jolla ei ole auttajaa.","Sillä hän vapahtaa huutavaisen köyhän, ja raadollisen, jolla ei ole auttajaa."],[72,13,"Hän on armollinen vaivaiselle ja köyhälle, ja köyhäin sielua hän auttaa.","Hän on armollinen vaivaiselle ja köyhälle, ja köyhäin sielua hän auttaa."],[72,14,"Hän lunastaa heidän sielunsa petoksesta ja väkivallasta, ja heidän verensä luetaan kalliiksi hänen silmäinsä edessä.","Hän lunastaa heidän sielunsa petoksesta ja väkivallasta, ja heidän verensä luetaan kalliiksi hänen silmäinsä edessä."],[72,15,"Ja hän elää ja hänelle pitää annettaman kultaa rikkaasta Arabiasta, ja häntä alati kumartaen rukoiltaman, joka päivä pitää häntä kiitettämän.","Ja hän elää ja hänelle pitää annettaman kultaa rikkaasta Arabiasta, ja häntä alati kumartaen rukoiltaman, joka päivä pitää häntä kiitettämän."],[72,16,"Pivo jyviä pitää niin oleman maassa ja vuorten kukkuloilla, että sen hedelmä pitää häälymän niinkuin Libanon; ja kaupungin asuvaiset pitää kukoistaman niinkuin ruoho maan päällä.","Pivo jyviä pitää niin oleman maassa ja vuorten kukkuloilla, että sen hedelmä pitää häälymän niinkuin Libanon; ja kaupungin asuvaiset pitää kukoistaman niinkuin ruoho maan päällä."],[72,17,"Hänen nimensä pysyy ijankaikkisesti: niinkauvan kuin aurinko on, ulottuu hänen nimensä jälkeentulevaisille; ja he tulevat siunatuksi hänen kauttansa: kaikki pakanat ylistävät häntä.","Hänen nimensä pysyy ijankaikkisesti: niinkauvan kuin aurinko on, ulottuu hänen nimensä jälkeentulevaisille; ja he tulevat siunatuksi hänen kauttansa: kaikki pakanat ylistävät häntä."],[72,18,"Kiitetty olkoon Herra Jumala, Israelin Jumala, joka yksinänsä ihmeitä tekee!","Kiitetty olkoon Herra Jumala, Israelin Jumala, joka yksinänsä ihmeitä tekee!"],[72,19,"Ja kiitetty olkoon hänen kunniansa nimi ijankaikkisesti; ja kaikki maa täytettäköön hänen kunniastansa, amen! amen!","Ja kiitetty olkoon hänen kunniansa nimi ijankaikkisesti; ja kaikki maa täytettäköön hänen kunniastansa, amen! amen!"],[72,20,"Davidin, Isain pojan, rukoukset loppuvat.","Davidin, Isain pojan, rukoukset loppuvat."],[73,1,"Asaphin Psalmi. Totta on Jumala hyvä Israelille, niille, jotka puhtaat sydämestä ovat.","Asaphin Psalmi. Totta on Jumala hyvä Israelille, niille, jotka puhtaat sydämestä ovat."],[73,2,"Mutta minä olisin pian jaloillani horjunut: minun askeleeni olisivat lähes liukastuneet.","Mutta minä olisin pian jaloillani horjunut: minun askeleeni olisivat lähes liukastuneet."],[73,3,"Sillä minä närkästyin öykkäreistä, että minä näin jumalattomat menestyvän.","Sillä minä närkästyin öykkäreistä, että minä näin jumalattomat menestyvän."],[73,4,"Sillä ei he ole missään kuoleman hädässä, vaan heidän voimansa pysyy vahvana.","Sillä ei he ole missään kuoleman hädässä, vaan heidän voimansa pysyy vahvana."],[73,5,"Ei he ole vastoinkäymisessä niinkuin muut ihmiset, ja ei heitä vaivata niinkuin muita ihmisiä.","Ei he ole vastoinkäymisessä niinkuin muut ihmiset, ja ei heitä vaivata niinkuin muita ihmisiä."],[73,6,"Sentähden on heidän ylpeytensä koria, ja heidän väkivaltansa kaunistaa heitä.","Sentähden on heidän ylpeytensä koria, ja heidän väkivaltansa kaunistaa heitä."],[73,7,"Heidän silmänsä paisuvat lihavuudesta: he tekevät mitä ainoastansa heille kelpaa.","Heidän silmänsä paisuvat lihavuudesta: he tekevät mitä ainoastansa heille kelpaa."],[73,8,"Kaikkia he katsovat ylön, ja sitte pahasti puhuvat: he puhuvat ja laittavat ylpiästi.","Kaikkia he katsovat ylön, ja sitte pahasti puhuvat: he puhuvat ja laittavat ylpiästi."],[73,9,"Mitä he puhuvat, sen täytyy olla taivaasta puhuttu: mitä he sanovat, sen täytyy maan päällä kelvata.","Mitä he puhuvat, sen täytyy olla taivaasta puhuttu: mitä he sanovat, sen täytyy maan päällä kelvata."],[73,10,"Sentähden noudattaa heitä yhteinen kansa, ja kokoontuvat heidän tykönsä niinkuin vedet,","Sentähden noudattaa heitä yhteinen kansa, ja kokoontuvat heidän tykönsä niinkuin vedet,"],[73,11,"Ja sanovat: mitä Jumalan pitäis heitä kysymän? mitä pitäis korkeimman heistä lukua pitämän?","Ja sanovat: mitä Jumalan pitäis heitä kysymän? mitä pitäis korkeimman heistä lukua pitämän?"],[73,12,"Katso, ne ovat jumalattomat: he ovat onnelliset maailmassa ja rikastuvat.","Katso, ne ovat jumalattomat: he ovat onnelliset maailmassa ja rikastuvat."],[73,13,"Pitäiskö siis sen turhaan oleman, että minun sydämeni nuhteetoinna elää, ja minä pesen viattomuudessa minun käteni?","Pitäiskö siis sen turhaan oleman, että minun sydämeni nuhteetoinna elää, ja minä pesen viattomuudessa minun käteni?"],[73,14,"Ja minä ruoskitaan joka päivä, ja minun rangaistukseni on joka aamu käsissä?","Ja minä ruoskitaan joka päivä, ja minun rangaistukseni on joka aamu käsissä?"],[73,15,"Minä olisin lähes niin sanonut kuin hekin; mutta katso, niin minä olisin tuominnut kaikki sinun lapses, jotka ikänänsä olleet ovat.","Minä olisin lähes niin sanonut kuin hekin; mutta katso, niin minä olisin tuominnut kaikki sinun lapses, jotka ikänänsä olleet ovat."],[73,16,"Minä ajattelin sitä tutkia; mutta se oli minulle ylen raskas,","Minä ajattelin sitä tutkia; mutta se oli minulle ylen raskas,"],[73,17,"Siihenasti kuin minä menin Jumalan pyhään, ja ymmärsin heidän loppunsa.","Siihenasti kuin minä menin Jumalan pyhään, ja ymmärsin heidän loppunsa."],[73,18,"Tosin sinä asetit heitä liukkaalle, ja syöksit heitä pohjaan.","Tosin sinä asetit heitä liukkaalle, ja syöksit heitä pohjaan."],[73,19,"Kuinka he niin pian hukkuvat: he hukkuvat ja saavat kauhian lopun.","Kuinka he niin pian hukkuvat: he hukkuvat ja saavat kauhian lopun."],[73,20,"Niinkuin uni, koska joku herää, niinpä sinä, Herra teet heidän kuvansa kaupungissa ylönkatsotuksi.","Niinkuin uni, koska joku herää, niinpä sinä, Herra teet heidän kuvansa kaupungissa ylönkatsotuksi."],[73,21,"Vaan kuin se karvasteli minun sydämessäni ja pisti minun munaskuitani,","Vaan kuin se karvasteli minun sydämessäni ja pisti minun munaskuitani,"],[73,22,"Silloin olin minä tyhmä ja en mitään tietänyt: minä olin niinkuin nauta sinun edessäs.","Silloin olin minä tyhmä ja en mitään tietänyt: minä olin niinkuin nauta sinun edessäs."],[73,23,"Kuitenkin minä pysyn alati sinun tykönäs; sillä sinä pidät minun oikiasta kädestäni.","Kuitenkin minä pysyn alati sinun tykönäs; sillä sinä pidät minun oikiasta kädestäni."],[73,24,"Sinä talutat minua neuvollas, ja korjaat minua viimein kunnialla.","Sinä talutat minua neuvollas, ja korjaat minua viimein kunnialla."],[73,25,"Kuin sinä ainoastansa minulla olisit, niin en minä ensinkään sitte taivaasta eli maasta tottelisi.","Kuin sinä ainoastansa minulla olisit, niin en minä ensinkään sitte taivaasta eli maasta tottelisi."],[73,26,"Vaikka vielä minun ruumiini ja sieluni vaipuis, niin sinä, Jumala, kuitenkin olet aina minun sydämeni uskallus ja minun osani.","Vaikka vielä minun ruumiini ja sieluni vaipuis, niin sinä, Jumala, kuitenkin olet aina minun sydämeni uskallus ja minun osani."],[73,27,"Sillä katso, jotka sinusta eriävät, ne hukkuvat: sinä kadotat kaikki, jotka sinua vastaan huorin tekevät.","Sillä katso, jotka sinusta eriävät, ne hukkuvat: sinä kadotat kaikki, jotka sinua vastaan huorin tekevät."],[73,28,"Mutta se on minun iloni, että minä itseni Jumalan tykö pidän, ja panen toivoni Herran, Herran päälle, ilmoittamaan kaikkia sinun töitäs.","Mutta se on minun iloni, että minä itseni Jumalan tykö pidän, ja panen toivoni Herran, Herran päälle, ilmoittamaan kaikkia sinun töitäs."],[74,1,"Asaphin opetus. Jumala, miksis meitä niin ratki pois syökset? ja olet niin hirmuisesti vihainen sinun laitumes lampaille?","Asaphin opetus. Jumala, miksis meitä niin ratki pois syökset? ja olet niin hirmuisesti vihainen sinun laitumes lampaille?"],[74,2,"Muista seurakuntaas, jonkas muinen omistit ja sinulle perimiseksi lunastanut olet, Zionin vuorta, jossas asuit.","Muista seurakuntaas, jonkas muinen omistit ja sinulle perimiseksi lunastanut olet, Zionin vuorta, jossas asuit."],[74,3,"Tallaa heitä jaloillas, ja sysää heitä ijäiseen hävitykseen: vihollinen on raiskannut kaikki pyhässä.","Tallaa heitä jaloillas, ja sysää heitä ijäiseen hävitykseen: vihollinen on raiskannut kaikki pyhässä."],[74,4,"Sinun vihollises kiljuvat sinun huoneessas, ja asettavat epäjumalansa siihen.","Sinun vihollises kiljuvat sinun huoneessas, ja asettavat epäjumalansa siihen."],[74,5,"Kirveet näkyvät välkkyvän ylhäällä, niinkuin metsässä hakattaisiin,","Kirveet näkyvät välkkyvän ylhäällä, niinkuin metsässä hakattaisiin,"],[74,6,"Ja hakkaavat rikki kaikki hänen kuvainsa kaunistukset, sekä keihäillä että kirveillä.","Ja hakkaavat rikki kaikki hänen kuvainsa kaunistukset, sekä keihäillä että kirveillä."],[74,7,"He polttavat sinun pyhäs, ja turmelevat sinun nimes asuinsian maan päällä.","He polttavat sinun pyhäs, ja turmelevat sinun nimes asuinsian maan päällä."],[74,8,"He puhuvat sydämessänsä: raadelkaamme heitä ynnä; he polttavat kaikki Jumalan huoneet maalla.","He puhuvat sydämessänsä: raadelkaamme heitä ynnä; he polttavat kaikki Jumalan huoneet maalla."],[74,9,"Emme näe meidän ihmeitämme, eikä silleen prophetaa ole: ei myös ketään meidän seassamme ole, joka ymmärtää kuinka kauvan.","Emme näe meidän ihmeitämme, eikä silleen prophetaa ole: ei myös ketään meidän seassamme ole, joka ymmärtää kuinka kauvan."],[74,10,"Jumala, kuinka kauvan vihamies häpäisee ja vihollinen sinun nimeäs ratki niin pilkkaa?","Jumala, kuinka kauvan vihamies häpäisee ja vihollinen sinun nimeäs ratki niin pilkkaa?"],[74,11,"Miksis käännät pois sinun kätes? ja oikian kätes niin ratki sinun povestas?","Miksis käännät pois sinun kätes? ja oikian kätes niin ratki sinun povestas?"],[74,12,"Mutta Jumala on alusta minun kuninkaani, joka kaikkinaisen autuuden matkaan saattaa maan päällä.","Mutta Jumala on alusta minun kuninkaani, joka kaikkinaisen autuuden matkaan saattaa maan päällä."],[74,13,"Sinä hajoitat meren voimallas: sinä murennat lohikärmeiden päät vesissä.","Sinä hajoitat meren voimallas: sinä murennat lohikärmeiden päät vesissä."],[74,14,"Sinä murensit valaskalain päät, ja annat ne kansalle ruaksi metsän korvessa.","Sinä murensit valaskalain päät, ja annat ne kansalle ruaksi metsän korvessa."],[74,15,"Sinä kuohutat lähteet ja virrat: sinä kuivaat väkevät kosket.","Sinä kuohutat lähteet ja virrat: sinä kuivaat väkevät kosket."],[74,16,"Päivä ja yö ovat sinun: sinä rakennat valkeuden ja auringon.","Päivä ja yö ovat sinun: sinä rakennat valkeuden ja auringon."],[74,17,"Sinä sovitit jokaisen maan rajat: sinä teet suven ja talven.","Sinä sovitit jokaisen maan rajat: sinä teet suven ja talven."],[74,18,"Niin muista siis, että vihollinen häpäisee Herraa, ja hullu kansa pilkkaa sinun nimeäs.","Niin muista siis, että vihollinen häpäisee Herraa, ja hullu kansa pilkkaa sinun nimeäs."],[74,19,"Älä siis anna pedolle mettises sielua, ja älä niin ratki unohda sinun köyhäis joukkoa.","Älä siis anna pedolle mettises sielua, ja älä niin ratki unohda sinun köyhäis joukkoa."],[74,20,"Muista liittoa; sillä maa on joka paikassa surkiasti hävitetty, ja huoneet ovat täynnä vääryyttä.","Muista liittoa; sillä maa on joka paikassa surkiasti hävitetty, ja huoneet ovat täynnä vääryyttä."],[74,21,"Älä anna köyhän mennä pois häpiällä; sillä köyhät ja raadolliset kiittävät sinun nimeäs.","Älä anna köyhän mennä pois häpiällä; sillä köyhät ja raadolliset kiittävät sinun nimeäs."],[74,22,"Nouse, Jumala, ja aja asias: muista niitä häväistyksiä, jotka sinulle joka päivä hulluilta tapahtuvat.","Nouse, Jumala, ja aja asias: muista niitä häväistyksiä, jotka sinulle joka päivä hulluilta tapahtuvat."],[74,23,"Älä unohda vihollistes ääntä: sinun vainollistes meteli tulee aina suuremmaksi.","Älä unohda vihollistes ääntä: sinun vainollistes meteli tulee aina suuremmaksi."],[75,1,"Asaphin Psalmi ja veisu, ettei hän hukkunut, edelläveisaajalle. (H75:2) Me kiitämme sinua, ja ilmoitamme ihmeitäs, että sinun nimes on niin läsnä.","Asaphin Psalmi ja veisu, ettei hän hukkunut, edelläveisaajalle. (H75:2) Me kiitämme sinua, ja ilmoitamme ihmeitäs, että sinun nimes on niin läsnä."],[75,2,"Sillä ajallansa minä oikein tuomitsen.","Sillä ajallansa minä oikein tuomitsen."],[75,3,"Maa vapisee ja kaikki, jotka sen päällä asuvat; mutta minä vahvistan lujasti hänen patsaansa, Sela!","Maa vapisee ja kaikki, jotka sen päällä asuvat; mutta minä vahvistan lujasti hänen patsaansa, Sela!"],[75,4,"Minä sanoin öykkäreille: älkäät niin kerskatko, ja jumalattomille: älkäät vallan päälle haastako.","Minä sanoin öykkäreille: älkäät niin kerskatko, ja jumalattomille: älkäät vallan päälle haastako."],[75,5,"Älkäät niin pahoin haastako teidän valtanne päälle: älkäät puhuko niin niskuristi,","Älkäät niin pahoin haastako teidän valtanne päälle: älkäät puhuko niin niskuristi,"],[75,6,"Niinkuin ei mitään hätää olisi, eikä idästä eikä lännestä, taikka vuorilta korvessa.","Niinkuin ei mitään hätää olisi, eikä idästä eikä lännestä, taikka vuorilta korvessa."],[75,7,"Sillä Jumala on tuomari, joka tämän alentaa ja toisen ylentää.","Sillä Jumala on tuomari, joka tämän alentaa ja toisen ylentää."],[75,8,"Sillä Herran kädessä on malja täynnä, väkevällä viinalla täytetty, ja siitä hän panee sisälle; vaan sen rahkan täytyy kaikkein jumalattomain maan päällä juoda, ja ryypätä ulos.","Sillä Herran kädessä on malja täynnä, väkevällä viinalla täytetty, ja siitä hän panee sisälle; vaan sen rahkan täytyy kaikkein jumalattomain maan päällä juoda, ja ryypätä ulos."],[75,9,"Mutta minä ilmoitan ijankaikkisesti, ja veisaan kiitosta Jakobin Jumalalle.","Mutta minä ilmoitan ijankaikkisesti, ja veisaan kiitosta Jakobin Jumalalle."],[75,10,"Ja minä tahdon särkeä kaiken jumalattomain vallan, että vanhurskasten valta korotettaisiin.","Ja minä tahdon särkeä kaiken jumalattomain vallan, että vanhurskasten valta korotettaisiin."],[76,1,"Asaphin Psalmi ja veisu, kanteleilla, edelläveisaajalle. (H76:2) Jumala on tuttu Juudassa, Israelissa on hänen suuri nimensä.","Asaphin Psalmi ja veisu, kanteleilla, edelläveisaajalle. (H76:2) Jumala on tuttu Juudassa, Israelissa on hänen suuri nimensä."],[76,2,"Salemissa on hänen majansa, ja Zionissa hänen asumisensa.","Salemissa on hänen majansa, ja Zionissa hänen asumisensa."],[76,3,"Siellä hän särkee joutsen nuolet, kilvet, miekan ja sodan, Sela!","Siellä hän särkee joutsen nuolet, kilvet, miekan ja sodan, Sela!"],[76,4,"Sinä olet kirkkaampi ja väkevämpi kuin ryöstövuoret.","Sinä olet kirkkaampi ja väkevämpi kuin ryöstövuoret."],[76,5,"Urhoolliset pitää ryöstettämän ja uneensa nukkuman; ja kaikki sotamiehet täytyy käsistänsä hermottomaksi tulla.","Urhoolliset pitää ryöstettämän ja uneensa nukkuman; ja kaikki sotamiehet täytyy käsistänsä hermottomaksi tulla."],[76,6,"Sinun rangaistuksestas, Jakobin Jumala, vajoo uneen orhi ja ratas,","Sinun rangaistuksestas, Jakobin Jumala, vajoo uneen orhi ja ratas,"],[76,7,"Sinä olet peljättävä: kuka voi seisoa sinun edessäs, koskas vihastut?","Sinä olet peljättävä: kuka voi seisoa sinun edessäs, koskas vihastut?"],[76,8,"Koskas tuomion annat kuulua taivaasta, niin maa vapisee ja vaikenee;","Koskas tuomion annat kuulua taivaasta, niin maa vapisee ja vaikenee;"],[76,9,"Koska Jumala nousee tuomitsemaan, että hän auttais kaikkia raadollisia maan päällä, Sela!","Koska Jumala nousee tuomitsemaan, että hän auttais kaikkia raadollisia maan päällä, Sela!"],[76,10,"Kuin ihmiset kiukuitsevat sinua vastaan, niin sinä voitat kunnian, ja kuin he vielä enemmin kiukuitsevat, niin sinä olet valmis.","Kuin ihmiset kiukuitsevat sinua vastaan, niin sinä voitat kunnian, ja kuin he vielä enemmin kiukuitsevat, niin sinä olet valmis."],[76,11,"Luvatkaat ja antakaat Herralle teidän Jumalallenne kaikki, jotka hänen ympärillänsä olette, viekäät lahjoja peljättävälle,","Luvatkaat ja antakaat Herralle teidän Jumalallenne kaikki, jotka hänen ympärillänsä olette, viekäät lahjoja peljättävälle,"],[76,12,"Joka päämiehiltä ottaa pois rohkeuden, ja on peljättävä maan kuninkaille.","Joka päämiehiltä ottaa pois rohkeuden, ja on peljättävä maan kuninkaille."],[77,1,"Asaphin Psalmi, Jedutunin edestä, edelläveisaajalle. (H77:2) Minä huudan äänelläni Jumalaa: Jumalaa minä huudan, ja hän kuultelee minua.","Asaphin Psalmi, Jedutunin edestä, edelläveisaajalle. (H77:2) Minä huudan äänelläni Jumalaa: Jumalaa minä huudan, ja hän kuultelee minua."],[77,2,"Minun hätä-ajallani etsin minä Herraa: minun käteni on yöllä ojettu, ja ei lakkaa; sillä ei minun sieluni salli itseänsä lohduttaa.","Minun hätä-ajallani etsin minä Herraa: minun käteni on yöllä ojettu, ja ei lakkaa; sillä ei minun sieluni salli itseänsä lohduttaa."],[77,3,"Minä ajattelen tosin Jumalan päälle, olen kuitenkin murheissani: minä tutkin, ja henkeni on sittekin ahdistuksessa, Sela!","Minä ajattelen tosin Jumalan päälle, olen kuitenkin murheissani: minä tutkin, ja henkeni on sittekin ahdistuksessa, Sela!"],[77,4,"Sinä pidät minun silmäni, että he valvovat: minä olen niin voimatoin, etten minä voi puhua.","Sinä pidät minun silmäni, että he valvovat: minä olen niin voimatoin, etten minä voi puhua."],[77,5,"Minä ajattelen vanhoja aikoja, entisiä vuosia:","Minä ajattelen vanhoja aikoja, entisiä vuosia:"],[77,6,"Minä muistan yöllä minun kantelettani: minä puhun sydämelleni, ja minun henkeni tutkii:","Minä muistan yöllä minun kantelettani: minä puhun sydämelleni, ja minun henkeni tutkii:"],[77,7,"Heittäneekö Jumala pois ijankaikkisesti, ja ei yhtään armoa silleen osoittane?","Heittäneekö Jumala pois ijankaikkisesti, ja ei yhtään armoa silleen osoittane?"],[77,8,"Puuttuneeko hänen laupiutensa ijankaikkisesti, ja olleeko lupauksella jo loppu suvusta sukuhun?","Puuttuneeko hänen laupiutensa ijankaikkisesti, ja olleeko lupauksella jo loppu suvusta sukuhun?"],[77,9,"Onko Jumala unohtanut olla armollinen? ja sulkenut laupiutensa vihan tähden? Sela!","Onko Jumala unohtanut olla armollinen? ja sulkenut laupiutensa vihan tähden? Sela!"],[77,10,"Minä sanoin: se on minun heikkouteni; mutta Ylimmäisen oikia käsi voi kaikki muuttaa.","Minä sanoin: se on minun heikkouteni; mutta Ylimmäisen oikia käsi voi kaikki muuttaa."],[77,11,"Sentähden minä muistan Herran töitä, ja minä ajattelen entisiä ihmeitäs,","Sentähden minä muistan Herran töitä, ja minä ajattelen entisiä ihmeitäs,"],[77,12,"Ja puhun kaikista sinun töistäs, ja sanon sinun teoistas.","Ja puhun kaikista sinun töistäs, ja sanon sinun teoistas."],[77,13,"Jumala, sinun ties on pyhä: kussa on niin väkevää Jumalaa kuin sinä Jumala?","Jumala, sinun ties on pyhä: kussa on niin väkevää Jumalaa kuin sinä Jumala?"],[77,14,"Sinä olet se Jumala, joka ihmeitä tekee: sinä osoitit voimas kansain seassa.","Sinä olet se Jumala, joka ihmeitä tekee: sinä osoitit voimas kansain seassa."],[77,15,"Sinä lunastit sinun kansas käsivarrellas, Jakobin ja Josephin lapset, Sela!","Sinä lunastit sinun kansas käsivarrellas, Jakobin ja Josephin lapset, Sela!"],[77,16,"Vedet näkivät sinun, Jumala, vedet näkivät sinun ja vapisivat, ja syvyydet pauhasivat,","Vedet näkivät sinun, Jumala, vedet näkivät sinun ja vapisivat, ja syvyydet pauhasivat,"],[77,17,"Paksut pilvet kaasivat vettä, pilvet jylisivät ja nuolet lensivät sekaan.","Paksut pilvet kaasivat vettä, pilvet jylisivät ja nuolet lensivät sekaan."],[77,18,"Se jylisi taivaassa, ja sinun leimaukses välkkyi maan piirin päälle: maa liikkui ja värisi siitä.","Se jylisi taivaassa, ja sinun leimaukses välkkyi maan piirin päälle: maa liikkui ja värisi siitä."],[77,19,"Sinun ties oli meressä, ja sinun polkus olivat suurissa vesissä, ja ei sinun jälkiäs kenkään tuntenut.","Sinun ties oli meressä, ja sinun polkus olivat suurissa vesissä, ja ei sinun jälkiäs kenkään tuntenut."],[77,20,"Sinä veit kansas niinkuin lammaslauman, Moseksen ja Aaronin kautta.","Sinä veit kansas niinkuin lammaslauman, Moseksen ja Aaronin kautta."],[78,1,"Asaphin opetus. Kuule, kansani, minun lakini: kallistakaat korvanne minun suuni sanoihin.","Asaphin opetus. Kuule, kansani, minun lakini: kallistakaat korvanne minun suuni sanoihin."],[78,2,"Minä avaan suuni sananlaskuun, ja vanhat tapaukset mainitsen,","Minä avaan suuni sananlaskuun, ja vanhat tapaukset mainitsen,"],[78,3,"Jotka me kuulleet olemme ja tiedämme, ja meidän isämme meille jutelleet ovat,","Jotka me kuulleet olemme ja tiedämme, ja meidän isämme meille jutelleet ovat,"],[78,4,"Ettemme sitä salaisi heidän lapsiltansa, jälkeentulevaiselta sukukunnalta, julistain Herran kiitoksia, ja hänen voimaansa ja ihmeitänsä, jotka hän on tehnyt.","Ettemme sitä salaisi heidän lapsiltansa, jälkeentulevaiselta sukukunnalta, julistain Herran kiitoksia, ja hänen voimaansa ja ihmeitänsä, jotka hän on tehnyt."],[78,5,"Hän sääsi todistuksen Jakobissa, ja antoi lain Israelissa, jonka hän käski meidän isäimme opettaa lapsillensa,","Hän sääsi todistuksen Jakobissa, ja antoi lain Israelissa, jonka hän käski meidän isäimme opettaa lapsillensa,"],[78,6,"Että vastatulevaiset oppisivat, ja lapset, jotka vielä syntyvät: kuin he kasvavat, että hekin myös ilmoittaisivat lapsillensa;","Että vastatulevaiset oppisivat, ja lapset, jotka vielä syntyvät: kuin he kasvavat, että hekin myös ilmoittaisivat lapsillensa;"],[78,7,"Että he panisivat toivonsa Jumalaan ja ei unohtaisi Jumalan tekoja, vaan pitäisivät hänen käskynsä,","Että he panisivat toivonsa Jumalaan ja ei unohtaisi Jumalan tekoja, vaan pitäisivät hänen käskynsä,"],[78,8,"Ja ei olisi niinkuin heidän isänsä, vastahakoinen ja kankia suku, joka ei vahvistanut sydäntänsä, ja heidän henkensä ei riippunut uskollisesti Jumalassa;","Ja ei olisi niinkuin heidän isänsä, vastahakoinen ja kankia suku, joka ei vahvistanut sydäntänsä, ja heidän henkensä ei riippunut uskollisesti Jumalassa;"],[78,9,"Niinkuin Ephraimin lapset, sota-aseilla varustetut joutsimiehet, pakenivat sodan ajalla.","Niinkuin Ephraimin lapset, sota-aseilla varustetut joutsimiehet, pakenivat sodan ajalla."],[78,10,"Ei he pitäneet Jumalan liittoa, ja ei vaeltaneet hänen laissansa.","Ei he pitäneet Jumalan liittoa, ja ei vaeltaneet hänen laissansa."],[78,11,"Ja he unohtivat hänen tekonsa ja ihmeensä, jotka hän heille osottanut oli.","Ja he unohtivat hänen tekonsa ja ihmeensä, jotka hän heille osottanut oli."],[78,12,"Heidän isäinsä edessä teki hän ihmeitä, Egyptin maassa, Zoanin kedolla.","Heidän isäinsä edessä teki hän ihmeitä, Egyptin maassa, Zoanin kedolla."],[78,13,"Hän halkasi meren ja vei heitä sen lävitse, ja asetti vedet niinkuin roukkion.","Hän halkasi meren ja vei heitä sen lävitse, ja asetti vedet niinkuin roukkion."],[78,14,"Ja hän talutti heitä yli päivää pilvellä, yli yötä tulen valolla.","Ja hän talutti heitä yli päivää pilvellä, yli yötä tulen valolla."],[78,15,"Hän halkasi kalliot korvessa, ja juotti heitä vedellä yltäkyllä.","Hän halkasi kalliot korvessa, ja juotti heitä vedellä yltäkyllä."],[78,16,"Ja hän laski ojat vuotamaan kalliosta, niin että vedet siitä vuosivat niinkuin virrat.","Ja hän laski ojat vuotamaan kalliosta, niin että vedet siitä vuosivat niinkuin virrat."],[78,17,"Ja vielä he sittenkin syntiä tekivät häntä vastaan, ja vihoittivat korkeimman korvessa.","Ja vielä he sittenkin syntiä tekivät häntä vastaan, ja vihoittivat korkeimman korvessa."],[78,18,"He kiusasivat Jumalaa sydämessänsä, anoen ruokaa sielullensa.","He kiusasivat Jumalaa sydämessänsä, anoen ruokaa sielullensa."],[78,19,"He puhuivat Jumalaa vastaan ja sanoivat: voineeko Jumala valmistaa pöydän korvessa?","He puhuivat Jumalaa vastaan ja sanoivat: voineeko Jumala valmistaa pöydän korvessa?"],[78,20,"Katso, kyllä tosin hän kallioon löi, ja vedet vuosivat, ja ojat juoksivat; mutta voineeko hän myös leipää antaa, eli kansallensa lihaa toimittaa?","Katso, kyllä tosin hän kallioon löi, ja vedet vuosivat, ja ojat juoksivat; mutta voineeko hän myös leipää antaa, eli kansallensa lihaa toimittaa?"],[78,21,"Kuin Herra sen kuuli, vihastui hän: ja tuli sytytettiin Jakobissa, ja julmuus tuli Israelin päälle,","Kuin Herra sen kuuli, vihastui hän: ja tuli sytytettiin Jakobissa, ja julmuus tuli Israelin päälle,"],[78,22,"Ettei he uskoneet Jumalan päälle, ja ei uskaltaneet hänen apuunsa.","Ettei he uskoneet Jumalan päälle, ja ei uskaltaneet hänen apuunsa."],[78,23,"Ja hän käski pilviä ylhäältä, ja avasi taivaan ovet,","Ja hän käski pilviä ylhäältä, ja avasi taivaan ovet,"],[78,24,"Ja antoi sataa heille mannaa syödäksensä, ja antoi heille taivaan leipää.","Ja antoi sataa heille mannaa syödäksensä, ja antoi heille taivaan leipää."],[78,25,"He söivät väkeväin leipää: hän lähetti heille kyllä ruokaa ravinnoksi.","He söivät väkeväin leipää: hän lähetti heille kyllä ruokaa ravinnoksi."],[78,26,"Hän antoi itätuulen puhaltaa taivaan alla, ja väkevyydellänsä kehoitti hän etelätuulen,","Hän antoi itätuulen puhaltaa taivaan alla, ja väkevyydellänsä kehoitti hän etelätuulen,"],[78,27,"Ja antoi sataa, niinkuin tomua, lihaa heille, ja lintuja niinkuin santaa meressä,","Ja antoi sataa, niinkuin tomua, lihaa heille, ja lintuja niinkuin santaa meressä,"],[78,28,"Ja salli langeta keskelle heidän leiriänsä, joka paikassa kuin he asuivat.","Ja salli langeta keskelle heidän leiriänsä, joka paikassa kuin he asuivat."],[78,29,"Niin he söivät ja yltäkyllä ravittiin: ja hän antoi heille heidän himonsa,","Niin he söivät ja yltäkyllä ravittiin: ja hän antoi heille heidän himonsa,"],[78,30,"Kuin ei he vielä lakanneet himoitsemasta, ja ruoka oli vielä heidän suussansa,","Kuin ei he vielä lakanneet himoitsemasta, ja ruoka oli vielä heidän suussansa,"],[78,31,"Tuli Jumalan viha heidän päällensä, ja tappoi jaloimmat heidän seastansa, ja parahimmat Israelissa hän maahan löi.","Tuli Jumalan viha heidän päällensä, ja tappoi jaloimmat heidän seastansa, ja parahimmat Israelissa hän maahan löi."],[78,32,"Mutta vielä sittenkin kaikissa näissä he syntiä tekivät ja ei uskoneet hänen ihmeitänsä.","Mutta vielä sittenkin kaikissa näissä he syntiä tekivät ja ei uskoneet hänen ihmeitänsä."],[78,33,"Sentähden lopetti hän heidän päivänsä turhuudessa, ja heidän vuotensa kiiruhtain.","Sentähden lopetti hän heidän päivänsä turhuudessa, ja heidän vuotensa kiiruhtain."],[78,34,"Kuin hän heitä tappoi, etsivät he häntä: ja he palasivat ja tulivat varhain Jumalan tykö,","Kuin hän heitä tappoi, etsivät he häntä: ja he palasivat ja tulivat varhain Jumalan tykö,"],[78,35,"Ja muistelivat, että Jumala on heidän turvansa, ja Jumala korkein heidän lunastajansa.","Ja muistelivat, että Jumala on heidän turvansa, ja Jumala korkein heidän lunastajansa."],[78,36,"Ja he puhuivat hänelle ulkokullaisesti suullansa, ja valehtelivat hänelle kielellänsä.","Ja he puhuivat hänelle ulkokullaisesti suullansa, ja valehtelivat hänelle kielellänsä."],[78,37,"Mutta heidän sydämensä ei ollut oikia hänen puoleensa, ja ei he pitäneet uskollisesti hänen liittoansa.","Mutta heidän sydämensä ei ollut oikia hänen puoleensa, ja ei he pitäneet uskollisesti hänen liittoansa."],[78,38,"Mutta hän oli armollinen, ja antoi pahat teot anteeksi, ja ei hukuttanut heitä; ja hän käänsi pois usein vihansa, ettei hän laskenut kaikkea vihaansa menemään.","Mutta hän oli armollinen, ja antoi pahat teot anteeksi, ja ei hukuttanut heitä; ja hän käänsi pois usein vihansa, ettei hän laskenut kaikkea vihaansa menemään."],[78,39,"Sillä hän muisti heidän lihaksi, tuuleksi, joka menee pois ja ei palaja.","Sillä hän muisti heidän lihaksi, tuuleksi, joka menee pois ja ei palaja."],[78,40,"Kuinka usein he vihoittivat hänen korvessa ja kehoittivat hänen erämaassa?","Kuinka usein he vihoittivat hänen korvessa ja kehoittivat hänen erämaassa?"],[78,41,"Ja he kiusasivat taas Jumalaa joka aika, ja laittivat pyhää Israelissa.","Ja he kiusasivat taas Jumalaa joka aika, ja laittivat pyhää Israelissa."],[78,42,"Ei he muistaneet hänen kättänsä sinä päivänä, jona hän lunasti heitä vihollisista:","Ei he muistaneet hänen kättänsä sinä päivänä, jona hän lunasti heitä vihollisista:"],[78,43,"Niinkuin hän oli merkkinsä Egyptissä tehnyt, ja ihmeensä Zoanin kedolla,","Niinkuin hän oli merkkinsä Egyptissä tehnyt, ja ihmeensä Zoanin kedolla,"],[78,44,"Koska hän heidän virtansa vereksi muutti, ettei he ojistansa taitaneet juoda:","Koska hän heidän virtansa vereksi muutti, ettei he ojistansa taitaneet juoda:"],[78,45,"Koska hän turilaat heidän sekaansa lähetti, jotka heitä söivät, ja sammakot, jotka heitä hukuttivat;","Koska hän turilaat heidän sekaansa lähetti, jotka heitä söivät, ja sammakot, jotka heitä hukuttivat;"],[78,46,"Ja antoi heidän tulonsa ruohomadoille, ja heidän työnsä heinäsirkoille;","Ja antoi heidän tulonsa ruohomadoille, ja heidän työnsä heinäsirkoille;"],[78,47,"Koska hän rakeilla heidän viinapuunsa löi, ja heidän metsäfikunansa jääkivillä;","Koska hän rakeilla heidän viinapuunsa löi, ja heidän metsäfikunansa jääkivillä;"],[78,48,"Koska hän löi heidän karjansa rakeilla, ja heidän laumansa pitkäisen tulella;","Koska hän löi heidän karjansa rakeilla, ja heidän laumansa pitkäisen tulella;"],[78,49,"Hän lähetti heidän päällensä vihansa, närkästyksen, julmuuden ja ahdistuksen, pahain enkelien lähettämisellä;","Hän lähetti heidän päällensä vihansa, närkästyksen, julmuuden ja ahdistuksen, pahain enkelien lähettämisellä;"],[78,50,"Hän päästi vihansa heidän sekaansa, ja ei päästänyt heidän sielujansa kuolemasta, ja heidän eläimensä rutolla kuoletti;","Hän päästi vihansa heidän sekaansa, ja ei päästänyt heidän sielujansa kuolemasta, ja heidän eläimensä rutolla kuoletti;"],[78,51,"Koska hän kaikki esikoiset löi Egyptissä, ensimäiset perilliset Hamin majoissa,","Koska hän kaikki esikoiset löi Egyptissä, ensimäiset perilliset Hamin majoissa,"],[78,52,"Ja antoi kansansa vaeltaa niinkuin lampaat, ja vei heidät niinkuin lauman korvessa,","Ja antoi kansansa vaeltaa niinkuin lampaat, ja vei heidät niinkuin lauman korvessa,"],[78,53,"Ja saatti heitä turvallisesti, ettei he peljänneet; vaan heidän vihollisensa peitti meri.","Ja saatti heitä turvallisesti, ettei he peljänneet; vaan heidän vihollisensa peitti meri."],[78,54,"Ja hän vei heitä pyhänsä rajoihin, tämän vuoren tykö, jonka hänen oikia kätensä saanut oli.","Ja hän vei heitä pyhänsä rajoihin, tämän vuoren tykö, jonka hänen oikia kätensä saanut oli."],[78,55,"Ja hän ajoi pois heidän edestänsä pakanat, ja jakoi heille perimisen arvalla: ja niiden majoissa antoi hän Israelin sukukunnat asua.","Ja hän ajoi pois heidän edestänsä pakanat, ja jakoi heille perimisen arvalla: ja niiden majoissa antoi hän Israelin sukukunnat asua."],[78,56,"Mutta he kiusasivat ja vihoittivat korkian Jumalan, ja ei pitäneet hänen todistuksiansa.","Mutta he kiusasivat ja vihoittivat korkian Jumalan, ja ei pitäneet hänen todistuksiansa."],[78,57,"Vaan he palasivat takaperin ja petollisesti luopuivat pois niinkuin heidän isänsäkin: poikkesivat pois niinkuin hellinnyt joutsi.","Vaan he palasivat takaperin ja petollisesti luopuivat pois niinkuin heidän isänsäkin: poikkesivat pois niinkuin hellinnyt joutsi."],[78,58,"Ja he vihoittivat hänen korkeuksillansa ja kehoittivat häntä epäjumalainsa kuvilla.","Ja he vihoittivat hänen korkeuksillansa ja kehoittivat häntä epäjumalainsa kuvilla."],[78,59,"Ja kuin Jumala sen kuuli, niin hän närkästyi, ja hylkäsi kovin Israelin,","Ja kuin Jumala sen kuuli, niin hän närkästyi, ja hylkäsi kovin Israelin,"],[78,60,"Niin että hän luopui asuinsiastansa Silossa, siitä majasta, jonka hän ihmisten sekaan asetti,","Niin että hän luopui asuinsiastansa Silossa, siitä majasta, jonka hän ihmisten sekaan asetti,"],[78,61,"Ja antoi heidän voimansa vankeuteen, ja heidän kauneutensa vihollisten käsiin.","Ja antoi heidän voimansa vankeuteen, ja heidän kauneutensa vihollisten käsiin."],[78,62,"Ja hän hylkäsi kansansa miekan alle, ja närkästyi perimistänsä vastaan.","Ja hän hylkäsi kansansa miekan alle, ja närkästyi perimistänsä vastaan."],[78,63,"Heidän parhaat nuorukaisensa kulutti tuli, ja heidän neitseensä ei tulleet häävirsillä kunnioitetuksi.","Heidän parhaat nuorukaisensa kulutti tuli, ja heidän neitseensä ei tulleet häävirsillä kunnioitetuksi."],[78,64,"Heidän pappinsa kaatuivat miekalla; ja heidän leskensä ei itkeneet,","Heidän pappinsa kaatuivat miekalla; ja heidän leskensä ei itkeneet,"],[78,65,"Ja Herra heräsi niinkuin joku makaavainen, niinkuin joku väkevä luihkaaja viinan juomisesta,","Ja Herra heräsi niinkuin joku makaavainen, niinkuin joku väkevä luihkaaja viinan juomisesta,"],[78,66,"Ja löi vihollistansa perävieriin, ja pani ijankaikkisen häpiän heidän päällensä,","Ja löi vihollistansa perävieriin, ja pani ijankaikkisen häpiän heidän päällensä,"],[78,67,"Ja heitti Josephin majan pois, ja ei valinnut Ephraimin sukukuntaa.","Ja heitti Josephin majan pois, ja ei valinnut Ephraimin sukukuntaa."],[78,68,"Vaan hän valitsi Juudan sukukunnan, Zionin vuoren, jota hän rakasti,","Vaan hän valitsi Juudan sukukunnan, Zionin vuoren, jota hän rakasti,"],[78,69,"Ja rakensi pyhänsä korkialle, niinkuin ijankaikkisesti pysyväisen maan,","Ja rakensi pyhänsä korkialle, niinkuin ijankaikkisesti pysyväisen maan,"],[78,70,"Ja valitsi palveliansa Davidin, ja otti hänen lammashuoneesta.","Ja valitsi palveliansa Davidin, ja otti hänen lammashuoneesta."],[78,71,"Imettävistä lampaista haki hän hänen, että hän hänen kanssansa Jakobin kaitsis, ja Israelin hänen perimisensä.","Imettävistä lampaista haki hän hänen, että hän hänen kanssansa Jakobin kaitsis, ja Israelin hänen perimisensä."],[78,72,"Ja hän kaitsi heitä kaikella sydämensä vakuudella, ja hallitsi heitä kaikella ahkeruudella.","Ja hän kaitsi heitä kaikella sydämensä vakuudella, ja hallitsi heitä kaikella ahkeruudella."],[79,1,"Asaphin Psalmi. Jumala, pakanat ovat perikuntaas karanneet: he ovat saastuttaneet pyhän temppelis, ja Jerusalemista kiviraunion tehneet.","Asaphin Psalmi. Jumala, pakanat ovat perikuntaas karanneet: he ovat saastuttaneet pyhän temppelis, ja Jerusalemista kiviraunion tehneet."],[79,2,"He antoivat sinun palveliais ruumiit linnuille taivaan alla ruaksi, ja pyhäis lihan maan pedoille.","He antoivat sinun palveliais ruumiit linnuille taivaan alla ruaksi, ja pyhäis lihan maan pedoille."],[79,3,"He vuodattivat heidän verensä niinkuin veden Jerusalemin ympärille, ja ei kenkään haudannut.","He vuodattivat heidän verensä niinkuin veden Jerusalemin ympärille, ja ei kenkään haudannut."],[79,4,"Me olemme läsnäasuvaisillemme nauruksi tulleet, häväistykseksi ja pilkaksi niille, jotka meidän ympärillämme ovat.","Me olemme läsnäasuvaisillemme nauruksi tulleet, häväistykseksi ja pilkaksi niille, jotka meidän ympärillämme ovat."],[79,5,"Herra, kuinka kauvan sinä taukoomata niin vihainen olet? ja annat kiivautes palaa niinkuin tulen?","Herra, kuinka kauvan sinä taukoomata niin vihainen olet? ja annat kiivautes palaa niinkuin tulen?"],[79,6,"Vuodata vihas pakanain päälle, jotka ei sinua tunne, ja niiden valtakuntain päälle, jotka ei sinun nimeäs avuksi huuda;","Vuodata vihas pakanain päälle, jotka ei sinua tunne, ja niiden valtakuntain päälle, jotka ei sinun nimeäs avuksi huuda;"],[79,7,"Sillä he ovat Jakobin syöneet, ja hänen huoneensa hävittäneet.","Sillä he ovat Jakobin syöneet, ja hänen huoneensa hävittäneet."],[79,8,"Älä muistele meidän entisiä pahoja tekojamme: armahda sinuas nopiasti meidän päällemme; sillä me olemme sangen viheliäisiksi tulleet.","Älä muistele meidän entisiä pahoja tekojamme: armahda sinuas nopiasti meidän päällemme; sillä me olemme sangen viheliäisiksi tulleet."],[79,9,"Auta meitä, meidän autuutemme Jumala, sinun nimes kunnian tähden: pelasta meitä, ja anna meille synnit anteeksi sinun nimes tähden.","Auta meitä, meidän autuutemme Jumala, sinun nimes kunnian tähden: pelasta meitä, ja anna meille synnit anteeksi sinun nimes tähden."],[79,10,"Miksis sallit pakanain sanoa: kussa on nyt heidän Jumalansa? ilmoitettakaan pakanain seassa, meidän silmäimme edessä, sinun palveliais veren kosto, joka vuodatettu on!","Miksis sallit pakanain sanoa: kussa on nyt heidän Jumalansa? ilmoitettakaan pakanain seassa, meidän silmäimme edessä, sinun palveliais veren kosto, joka vuodatettu on!"],[79,11,"Anna etees tulla vankein huokaukset: suuren käsivartes kautta, korjaa kuoleman lapset,","Anna etees tulla vankein huokaukset: suuren käsivartes kautta, korjaa kuoleman lapset,"],[79,12,"Ja kosta meidän läsnäasuvaisillemme seitsemin kerroin heidän helmaansa heidän pilkkansa, jolla he sinua, Herra, pilkanneet ovat.","Ja kosta meidän läsnäasuvaisillemme seitsemin kerroin heidän helmaansa heidän pilkkansa, jolla he sinua, Herra, pilkanneet ovat."],[79,13,"Mutta me sinun kansas, ja sinun laitumes lauma, kiitämme sinua ijankaikkisesti, ja julistamme sinun kiitostas suvusta sukuun.","Mutta me sinun kansas, ja sinun laitumes lauma, kiitämme sinua ijankaikkisesti, ja julistamme sinun kiitostas suvusta sukuun."],[80,1,"Asaphin Psalmi, kultasesta kukkaisesta, edelläveisaajalle. (H80:2) Kuules, Israelin paimen, joka saatat Josephin niinkuin lampaat: ilmoita sinus, joka istut Kerubimin päällä.","Asaphin Psalmi, kultasesta kukkaisesta, edelläveisaajalle. (H80:2) Kuules, Israelin paimen, joka saatat Josephin niinkuin lampaat: ilmoita sinus, joka istut Kerubimin päällä."],[80,2,"Herätä voimas, sinä joka Ephraimin, Benjaminin ja Manassen edessä olet, ja tule meidän avuksemme.","Herätä voimas, sinä joka Ephraimin, Benjaminin ja Manassen edessä olet, ja tule meidän avuksemme."],[80,3,"Jumala, käännä meitä, ja anna kasvos paistaa, niin me tulemme autetuksi.","Jumala, käännä meitä, ja anna kasvos paistaa, niin me tulemme autetuksi."],[80,4,"Herra Jumala Zebaot, kuinka kauvan sinä vihastut kansas rukouksiin?","Herra Jumala Zebaot, kuinka kauvan sinä vihastut kansas rukouksiin?"],[80,5,"Sinä ruokit heitä kyyneleiden leivällä, ja juotat heitä suurella mitalla, täynnä kyyneleitä,","Sinä ruokit heitä kyyneleiden leivällä, ja juotat heitä suurella mitalla, täynnä kyyneleitä,"],[80,6,"Sinä olet meidät pannut riidaksi läsnäasuvaisillemme; ja meidän vihollisemme pilkkaavat meitä.","Sinä olet meidät pannut riidaksi läsnäasuvaisillemme; ja meidän vihollisemme pilkkaavat meitä."],[80,7,"Jumala Zebaot, käännä meitä, ja anna kasvos paistaa, niin me autetuksi tulemme.","Jumala Zebaot, käännä meitä, ja anna kasvos paistaa, niin me autetuksi tulemme."],[80,8,"Sinä toit viinapuun Egyptistä, olet pakanat karkoittanut ulos, ja sen istuttanut.","Sinä toit viinapuun Egyptistä, olet pakanat karkoittanut ulos, ja sen istuttanut."],[80,9,"Sinä perkasit tien hänen eteensä, ja annoit hänen hyvästi juurtua, niin että se täytti maan.","Sinä perkasit tien hänen eteensä, ja annoit hänen hyvästi juurtua, niin että se täytti maan."],[80,10,"Vuoret ovat sen varjolla peitetyt, ja hänen oksillansa Jumalan sedripuut.","Vuoret ovat sen varjolla peitetyt, ja hänen oksillansa Jumalan sedripuut."],[80,11,"Sinä levitit hänen oksansa hamaan mereen asti, ja hänen haaransa hamaan virran tykö.","Sinä levitit hänen oksansa hamaan mereen asti, ja hänen haaransa hamaan virran tykö."],[80,12,"Miksis siis särjit hänen aitansa, että sitä kaikki ohitsekäyvät repivät.","Miksis siis särjit hänen aitansa, että sitä kaikki ohitsekäyvät repivät."],[80,13,"Metsäsika on sen kaivanut ylös, ja metsän pedot sen syövät.","Metsäsika on sen kaivanut ylös, ja metsän pedot sen syövät."],[80,14,"Jumala Zebaot, käännä siis sinuas, katso alas taivaasta ja näe, ja etsi sitä viinapuuta,","Jumala Zebaot, käännä siis sinuas, katso alas taivaasta ja näe, ja etsi sitä viinapuuta,"],[80,15,"Ja pidä se kiintiänä, jonka sinun oikia kätes on istuttanut, (ihmisen) pojan tähden, jonka sinulles lujasti valinnut olet.","Ja pidä se kiintiänä, jonka sinun oikia kätes on istuttanut, (ihmisen) pojan tähden, jonka sinulles lujasti valinnut olet."],[80,16,"Se on poltettu tulella ja revitty: sinun uhkauksestas he ovat hukkuneet.","Se on poltettu tulella ja revitty: sinun uhkauksestas he ovat hukkuneet."],[80,17,"Sinun kätes varjelkoon oikian kätes kansan, ja ihmisen pojan, jonka sinulles lujasti valinnut olet.","Sinun kätes varjelkoon oikian kätes kansan, ja ihmisen pojan, jonka sinulles lujasti valinnut olet."],[80,18,"Niin emme sinusta luovu: suo meidän elää, niin me sinun nimeäs avuksi huudamme.","Niin emme sinusta luovu: suo meidän elää, niin me sinun nimeäs avuksi huudamme."],[80,19,"Herra Jumala Zebaot, käännä meitä: anna kasvos paistaa, niin me autetuksi tulemme.","Herra Jumala Zebaot, käännä meitä: anna kasvos paistaa, niin me autetuksi tulemme."],[81,1,"Gittitin päällä, edelläveisaajalle, Asaphin (Psalmi.) (H81:2) Veisatkaat iloisesti Jumalalle, joka on meidän väkevyytemme: ihastukaat Jakobin Jumalalle.","Gittitin päällä, edelläveisaajalle, Asaphin (Psalmi.) (H81:2) Veisatkaat iloisesti Jumalalle, joka on meidän väkevyytemme: ihastukaat Jakobin Jumalalle."],[81,2,"Ottakaat psalmit ja tuokaat kanteleet, iloiset harput ja psaltari.","Ottakaat psalmit ja tuokaat kanteleet, iloiset harput ja psaltari."],[81,3,"Soittakaat pasunilla uudessa kuussa, meidän lehtimajamme juhlapäivänä.","Soittakaat pasunilla uudessa kuussa, meidän lehtimajamme juhlapäivänä."],[81,4,"Sillä se on tapa Israelissa, ja Jakobin Jumalan oikeus.","Sillä se on tapa Israelissa, ja Jakobin Jumalan oikeus."],[81,5,"Sen hän pani Josephissa todistukseksi, koska he Egyptin maalta läksivät, ja oudon kielen kuulleet olivat.","Sen hän pani Josephissa todistukseksi, koska he Egyptin maalta läksivät, ja oudon kielen kuulleet olivat."],[81,6,"Minä olen heidän olkansa kuormasta vapahtanut; ja heidän kätensä pääsivät tiiliä tekemästä.","Minä olen heidän olkansa kuormasta vapahtanut; ja heidän kätensä pääsivät tiiliä tekemästä."],[81,7,"Koska sinä tuskassas minua avukses huusit, niin minä autin sinua: minä kuulin sinua, koska tuulispää tuli sinun päälles, ja koettelin sinua riitaveden tykönä, Sela!","Koska sinä tuskassas minua avukses huusit, niin minä autin sinua: minä kuulin sinua, koska tuulispää tuli sinun päälles, ja koettelin sinua riitaveden tykönä, Sela!"],[81,8,"Kuule, minun kansani, minä todistan sinun seassas: Israel, jospa sinä minua kuulisit!","Kuule, minun kansani, minä todistan sinun seassas: Israel, jospa sinä minua kuulisit!"],[81,9,"Ei pidä sinun seassas muukalainen jumala oleman, ja ei pidä sinun vierasta jumalaa kumartaman.","Ei pidä sinun seassas muukalainen jumala oleman, ja ei pidä sinun vierasta jumalaa kumartaman."],[81,10,"Minä olen Herra sinun Jumalas, joka sinun vein ulos Egyptin maalta: levitä suus, niin minä sen täytän.","Minä olen Herra sinun Jumalas, joka sinun vein ulos Egyptin maalta: levitä suus, niin minä sen täytän."],[81,11,"Mutta minun kansani ei kuullut minun ääntäni, ja Israel ei totellut minua.","Mutta minun kansani ei kuullut minun ääntäni, ja Israel ei totellut minua."],[81,12,"Niin minä laskin heitä sydämensä pahuuteen, vaeltamaan neuvonsa jälkeen.","Niin minä laskin heitä sydämensä pahuuteen, vaeltamaan neuvonsa jälkeen."],[81,13,"Jos minun kansani kuulis minua, ja Israel minun teissäni kävis,","Jos minun kansani kuulis minua, ja Israel minun teissäni kävis,"],[81,14,"Niin minä pian heidän vihollisensa painaisin alas, ja käteni kääntäisin heidän vihollistensa päälle,","Niin minä pian heidän vihollisensa painaisin alas, ja käteni kääntäisin heidän vihollistensa päälle,"],[81,15,"Ja Herran viholliset hukkaan tulisivat; mutta heidän aikansa olisi ijankaikkisesti pysyvä,","Ja Herran viholliset hukkaan tulisivat; mutta heidän aikansa olisi ijankaikkisesti pysyvä,"],[81,16,"Ja minä ruokkisin heitä parhailla nisuilla, ja ravitsisin heitä hunajalla kalliosta.","Ja minä ruokkisin heitä parhailla nisuilla, ja ravitsisin heitä hunajalla kalliosta."],[82,1,"Asaphin Psalmi. Jumala seisoo Jumalan seurakunnassa: hän on tuomari Jumalain seassa.","Asaphin Psalmi. Jumala seisoo Jumalan seurakunnassa: hän on tuomari Jumalain seassa."],[82,2,"Kuinka kauvan te väärin tuomitsette, ja jumalattoman muotoa katsotte? Sela!","Kuinka kauvan te väärin tuomitsette, ja jumalattoman muotoa katsotte? Sela!"],[82,3,"Tehkää oikeus köyhälle ja orvolle, ja auttakaat raadolliset ja vaivaiset oikeudelle.","Tehkää oikeus köyhälle ja orvolle, ja auttakaat raadolliset ja vaivaiset oikeudelle."],[82,4,"Pelastakaat ylönkatsottua ja köyhää, ja päästäkäät häntä jumalattoman kädestä.","Pelastakaat ylönkatsottua ja köyhää, ja päästäkäät häntä jumalattoman kädestä."],[82,5,"Mutta ei he tottele eikä lukua pidä: he käyvät lakkaamata pimeässä: sentähden täytyy kaikki maan perustukset kaatua.","Mutta ei he tottele eikä lukua pidä: he käyvät lakkaamata pimeässä: sentähden täytyy kaikki maan perustukset kaatua."],[82,6,"Minä tosin sanoin: te olette jumalat, ja kaikki Korkeimman lapset;","Minä tosin sanoin: te olette jumalat, ja kaikki Korkeimman lapset;"],[82,7,"Kuitenkin täytyy teidän kuolla niinkuin ihmiset, ja niinkuin tyrannit hukkua.","Kuitenkin täytyy teidän kuolla niinkuin ihmiset, ja niinkuin tyrannit hukkua."],[82,8,"Nouse, Jumala, ja tuomitse maa; sillä kaikki pakanat ovat sinun omas.","Nouse, Jumala, ja tuomitse maa; sillä kaikki pakanat ovat sinun omas."],[83,1,"Asaphin Psalmi ja veisu. (H83:2) Jumala, älä niin ratki vaikene, ja älä niin ääneti ole: Jumala, älä sitä niin kärsi.","Asaphin Psalmi ja veisu. (H83:2) Jumala, älä niin ratki vaikene, ja älä niin ääneti ole: Jumala, älä sitä niin kärsi."],[83,2,"Sillä katso, Sinun vihollises kiukuitsevat, ja jotka sinua vihaavat, ylentävät päänsä.","Sillä katso, Sinun vihollises kiukuitsevat, ja jotka sinua vihaavat, ylentävät päänsä."],[83,3,"He pitävät kavaloita juonia sinun kansaas vastaan, ja pitävät neuvoa sinun salatuitas vastaan,","He pitävät kavaloita juonia sinun kansaas vastaan, ja pitävät neuvoa sinun salatuitas vastaan,"],[83,4,"Sanoen: tulkaat, hävittäkäämme heitä, niin ettei he ensinkään kansa olisikaan, ettei Israelin nimeä silleen muisteltaisi.","Sanoen: tulkaat, hävittäkäämme heitä, niin ettei he ensinkään kansa olisikaan, ettei Israelin nimeä silleen muisteltaisi."],[83,5,"Sillä he ovat sydämessänsä panneet neuvonsa yhteen, ja tehneet liiton sinua vastaan:","Sillä he ovat sydämessänsä panneet neuvonsa yhteen, ja tehneet liiton sinua vastaan:"],[83,6,"Edomilaiset ja Ismaelilaiset majat, Moabilaiset ja Hagarilaiset,","Edomilaiset ja Ismaelilaiset majat, Moabilaiset ja Hagarilaiset,"],[83,7,"Gebalilaiset, Ammonilaiset ja Amalekilaiset, Philistealaiset ja Tyron asuvaiset.","Gebalilaiset, Ammonilaiset ja Amalekilaiset, Philistealaiset ja Tyron asuvaiset."],[83,8,"Assur on myös itsensä heihin liittänyt, auttamaan Lotin lapsia, Sela!","Assur on myös itsensä heihin liittänyt, auttamaan Lotin lapsia, Sela!"],[83,9,"Tee niille niinkuin Midianilaisille, niinkuin Siseralle, niinkuin Jabinille Kisonin ojan tykönä;","Tee niille niinkuin Midianilaisille, niinkuin Siseralle, niinkuin Jabinille Kisonin ojan tykönä;"],[83,10,"Jotka mestattiin Endorin tykönä, ja tulivat loaksi maan päälle.","Jotka mestattiin Endorin tykönä, ja tulivat loaksi maan päälle."],[83,11,"Tee heidän pääruhtinaansa niinkuin Orebin ja Seebin, ja kaikki heidän ylimmäisensä niinkuin Seban ja Salmunnan,","Tee heidän pääruhtinaansa niinkuin Orebin ja Seebin, ja kaikki heidän ylimmäisensä niinkuin Seban ja Salmunnan,"],[83,12,"Jotka sanovat: me omistamme meillemme Jumalan huoneet.","Jotka sanovat: me omistamme meillemme Jumalan huoneet."],[83,13,"Jumala, tee heitä niinkuin rattaan, niinkuin korren tuulen edessä.","Jumala, tee heitä niinkuin rattaan, niinkuin korren tuulen edessä."],[83,14,"Niinkuin kulo metsän polttaa, ja niinkuin liekki mäet sytyttää;","Niinkuin kulo metsän polttaa, ja niinkuin liekki mäet sytyttää;"],[83,15,"Vainoo juuri niin heitä sinun rajuilmallas, ja hämmästytä heitä tuulispäälläs.","Vainoo juuri niin heitä sinun rajuilmallas, ja hämmästytä heitä tuulispäälläs."],[83,16,"Täytä heidän kasvonsa häpiällä, että he sinun nimeäs, Herra, etsisivät.","Täytä heidän kasvonsa häpiällä, että he sinun nimeäs, Herra, etsisivät."],[83,17,"Hävetköön he ja hämmästyköön ijankaikkisesti, ja häpiään tulkoon ja hukkukoon.","Hävetköön he ja hämmästyköön ijankaikkisesti, ja häpiään tulkoon ja hukkukoon."],[83,18,"Niin he saavat tuta, että sinä, jonka ainoan nimi on Herra, olet ylimmäinen kaikessa maailmassa.","Niin he saavat tuta, että sinä, jonka ainoan nimi on Herra, olet ylimmäinen kaikessa maailmassa."],[84,1,"Koran lasten Psalmi, Gittitin päällä, edelläveisaajalle. (H84:2) Kuinka ihanat ovat sinun asuinsijas, Herra Zebaot!","Koran lasten Psalmi, Gittitin päällä, edelläveisaajalle. (H84:2) Kuinka ihanat ovat sinun asuinsijas, Herra Zebaot!"],[84,2,"Minun sieluni ikävöitsee ja halajaa Herran esikartanoihin: minun ruumiini ja sieluni iloitsee elävässä Jumalassa.","Minun sieluni ikävöitsee ja halajaa Herran esikartanoihin: minun ruumiini ja sieluni iloitsee elävässä Jumalassa."],[84,3,"Sillä lintu on huoneen löytänyt, ja pääskynen pesänsä, johonka he poikansa laskevat: sinun alttaris, Herra Zebaot, minun kuninkaani ja minun Jumalani.","Sillä lintu on huoneen löytänyt, ja pääskynen pesänsä, johonka he poikansa laskevat: sinun alttaris, Herra Zebaot, minun kuninkaani ja minun Jumalani."],[84,4,"Autuaat ovat, jotka sinun huoneessas asuvat: he kiittävät sinua ijankaikkisesti, Sela!","Autuaat ovat, jotka sinun huoneessas asuvat: he kiittävät sinua ijankaikkisesti, Sela!"],[84,5,"Autuaat ovat ne ihmiset, jotka sinun pitävät väkenänsä, ja sydämestänsä vaeltavat sinun jälkees,","Autuaat ovat ne ihmiset, jotka sinun pitävät väkenänsä, ja sydämestänsä vaeltavat sinun jälkees,"],[84,6,"Jotka käyvät itkun laakson lävitse, ja tekevät siellä kaivoja; ja opettajat monella siunauksella kaunistetaan.","Jotka käyvät itkun laakson lävitse, ja tekevät siellä kaivoja; ja opettajat monella siunauksella kaunistetaan."],[84,7,"He saavat yhden voiton toisen jälkeen, että tunnettaisiin oikia Jumala Zionissa.","He saavat yhden voiton toisen jälkeen, että tunnettaisiin oikia Jumala Zionissa."],[84,8,"Herra Jumala Zebaot, kuule minun rukoukseni: ota, Jakobin Jumala, tätä korviis, Sela!","Herra Jumala Zebaot, kuule minun rukoukseni: ota, Jakobin Jumala, tätä korviis, Sela!"],[84,9,"Katsele siis, Jumala, meidän kilpemme, katso sinun voideltus kasvoja.","Katsele siis, Jumala, meidän kilpemme, katso sinun voideltus kasvoja."],[84,10,"Sillä yksi päivä esikartanoissas on parempi kuin tuhannen muualla: ennen minä olisin ovenvartia Jumalani huoneessa, kuin asuisin jumalattomain majoissa.","Sillä yksi päivä esikartanoissas on parempi kuin tuhannen muualla: ennen minä olisin ovenvartia Jumalani huoneessa, kuin asuisin jumalattomain majoissa."],[84,11,"Sillä Herra Jumala on aurinko ja kilpi: Herra antaa armon ja kunnian: ei hän anna hurskailta mitään hyvää puuttua.","Sillä Herra Jumala on aurinko ja kilpi: Herra antaa armon ja kunnian: ei hän anna hurskailta mitään hyvää puuttua."],[84,12,"Herra Zebaot, autuas on se ihminen, joka sinuun uskaltaa.","Herra Zebaot, autuas on se ihminen, joka sinuun uskaltaa."],[85,1,"Koran lasten Psalmi, edelläveisaajalle. (H85:2) Herra, sinä kuin (muinen) olit armollinen sinun maakunnalles, ja Jakobin vangit lunastit,","Koran lasten Psalmi, edelläveisaajalle. (H85:2) Herra, sinä kuin (muinen) olit armollinen sinun maakunnalles, ja Jakobin vangit lunastit,"],[85,2,"Sinä anteeksi annoit kansas pahat teot, ja kaikki heidän syntinsä peitit, Sela!","Sinä anteeksi annoit kansas pahat teot, ja kaikki heidän syntinsä peitit, Sela!"],[85,3,"Sinä lepytit kaiken vihas, ja käänsit sinuas vihas julmuudesta.","Sinä lepytit kaiken vihas, ja käänsit sinuas vihas julmuudesta."],[85,4,"Käännä meitä, meidän autuutemme Jumala, ja pane pois vihas meistä.","Käännä meitä, meidän autuutemme Jumala, ja pane pois vihas meistä."],[85,5,"Tahdotkos siis ijankaikkisesti olla vihainen meidän päällemme? eli vihas pitää sukukunnasta sukukuntaan?","Tahdotkos siis ijankaikkisesti olla vihainen meidän päällemme? eli vihas pitää sukukunnasta sukukuntaan?"],[85,6,"Etkös käänny, ja meitä virvoita, että kansas sinussa iloitsis?","Etkös käänny, ja meitä virvoita, että kansas sinussa iloitsis?"],[85,7,"Herra, osoita meille armos, ja sinun autuutes anna meille.","Herra, osoita meille armos, ja sinun autuutes anna meille."],[85,8,"Jospa minä kuulisin, mitä Herra Jumala puhuu, että hän rauhan lupasi kansallensa ja pyhillensä, ettei he hulluuteen joutuisi.","Jospa minä kuulisin, mitä Herra Jumala puhuu, että hän rauhan lupasi kansallensa ja pyhillensä, ettei he hulluuteen joutuisi."],[85,9,"Kuitenkin on hänen apunsa niiden tykönä, jotka häntä pelkäävät, että meidän maallamme kunnia asuis;","Kuitenkin on hänen apunsa niiden tykönä, jotka häntä pelkäävät, että meidän maallamme kunnia asuis;"],[85,10,"Että laupius ja totuus keskenänsä kohtaisivat: vanhurskaus ja rauha toinen toisellensa suuta antaisivat;","Että laupius ja totuus keskenänsä kohtaisivat: vanhurskaus ja rauha toinen toisellensa suuta antaisivat;"],[85,11,"Että totuus maasta vesois, ja vanhurskaus taivaasta katsois;","Että totuus maasta vesois, ja vanhurskaus taivaasta katsois;"],[85,12,"Että myös meille Herra hyvin tekis, ja meidän maamme hedemänsä antais;","Että myös meille Herra hyvin tekis, ja meidän maamme hedemänsä antais;"],[85,13,"Että vanhurskaus sittenkin hänen edessänsä pysyis ja menestyis.","Että vanhurskaus sittenkin hänen edessänsä pysyis ja menestyis."],[86,1,"Davidin rukous. Kallista, Herra, korvas ja kuule minua; sillä minä olen raadollinen ja köyhä.","Davidin rukous. Kallista, Herra, korvas ja kuule minua; sillä minä olen raadollinen ja köyhä."],[86,2,"Kätke minun sieluni; sillä minä olen pyhä. Auta minua, minun Jumalani, palveliaas, joka sinuun luotan.","Kätke minun sieluni; sillä minä olen pyhä. Auta minua, minun Jumalani, palveliaas, joka sinuun luotan."],[86,3,"Herra, ole minulle armollinen; sillä minä huudan ylipäivää sinua.","Herra, ole minulle armollinen; sillä minä huudan ylipäivää sinua."],[86,4,"Ilahuta palvelias sielu; sillä sinun tykös, Herra, minä ylennän sieluni.","Ilahuta palvelias sielu; sillä sinun tykös, Herra, minä ylennän sieluni."],[86,5,"Sillä sinä, Herra, olet hyvä ja armollinen, sangen laupias kaikille, jotka sinua avuksensa huutavat.","Sillä sinä, Herra, olet hyvä ja armollinen, sangen laupias kaikille, jotka sinua avuksensa huutavat."],[86,6,"Ota korviis, Herra, minun rukoukseni, ja ota vaari minun rukoukseni äänestä.","Ota korviis, Herra, minun rukoukseni, ja ota vaari minun rukoukseni äänestä."],[86,7,"Tuskassani minä sinua rukoilen, ettäs minun kuulisit.","Tuskassani minä sinua rukoilen, ettäs minun kuulisit."],[86,8,"Herra! ei ole yksikään jumalista sinun kaltaises, ja ei ole kenkään, joka niin tehdä taitaa kuin sinä.","Herra! ei ole yksikään jumalista sinun kaltaises, ja ei ole kenkään, joka niin tehdä taitaa kuin sinä."],[86,9,"Kaikki pakanat, jotka tehnyt olet, pitää tuleman ja kumartaman sinua, Herra, ja sinun nimeäs kunnioittaman,","Kaikki pakanat, jotka tehnyt olet, pitää tuleman ja kumartaman sinua, Herra, ja sinun nimeäs kunnioittaman,"],[86,10,"Ettäs niin suuri olet, ja teet ihmeitä; ja sinä olet yksinäs Jumala.","Ettäs niin suuri olet, ja teet ihmeitä; ja sinä olet yksinäs Jumala."],[86,11,"Osoita minulle, Herra, sinun ties, vaeltaakseni sinun totuudessas: kiinnitä minun sydämeni siihen yhteen, että minä sinun nimeäs pelkäisin.","Osoita minulle, Herra, sinun ties, vaeltaakseni sinun totuudessas: kiinnitä minun sydämeni siihen yhteen, että minä sinun nimeäs pelkäisin."],[86,12,"Minä kiitän sinua, Herra minun Jumalani, kaikesta sydämestäni, ja kunnioitan sinun nimeäs ijankaikkisesti.","Minä kiitän sinua, Herra minun Jumalani, kaikesta sydämestäni, ja kunnioitan sinun nimeäs ijankaikkisesti."],[86,13,"Sillä sinun hyvyytes on suuri minussa, ja sinä olet pelastanut sieluni syvimmästä helvetistä.","Sillä sinun hyvyytes on suuri minussa, ja sinä olet pelastanut sieluni syvimmästä helvetistä."],[86,14,"Jumala! ylpiät karkaavat minua vastaan, ja julmain joukot väijyvät minun sieluani, ja ei pidä sinua silmäinsä edessä.","Jumala! ylpiät karkaavat minua vastaan, ja julmain joukot väijyvät minun sieluani, ja ei pidä sinua silmäinsä edessä."],[86,15,"Mutta sinä, Herra Jumala, olet armollinen ja laupias, kärsiväinen ja sangen hyvä ja vakaa.","Mutta sinä, Herra Jumala, olet armollinen ja laupias, kärsiväinen ja sangen hyvä ja vakaa."],[86,16,"Käännä itses minuun päin, ole minulle armollinen; vahvista palveliaas sinun voimallas, ja auta piikas poikaa.","Käännä itses minuun päin, ole minulle armollinen; vahvista palveliaas sinun voimallas, ja auta piikas poikaa."],[86,17,"Tee merkki minun kanssani, että minulle hyvin kävis, ja he sen näkisivät, jotka minua vihaavat, ja häpeäisivät, että sinä Herra autat ja lohdutat minua.","Tee merkki minun kanssani, että minulle hyvin kävis, ja he sen näkisivät, jotka minua vihaavat, ja häpeäisivät, että sinä Herra autat ja lohdutat minua."],[87,1,"Psalmi, Koran lasten veisu. Hän on vahvasti perustettu pyhäin vuorten päälle.","Psalmi, Koran lasten veisu. Hän on vahvasti perustettu pyhäin vuorten päälle."],[87,2,"Herra rakastaa Zionin portteja enempi kuin kaikkia Jakobin asuinsioja.","Herra rakastaa Zionin portteja enempi kuin kaikkia Jakobin asuinsioja."],[87,3,"Korkiat ja kunnialliset asiat sinussa saarnataan, sinä Jumalan kaupunki, Sela!","Korkiat ja kunnialliset asiat sinussa saarnataan, sinä Jumalan kaupunki, Sela!"],[87,4,"Minä annan saarnata Rahabin ja Babelin edessä, että he minun tuntevat: katso, Philistealaiset, Tyrolaiset ja Etiopialaiset syntyvät siellä.","Minä annan saarnata Rahabin ja Babelin edessä, että he minun tuntevat: katso, Philistealaiset, Tyrolaiset ja Etiopialaiset syntyvät siellä."],[87,5,"Zionille pitää sanottaman, että kaikkinaiset kansat siellä syntyvät, ja että Korkein sitä rakentaa.","Zionille pitää sanottaman, että kaikkinaiset kansat siellä syntyvät, ja että Korkein sitä rakentaa."],[87,6,"Herra antaa saarnata kirjoituksessa kaikkinaisilla kielillä, että myös muutamat heistä siellä syntyvät, Sela!","Herra antaa saarnata kirjoituksessa kaikkinaisilla kielillä, että myös muutamat heistä siellä syntyvät, Sela!"],[87,7,"Ja veisaajat niinkuin tanssissa, kaikki minun lähteeni sinussa.","Ja veisaajat niinkuin tanssissa, kaikki minun lähteeni sinussa."],[88,1,"Psalmi, Koran lasten veisu, edelläveisaajalle, raadollisten heikkoudesta, Hemanin Esrahilaisen oppi. (H88:2) Herra, minun autuuteni Jumala, minä huudan päivällä ja yöllä sinun edessäs,","Psalmi, Koran lasten veisu, edelläveisaajalle, raadollisten heikkoudesta, Hemanin Esrahilaisen oppi. (H88:2) Herra, minun autuuteni Jumala, minä huudan päivällä ja yöllä sinun edessäs,"],[88,2,"Anna minun rukoukseni etees tulla: kallista korvas huutoni puoleen.","Anna minun rukoukseni etees tulla: kallista korvas huutoni puoleen."],[88,3,"Sillä minun sieluni on surkeutta täynnä, ja minun elämäni on juuri liki helvettiä.","Sillä minun sieluni on surkeutta täynnä, ja minun elämäni on juuri liki helvettiä."],[88,4,"Minä olen arvattu niiden kaltaiseksi, jotka hautaan menevät: minä olen niinkuin se mies, jolla ei yhtään apua ole.","Minä olen arvattu niiden kaltaiseksi, jotka hautaan menevät: minä olen niinkuin se mies, jolla ei yhtään apua ole."],[88,5,"Minä makaan hyljättynä kuolleiden seassa, niinkuin haavoitetut, jotka haudassa makaavat, joita et sinä enää muista, ja jotka kädestäs eroitetut ovat.","Minä makaan hyljättynä kuolleiden seassa, niinkuin haavoitetut, jotka haudassa makaavat, joita et sinä enää muista, ja jotka kädestäs eroitetut ovat."],[88,6,"Sinä olet painanut minun alimmaiseen kaivoon, pimeyteen ja syvyyteen.","Sinä olet painanut minun alimmaiseen kaivoon, pimeyteen ja syvyyteen."],[88,7,"Sinun hirmuisuutes ahdistaa minua, ja pakottaa minua sinun aalloillas, Sela!","Sinun hirmuisuutes ahdistaa minua, ja pakottaa minua sinun aalloillas, Sela!"],[88,8,"Sinä eroitat kauvas ystäväni minusta: sinä olet minun tehnyt heille kauhistukseksi: minä makaan vangittuna, etten minä voi päästä ulos.","Sinä eroitat kauvas ystäväni minusta: sinä olet minun tehnyt heille kauhistukseksi: minä makaan vangittuna, etten minä voi päästä ulos."],[88,9,"Minun kasvoni ovat surkiat raadollisuuden tähden: Herra, minä avukseni huudan sinua joka päivä: minä hajoitan käteni sinun puolees.","Minun kasvoni ovat surkiat raadollisuuden tähden: Herra, minä avukseni huudan sinua joka päivä: minä hajoitan käteni sinun puolees."],[88,10,"Teetkös siis ihmeitä kuolleiden seassa? eli nousevatko kuolleet sinua kiittämään? Sela!","Teetkös siis ihmeitä kuolleiden seassa? eli nousevatko kuolleet sinua kiittämään? Sela!"],[88,11,"Luetellaanko haudoissa sinun hyvyyttäs? ja totuuttas kadotuksessa?","Luetellaanko haudoissa sinun hyvyyttäs? ja totuuttas kadotuksessa?"],[88,12,"Tunnetaanko sinun ihmees pimiässä? eli vanhurskautes siinä maassa, jossa kaikki unohdetaan?","Tunnetaanko sinun ihmees pimiässä? eli vanhurskautes siinä maassa, jossa kaikki unohdetaan?"],[88,13,"Mutta minä huudan sinua, Herra, ja minun rukoukseni tulee varhain sinun etees.","Mutta minä huudan sinua, Herra, ja minun rukoukseni tulee varhain sinun etees."],[88,14,"Miksis, Herra, heität pois sieluni, ja peität kasvos minulta?","Miksis, Herra, heität pois sieluni, ja peität kasvos minulta?"],[88,15,"Minä olen raadollinen ja väetöin, että minä niin hylätty olen: minä kärsin sinun hirmuisuuttas, että minä lähes epäilen.","Minä olen raadollinen ja väetöin, että minä niin hylätty olen: minä kärsin sinun hirmuisuuttas, että minä lähes epäilen."],[88,16,"Sinun vihas tulee minun päälleni: sinun pelkos likistää minua.","Sinun vihas tulee minun päälleni: sinun pelkos likistää minua."],[88,17,"Ne saartavat minua joka päivä niinkuin vesi, ja ynnä minua piirittävät.","Ne saartavat minua joka päivä niinkuin vesi, ja ynnä minua piirittävät."],[88,18,"Sinä teet, että minun ystäväni ja lähimmäiseni erkanevat kauvas minusta, ja minun tuttavilleni olen minä pimeydessä.","Sinä teet, että minun ystäväni ja lähimmäiseni erkanevat kauvas minusta, ja minun tuttavilleni olen minä pimeydessä."],[89,1,"Etanin sen Esrahilaisen opetus. (H89:2) Minä veisaan Herran armoja ijankaikkisesti, ja ilmoitan sinun totuuttas suullani suvusta sukuun,","Etanin sen Esrahilaisen opetus. (H89:2) Minä veisaan Herran armoja ijankaikkisesti, ja ilmoitan sinun totuuttas suullani suvusta sukuun,"],[89,2,"Ja sanon: ijankaikkinen armo käy ylös: sinä pidät uskollisesti totuutes taivaissa.","Ja sanon: ijankaikkinen armo käy ylös: sinä pidät uskollisesti totuutes taivaissa."],[89,3,"Minä olen liiton tehnyt valittuini kanssa: minä olen vannonut Davidille palvelialleni:","Minä olen liiton tehnyt valittuini kanssa: minä olen vannonut Davidille palvelialleni:"],[89,4,"Hamaan ijankaikkisuuteen vahvistan minä sinun siemenes, ja rakennan sinun istuimes suvusta sukuun, Sela!","Hamaan ijankaikkisuuteen vahvistan minä sinun siemenes, ja rakennan sinun istuimes suvusta sukuun, Sela!"],[89,5,"Ja taivaat pitää ylistämän, Herra, sinun ihmeitäs, niin myös totuuttas pyhäin seurakunnassa.","Ja taivaat pitää ylistämän, Herra, sinun ihmeitäs, niin myös totuuttas pyhäin seurakunnassa."],[89,6,"Sillä kuka taidetaan pilvissä verrattaa Herraan? ja kuka on Herran kaltainen jumalain lasten seassa?","Sillä kuka taidetaan pilvissä verrattaa Herraan? ja kuka on Herran kaltainen jumalain lasten seassa?"],[89,7,"Jumala on sangen väkevä pyhäinsä kokouksissa, ja ihmeellinen kaikkein seassa, jotka ovat hänen ympärillänsä.","Jumala on sangen väkevä pyhäinsä kokouksissa, ja ihmeellinen kaikkein seassa, jotka ovat hänen ympärillänsä."],[89,8,"Herra Jumala Zebaot, kuka on niinkuin sinä, väkevä Jumala? ja sinun totuutes on sinun ympärilläs.","Herra Jumala Zebaot, kuka on niinkuin sinä, väkevä Jumala? ja sinun totuutes on sinun ympärilläs."],[89,9,"Sinä vallitset pauhaavaisen meren: sinä hillitset paisuvaiset aallot.","Sinä vallitset pauhaavaisen meren: sinä hillitset paisuvaiset aallot."],[89,10,"Sinä lyöt Rahabin kuoliaaksi: sinä hajoitat vihollises urhoollisella käsivarrellas.","Sinä lyöt Rahabin kuoliaaksi: sinä hajoitat vihollises urhoollisella käsivarrellas."],[89,11,"Taivaat ovat sinun, maa myös on sinun: sinä olet perustanut maan piirin, ja mitä siinä on.","Taivaat ovat sinun, maa myös on sinun: sinä olet perustanut maan piirin, ja mitä siinä on."],[89,12,"Pohjan ja etelän olet sinä luonut: Tabor ja Hermon kiittävät sinun nimeäs.","Pohjan ja etelän olet sinä luonut: Tabor ja Hermon kiittävät sinun nimeäs."],[89,13,"Sinulla on voimallinen käsivarsi: väkevä on sinun kätes, ja korkia on oikia kätes.","Sinulla on voimallinen käsivarsi: väkevä on sinun kätes, ja korkia on oikia kätes."],[89,14,"Vanhurskaus ja tuomio on istuimes vahvistus: armo ja totuus ovat sinun kasvois edessä.","Vanhurskaus ja tuomio on istuimes vahvistus: armo ja totuus ovat sinun kasvois edessä."],[89,15,"Autuas on se kansa, joka ihastua taitaa: Herra, heidän pitää vaeltaman sinun kasvois valkeudessa.","Autuas on se kansa, joka ihastua taitaa: Herra, heidän pitää vaeltaman sinun kasvois valkeudessa."],[89,16,"Heidän pitää iloitseman joka päivä sinun nimestäs, ja sinun vanhurskaudessas kunnialliset oleman.","Heidän pitää iloitseman joka päivä sinun nimestäs, ja sinun vanhurskaudessas kunnialliset oleman."],[89,17,"Sillä sinä olet heidän väkevyytensä kerskaus, ja sinun armos kautta nostat sinä ylös meidän sarvemme.","Sillä sinä olet heidän väkevyytensä kerskaus, ja sinun armos kautta nostat sinä ylös meidän sarvemme."],[89,18,"Sillä Herra on meidän kilpemme, ja pyhä Israelissa on meidän kuninkaamme.","Sillä Herra on meidän kilpemme, ja pyhä Israelissa on meidän kuninkaamme."],[89,19,"Silloin sinä puhuit näyissä pyhilles ja sanoit: minä olen sankarin herättänyt auttamaan: minä olen korottanut valitun kansasta.","Silloin sinä puhuit näyissä pyhilles ja sanoit: minä olen sankarin herättänyt auttamaan: minä olen korottanut valitun kansasta."],[89,20,"Minä olen löytänyt palveliani Davidin: minä olen hänen voidellut pyhällä öljylläni.","Minä olen löytänyt palveliani Davidin: minä olen hänen voidellut pyhällä öljylläni."],[89,21,"Minun käteni tukee häntä, ja minun käsivarteni vahvistaa häntä.","Minun käteni tukee häntä, ja minun käsivarteni vahvistaa häntä."],[89,22,"Ei pidä viholliset häntä voittaman, ja väärät ei pidä häntä sulloman.","Ei pidä viholliset häntä voittaman, ja väärät ei pidä häntä sulloman."],[89,23,"Vaan minä lyön hänen vihollisensa hänen edestänsä; ja niitä, jotka häntä vihaavat, tahdon minä vaivata.","Vaan minä lyön hänen vihollisensa hänen edestänsä; ja niitä, jotka häntä vihaavat, tahdon minä vaivata."],[89,24,"Mutta minun totuuteni ja armoni pitää hänen tykönänsä oleman, ja hänen sarvensa pitää minun nimeeni nostettaman ylös.","Mutta minun totuuteni ja armoni pitää hänen tykönänsä oleman, ja hänen sarvensa pitää minun nimeeni nostettaman ylös."],[89,25,"Minä asetan hänen kätensä mereen, ja hänen oikian kätensä virtoihin.","Minä asetan hänen kätensä mereen, ja hänen oikian kätensä virtoihin."],[89,26,"Näin hänen pitää minun kutsuman: sinä olet minun Isäni, Jumalani ja turvani, joka minua auttaa.","Näin hänen pitää minun kutsuman: sinä olet minun Isäni, Jumalani ja turvani, joka minua auttaa."],[89,27,"Ja minä asetan hänen esikoiseksi, kaikkein korkeimmaksi kuningasten seassa maan päällä.","Ja minä asetan hänen esikoiseksi, kaikkein korkeimmaksi kuningasten seassa maan päällä."],[89,28,"Minä pidän hänelle armoni tähteellä ijankaikkisesti, ja minun liittoni pitää hänelle vahva oleman.","Minä pidän hänelle armoni tähteellä ijankaikkisesti, ja minun liittoni pitää hänelle vahva oleman."],[89,29,"Minä annan hänelle ijankaikkisen siemenen, ja vahvistan hänen istuimensa niinkauvan kuin taivaat pysyvät.","Minä annan hänelle ijankaikkisen siemenen, ja vahvistan hänen istuimensa niinkauvan kuin taivaat pysyvät."],[89,30,"Mutta jos hänen lapsensa minun lakini hylkäävät, ja ei vaella minun oikeudessani,","Mutta jos hänen lapsensa minun lakini hylkäävät, ja ei vaella minun oikeudessani,"],[89,31,"Jos he minun säätyni turmelevat, ja ei minun käskyjäni pidä;","Jos he minun säätyni turmelevat, ja ei minun käskyjäni pidä;"],[89,32,"Niin minä heidän syntinsä vitsalla rankaisen, ja heidän pahat tekonsa haavoilla.","Niin minä heidän syntinsä vitsalla rankaisen, ja heidän pahat tekonsa haavoilla."],[89,33,"Mutta armoani en minä hänestä käännä pois, enkä salli totuuteni vilpistellä.","Mutta armoani en minä hänestä käännä pois, enkä salli totuuteni vilpistellä."],[89,34,"En minä riko liittoani, ja mitä minun suustani käynyt on, en minä muuta.","En minä riko liittoani, ja mitä minun suustani käynyt on, en minä muuta."],[89,35,"Minä olen vihdoin vannonut pyhyyteni kautta: en minä Davidille valehtele.","Minä olen vihdoin vannonut pyhyyteni kautta: en minä Davidille valehtele."],[89,36,"Hänen siemenensä on oleva ijankaikkisesti, ja hänen istuimensa minun edessäni niinkuin aurinko.","Hänen siemenensä on oleva ijankaikkisesti, ja hänen istuimensa minun edessäni niinkuin aurinko."],[89,37,"Ja niinkuin kuu, vahvistetaan se ijankaikkisesti, ja on vahvana niinkuin todistus pilvissä, Sela!","Ja niinkuin kuu, vahvistetaan se ijankaikkisesti, ja on vahvana niinkuin todistus pilvissä, Sela!"],[89,38,"Vaan nyt sinä syökset ja heität pois, ja vihastut voidellulles.","Vaan nyt sinä syökset ja heität pois, ja vihastut voidellulles."],[89,39,"Sinä särjet palvelias liiton, ja tallaat hänen kruununsa maahan.","Sinä särjet palvelias liiton, ja tallaat hänen kruununsa maahan."],[89,40,"Sinä rikot hänen muurinsa, ja annat hänen linnansa särjettää.","Sinä rikot hänen muurinsa, ja annat hänen linnansa särjettää."],[89,41,"Häntä raatelevat kaikki ohitsekäyväiset: hän on tullut läsnäolevaisillensa nauruksi.","Häntä raatelevat kaikki ohitsekäyväiset: hän on tullut läsnäolevaisillensa nauruksi."],[89,42,"Sinä korotat hänen vihollistensa oikian käden, ja ilahutat kaikki hänen vainollisensa.","Sinä korotat hänen vihollistensa oikian käden, ja ilahutat kaikki hänen vainollisensa."],[89,43,"Hänen miekkansa voiman olet sinä myös ottanut pois, ja et salli hänen voittaa sodassa,","Hänen miekkansa voiman olet sinä myös ottanut pois, ja et salli hänen voittaa sodassa,"],[89,44,"Sinä hävitit hänen puhtautensa, ja annoit hänen istuimensa kaatua maahan.","Sinä hävitit hänen puhtautensa, ja annoit hänen istuimensa kaatua maahan."],[89,45,"Sinä lyhennät hänen nuoruutensa ajat, ja peität hänen häpiällä, Sela!","Sinä lyhennät hänen nuoruutensa ajat, ja peität hänen häpiällä, Sela!"],[89,46,"Herra, kuinka kauvan sinä sinus niin salaat? ja annat hirmuisuutes palaa niinkuin tulen?","Herra, kuinka kauvan sinä sinus niin salaat? ja annat hirmuisuutes palaa niinkuin tulen?"],[89,47,"Muista, kuinka lyhyt minun elämäni on: miksis tahdoit kaikki ihmiset hukkaan luoda?","Muista, kuinka lyhyt minun elämäni on: miksis tahdoit kaikki ihmiset hukkaan luoda?"],[89,48,"Kuka elää, ja ei näe kuolemaa? kuka sielunsa tuonelan käsistä pelastaa? Sela!","Kuka elää, ja ei näe kuolemaa? kuka sielunsa tuonelan käsistä pelastaa? Sela!"],[89,49,"Herra, kussa ovat sinun entiset armos, jotkas Davidille vannonut olet totuudessas?","Herra, kussa ovat sinun entiset armos, jotkas Davidille vannonut olet totuudessas?"],[89,50,"Muista, Herra, palveliais pilkkaa, jonka minä kannan helmassani, kaikista niin monista kansoista,","Muista, Herra, palveliais pilkkaa, jonka minä kannan helmassani, kaikista niin monista kansoista,"],[89,51,"Joilla, Herra, vihollises pilkkaavat, joilla he pilkkaavat voideltus askelia.","Joilla, Herra, vihollises pilkkaavat, joilla he pilkkaavat voideltus askelia."],[89,52,"Kiitetty olkoon Herra ijankaikkisesti, amen! ja amen!","Kiitetty olkoon Herra ijankaikkisesti, amen! ja amen!"],[90,1,"Moseksen Jumalan miehen rukous. Herra, sinä olet meidän turvamme, suvusta sukuun.","Moseksen Jumalan miehen rukous. Herra, sinä olet meidän turvamme, suvusta sukuun."],[90,2,"Ennenkuin vuoret olivat, eli maa ja maailma luotiin, olet sinä Jumala ijankaikkisesta ijankaikkiseen,","Ennenkuin vuoret olivat, eli maa ja maailma luotiin, olet sinä Jumala ijankaikkisesta ijankaikkiseen,"],[90,3,"Sinä, joka annat ihmiset kuolla, ja sanot: tulkaat jälleen, te ihmisten lapset.","Sinä, joka annat ihmiset kuolla, ja sanot: tulkaat jälleen, te ihmisten lapset."],[90,4,"Sillä tuhat ajastaikaa ovat sinun edessäs niinkuin eilinen päivä, joka meni ohitse, ja niinkuin vartio yöllä.","Sillä tuhat ajastaikaa ovat sinun edessäs niinkuin eilinen päivä, joka meni ohitse, ja niinkuin vartio yöllä."],[90,5,"Sinä vuodatat heitä niinkuin kosken, ja he ovat niinkuin uni, niinkuin ruoho aamulla, joka kohta lakastuu,","Sinä vuodatat heitä niinkuin kosken, ja he ovat niinkuin uni, niinkuin ruoho aamulla, joka kohta lakastuu,"],[90,6,"Joka aamulla kukoistaa ja nopiasti kuivuu, ja ehtoona leikataan ja kuivettuu.","Joka aamulla kukoistaa ja nopiasti kuivuu, ja ehtoona leikataan ja kuivettuu."],[90,7,"Sen tekee sinun vihas, että me niin hukumme, ja sinun hirmuisuutes, että me niin äkisti täältä temmataan.","Sen tekee sinun vihas, että me niin hukumme, ja sinun hirmuisuutes, että me niin äkisti täältä temmataan."],[90,8,"Sillä meidän pahat tekomme sinä asetat etees, meidän tuntemattomat syntimme valkeuteen sinun kasvois eteen.","Sillä meidän pahat tekomme sinä asetat etees, meidän tuntemattomat syntimme valkeuteen sinun kasvois eteen."],[90,9,"Sentähden kuluvat kaikki meidän päivämme sinun vihastas: meidän vuotemme loppuvat pikemmin kuin juttu.","Sentähden kuluvat kaikki meidän päivämme sinun vihastas: meidän vuotemme loppuvat pikemmin kuin juttu."],[90,10,"Meidän elinaikamme on seitsemänkymmentä vuotta, taikka enintään kahdeksankymmentä vuotta: ja kuin se paras on ollut, niin on se tuska ja työ ollut: sillä se leikataan pois. niinkuin me lentäisimme pois.","Meidän elinaikamme on seitsemänkymmentä vuotta, taikka enintään kahdeksankymmentä vuotta: ja kuin se paras on ollut, niin on se tuska ja työ ollut: sillä se leikataan pois. niinkuin me lentäisimme pois."],[90,11,"Mutta kuka uskoo sinun niin raskaasti vihastuvan? ja kuka pelkää senkaltaista hirmuisuuttas?","Mutta kuka uskoo sinun niin raskaasti vihastuvan? ja kuka pelkää senkaltaista hirmuisuuttas?"],[90,12,"Opeta meitä ajattelemaan, että meidän pitää kuoleman, että me ymmärtäväisiksi tulisimme.","Opeta meitä ajattelemaan, että meidän pitää kuoleman, että me ymmärtäväisiksi tulisimme."],[90,13,"Herra! käännä siis itses taas meidän puoleemme, ja ole palvelioilles armollinen.","Herra! käännä siis itses taas meidän puoleemme, ja ole palvelioilles armollinen."],[90,14,"Täytä meitä pian armoillas, niin me riemuitsemme ja iloitsemme kaikkena meidän elinaikanamme.","Täytä meitä pian armoillas, niin me riemuitsemme ja iloitsemme kaikkena meidän elinaikanamme."],[90,15,"Ilahuta nyt meitä jälleen, ettäs meitä niin kauvan vaivannut olet, että me niin kauvan onnettomuutta kärsineet olemme.","Ilahuta nyt meitä jälleen, ettäs meitä niin kauvan vaivannut olet, että me niin kauvan onnettomuutta kärsineet olemme."],[90,16,"Osoita palvelialles sinun tekos, ja kunnias heidän lapsillensa.","Osoita palvelialles sinun tekos, ja kunnias heidän lapsillensa."],[90,17,"Ja, Herra meidän Jumalamme olkoon meille leppyinen, ja vahvistakoon meidän kättemme teot meissä: jaa, meidän kättemme teot hän vahvistakoon!","Ja, Herra meidän Jumalamme olkoon meille leppyinen, ja vahvistakoon meidän kättemme teot meissä: jaa, meidän kättemme teot hän vahvistakoon!"],[91,1,"Joka Korkeimman varjeluksessa istuu ja Kaikkivaltiaan varjossa oleskelee,","Joka Korkeimman varjeluksessa istuu ja Kaikkivaltiaan varjossa oleskelee,"],[91,2,"Hän sanoo Herralle: minun toivoni ja linnani, minun Jumalani, johon minä uskallan.","Hän sanoo Herralle: minun toivoni ja linnani, minun Jumalani, johon minä uskallan."],[91,3,"Sillä hän pelastaa sinun väijyjän paulasta, ja vahingollisesta ruttotaudista.","Sillä hän pelastaa sinun väijyjän paulasta, ja vahingollisesta ruttotaudista."],[91,4,"Hän sulillansa sinua varjoo, ja sinun turvas on hänen siipeinsä alla: hänen totuutensa on keihäs ja kilpi;","Hän sulillansa sinua varjoo, ja sinun turvas on hänen siipeinsä alla: hänen totuutensa on keihäs ja kilpi;"],[91,5,"Ettes pelkäisi yön kauhistusta, ja nuolia, jotka päivällä lentävät,","Ettes pelkäisi yön kauhistusta, ja nuolia, jotka päivällä lentävät,"],[91,6,"Sitä ruttoa, joka pimeässä liikkuu, ja sairautta, joka puolipäivänä turmelee.","Sitä ruttoa, joka pimeässä liikkuu, ja sairautta, joka puolipäivänä turmelee."],[91,7,"Vaikka tuhannen lankeisi sivullas, ja kymmenentuhatta sinun oikiallas, niin ei se sinuun satu.","Vaikka tuhannen lankeisi sivullas, ja kymmenentuhatta sinun oikiallas, niin ei se sinuun satu."],[91,8,"Ja tosin sinun pitää silmilläs näkemän ja katsoman, kuinka jumalattomille kostetaan.","Ja tosin sinun pitää silmilläs näkemän ja katsoman, kuinka jumalattomille kostetaan."],[91,9,"Sillä Herra on sinun toivos, ja Ylimmäinen on sinun turvas.","Sillä Herra on sinun toivos, ja Ylimmäinen on sinun turvas."],[91,10,"Ei sinua pidä mikään paha kohtaaman, ja ei yhtään vaivaa pidä sinun majaas lähestymän.","Ei sinua pidä mikään paha kohtaaman, ja ei yhtään vaivaa pidä sinun majaas lähestymän."],[91,11,"Sillä hän on antanut käskyn enkeleillensä sinusta, että he kätkevät sinua kaikissa teissäs,","Sillä hän on antanut käskyn enkeleillensä sinusta, että he kätkevät sinua kaikissa teissäs,"],[91,12,"Että he kantavat sinua käsissä, ettes jalkaas kiveen loukkaisi.","Että he kantavat sinua käsissä, ettes jalkaas kiveen loukkaisi."],[91,13,"Sinä käyt jalopeuran ja kyykäärmeen päällä, ja tallaat nuoren jalopeuran ja lohikäärmeen.","Sinä käyt jalopeuran ja kyykäärmeen päällä, ja tallaat nuoren jalopeuran ja lohikäärmeen."],[91,14,"Että hän minua halasi, niin minä hänen päästän: hän tuntee minun nimeni, sentähden minä varjelen häntä.","Että hän minua halasi, niin minä hänen päästän: hän tuntee minun nimeni, sentähden minä varjelen häntä."],[91,15,"Hän avuksihuutaa minua, sentähden minä kuulen häntä; hänen tykönänsä olen minä tuskassa; siitä minä hänen tempaan pois ja saatan hänen kunniaan.","Hän avuksihuutaa minua, sentähden minä kuulen häntä; hänen tykönänsä olen minä tuskassa; siitä minä hänen tempaan pois ja saatan hänen kunniaan."],[91,16,"Minä ravitsen hänen pitkällä ijällä, ja osoitan hänelle autuuteni.","Minä ravitsen hänen pitkällä ijällä, ja osoitan hänelle autuuteni."],[92,1,"Psalmi sabbatina veisattava. (H92:2) Hyvä on Herraa kiittää, ja veisata kiitosta sinun nimelles, sinä kaikkein Ylimmäinen.","Psalmi sabbatina veisattava. (H92:2) Hyvä on Herraa kiittää, ja veisata kiitosta sinun nimelles, sinä kaikkein Ylimmäinen."],[92,2,"Aamulla julistaa armoas, ja ehtoolla totuuttas,","Aamulla julistaa armoas, ja ehtoolla totuuttas,"],[92,3,"Kymmenkielisellä ja psaltarilla, soittain kanteleilla.","Kymmenkielisellä ja psaltarilla, soittain kanteleilla."],[92,4,"Sillä sinä ilahutit minua, Herra, sinun teoissas: ja minä iloiten kerskaan kättes töitä.","Sillä sinä ilahutit minua, Herra, sinun teoissas: ja minä iloiten kerskaan kättes töitä."],[92,5,"Herra, kuinka sinun tekos ovat niin suuret? Sinun ajatukses ovat ylen syvät.","Herra, kuinka sinun tekos ovat niin suuret? Sinun ajatukses ovat ylen syvät."],[92,6,"Hullu ei usko sitä, ja tomppeli ei ymmärrä niitä.","Hullu ei usko sitä, ja tomppeli ei ymmärrä niitä."],[92,7,"Jumalattomat viheriöitsevät niinkuin ruoho, ja pahointekiät kaikki kukoistavat, siihenasti kuin he hukkuvat ijankaikkisesti.","Jumalattomat viheriöitsevät niinkuin ruoho, ja pahointekiät kaikki kukoistavat, siihenasti kuin he hukkuvat ijankaikkisesti."],[92,8,"Mutta sinä, Herra, olet korkein, ja pysyt ijankaikkisesti.","Mutta sinä, Herra, olet korkein, ja pysyt ijankaikkisesti."],[92,9,"Sillä katso, sinun vihollises, Herra, katso, sinun vihollises pitää katooman, ja kaikki pahantekiät pitää hajoitettaman.","Sillä katso, sinun vihollises, Herra, katso, sinun vihollises pitää katooman, ja kaikki pahantekiät pitää hajoitettaman."],[92,10,"Mutta minun sarveni tulee korotetuksi niinkuin yksisarvisen, ja minä voidellaan tuoreella öljyllä,","Mutta minun sarveni tulee korotetuksi niinkuin yksisarvisen, ja minä voidellaan tuoreella öljyllä,"],[92,11,"Ja minun silmäni näkevät viholliseni, ja minun korvani kuulevat pahoja, jotka heitänsä asettavat minua vastaan.","Ja minun silmäni näkevät viholliseni, ja minun korvani kuulevat pahoja, jotka heitänsä asettavat minua vastaan."],[92,12,"Vanhurskaan pitää viheriöitsemän niinkuin palmupuu, ja kasvaman niinkuin sedripuu Libanonissa.","Vanhurskaan pitää viheriöitsemän niinkuin palmupuu, ja kasvaman niinkuin sedripuu Libanonissa."],[92,13,"Jotka ovat istutetut Herran huoneessa, pitää viheriöitsemän meidän Jumalamme kartanoissa.","Jotka ovat istutetut Herran huoneessa, pitää viheriöitsemän meidän Jumalamme kartanoissa."],[92,14,"Heidän pitää vesoman vielä vanhuudessansa, hedelmälliset ja vihannat oleman,","Heidän pitää vesoman vielä vanhuudessansa, hedelmälliset ja vihannat oleman,"],[92,15,"Ja julistaman, että Herra on niin hurskas, minun turvani, ja ei ole hänessä vääryyttä.","Ja julistaman, että Herra on niin hurskas, minun turvani, ja ei ole hänessä vääryyttä."],[93,1,"Herra on kuningas: hän on pukenut yllensä suuren kunnian: Herra on pukenut ja vyöttänyt itsensä väkevyydellä, ja on vahvistanut maan piirin, ettei sen pidä liikkuman.","Herra on kuningas: hän on pukenut yllensä suuren kunnian: Herra on pukenut ja vyöttänyt itsensä väkevyydellä, ja on vahvistanut maan piirin, ettei sen pidä liikkuman."],[93,2,"Siitä ajasta pysyy sinun istuimes vahvana: sinä olet ijankaikkinen.","Siitä ajasta pysyy sinun istuimes vahvana: sinä olet ijankaikkinen."],[93,3,"Herra, vesikosket paisuvat, vesikosket paisuttavat pauhinansa, vesikosket paisuttavat aaltonsa.","Herra, vesikosket paisuvat, vesikosket paisuttavat pauhinansa, vesikosket paisuttavat aaltonsa."],[93,4,"Aallot meressä ovat suuret ja pauhaavat hirmuisesti; mutta Herra on vielä väkevämpi korkeudessa.","Aallot meressä ovat suuret ja pauhaavat hirmuisesti; mutta Herra on vielä väkevämpi korkeudessa."],[93,5,"Sinun todistukses ovat aivan lujat: pyhyys on sinun huonees kaunistus, Herra, ijankaikkisesti.","Sinun todistukses ovat aivan lujat: pyhyys on sinun huonees kaunistus, Herra, ijankaikkisesti."],[94,1,"Herra Jumala, jonka kostot ovat, Jumala, jonka kostot ovat, selkiästi itses näytä.","Herra Jumala, jonka kostot ovat, Jumala, jonka kostot ovat, selkiästi itses näytä."],[94,2,"Korota sinuas, maailman tuomari: maksa ylpeille, mitä he ansainneet ovat.","Korota sinuas, maailman tuomari: maksa ylpeille, mitä he ansainneet ovat."],[94,3,"Herra, kuinka kauvan pitää jumalattomain, kuinka kauvan pitää jumalattomain riemuitseman?","Herra, kuinka kauvan pitää jumalattomain, kuinka kauvan pitää jumalattomain riemuitseman?"],[94,4,"Tiuskuman ja puhuman niin ylpiästi, ja kaikki pahantekiät niin kerskaaman?","Tiuskuman ja puhuman niin ylpiästi, ja kaikki pahantekiät niin kerskaaman?"],[94,5,"Herra, he polkevat alas sinun kansas, ja sinun perimistäs he vaivaavat.","Herra, he polkevat alas sinun kansas, ja sinun perimistäs he vaivaavat."],[94,6,"Lesket ja muukalaiset he tappavat, ja orvot he kuolettavat,","Lesket ja muukalaiset he tappavat, ja orvot he kuolettavat,"],[94,7,"Ja sanovat: ei Herra sitä näe, ja Jakobin Jumala ei sitä tottele.","Ja sanovat: ei Herra sitä näe, ja Jakobin Jumala ei sitä tottele."],[94,8,"Ymmärtäkäät siis, te hullut kansan seassa! ja, te tyhmät, koska te taitaviksi tulette?","Ymmärtäkäät siis, te hullut kansan seassa! ja, te tyhmät, koska te taitaviksi tulette?"],[94,9,"Joka korvan on istuttanut, eikö hän kuule? eli joka silmän loi, eikö hän näe?","Joka korvan on istuttanut, eikö hän kuule? eli joka silmän loi, eikö hän näe?"],[94,10,"Joka pakanoita kurittaa, eikö hän rankaise, joka ihmisille opettaa tiedon?","Joka pakanoita kurittaa, eikö hän rankaise, joka ihmisille opettaa tiedon?"],[94,11,"Mutta Herra tietää ihmisten ajatukset, että ne turhat ovat.","Mutta Herra tietää ihmisten ajatukset, että ne turhat ovat."],[94,12,"Autuas on se, jota sinä, Herra, kuritat, ja opetat sinun laistas,","Autuas on se, jota sinä, Herra, kuritat, ja opetat sinun laistas,"],[94,13,"Että hänellä kärsivällisyys olis, koska vastoin käy, siihenasti kuin jumalattomalle hauta valmistetaan.","Että hänellä kärsivällisyys olis, koska vastoin käy, siihenasti kuin jumalattomalle hauta valmistetaan."],[94,14,"Sillä ei Herra heitä kansaansa pois, eli hylkää perimistänsä.","Sillä ei Herra heitä kansaansa pois, eli hylkää perimistänsä."],[94,15,"Sillä oikeuden pitää sittekin oikeuden oleman, ja kaikki hurskaat sydämet sitä seuraavat.","Sillä oikeuden pitää sittekin oikeuden oleman, ja kaikki hurskaat sydämet sitä seuraavat."],[94,16,"Kuka seisoo minun kanssani pahoja vastaan? kuka astuu minun tyköni pahointekiöitä vastaan?","Kuka seisoo minun kanssani pahoja vastaan? kuka astuu minun tyköni pahointekiöitä vastaan?"],[94,17,"Ellei Herra minua auttaisi, niin minun sieluni makais lähes hiljaisuudessa.","Ellei Herra minua auttaisi, niin minun sieluni makais lähes hiljaisuudessa."],[94,18,"Minä sanoin: minun jalkani on horjunut, vaan sinun armos, Herra, minun tukesi.","Minä sanoin: minun jalkani on horjunut, vaan sinun armos, Herra, minun tukesi."],[94,19,"Minulla oli paljo surua sydämessäni; mutta sinun lohdutukses ilahutti minun sieluni.","Minulla oli paljo surua sydämessäni; mutta sinun lohdutukses ilahutti minun sieluni."],[94,20,"Etpäs mielisty koskaan tosin vahingolliseen istuimeen, joka lain häijysti opettaa.","Etpäs mielisty koskaan tosin vahingolliseen istuimeen, joka lain häijysti opettaa."],[94,21,"He kokoovat joukkonsa vanhurskaan sielua vastaan, ja tuomitsevat viattoman veren kadotukseen,","He kokoovat joukkonsa vanhurskaan sielua vastaan, ja tuomitsevat viattoman veren kadotukseen,"],[94,22,"Mutta Herra on minun varjelukseni: minun Jumalani on minun uskallukseni turva,","Mutta Herra on minun varjelukseni: minun Jumalani on minun uskallukseni turva,"],[94,23,"Ja hän kostaa heidän vääryytensä, ja hukuttaa heitä heidän pahuutensa tähden: Herra, meidän Jumalamme, hukuttaa heitä.","Ja hän kostaa heidän vääryytensä, ja hukuttaa heitä heidän pahuutensa tähden: Herra, meidän Jumalamme, hukuttaa heitä."],[95,1,"Tulkaat, veisatkaamme kiitosta Herralle, ja iloitkaamme meidän autuutemme turvalle!","Tulkaat, veisatkaamme kiitosta Herralle, ja iloitkaamme meidän autuutemme turvalle!"],[95,2,"Tulkaamme hänen kasvoinsa eteen kiitoksella, ja riemuitkaamme hänelle lauluilla!","Tulkaamme hänen kasvoinsa eteen kiitoksella, ja riemuitkaamme hänelle lauluilla!"],[95,3,"Sillä Herra on suuri Jumala, ja suuri kuningas kaikkein jumalain ylitse.","Sillä Herra on suuri Jumala, ja suuri kuningas kaikkein jumalain ylitse."],[95,4,"Sillä hänen kädessänsä on kaikki, mitä maa kantaa, ja vuorten kukkulat ovat myös hänen.","Sillä hänen kädessänsä on kaikki, mitä maa kantaa, ja vuorten kukkulat ovat myös hänen."],[95,5,"Sillä hänen on meri, ja hän on sen tehnyt, ja hänen kätensä ovat kuivan valmistaneet.","Sillä hänen on meri, ja hän on sen tehnyt, ja hänen kätensä ovat kuivan valmistaneet."],[95,6,"Tulkaat, kumartakaamme ja polvillemme langetkaamme, ja maahan laskeukaamme Herran meidän Luojamme eteen!","Tulkaat, kumartakaamme ja polvillemme langetkaamme, ja maahan laskeukaamme Herran meidän Luojamme eteen!"],[95,7,"Sillä hän on meidän Jumalamme ja me hänen elatuskansansa, ja hänen kättensä lauma. Tänäpänä, jos kuulette hänen äänensä,","Sillä hän on meidän Jumalamme ja me hänen elatuskansansa, ja hänen kättensä lauma. Tänäpänä, jos kuulette hänen äänensä,"],[95,8,"Niin älkäät paaduttako sydämiänne, niinkuin Meribassa tapahtui, niinkuin kiusauksen päivänä korvessa,","Niin älkäät paaduttako sydämiänne, niinkuin Meribassa tapahtui, niinkuin kiusauksen päivänä korvessa,"],[95,9,"Kussa isänne minua kiusasivat, koettelivat minua, ja näkivät myös minun tekoni;","Kussa isänne minua kiusasivat, koettelivat minua, ja näkivät myös minun tekoni;"],[95,10,"Että minä neljäkymmentä ajastaikaa suutuin tähän kansaan, ja sanoin: se on senkaltainen kansa, jonka sydämet aina eksyä tahtovat, ja jotka minun tietäni ei tahtoneet oppia;","Että minä neljäkymmentä ajastaikaa suutuin tähän kansaan, ja sanoin: se on senkaltainen kansa, jonka sydämet aina eksyä tahtovat, ja jotka minun tietäni ei tahtoneet oppia;"],[95,11,"Joille minä vihoissani vannoin: ettei heidän pidä minun lepooni tuleman.","Joille minä vihoissani vannoin: ettei heidän pidä minun lepooni tuleman."],[96,1,"Veisatkaat Herralle uusi veisu: veisatkaat Herralle, kaikki maa!","Veisatkaat Herralle uusi veisu: veisatkaat Herralle, kaikki maa!"],[96,2,"Veisatkaat Herralle, ja kiittäkäät hänen nimeänsä: julistakaat päivä päivältä hänen autuuttansa.","Veisatkaat Herralle, ja kiittäkäät hänen nimeänsä: julistakaat päivä päivältä hänen autuuttansa."],[96,3,"Luetelkaat pakanain seassa hänen kunniaansa, kaikkein kansain seassa hänen ihmeitänsä!","Luetelkaat pakanain seassa hänen kunniaansa, kaikkein kansain seassa hänen ihmeitänsä!"],[96,4,"Sillä Herra on suuri ja sangen kiitettävä, ihmeellinen kaikkein jumalain seassa.","Sillä Herra on suuri ja sangen kiitettävä, ihmeellinen kaikkein jumalain seassa."],[96,5,"Sillä kaikki kansain jumalat ovat epäjumalat; mutta Herra on taivaat tehnyt.","Sillä kaikki kansain jumalat ovat epäjumalat; mutta Herra on taivaat tehnyt."],[96,6,"Kunnia ja kaunistus ovat hänen edessänsä, väkevyys ja kauneus hänen pyhässänsä.","Kunnia ja kaunistus ovat hänen edessänsä, väkevyys ja kauneus hänen pyhässänsä."],[96,7,"Kansain sukukunnat, tuokaat Herralle, tuokaat Herralle kunnia ja voima!","Kansain sukukunnat, tuokaat Herralle, tuokaat Herralle kunnia ja voima!"],[96,8,"Tuokaat Herralle hänen nimensä kunnia: tuokaat lahjoja ja tulkaat hänen esihuoneisiinsa!","Tuokaat Herralle hänen nimensä kunnia: tuokaat lahjoja ja tulkaat hänen esihuoneisiinsa!"],[96,9,"Kumartakaat Herraa pyhässä kaunistuksessa: peljätkään häntä kaikki maailma!","Kumartakaat Herraa pyhässä kaunistuksessa: peljätkään häntä kaikki maailma!"],[96,10,"Sanokaat pakanain seassa: Herra on kuningas, joka maan piirin on vahvistanut, ettei se liiku, ja tuomitsee kansan oikeudella.","Sanokaat pakanain seassa: Herra on kuningas, joka maan piirin on vahvistanut, ettei se liiku, ja tuomitsee kansan oikeudella."],[96,11,"Taivaat riemuitkaan, ja maa iloitkaan: meri pauhatkaan ja mitä siinä on.","Taivaat riemuitkaan, ja maa iloitkaan: meri pauhatkaan ja mitä siinä on."],[96,12,"Kedot olkaan iloiset, ja kaikki mitkä hänessä ovat, ja kaikki puut ihastukaan metsissä,","Kedot olkaan iloiset, ja kaikki mitkä hänessä ovat, ja kaikki puut ihastukaan metsissä,"],[96,13,"Herran edessä; sillä hän tulee, hän tulee tuomitsemaan maata. Hän tuomitsee maan piirin vanhurskaudessa ja kansat totuudessansa.","Herran edessä; sillä hän tulee, hän tulee tuomitsemaan maata. Hän tuomitsee maan piirin vanhurskaudessa ja kansat totuudessansa."],[97,1,"Herra on kuningas, siitä maa iloitkaan: olkoon saaret riemuiset, niin monta kuin heitä on.","Herra on kuningas, siitä maa iloitkaan: olkoon saaret riemuiset, niin monta kuin heitä on."],[97,2,"Pilvet ja pimeys ovat hänen ympärillänsä: vanhurskaus ja tuomio ovat hänen istuimensa vahvistus.","Pilvet ja pimeys ovat hänen ympärillänsä: vanhurskaus ja tuomio ovat hänen istuimensa vahvistus."],[97,3,"Tuli käy hänen edellänsä ja polttaa ympärillä hänen vihollisensa.","Tuli käy hänen edellänsä ja polttaa ympärillä hänen vihollisensa."],[97,4,"Hänen leimauksensa välkkyvät maan piirin päällä: maa näkee sen ja vapisee.","Hänen leimauksensa välkkyvät maan piirin päällä: maa näkee sen ja vapisee."],[97,5,"Vuoret sulavat niinkuin vedenvaha Herran edessä, koko maailman Herran edessä.","Vuoret sulavat niinkuin vedenvaha Herran edessä, koko maailman Herran edessä."],[97,6,"Taivaat julistavat hänen vanhurskauttansa, ja kaikki kansat näkevät hänen kunniansa.","Taivaat julistavat hänen vanhurskauttansa, ja kaikki kansat näkevät hänen kunniansa."],[97,7,"Hävetkäät kaikki, jotka kuvia palvelevat, ja kerskaavat epäjumalista: kumartakaat häntä kaikki enkelit.","Hävetkäät kaikki, jotka kuvia palvelevat, ja kerskaavat epäjumalista: kumartakaat häntä kaikki enkelit."],[97,8,"Zion kuulee sen ja iloitsee, ja Juudan tyttäret ovat riemuissansa, Herra, sinun hallituksestas.","Zion kuulee sen ja iloitsee, ja Juudan tyttäret ovat riemuissansa, Herra, sinun hallituksestas."],[97,9,"Sillä sinä, Herra, olet Korkein kaikissa maakunnissa: sinä olet sangen suuresti korotettu kaikkein jumalain ylitse.","Sillä sinä, Herra, olet Korkein kaikissa maakunnissa: sinä olet sangen suuresti korotettu kaikkein jumalain ylitse."],[97,10,"Te kuin Herraa rakastatte, vihatkaat pahaa! hän kätkee pyhäinsä sielut: jumalattomain käsistä hän heitä pelastaa.","Te kuin Herraa rakastatte, vihatkaat pahaa! hän kätkee pyhäinsä sielut: jumalattomain käsistä hän heitä pelastaa."],[97,11,"Vanhurskaalle koittaa valkeus, ja ilo hurskaille sydämille,","Vanhurskaalle koittaa valkeus, ja ilo hurskaille sydämille,"],[97,12,"Vanhurskaat iloitkaat Herrassa, kiittäkäät hänen pyhyytensä muistoksi.","Vanhurskaat iloitkaat Herrassa, kiittäkäät hänen pyhyytensä muistoksi."],[98,1,"Psalmi. Veisatkaat Herralle uusi veisu; sillä hän tekee ihmeitä. Hän saa voiton oikialla kädellänsä ja pyhällä käsivarrellansa.","Psalmi. Veisatkaat Herralle uusi veisu; sillä hän tekee ihmeitä. Hän saa voiton oikialla kädellänsä ja pyhällä käsivarrellansa."],[98,2,"Herra antaa tiettäväksi tehdä autuutensa: kansain edessä hän ilmoittaa vanhurskautensa.","Herra antaa tiettäväksi tehdä autuutensa: kansain edessä hän ilmoittaa vanhurskautensa."],[98,3,"Hän muistaa armonsa ja totuutensa Israelin huoneelle: kaikki maailman ääret näkevät meidän Jumalamme autuuden.","Hän muistaa armonsa ja totuutensa Israelin huoneelle: kaikki maailman ääret näkevät meidän Jumalamme autuuden."],[98,4,"Riemuitkaat Herralle kaikki maa: veisatkaat, ylistäkäät ja kiittäkäät.","Riemuitkaat Herralle kaikki maa: veisatkaat, ylistäkäät ja kiittäkäät."],[98,5,"Kiittäkäät Herraa kanteleella, kanteleella ja psalmilla,","Kiittäkäät Herraa kanteleella, kanteleella ja psalmilla,"],[98,6,"Vaskitorvilla ja basunilla: riemuitkaat Herran, kuninkaan, edessä.","Vaskitorvilla ja basunilla: riemuitkaat Herran, kuninkaan, edessä."],[98,7,"Meri pauhatkaan ja kaikki, mitä hänessä on, maan piiri ja jotka asuvat sen päällä.","Meri pauhatkaan ja kaikki, mitä hänessä on, maan piiri ja jotka asuvat sen päällä."],[98,8,"Kosket pauhatkaan ilosta, ja kaikki vuoret olkaan iloiset,","Kosket pauhatkaan ilosta, ja kaikki vuoret olkaan iloiset,"],[98,9,"Herran edessä; sillä hän tulee maata tuomitsemaan: hän tuomitsee maan piirin vanhurskaudella ja kansat oikeudella.","Herran edessä; sillä hän tulee maata tuomitsemaan: hän tuomitsee maan piirin vanhurskaudella ja kansat oikeudella."],[99,1,"Herra on Kuningas, kansat kiukuitsevat: hän istuu Kerubimin päällä, sentähden liikkuu maailma.","Herra on Kuningas, kansat kiukuitsevat: hän istuu Kerubimin päällä, sentähden liikkuu maailma."],[99,2,"Suuri on Herra Zionissa, ja korkein kaikkein kansain ylitse.","Suuri on Herra Zionissa, ja korkein kaikkein kansain ylitse."],[99,3,"Kiittäkään he sinun suurta ja ihmeellistä nimeäs, joka pyhä on.","Kiittäkään he sinun suurta ja ihmeellistä nimeäs, joka pyhä on."],[99,4,"Ja Kuninkaan voima rakastaa oikeutta: sinä toimitat oikeuden, sinä saatat tuomion ja vanhurskauden Jakobissa.","Ja Kuninkaan voima rakastaa oikeutta: sinä toimitat oikeuden, sinä saatat tuomion ja vanhurskauden Jakobissa."],[99,5,"Korottakaat Herraa meidän Jumalaamme, ja kumartakaat hänen astinlautansa juuressa, sillä hän on pyhä.","Korottakaat Herraa meidän Jumalaamme, ja kumartakaat hänen astinlautansa juuressa, sillä hän on pyhä."],[99,6,"Moses ja Aaron hänen pappeinsa seassa, ja Samuel niiden seassa, jotka hänen nimeänsä avuksensa huutavat: he avuksensa huutavat Herraa, ja hän kuulee heidän rukouksensa.","Moses ja Aaron hänen pappeinsa seassa, ja Samuel niiden seassa, jotka hänen nimeänsä avuksensa huutavat: he avuksensa huutavat Herraa, ja hän kuulee heidän rukouksensa."],[99,7,"Hän puhui heille pilven patsaasta: he pitivät hänen todistuksensa ja säätynsä, jonka hän heille antoi.","Hän puhui heille pilven patsaasta: he pitivät hänen todistuksensa ja säätynsä, jonka hän heille antoi."],[99,8,"Herra, sinä olet Jumalamme, sinä kuulit heidän rukouksensa: sinä, Jumala, annoit heille anteeksi, ja laitit heidän työnsä.","Herra, sinä olet Jumalamme, sinä kuulit heidän rukouksensa: sinä, Jumala, annoit heille anteeksi, ja laitit heidän työnsä."],[99,9,"Korottakaat Herraa meidän Jumalaamme, ja kumartakaat hänen pyhällä vuorellansa; sillä Herra meidän Jumalamme on pyhä.","Korottakaat Herraa meidän Jumalaamme, ja kumartakaat hänen pyhällä vuorellansa; sillä Herra meidän Jumalamme on pyhä."],[100,1,"Kiitos-Psalmi. Riemuitkaat Herralle, kaikki maa!","Kiitos-Psalmi. Riemuitkaat Herralle, kaikki maa!"],[100,2,"Palvelkaat Herraa ilolla: tulkaat hänen kasvoinsa eteen riemulla!","Palvelkaat Herraa ilolla: tulkaat hänen kasvoinsa eteen riemulla!"],[100,3,"Tietäkäät, että Herra on Jumala: hänpä meidän teki, ja emme itse meitämme, kansaksensa ja laitumensa lampaiksi.","Tietäkäät, että Herra on Jumala: hänpä meidän teki, ja emme itse meitämme, kansaksensa ja laitumensa lampaiksi."],[100,4,"Menkäät hänen porttiinsa kiitoksella, hänen esihuoneisiinsa veisulla: kiittäkäät häntä ja ylistäkäät hänen nimeänsä!","Menkäät hänen porttiinsa kiitoksella, hänen esihuoneisiinsa veisulla: kiittäkäät häntä ja ylistäkäät hänen nimeänsä!"],[100,5,"Sillä Herra on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti, ja hänen totuutensa sukukunnasta sukukuntaan.","Sillä Herra on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti, ja hänen totuutensa sukukunnasta sukukuntaan."],[101,1,"Davidin Psalmi. Minä veisaan armosta ja oikeudesta: sinulle, Herra, minä veisaan.","Davidin Psalmi. Minä veisaan armosta ja oikeudesta: sinulle, Herra, minä veisaan."],[101,2,"Minä tahdon vaarin ottaa oikiasta tiestä, koskas minun tyköni tulet: minä tahdon vaeltaa sydämeni vakuudessa minun huoneessani.","Minä tahdon vaarin ottaa oikiasta tiestä, koskas minun tyköni tulet: minä tahdon vaeltaa sydämeni vakuudessa minun huoneessani."],[101,3,"En minä ota pahaa asiaa eteeni: minä vihaan väärintekiöitä, ja en salli heitä olla tykönäni.","En minä ota pahaa asiaa eteeni: minä vihaan väärintekiöitä, ja en salli heitä olla tykönäni."],[101,4,"Nurja sydän olkoon minusta pois: en minä kärsi pahaa.","Nurja sydän olkoon minusta pois: en minä kärsi pahaa."],[101,5,"Joka lähimmäistänsä salaa panettelee, sen minä hukutan: en minä kärsi ylpeitä ja röyhkeitä.","Joka lähimmäistänsä salaa panettelee, sen minä hukutan: en minä kärsi ylpeitä ja röyhkeitä."],[101,6,"Minun silmäni katsovat uskollisia maan päällä, että he asuisivat minun tykönäni: joka vaeltaa oikialla tiellä, se pitää oleman minun palveliani.","Minun silmäni katsovat uskollisia maan päällä, että he asuisivat minun tykönäni: joka vaeltaa oikialla tiellä, se pitää oleman minun palveliani."],[101,7,"Petollisia ihmisiä en minä pidä huoneessani: ei valehteliat menesty minun tykönäni.","Petollisia ihmisiä en minä pidä huoneessani: ei valehteliat menesty minun tykönäni."],[101,8,"Varhain minä hukutan kaikki jumalattomat maasta, hävittääkseni kaikkia pahantekiöitä Herran kaupungista.","Varhain minä hukutan kaikki jumalattomat maasta, hävittääkseni kaikkia pahantekiöitä Herran kaupungista."],[102,1,"Raadollisen rukous, kuin hän murheissansa on, ja valituksensa Herran eteen vuodattaa. (H102:2) Herra, kuule minun rukoukseni, ja anna minun huutoni tykös tulla!","Raadollisen rukous, kuin hän murheissansa on, ja valituksensa Herran eteen vuodattaa. (H102:2) Herra, kuule minun rukoukseni, ja anna minun huutoni tykös tulla!"],[102,2,"Älä kasvojas minulta peitä hädässä: kallista korvas minun puoleeni; koska minä sinua rukoilen, niin kuule pian minun rukoukseni.","Älä kasvojas minulta peitä hädässä: kallista korvas minun puoleeni; koska minä sinua rukoilen, niin kuule pian minun rukoukseni."],[102,3,"Sillä minun päiväni ovat kuluneet niinkuin savu, ja minun luuni ovat poltetut niinkuin kekäle.","Sillä minun päiväni ovat kuluneet niinkuin savu, ja minun luuni ovat poltetut niinkuin kekäle."],[102,4,"Minun sydämeni on lyöty ja kuivettunut niinkuin heinä, niin että minä myös unohdan leipäni syödä.","Minun sydämeni on lyöty ja kuivettunut niinkuin heinä, niin että minä myös unohdan leipäni syödä."],[102,5,"Minun luuni tarttuvat lihaani huokauksestani.","Minun luuni tarttuvat lihaani huokauksestani."],[102,6,"Minä olen niinkuin ruovonpäristäjä korvessa: minä olen niinkuin hyypiä hävitetyissä kaupungeissa.","Minä olen niinkuin ruovonpäristäjä korvessa: minä olen niinkuin hyypiä hävitetyissä kaupungeissa."],[102,7,"Minä valvon, ja olen niinkuin yksinäinen lintu katon päällä.","Minä valvon, ja olen niinkuin yksinäinen lintu katon päällä."],[102,8,"Joka päivä häpäisevät viholliseni minua, ja jotka minua syljeskelevät, vannovat minun kauttani.","Joka päivä häpäisevät viholliseni minua, ja jotka minua syljeskelevät, vannovat minun kauttani."],[102,9,"Sillä minä syön tuhkaa niinkuin leipää, ja sekoitan juomani itkulla,","Sillä minä syön tuhkaa niinkuin leipää, ja sekoitan juomani itkulla,"],[102,10,"Sinun uhkaukses ja vihas tähden, ettäs minun nostanut olet ja paiskannut maahan.","Sinun uhkaukses ja vihas tähden, ettäs minun nostanut olet ja paiskannut maahan."],[102,11,"Minun päiväni ovat kuluneet niinkuin varjo, ja minä kuivetun niinkuin ruoho.","Minun päiväni ovat kuluneet niinkuin varjo, ja minä kuivetun niinkuin ruoho."],[102,12,"Mutta sinä, Herra, pysyt ijankaikkisesti, ja sinun muistos sukukunnasta sukukuntaan.","Mutta sinä, Herra, pysyt ijankaikkisesti, ja sinun muistos sukukunnasta sukukuntaan."],[102,13,"Nouse siis ja armahda Zionia; sillä aika on häntä armahtaa, ja aika on tullut.","Nouse siis ja armahda Zionia; sillä aika on häntä armahtaa, ja aika on tullut."],[102,14,"Sillä sinun palvelias halajavat sitä rakentaa, ja näkisivät mielellänsä, että hänen kivensä ja kalkkinsa valmiit olisivat,","Sillä sinun palvelias halajavat sitä rakentaa, ja näkisivät mielellänsä, että hänen kivensä ja kalkkinsa valmiit olisivat,"],[102,15,"Että pakanat Herran nimeä pelkäisivät, ja kaikki kuninkaat maan päällä sinun kunniaas.","Että pakanat Herran nimeä pelkäisivät, ja kaikki kuninkaat maan päällä sinun kunniaas."],[102,16,"Kuin Herra rakentaa Zionin, niin hän nähdään kunniassansa.","Kuin Herra rakentaa Zionin, niin hän nähdään kunniassansa."],[102,17,"Hän kääntää itsensä hyljättyjen rukouksen puoleen, ja ei katso heidän rukoustansa ylön.","Hän kääntää itsensä hyljättyjen rukouksen puoleen, ja ei katso heidän rukoustansa ylön."],[102,18,"Se pitää kirjoitettaman tulevaisille sukukunnille, ja se kansa, joka luodaan, pitää kiittämän Herraa.","Se pitää kirjoitettaman tulevaisille sukukunnille, ja se kansa, joka luodaan, pitää kiittämän Herraa."],[102,19,"Sillä hän katselee pyhästä korkeudestansa: Herra näkee taivaasta maan päälle,","Sillä hän katselee pyhästä korkeudestansa: Herra näkee taivaasta maan päälle,"],[102,20,"Että hän kuulee vankein huokaukset, ja kirvoittaa kuoleman lapset;","Että hän kuulee vankein huokaukset, ja kirvoittaa kuoleman lapset;"],[102,21,"Että he saarnaavat Herran nimeä Zionissa, ja hänen kiitostansa Jerusalemissa,","Että he saarnaavat Herran nimeä Zionissa, ja hänen kiitostansa Jerusalemissa,"],[102,22,"Koska kansat ynnä kokoontuvat, ja valtakunnat, Herraa palvelemaan.","Koska kansat ynnä kokoontuvat, ja valtakunnat, Herraa palvelemaan."],[102,23,"Hän nöyryyttää tiellä minun voimani: hän lyhentää minun päiväni.","Hän nöyryyttää tiellä minun voimani: hän lyhentää minun päiväni."],[102,24,"Minä sanoin: minun Jumalani, älä minua ota pois keski-ijässäni: sinun ajastaikas pysyvät suvusta sukuun.","Minä sanoin: minun Jumalani, älä minua ota pois keski-ijässäni: sinun ajastaikas pysyvät suvusta sukuun."],[102,25,"Sinä olet muinen maan perustanut, ja taivaat ovat sinun käsialas.","Sinä olet muinen maan perustanut, ja taivaat ovat sinun käsialas."],[102,26,"Ne katoovat, mutta sinä pysyt: ne kaikki vanhenevat niinkuin vaate: ne muuttuvat niinkuin vaate, koska sinä heitä muuttelet.","Ne katoovat, mutta sinä pysyt: ne kaikki vanhenevat niinkuin vaate: ne muuttuvat niinkuin vaate, koska sinä heitä muuttelet."],[102,27,"Mutta sinä pysyt niinkuin sinä olet, ja sinun vuotes ei lopu.","Mutta sinä pysyt niinkuin sinä olet, ja sinun vuotes ei lopu."],[102,28,"Sinun palveliais lapset pysyvät ja heidän sikiänsä sinun edessäs menestyvät.","Sinun palveliais lapset pysyvät ja heidän sikiänsä sinun edessäs menestyvät."],[103,1,"Davidin Psalmi. Kiitä Herraa, sieluni, ja kaikki mitä minussa on, hänen pyhää nimeänsä!","Davidin Psalmi. Kiitä Herraa, sieluni, ja kaikki mitä minussa on, hänen pyhää nimeänsä!"],[103,2,"Kiitä Herraa, sieluni, ja älä unohda, mitä hyvää hän minulle tehnyt on,","Kiitä Herraa, sieluni, ja älä unohda, mitä hyvää hän minulle tehnyt on,"],[103,3,"Joka sinulle kaikki syntis antaa anteeksi, ja parantaa kaikki rikokses;","Joka sinulle kaikki syntis antaa anteeksi, ja parantaa kaikki rikokses;"],[103,4,"Joka henkes päästää turmeluksesta, joka sinun kruunaa armolla ja laupiudella;","Joka henkes päästää turmeluksesta, joka sinun kruunaa armolla ja laupiudella;"],[103,5,"Joka suus täyttää hyvyydellä, että sinun nuoruutes uudistetaan niinkuin kotkan.","Joka suus täyttää hyvyydellä, että sinun nuoruutes uudistetaan niinkuin kotkan."],[103,6,"Herra saattaa vanhurskauden ja tuomion kaikille, jotka vääryyttä kärsivät.","Herra saattaa vanhurskauden ja tuomion kaikille, jotka vääryyttä kärsivät."],[103,7,"Hän on tiensä Mosekselle tiettäväksi tehnyt, Israelin lapsille tekonsa.","Hän on tiensä Mosekselle tiettäväksi tehnyt, Israelin lapsille tekonsa."],[103,8,"Laupias ja armollinen on Herra, kärsiväinen ja aivan hyvä.","Laupias ja armollinen on Herra, kärsiväinen ja aivan hyvä."],[103,9,"Ei hän aina riitele, eikä vihastu ijankaikkisesti.","Ei hän aina riitele, eikä vihastu ijankaikkisesti."],[103,10,"Ei hän synteimme perästä tee meille, eikä kosta meille pahain tekoimme jälkeen.","Ei hän synteimme perästä tee meille, eikä kosta meille pahain tekoimme jälkeen."],[103,11,"Sillä niin korkia kuin taivas on maasta, antaa hän armonsa lisääntyä niille, jotka häntä pelkäävät.","Sillä niin korkia kuin taivas on maasta, antaa hän armonsa lisääntyä niille, jotka häntä pelkäävät."],[103,12,"Niin kaukana kuin itä on lännestä, siirsi hän meistä pahat tekomme.","Niin kaukana kuin itä on lännestä, siirsi hän meistä pahat tekomme."],[103,13,"Niinkuin isä armahtaa lapsia, niin Herrakin armahtaa pelkääväisiänsä;","Niinkuin isä armahtaa lapsia, niin Herrakin armahtaa pelkääväisiänsä;"],[103,14,"Sillä hän tietää, minkäkaltainen teko me olemme: hän muistaa meidät tomuksi.","Sillä hän tietää, minkäkaltainen teko me olemme: hän muistaa meidät tomuksi."],[103,15,"Ihminen on eläissänsä niinkuin ruoho: hän kukoistaa niinkuin kukkanen kedolla:","Ihminen on eläissänsä niinkuin ruoho: hän kukoistaa niinkuin kukkanen kedolla:"],[103,16,"Kuin tuuli käy sen päällitse, niin ei hän enään kestä, eikä hänen siansa tunne häntä ensinkään.","Kuin tuuli käy sen päällitse, niin ei hän enään kestä, eikä hänen siansa tunne häntä ensinkään."],[103,17,"Mutta Herran armo pysyy ijankaikkisesta ijankaikkiseen, hänen pelkääväistensä päälle, ja hänen vanhurskautensa lasten lapsiin,","Mutta Herran armo pysyy ijankaikkisesta ijankaikkiseen, hänen pelkääväistensä päälle, ja hänen vanhurskautensa lasten lapsiin,"],[103,18,"Niille, jotka hänen liittonsa pitävät, ja muistavat hänen käskyjänsä, tehdäksensä niitä.","Niille, jotka hänen liittonsa pitävät, ja muistavat hänen käskyjänsä, tehdäksensä niitä."],[103,19,"Herra on valmistanut istuimensa taivaassa, ja hänen valtakuntansa hallitsee kaikkia.","Herra on valmistanut istuimensa taivaassa, ja hänen valtakuntansa hallitsee kaikkia."],[103,20,"Kiittäkäät Herraa, te hänen enkelinsä, te väkevät sankarit, jotka hänen käskynsä toimitatte, että hänen sanansa ääni kuultaisiin.","Kiittäkäät Herraa, te hänen enkelinsä, te väkevät sankarit, jotka hänen käskynsä toimitatte, että hänen sanansa ääni kuultaisiin."],[103,21,"Kiittäkäät Herraa, kaikki hänen sotaväkensä, te hänen palveliansa, jotka teette hänen tahtonsa.","Kiittäkäät Herraa, kaikki hänen sotaväkensä, te hänen palveliansa, jotka teette hänen tahtonsa."],[103,22,"Kiittäkäät Herraa, kaikki hänen työnsä, kaikissa hänen valtansa paikoissa: kiitä, sieluni, Herraa.","Kiittäkäät Herraa, kaikki hänen työnsä, kaikissa hänen valtansa paikoissa: kiitä, sieluni, Herraa."],[104,1,"Kiitä Herraa, sieluni! Herra, minun Jumalani, sinä olet sangen suuresti kunnioitettu, suurella kunnialla ja kaunistuksella olet sinä puetettu.","Kiitä Herraa, sieluni! Herra, minun Jumalani, sinä olet sangen suuresti kunnioitettu, suurella kunnialla ja kaunistuksella olet sinä puetettu."],[104,2,"Sinä puetat itses valkeudella niinkuin vaatteella: sinä levität taivaat niinkuin peitteen.","Sinä puetat itses valkeudella niinkuin vaatteella: sinä levität taivaat niinkuin peitteen."],[104,3,"Sinä peität sen päällyksen vedellä: sinä menet pilvissä niinkuin ratasten päällä, ja käyt tuulen siipein päällä.","Sinä peität sen päällyksen vedellä: sinä menet pilvissä niinkuin ratasten päällä, ja käyt tuulen siipein päällä."],[104,4,"Sinä teet enkelis hengeksi ja palvelias liekitseväiseksi tuleksi.","Sinä teet enkelis hengeksi ja palvelias liekitseväiseksi tuleksi."],[104,5,"Sinä joka maan perustit perustuksensa päälle, ettei sen pidä liikkuman ijankaikkisesti.","Sinä joka maan perustit perustuksensa päälle, ettei sen pidä liikkuman ijankaikkisesti."],[104,6,"Syvyydellä sinä sen peität niinkuin vaatteella, ja vedet seisovat vuorilla.","Syvyydellä sinä sen peität niinkuin vaatteella, ja vedet seisovat vuorilla."],[104,7,"Mutta sinun nuhtelemisestas he pakenevat: sinun jylinästäs he menevät pois.","Mutta sinun nuhtelemisestas he pakenevat: sinun jylinästäs he menevät pois."],[104,8,"Vuoret astuvat ylös, ja laaksot astuvat alas siallensa, johon heidät perustanut olet.","Vuoret astuvat ylös, ja laaksot astuvat alas siallensa, johon heidät perustanut olet."],[104,9,"Määrän sinä panit, jota ei he käy ylitse, eikä palaja maata peittämään.","Määrän sinä panit, jota ei he käy ylitse, eikä palaja maata peittämään."],[104,10,"Sinä annat lähteet laaksoissa kuohua, niin että ne vuorten välitse vuotavat;","Sinä annat lähteet laaksoissa kuohua, niin että ne vuorten välitse vuotavat;"],[104,11,"Että kaikki eläimet metsässä joisivat, ja että pedot janonsa sammuttaisivat.","Että kaikki eläimet metsässä joisivat, ja että pedot janonsa sammuttaisivat."],[104,12,"Heidän tykönänsä istuvat taivaan linnut, ja visertävät oksilla.","Heidän tykönänsä istuvat taivaan linnut, ja visertävät oksilla."],[104,13,"Sinä liotat vuoret ylhäältä: sinä täytät maan hedelmällä, jonka sinä saatat.","Sinä liotat vuoret ylhäältä: sinä täytät maan hedelmällä, jonka sinä saatat."],[104,14,"Sinä kasvatat ruohon karjalle, ja jyvät ihmisten tarpeeksi, tuottaakses leipää maasta.","Sinä kasvatat ruohon karjalle, ja jyvät ihmisten tarpeeksi, tuottaakses leipää maasta."],[104,15,"Ja että viina ihmisen sydämen ilahuttaa, ja hänen kasvonsa kaunistuu öljystä: ja leipä vahvistaa ihmisen sydämen.","Ja että viina ihmisen sydämen ilahuttaa, ja hänen kasvonsa kaunistuu öljystä: ja leipä vahvistaa ihmisen sydämen."],[104,16,"Että Herran puut nesteestä täynnä olisivat: Libanonin sedripuut, jotka hän on istuttanut;","Että Herran puut nesteestä täynnä olisivat: Libanonin sedripuut, jotka hän on istuttanut;"],[104,17,"Siellä linnut pesiä tekevät, ja haikarat hongissa asuvat.","Siellä linnut pesiä tekevät, ja haikarat hongissa asuvat."],[104,18,"Korkiat vuoret ovat metsävuohten turva, ja kivirauniot kaninein.","Korkiat vuoret ovat metsävuohten turva, ja kivirauniot kaninein."],[104,19,"Sinä teet kuun aikoja jakamaan, ja aurinko tietää laskemisensa.","Sinä teet kuun aikoja jakamaan, ja aurinko tietää laskemisensa."],[104,20,"Sinä teet pimeyden ja yö tulee: silloin kaikki metsän eläimet tulevat ulos.","Sinä teet pimeyden ja yö tulee: silloin kaikki metsän eläimet tulevat ulos."],[104,21,"Nuoret jalopeurat saaliin perään kiljuvat, ja elatustansa Jumalalta etsivät.","Nuoret jalopeurat saaliin perään kiljuvat, ja elatustansa Jumalalta etsivät."],[104,22,"Mutta kuin aurinko koittaa, niin he kokoontuvat, ja luolissansa makaavat.","Mutta kuin aurinko koittaa, niin he kokoontuvat, ja luolissansa makaavat."],[104,23,"Niin menee myös ihminen työhönsä, ja askareillensa ehtoosen asti.","Niin menee myös ihminen työhönsä, ja askareillensa ehtoosen asti."],[104,24,"Herra, kuinka suuret ja monet ovat sinun käsialas? Sinä olet kaikki taitavasti säätänyt, ja maa on täynnä sinun tavaraas.","Herra, kuinka suuret ja monet ovat sinun käsialas? Sinä olet kaikki taitavasti säätänyt, ja maa on täynnä sinun tavaraas."],[104,25,"Tämä meri, joka niin suuri ja lavia on, siinä epälukuiset liikuvat, sekä pienet että suuret eläimet;","Tämä meri, joka niin suuri ja lavia on, siinä epälukuiset liikuvat, sekä pienet että suuret eläimet;"],[104,26,"Siellä haahdet kuljeskelevat: siinä valaskalat ovat, jotkas tehnyt olet, leikitsemään hänessä.","Siellä haahdet kuljeskelevat: siinä valaskalat ovat, jotkas tehnyt olet, leikitsemään hänessä."],[104,27,"Kaikki odottavat sinua, ettäs heille antaisit ruan ajallansa.","Kaikki odottavat sinua, ettäs heille antaisit ruan ajallansa."],[104,28,"Koskas heille annat, niin he kokoovat: koskas kätes avaat, niin he hyvyydellä ravitaan.","Koskas heille annat, niin he kokoovat: koskas kätes avaat, niin he hyvyydellä ravitaan."],[104,29,"Jos sinä kasvos peität, niin he hämmästyvät: koska sinä otat heidän henkensä pois, niin he hukkuvat, ja tomuksi tulevat jälleen.","Jos sinä kasvos peität, niin he hämmästyvät: koska sinä otat heidän henkensä pois, niin he hukkuvat, ja tomuksi tulevat jälleen."],[104,30,"Sinä lähetät ulos henkes, niin he luoduksi tulevat, ja sinä uudistat maan muodon.","Sinä lähetät ulos henkes, niin he luoduksi tulevat, ja sinä uudistat maan muodon."],[104,31,"Herran kunnia pysyy ijankaikkisesti: Herra iloitsee töissänsä.","Herran kunnia pysyy ijankaikkisesti: Herra iloitsee töissänsä."],[104,32,"Hän katsahtaa maan päälle, niin se vapisee: hän rupee vuoriin, niin ne suitsevat.","Hän katsahtaa maan päälle, niin se vapisee: hän rupee vuoriin, niin ne suitsevat."],[104,33,"Minä veisaan Herralle minun elinaikanani, ja kiitän minun Jumalaani niinkauvan kuin minä olen.","Minä veisaan Herralle minun elinaikanani, ja kiitän minun Jumalaani niinkauvan kuin minä olen."],[104,34,"Minun puheeni kelpaa hänelle, ja minä iloitsen Herrassa.","Minun puheeni kelpaa hänelle, ja minä iloitsen Herrassa."],[104,35,"Syntiset maalta lopetetaan, ja jumalattomat ei pidä silleen oleman: kiitä Herraa, sieluni, Halleluja!","Syntiset maalta lopetetaan, ja jumalattomat ei pidä silleen oleman: kiitä Herraa, sieluni, Halleluja!"],[105,1,"Kiittäkäät Herraa, ja saarnatkaat hänen nimeänsä, julistakaat hänen töitänsä kansain seassa!","Kiittäkäät Herraa, ja saarnatkaat hänen nimeänsä, julistakaat hänen töitänsä kansain seassa!"],[105,2,"Veisatkaat hänelle, soittakaat hänelle, puhukaat kaikista hänen ihmeistänsä.","Veisatkaat hänelle, soittakaat hänelle, puhukaat kaikista hänen ihmeistänsä."],[105,3,"Ylistäkäät hänen pyhää nimeänsä: niiden sydän iloitkaan, jotka etsivät Herraa!","Ylistäkäät hänen pyhää nimeänsä: niiden sydän iloitkaan, jotka etsivät Herraa!"],[105,4,"Kysykäät Herraa ja hänen voimaansa, etsikäät alati hänen kasvojansa!","Kysykäät Herraa ja hänen voimaansa, etsikäät alati hänen kasvojansa!"],[105,5,"Muistakaat hänen ihmeellisiä töitänsä, jotka hän tehnyt on, hänen ihmeitänsä ja hänen sanojansa.","Muistakaat hänen ihmeellisiä töitänsä, jotka hän tehnyt on, hänen ihmeitänsä ja hänen sanojansa."],[105,6,"Te Abrahamin hänen palveliansa siemen, te Jakobin hänen valittunsa lapset.","Te Abrahamin hänen palveliansa siemen, te Jakobin hänen valittunsa lapset."],[105,7,"Hänpä on Herra meidän Jumalamme: hän tuomitsee kaikessa maailmassa.","Hänpä on Herra meidän Jumalamme: hän tuomitsee kaikessa maailmassa."],[105,8,"Hän muistaa liittonsa ijankaikkisesti, sanansa, jonka hän on käskenyt tuhannelle sukukunnalle,","Hän muistaa liittonsa ijankaikkisesti, sanansa, jonka hän on käskenyt tuhannelle sukukunnalle,"],[105,9,"Jonka hän teki Abrahamin kanssa, ja valansa Isaakin kanssa.","Jonka hän teki Abrahamin kanssa, ja valansa Isaakin kanssa."],[105,10,"Ja pani sen Jakobille säädyksi ja Israelille ijankaikkiseksi liitoksi,","Ja pani sen Jakobille säädyksi ja Israelille ijankaikkiseksi liitoksi,"],[105,11,"Ja sanoi: sinulle minä annan Kanaanin maan, teidän perimisenne arvan.","Ja sanoi: sinulle minä annan Kanaanin maan, teidän perimisenne arvan."],[105,12,"Koska heitä vähä ja harvat olivat, ja he olivat muukalaiset siinä,","Koska heitä vähä ja harvat olivat, ja he olivat muukalaiset siinä,"],[105,13,"Ja vaelsivat kansasta kansaan ja valtakunnasta toiseen kansaan:","Ja vaelsivat kansasta kansaan ja valtakunnasta toiseen kansaan:"],[105,14,"Ei hän sallinut yhdenkään ihmisen heitä vahingoittaa, vaan rankaisi kuninkaat heidän tähtensä.","Ei hän sallinut yhdenkään ihmisen heitä vahingoittaa, vaan rankaisi kuninkaat heidän tähtensä."],[105,15,"Älkäät ruvetko minun voideltuihini, ja älkäät tehkö pahaa minun prophetailleni.","Älkäät ruvetko minun voideltuihini, ja älkäät tehkö pahaa minun prophetailleni."],[105,16,"Ja hän kutsui nälän maan päälle, ja vei kaiken leivän varan pois.","Ja hän kutsui nälän maan päälle, ja vei kaiken leivän varan pois."],[105,17,"Hän lähetti miehen heidän eteensä: Joseph myytiin orjaksi.","Hän lähetti miehen heidän eteensä: Joseph myytiin orjaksi."],[105,18,"He ahdistivat hänen jalkansa jalkapuuhun: hänen ruumiinsa täytyi raudoissa maata,","He ahdistivat hänen jalkansa jalkapuuhun: hänen ruumiinsa täytyi raudoissa maata,"],[105,19,"Siihenasti että hänen sanansa tuli, ja Herran puhe koetteli hänen.","Siihenasti että hänen sanansa tuli, ja Herran puhe koetteli hänen."],[105,20,"Niin lähetti kuningas ja päästi hänen: kansain päämies laski hänen vallallensa,","Niin lähetti kuningas ja päästi hänen: kansain päämies laski hänen vallallensa,"],[105,21,"Ja asetti hänen huoneensa herraksi, ja kaiken tavaransa haltiaksi,","Ja asetti hänen huoneensa herraksi, ja kaiken tavaransa haltiaksi,"],[105,22,"Opettamaan päämiehiänsä oman tahtonsa jälkeen, ja vanhimmille viisautta.","Opettamaan päämiehiänsä oman tahtonsa jälkeen, ja vanhimmille viisautta."],[105,23,"Ja Israel meni Egyptiin, ja Jakob tuli muukalaiseksi Hamin maalle.","Ja Israel meni Egyptiin, ja Jakob tuli muukalaiseksi Hamin maalle."],[105,24,"Ja hän antoi kansansa sangen suuresti kasvaa, ja teki heitä väkevämmäksi kuin heidän vihollisensa.","Ja hän antoi kansansa sangen suuresti kasvaa, ja teki heitä väkevämmäksi kuin heidän vihollisensa."],[105,25,"Hän käänsi heidän sydämensä vihaamaan hänen kansaansa, ja hänen palvelioitansa viekkaudella painamaan alas.","Hän käänsi heidän sydämensä vihaamaan hänen kansaansa, ja hänen palvelioitansa viekkaudella painamaan alas."],[105,26,"Hän lähetti palveliansa Moseksen, ja Aaronin, jonka hän valitsi.","Hän lähetti palveliansa Moseksen, ja Aaronin, jonka hän valitsi."],[105,27,"Ne tekivät hänen merkkinsä heidän seassansa, ja hänen ihmeensä Hamin maalla.","Ne tekivät hänen merkkinsä heidän seassansa, ja hänen ihmeensä Hamin maalla."],[105,28,"Hän antoi pimeyden tulla, ja sen pimeytti; ja ei olleet he hänen sanoillensa kuulemattomat.","Hän antoi pimeyden tulla, ja sen pimeytti; ja ei olleet he hänen sanoillensa kuulemattomat."],[105,29,"Hän muutti heidän vetensä vereksi ja kuoletti heidän kalansa.","Hän muutti heidän vetensä vereksi ja kuoletti heidän kalansa."],[105,30,"Heidän maansa kuohutti sammakoita, heidän kuningastensa kammioissa.","Heidän maansa kuohutti sammakoita, heidän kuningastensa kammioissa."],[105,31,"Hän sanoi, niin turilaat ja täit tulivat heidän maansa ääriin.","Hän sanoi, niin turilaat ja täit tulivat heidän maansa ääriin."],[105,32,"Hän antoi rakeet heille sateeksi, tulen liekit heidän maallensa,","Hän antoi rakeet heille sateeksi, tulen liekit heidän maallensa,"],[105,33,"Ja löi heidän viinapuunsa ja fikunapuunsa, ja särki puut heidän maansa äärissä.","Ja löi heidän viinapuunsa ja fikunapuunsa, ja särki puut heidän maansa äärissä."],[105,34,"Hän sanoi, niin tulivat epälukuiset paarmat ja vapsaiset,","Hän sanoi, niin tulivat epälukuiset paarmat ja vapsaiset,"],[105,35,"Ja ne söivät kaiken ruohon heidän maaltansa, ja ne söivät heidän maansa hedelmän.","Ja ne söivät kaiken ruohon heidän maaltansa, ja ne söivät heidän maansa hedelmän."],[105,36,"Ja hän löi kaikki esikoiset heidän maallansa, ensimäiset kaikesta heidän voimastansa,","Ja hän löi kaikki esikoiset heidän maallansa, ensimäiset kaikesta heidän voimastansa,"],[105,37,"Ja vei heitä hopialla ja kullalla ulos: ja ei ollut heidän sukukunnissansa yksikään sairas.","Ja vei heitä hopialla ja kullalla ulos: ja ei ollut heidän sukukunnissansa yksikään sairas."],[105,38,"Egypti iloitsi heidän lähtemisestänsä; sillä heidän pelkonsa oli tullut heidän päällensä.","Egypti iloitsi heidän lähtemisestänsä; sillä heidän pelkonsa oli tullut heidän päällensä."],[105,39,"Hän levitti pilven verhoksi ja tulen yötä valistamaan.","Hän levitti pilven verhoksi ja tulen yötä valistamaan."],[105,40,"He anoivat, niin antoi hän metsäkanat tulla, ja ravitsi heitä taivaan leivällä.","He anoivat, niin antoi hän metsäkanat tulla, ja ravitsi heitä taivaan leivällä."],[105,41,"Hän avasi kallion, niin vesi vuoti, ja virrat juoksivat kuivaa myöten.","Hän avasi kallion, niin vesi vuoti, ja virrat juoksivat kuivaa myöten."],[105,42,"Sillä hän muisti pyhän sanansa, jonka hän palveliallensa Abrahamille puhunut oli,","Sillä hän muisti pyhän sanansa, jonka hän palveliallensa Abrahamille puhunut oli,"],[105,43,"Ja vei kansansa ilolla ulos, ja valittunsa riemulla,","Ja vei kansansa ilolla ulos, ja valittunsa riemulla,"],[105,44,"Ja antoi heille pakanain maan, niin että he kansain hyvyydet omistivat heillensä.","Ja antoi heille pakanain maan, niin että he kansain hyvyydet omistivat heillensä."],[105,45,"Että he pitäisivät hänen säätynsä, ja hänen lakinsa kätkisivät, Halleluja!","Että he pitäisivät hänen säätynsä, ja hänen lakinsa kätkisivät, Halleluja!"],[106,1,"Halleluja. Kiittäkäät Herraa! sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti.","Halleluja. Kiittäkäät Herraa! sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti."],[106,2,"Kuka taitaa puhua ulos Herran suurta voimaa, ja ylistää kaikkia hänen kiitettäviä tekojansa?","Kuka taitaa puhua ulos Herran suurta voimaa, ja ylistää kaikkia hänen kiitettäviä tekojansa?"],[106,3,"Autuaat ovat, jotka käskyn pitävät ja aina vanhurskauden tekevät.","Autuaat ovat, jotka käskyn pitävät ja aina vanhurskauden tekevät."],[106,4,"Herra, muista minua armos perästä, jonkas kansalles luvannut olet: opi minua sinun autuudellas,","Herra, muista minua armos perästä, jonkas kansalles luvannut olet: opi minua sinun autuudellas,"],[106,5,"Että minä näkisin valittujes menestyksen, ja iloitsisin kansas ilossa, ja kerskaisin perimises kanssa.","Että minä näkisin valittujes menestyksen, ja iloitsisin kansas ilossa, ja kerskaisin perimises kanssa."],[106,6,"Me teimme syntiä meidän isäimme kanssa: me teimme väärin, ja olemme olleet jumalattomat.","Me teimme syntiä meidän isäimme kanssa: me teimme väärin, ja olemme olleet jumalattomat."],[106,7,"Ei meidän isämme tahtoneet ymmärtää Egyptissä sinun ihmeitäs, eikä muistaneet sinun suurta laupiuttas, ja olivat meren tykönä tottelemattomat, Punaisen meren tykönä.","Ei meidän isämme tahtoneet ymmärtää Egyptissä sinun ihmeitäs, eikä muistaneet sinun suurta laupiuttas, ja olivat meren tykönä tottelemattomat, Punaisen meren tykönä."],[106,8,"Kuitenkin autti hän heitä nimensä tähden, niin että hän voimansa osoitti.","Kuitenkin autti hän heitä nimensä tähden, niin että hän voimansa osoitti."],[106,9,"Ja hän uhkasi Punaista merta, niin se kuivui; ja vei heitä syvyyden lävitse, niinkuin korvessa,","Ja hän uhkasi Punaista merta, niin se kuivui; ja vei heitä syvyyden lävitse, niinkuin korvessa,"],[106,10,"Ja vapahti heitä niiden käsistä, joka heitä vihasivat, ja lunasti heitä vihollistensa käsistä.","Ja vapahti heitä niiden käsistä, joka heitä vihasivat, ja lunasti heitä vihollistensa käsistä."],[106,11,"Ja vedet peittivät heidän vainollisensa, niin ettei yksikään eläväksi jäänyt.","Ja vedet peittivät heidän vainollisensa, niin ettei yksikään eläväksi jäänyt."],[106,12,"Silloin he uskoivat hänen sanansa, ja veisasivat hänen kiitoksensa.","Silloin he uskoivat hänen sanansa, ja veisasivat hänen kiitoksensa."],[106,13,"Mutta he unohtivat pian hänen työnsä, ja ei ottaneet hänen neuvoansa.","Mutta he unohtivat pian hänen työnsä, ja ei ottaneet hänen neuvoansa."],[106,14,"He kiehuivat himosta korvessa, ja kiusasivat Jumalaa erämaassa.","He kiehuivat himosta korvessa, ja kiusasivat Jumalaa erämaassa."],[106,15,"Mutta hän antoi heille heidän anomisensa, ja lähetti heille laihuuden heidän himonsa tähden.","Mutta hän antoi heille heidän anomisensa, ja lähetti heille laihuuden heidän himonsa tähden."],[106,16,"Ja he asettuivat Mosesta vastaan leirissä, Aaronia Herran pyhää vastaan.","Ja he asettuivat Mosesta vastaan leirissä, Aaronia Herran pyhää vastaan."],[106,17,"Maa aukeni ja nieli Datanin, ja peitti Abiramin joukon,","Maa aukeni ja nieli Datanin, ja peitti Abiramin joukon,"],[106,18,"Ja tuli syttyi heidän joukossansa, ja liekki poltti jumalattomat.","Ja tuli syttyi heidän joukossansa, ja liekki poltti jumalattomat."],[106,19,"He tekivät vasikan Horebissa, ja kumarsivat valettua kuvaa.","He tekivät vasikan Horebissa, ja kumarsivat valettua kuvaa."],[106,20,"Ja he muuttelivat kunniansa härjän muotoon, joka heiniä syö.","Ja he muuttelivat kunniansa härjän muotoon, joka heiniä syö."],[106,21,"He unohtivat Jumalan, vapahtajansa, joka oli niin suuria töitä tehnyt Egyptissä,","He unohtivat Jumalan, vapahtajansa, joka oli niin suuria töitä tehnyt Egyptissä,"],[106,22,"Ihmeitä Hamin maalla, ja peljättäviä töitä Punaisen meren tykönä.","Ihmeitä Hamin maalla, ja peljättäviä töitä Punaisen meren tykönä."],[106,23,"Ja hän sanoi heitä hukuttavansa, ellei Moses hänen valittunsa olisi seisonut siinä välissä, ja palauttanut hänen vihaansa, ettei hän ratki heitä kadottanut.","Ja hän sanoi heitä hukuttavansa, ellei Moses hänen valittunsa olisi seisonut siinä välissä, ja palauttanut hänen vihaansa, ettei hän ratki heitä kadottanut."],[106,24,"Ja he katsoivat sen ihanan maan ylön, eikä uskoneet hänen sanaansa,","Ja he katsoivat sen ihanan maan ylön, eikä uskoneet hänen sanaansa,"],[106,25,"Ja napisivat majoissansa, eikä olleet kuuliaiset Herran äänelle.","Ja napisivat majoissansa, eikä olleet kuuliaiset Herran äänelle."],[106,26,"Ja hän nosti kätensä heitä vastaan, maahan lyödäksensä heitä korvessa,","Ja hän nosti kätensä heitä vastaan, maahan lyödäksensä heitä korvessa,"],[106,27,"Ja heittääksensä heidän siemenensä pakanain sekaan, ja hajoittaaksensa heitä maakuntiin.","Ja heittääksensä heidän siemenensä pakanain sekaan, ja hajoittaaksensa heitä maakuntiin."],[106,28,"Ja he ryhtyivät BaalPeoriin, ja söivät kuolleiden (epäjumalain) uhreista,","Ja he ryhtyivät BaalPeoriin, ja söivät kuolleiden (epäjumalain) uhreista,"],[106,29,"Ja vihoittivat hänen töillänsä; niin tuli myös rangaistus heidän sekaansa.","Ja vihoittivat hänen töillänsä; niin tuli myös rangaistus heidän sekaansa."],[106,30,"Niin Pinehas astui edes, ja lepytti asian, ja rangaistus lakkasi.","Niin Pinehas astui edes, ja lepytti asian, ja rangaistus lakkasi."],[106,31,"Ja se luettiin hänelle vanhurskaudeksi, suvusta sukuun ijankaikkisesti.","Ja se luettiin hänelle vanhurskaudeksi, suvusta sukuun ijankaikkisesti."],[106,32,"Ja vihoittivat hänen riitaveden tykönä ja tapahtui Mosekselle pahoin heidän tähtensä;","Ja vihoittivat hänen riitaveden tykönä ja tapahtui Mosekselle pahoin heidän tähtensä;"],[106,33,"Sillä he saattivat hänen sydämensä murheelliseksi, niin että hän sanoissansa eksyi.","Sillä he saattivat hänen sydämensä murheelliseksi, niin että hän sanoissansa eksyi."],[106,34,"Ei he hukuttaneet pakanoita, niinkuin Herra heille käskenyt oli,","Ei he hukuttaneet pakanoita, niinkuin Herra heille käskenyt oli,"],[106,35,"Vaan sekaantuivat pakanain sekaan, ja oppivat heidän töitänsä,","Vaan sekaantuivat pakanain sekaan, ja oppivat heidän töitänsä,"],[106,36,"Ja palvelivat heidän epäjumaliansa; ja ne tulivat heille paulaksi.","Ja palvelivat heidän epäjumaliansa; ja ne tulivat heille paulaksi."],[106,37,"Ja he uhrasivat poikansa ja tyttärensä perkeleille,","Ja he uhrasivat poikansa ja tyttärensä perkeleille,"],[106,38,"Ja vuodattivat viattoman veren, poikainsa ja tyttäriensä veren, jotka he uhrasivat Kanaanealaisten epäjumalille, niin että maa veren vioilla turmeltiin,","Ja vuodattivat viattoman veren, poikainsa ja tyttäriensä veren, jotka he uhrasivat Kanaanealaisten epäjumalille, niin että maa veren vioilla turmeltiin,"],[106,39,"Ja saastuttivat itsensä omissa töissänsä, ja tekivät huorin teoissansa.","Ja saastuttivat itsensä omissa töissänsä, ja tekivät huorin teoissansa."],[106,40,"Niin julmistui Herran viha kansansa päälle, ja hän kauhistui perimistänsä,","Niin julmistui Herran viha kansansa päälle, ja hän kauhistui perimistänsä,"],[106,41,"Ja hylkäsi ne pakanain käsiin, että ne vallitsivat heitä, jotka heitä vihasivat.","Ja hylkäsi ne pakanain käsiin, että ne vallitsivat heitä, jotka heitä vihasivat."],[106,42,"Ja heidän vihollisensa ahdistivat heitä, ja he painettiin heidän kätensä alle.","Ja heidän vihollisensa ahdistivat heitä, ja he painettiin heidän kätensä alle."],[106,43,"Hän monesti heitä pelasti; mutta he vihoittivat hänen neuvoillansa, ja he painettiin alas pahain tekoinsa tähden.","Hän monesti heitä pelasti; mutta he vihoittivat hänen neuvoillansa, ja he painettiin alas pahain tekoinsa tähden."],[106,44,"Ja hän näki heidän tuskansa, kuin hän heidän valituksensa kuuli,","Ja hän näki heidän tuskansa, kuin hän heidän valituksensa kuuli,"],[106,45,"Ja muisti liittonsa, jonka hän heidän kanssansa tehnyt oli, ja katui sitä suuresta laupiudestansa,","Ja muisti liittonsa, jonka hän heidän kanssansa tehnyt oli, ja katui sitä suuresta laupiudestansa,"],[106,46,"Ja antoi heidän löytää armon kaikkein edessä, jotka heitä vanginneet olivat.","Ja antoi heidän löytää armon kaikkein edessä, jotka heitä vanginneet olivat."],[106,47,"Auta meitä, Herra meidän Jumalamme, ja kokoa meitä pakanoista, että kiittäisimme sinun pyhää nimeäs, ja kehuisimme sinun kiitostas.","Auta meitä, Herra meidän Jumalamme, ja kokoa meitä pakanoista, että kiittäisimme sinun pyhää nimeäs, ja kehuisimme sinun kiitostas."],[106,48,"Kiitetty olkoon Herra Israelin Jumala, ijankaikkisuudesta niin ijankaikkisuuteen: ja sanokaan kaikki kansa: Amen, Halleluja!","Kiitetty olkoon Herra Israelin Jumala, ijankaikkisuudesta niin ijankaikkisuuteen: ja sanokaan kaikki kansa: Amen, Halleluja!"],[107,1,"Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti.","Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti."],[107,2,"Sanokaan Herran lunastetut, jotka hän on tuskasta vapahtanut,","Sanokaan Herran lunastetut, jotka hän on tuskasta vapahtanut,"],[107,3,"Ja jotka hän on maakunnista koonnut, idästä ja lännestä, pohjoisesta ja etelästä,","Ja jotka hän on maakunnista koonnut, idästä ja lännestä, pohjoisesta ja etelästä,"],[107,4,"Jotka eksyksissä vaelsivat korvessa umpitietä, ja ei he löytäneet kaupunkia asuaksensa,","Jotka eksyksissä vaelsivat korvessa umpitietä, ja ei he löytäneet kaupunkia asuaksensa,"],[107,5,"Isoovaiset ja janoovaiset; ja heidän sielunsa vaipui heissä.","Isoovaiset ja janoovaiset; ja heidän sielunsa vaipui heissä."],[107,6,"Ja he huusivat Herraa tuskissansa, ja hän pelasti heitä heidän hädistänsä,","Ja he huusivat Herraa tuskissansa, ja hän pelasti heitä heidän hädistänsä,"],[107,7,"Ja vei heitä oikiaa tietä, että he menivät asuinkaupunkiin.","Ja vei heitä oikiaa tietä, että he menivät asuinkaupunkiin."],[107,8,"Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee:","Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee:"],[107,9,"Että hän ravitsee himoitsevaisen sielun ja täyttää isoovaisen sielun hyvyydellä.","Että hän ravitsee himoitsevaisen sielun ja täyttää isoovaisen sielun hyvyydellä."],[107,10,"Jotka istuvat pimeässä ja kuoleman varjossa, vangitut ahdistuksessa ja raudoissa:","Jotka istuvat pimeässä ja kuoleman varjossa, vangitut ahdistuksessa ja raudoissa:"],[107,11,"Että he olivat Jumalan käskyä vastaan kovakorvaiset, ja olivat katsoneet ylön ylimmäisen lain;","Että he olivat Jumalan käskyä vastaan kovakorvaiset, ja olivat katsoneet ylön ylimmäisen lain;"],[107,12,"Sentähden täytyi heidän sydämensä onnettomuudella vaivattaa, niin että he lankesivat, ja ei kenkään heitä auttanut.","Sentähden täytyi heidän sydämensä onnettomuudella vaivattaa, niin että he lankesivat, ja ei kenkään heitä auttanut."],[107,13,"Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä,","Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä,"],[107,14,"Ja vei heitä pimeydestä ulos ja kuoleman varjosta, ja särki heidän siteensä.","Ja vei heitä pimeydestä ulos ja kuoleman varjosta, ja särki heidän siteensä."],[107,15,"Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee:","Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee:"],[107,16,"Että hän särkee vaskiportit, ja rikkoo rautaiset salvat.","Että hän särkee vaskiportit, ja rikkoo rautaiset salvat."],[107,17,"Hullut, jotka rangaistiin ylitsekäymisensä tähden, ja synteinsä tähden,","Hullut, jotka rangaistiin ylitsekäymisensä tähden, ja synteinsä tähden,"],[107,18,"Heidän sielunsa kauhistui kaikkea ruokaa, ja saivat kuolintautinsa.","Heidän sielunsa kauhistui kaikkea ruokaa, ja saivat kuolintautinsa."],[107,19,"Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä.","Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä."],[107,20,"Hän lähetti sanansa ja paransi heitä, ja pelasti heitä, ettei he kuolleet.","Hän lähetti sanansa ja paransi heitä, ja pelasti heitä, ettei he kuolleet."],[107,21,"Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee,","Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee,"],[107,22,"Ja uhratkaan kiitosuhria, ja luetelkaan hänen tekojansa ilolla.","Ja uhratkaan kiitosuhria, ja luetelkaan hänen tekojansa ilolla."],[107,23,"Jotka haaksilla meressä vaeltavat, ja asiansa toimittavat suurilla vesillä,","Jotka haaksilla meressä vaeltavat, ja asiansa toimittavat suurilla vesillä,"],[107,24,"He näkivät Herran työt, ja hänen ihmeensä syvyydessä.","He näkivät Herran työt, ja hänen ihmeensä syvyydessä."],[107,25,"Kuin hän sanoi, ja paisutti suuren ilman, joka aallot nosti ylös,","Kuin hän sanoi, ja paisutti suuren ilman, joka aallot nosti ylös,"],[107,26,"Niin he menivät ylös taivasta kohden ja menivät syvyyteen alas, että heidän sielunsa ahdistuksesta epäili,","Niin he menivät ylös taivasta kohden ja menivät syvyyteen alas, että heidän sielunsa ahdistuksesta epäili,"],[107,27,"Että he horjuivat ja hoipertelivat niinkuin juopuneet, ja ei silleen neuvoa tietäneet;","Että he horjuivat ja hoipertelivat niinkuin juopuneet, ja ei silleen neuvoa tietäneet;"],[107,28,"Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä.","Ja he huusivat Herraa tuskissansa, ja hän autti heitä heidän hädistänsä."],[107,29,"Ja hän hillitsi kovan ilman, että aallot asettuivat.","Ja hän hillitsi kovan ilman, että aallot asettuivat."],[107,30,"Ja he tulivat iloisiksi, että tyveni, ja hän vei heitä satamaan heidän mielensä jälkeen.","Ja he tulivat iloisiksi, että tyveni, ja hän vei heitä satamaan heidän mielensä jälkeen."],[107,31,"Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee.","Kiittäkään he siis Herraa hänen laupiutensa edestä, ja hänen ihmeittensä tähden, jotka hän ihmisten lasten kohtaan tekee."],[107,32,"Ja ylistäkään häntä kansan seurakunnassa, ja kiittäkään häntä vanhimpain seassa,","Ja ylistäkään häntä kansan seurakunnassa, ja kiittäkään häntä vanhimpain seassa,"],[107,33,"Joka virrat teki erämaaksi, ja vesilähteet kuivaksi maaksi,","Joka virrat teki erämaaksi, ja vesilähteet kuivaksi maaksi,"],[107,34,"Ettei hedelmällinen maa mitään kantanut, heidän pahuutensa tähden, jotka siinä asuivat.","Ettei hedelmällinen maa mitään kantanut, heidän pahuutensa tähden, jotka siinä asuivat."],[107,35,"Erämaan teki hän vesilammiksi ja kuivan maan vesilähteeksi,","Erämaan teki hän vesilammiksi ja kuivan maan vesilähteeksi,"],[107,36,"Ja asetti sinne isoovaiset; ja he valmistivat siihen kaupunkia, jossa he asuivat,","Ja asetti sinne isoovaiset; ja he valmistivat siihen kaupunkia, jossa he asuivat,"],[107,37,"Ja kylvivät pellot ja viinapuita istuttivat, ja saivat jokavuotisen hedelmän.","Ja kylvivät pellot ja viinapuita istuttivat, ja saivat jokavuotisen hedelmän."],[107,38,"Ja hän siunasi heitä ja he sangen suuresti enenivät, ja hän antoi paljon karjaa heille;","Ja hän siunasi heitä ja he sangen suuresti enenivät, ja hän antoi paljon karjaa heille;"],[107,39,"Jotka olivat painetut alas ja sorretut pahain väkivallalta ja ahdistukselta,","Jotka olivat painetut alas ja sorretut pahain väkivallalta ja ahdistukselta,"],[107,40,"Koska ylönkatse päämiesten päälle vuodatettu oli, ja kaikki maa eksyksissä ja autiona oli.","Koska ylönkatse päämiesten päälle vuodatettu oli, ja kaikki maa eksyksissä ja autiona oli."],[107,41,"Ja hän varjeli köyhää raadollisuudesta, ja enensi hänen sukunsa niinkuin lauman.","Ja hän varjeli köyhää raadollisuudesta, ja enensi hänen sukunsa niinkuin lauman."],[107,42,"Näitä vanhurskaat näkevät ja iloitsevat, ja jokainen paha suu pitää tukittaman.","Näitä vanhurskaat näkevät ja iloitsevat, ja jokainen paha suu pitää tukittaman."],[107,43,"Kuka on taitava ja näitä kätkee, se ymmärtää Herran moninaisen laupiuden.","Kuka on taitava ja näitä kätkee, se ymmärtää Herran moninaisen laupiuden."],[108,1,"Psalmi, Davidin veisu. (H108:2) Jumala! minun sydämeni on valmis: minä veisaan ja kiitän, niin myös minun kunniani.","Psalmi, Davidin veisu. (H108:2) Jumala! minun sydämeni on valmis: minä veisaan ja kiitän, niin myös minun kunniani."],[108,2,"Nouse, psaltari ja kantele; minä nousen varhain.","Nouse, psaltari ja kantele; minä nousen varhain."],[108,3,"Sinua, Herra, minä kiitän kansain seassa: minä veisaan sinulle kiitosta sukukunnissa.","Sinua, Herra, minä kiitän kansain seassa: minä veisaan sinulle kiitosta sukukunnissa."],[108,4,"Sillä sinun armos on suuri ylitse taivasten, ja sinun totuutes hamaan pilviin asti.","Sillä sinun armos on suuri ylitse taivasten, ja sinun totuutes hamaan pilviin asti."],[108,5,"Korota sinuas, Jumala, taivasten ylitse ja kunnias kaiken maan ylitse,","Korota sinuas, Jumala, taivasten ylitse ja kunnias kaiken maan ylitse,"],[108,6,"Että sinun rakkaat ystäväs vapaaksi tulisivat; auta oikialla kädelläs, ja kuule minun rukoukseni.","Että sinun rakkaat ystäväs vapaaksi tulisivat; auta oikialla kädelläs, ja kuule minun rukoukseni."],[108,7,"Jumala on puhunut pyhässänsä, siitä minä iloitsen: minä jaan Sikemin, ja mittaan Sukkotin laakson.","Jumala on puhunut pyhässänsä, siitä minä iloitsen: minä jaan Sikemin, ja mittaan Sukkotin laakson."],[108,8,"Gilead on minun, Manasse on myös minun, ja Ephraim on minun pääni väkevyys: Juuda on minun päämieheni;","Gilead on minun, Manasse on myös minun, ja Ephraim on minun pääni väkevyys: Juuda on minun päämieheni;"],[108,9,"Moab on minun pesinastiani, minä venytän kenkäni Edomin päälle: Philistealaisten ylitse minä iloitsen.","Moab on minun pesinastiani, minä venytän kenkäni Edomin päälle: Philistealaisten ylitse minä iloitsen."],[108,10,"Kuka vie minua vahvaan kaupunkiin? kuka vie minua Edomiin?","Kuka vie minua vahvaan kaupunkiin? kuka vie minua Edomiin?"],[108,11,"Etkös sinä, Jumala, joka meitä heittänyt olet pois? Ja etkös mene ulos, Jumala, meidän sotaväkemme kanssa?","Etkös sinä, Jumala, joka meitä heittänyt olet pois? Ja etkös mene ulos, Jumala, meidän sotaväkemme kanssa?"],[108,12,"Saata meille apua tuskissamme; sillä ihmisten apu on turha.","Saata meille apua tuskissamme; sillä ihmisten apu on turha."],[108,13,"Jumalassa me tahdomme urhoollisia töitä tehdä; ja hän polkee meidän vihollisemme alas.","Jumalassa me tahdomme urhoollisia töitä tehdä; ja hän polkee meidän vihollisemme alas."],[109,1,"Davidin Psalmi, edelläveisaajalle. Jumala, minun kiitokseni, älä vaikene.","Davidin Psalmi, edelläveisaajalle. Jumala, minun kiitokseni, älä vaikene."],[109,2,"Sillä he ovat jumalattoman ja pettäväisen suunsa avanneet minua vastaan: he puhuvat minun kanssani viekkaalla kielellä,","Sillä he ovat jumalattoman ja pettäväisen suunsa avanneet minua vastaan: he puhuvat minun kanssani viekkaalla kielellä,"],[109,3,"Ja myrkyllisillä sanoilla ovat he minun piirittäneet, ja sotivat minua vastaan ilman syytä.","Ja myrkyllisillä sanoilla ovat he minun piirittäneet, ja sotivat minua vastaan ilman syytä."],[109,4,"Että minä heitä rakastan, ovat he minua vastaan; mutta minä rukoilen.","Että minä heitä rakastan, ovat he minua vastaan; mutta minä rukoilen."],[109,5,"He osoittavat minulle pahaa hyvän edestä ja vihaa rakkauden edestä.","He osoittavat minulle pahaa hyvän edestä ja vihaa rakkauden edestä."],[109,6,"Aseta jumalattomat hänen päällensä, ja perkele seisokaan hänen oikialla kädellänsä.","Aseta jumalattomat hänen päällensä, ja perkele seisokaan hänen oikialla kädellänsä."],[109,7,"Koska hän tuomitaan, niin lähtekään siitä ulos jumalattomana, ja hänen rukouksensa olkoon synti.","Koska hän tuomitaan, niin lähtekään siitä ulos jumalattomana, ja hänen rukouksensa olkoon synti."],[109,8,"Olkoon hänen päivänsä harvat, ja hänen virkansa ottakoon toinen.","Olkoon hänen päivänsä harvat, ja hänen virkansa ottakoon toinen."],[109,9,"Hänen lapsensa olkoon orvot, ja hänen emäntänsä leski.","Hänen lapsensa olkoon orvot, ja hänen emäntänsä leski."],[109,10,"Käykään hänen lapsensa kulkiana, ja kerjätkään, ja etsikään elatuksensa köyhyydessänsä.","Käykään hänen lapsensa kulkiana, ja kerjätkään, ja etsikään elatuksensa köyhyydessänsä."],[109,11,"Kaikki mitä hänellä on, korkorahainen ottakoon, ja muukalaiset repikään hänen hyvyytensä.","Kaikki mitä hänellä on, korkorahainen ottakoon, ja muukalaiset repikään hänen hyvyytensä."],[109,12,"Älköön kenkään hänelle hyvää tehkö, eikä yksikään armahtako hänen orpojansa.","Älköön kenkään hänelle hyvää tehkö, eikä yksikään armahtako hänen orpojansa."],[109,13,"Hänen sukunsa olkoon hävitetty: heidän nimensä olkoon toisessa polvessa pyyhitty pois.","Hänen sukunsa olkoon hävitetty: heidän nimensä olkoon toisessa polvessa pyyhitty pois."],[109,14,"Hänen isäinsä pahat teot tulkaan muistoksi Herran edessä, ja hänen äitinsä synti ei pidä pyyhittämän pois.","Hänen isäinsä pahat teot tulkaan muistoksi Herran edessä, ja hänen äitinsä synti ei pidä pyyhittämän pois."],[109,15,"Olkoon ne alati Herran kasvoin edessä, ja hukkukoon heidän muistonsa maan päältä,","Olkoon ne alati Herran kasvoin edessä, ja hukkukoon heidän muistonsa maan päältä,"],[109,16,"Ettei hänellä ensinkään laupiutta ollut, vaan vainosi raadollista ja köyhää, ja murheellista tappaaksensa.","Ettei hänellä ensinkään laupiutta ollut, vaan vainosi raadollista ja köyhää, ja murheellista tappaaksensa."],[109,17,"Ja hän tahtoi kirousta, sen myös pitää hänelle tuleman: ei hän tahtonut siunausta, sen pitää myös hänestä kauvas erkaneman.","Ja hän tahtoi kirousta, sen myös pitää hänelle tuleman: ei hän tahtonut siunausta, sen pitää myös hänestä kauvas erkaneman."],[109,18,"Ja hän puki kirouksen päällensä niinkuin paitansa ja se meni hänen sisällyksiinsä niinkuin vesi, ja hänen luihinsa niinkuin öljy.","Ja hän puki kirouksen päällensä niinkuin paitansa ja se meni hänen sisällyksiinsä niinkuin vesi, ja hänen luihinsa niinkuin öljy."],[109,19,"Se olkoon hänelle niinkuin vaate, jolla hän itsensä verhottaa, ja niinkuin vyö, jolla hän aina itsensä vyöttää.","Se olkoon hänelle niinkuin vaate, jolla hän itsensä verhottaa, ja niinkuin vyö, jolla hän aina itsensä vyöttää."],[109,20,"Aivan näin tapahtukoon heille Herralta, jotka ovat minua vastaan, ja puhuvat pahoin minun sieluani vastaan.","Aivan näin tapahtukoon heille Herralta, jotka ovat minua vastaan, ja puhuvat pahoin minun sieluani vastaan."],[109,21,"Mutta sinä, Herra, Herra, tee minun kanssani sinun nimes tähden; sillä sinun armos on hyvä, pelasta minua.","Mutta sinä, Herra, Herra, tee minun kanssani sinun nimes tähden; sillä sinun armos on hyvä, pelasta minua."],[109,22,"Sillä minä olen köyhä ja raadollinen: minun sydämeni on särjetty minussa.","Sillä minä olen köyhä ja raadollinen: minun sydämeni on särjetty minussa."],[109,23,"Minä menen pois niinkuin varjo, koska se kulkee pois, ja pudistetaan ulos niinkuin kaskaat.","Minä menen pois niinkuin varjo, koska se kulkee pois, ja pudistetaan ulos niinkuin kaskaat."],[109,24,"Minun polveni ovat heikoksi tulleet paastosta, ja minun lihani on laihtunut lihavuudesta.","Minun polveni ovat heikoksi tulleet paastosta, ja minun lihani on laihtunut lihavuudesta."],[109,25,"Ja minun täytyy olla heidän pilkkansa: koska he minun näkevät, niin he päätänsä pudistavat.","Ja minun täytyy olla heidän pilkkansa: koska he minun näkevät, niin he päätänsä pudistavat."],[109,26,"Auta minua, Herra minun Jumalani: auta minua sinun armos perästä,","Auta minua, Herra minun Jumalani: auta minua sinun armos perästä,"],[109,27,"Että he tuntisivat sen sinun kädekses, ja että sinä Herra sen teet.","Että he tuntisivat sen sinun kädekses, ja että sinä Herra sen teet."],[109,28,"Koska he sadattavat, niin siunaa sinä: koska he karkaavat minua vastaan, niin tulkoon he häpiään, mutta sinun palvelias iloitkaan.","Koska he sadattavat, niin siunaa sinä: koska he karkaavat minua vastaan, niin tulkoon he häpiään, mutta sinun palvelias iloitkaan."],[109,29,"Olkoon minun vainolliseni häväistyksellä puetut, ja olkoon häpiällänsä verhotetut niinkuin hameella.","Olkoon minun vainolliseni häväistyksellä puetut, ja olkoon häpiällänsä verhotetut niinkuin hameella."],[109,30,"Minä kiitän suuresti Herraa suullani, ja ylistän häntä monen seassa.","Minä kiitän suuresti Herraa suullani, ja ylistän häntä monen seassa."],[109,31,"Sillä hän seisoo köyhän oikialla kädellä, auttamassa häntä niistä, jotka hänen sieluansa tuomitsevat.","Sillä hän seisoo köyhän oikialla kädellä, auttamassa häntä niistä, jotka hänen sieluansa tuomitsevat."],[110,1,"Davidin Psalmi. Herra sanoi minun Herralleni: istu oikialle kädelleni, siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi.","Davidin Psalmi. Herra sanoi minun Herralleni: istu oikialle kädelleni, siihenasti kuin minä panen sinun vihollises sinun jalkais astinlaudaksi."],[110,2,"Herra lähettää sinun väkevyytes valtikan Zionista: vallitse vihollistes seassa.","Herra lähettää sinun väkevyytes valtikan Zionista: vallitse vihollistes seassa."],[110,3,"Sinun voittos päivänä palvelee sinun kansas sinua mielellänsä pyhissä kaunistuksissa: sinun lapses synnytetään sinulle niinkuin kaste aamuruskosta.","Sinun voittos päivänä palvelee sinun kansas sinua mielellänsä pyhissä kaunistuksissa: sinun lapses synnytetään sinulle niinkuin kaste aamuruskosta."],[110,4,"Herra on vannonut, ja ei kadu sitä: sinä olet pappi ijankaikkisesti, Melkisedekin säädyn jälkeen.","Herra on vannonut, ja ei kadu sitä: sinä olet pappi ijankaikkisesti, Melkisedekin säädyn jälkeen."],[110,5,"Herra on sinun oikialla kädelläs: hän musertaa kuninkaat vihansa päivänä.","Herra on sinun oikialla kädelläs: hän musertaa kuninkaat vihansa päivänä."],[110,6,"Hän tuomitsee pakanain seassa, hän täyttää maakunnat ruumiilla: hän musertaa monen maakunnan pään.","Hän tuomitsee pakanain seassa, hän täyttää maakunnat ruumiilla: hän musertaa monen maakunnan pään."],[110,7,"Hän juo ojasta tiellä; sen tähden korottaa hän päänsä.","Hän juo ojasta tiellä; sen tähden korottaa hän päänsä."],[111,1,"Halleluja! Minä kiitän Herraa kaikesta sydämestäni, hurskasten neuvossa ja seurakunnassa.","Halleluja! Minä kiitän Herraa kaikesta sydämestäni, hurskasten neuvossa ja seurakunnassa."],[111,2,"Suuret ovat Herran työt: joka niistä ottaa vaarin, hänellä on sula riemu niistä.","Suuret ovat Herran työt: joka niistä ottaa vaarin, hänellä on sula riemu niistä."],[111,3,"Mitä hän asettaa, se on kunniallinen ja jalo, ja hänen vanhurskautensa pysyy ijankaikkisesti.","Mitä hän asettaa, se on kunniallinen ja jalo, ja hänen vanhurskautensa pysyy ijankaikkisesti."],[111,4,"Hän on säätänyt ihmeittensä muiston: armollinen ja laupias on Herra.","Hän on säätänyt ihmeittensä muiston: armollinen ja laupias on Herra."],[111,5,"Hän antaa ruan pelkääväisillensä: hän muistaa liittonsa ijankaikkisesti.","Hän antaa ruan pelkääväisillensä: hän muistaa liittonsa ijankaikkisesti."],[111,6,"Hän ilmoittaa kansallensa väkevät työnsä, antaaksensa heille pakanain perimisen.","Hän ilmoittaa kansallensa väkevät työnsä, antaaksensa heille pakanain perimisen."],[111,7,"Hänen kättensä työt ovat totuus ja oikeus: kaikki hänen käskynsä ovat toimelliset.","Hänen kättensä työt ovat totuus ja oikeus: kaikki hänen käskynsä ovat toimelliset."],[111,8,"Ne pysyvät vahvana aina ja ijankaikkisesti: ne ovat tehdyt totuudessa ja oikeudessa.","Ne pysyvät vahvana aina ja ijankaikkisesti: ne ovat tehdyt totuudessa ja oikeudessa."],[111,9,"Hän lähetti kansallensa lunastuksen, hän lupaa liittonsa pysymään ijankaikkisesti: pyhä ja peljättävä on hänen nimensä.","Hän lähetti kansallensa lunastuksen, hän lupaa liittonsa pysymään ijankaikkisesti: pyhä ja peljättävä on hänen nimensä."],[111,10,"Herran pelko on viisauden alku: se on hyvä ymmärrys kaikille, jotka sen tekevät: hänen kiitoksensa pysyy ijankaikkisesti.","Herran pelko on viisauden alku: se on hyvä ymmärrys kaikille, jotka sen tekevät: hänen kiitoksensa pysyy ijankaikkisesti."],[112,1,"Halleluja! Autuas on, joka pelkää Herraa: joka hänen käskyjänsä sangen himoitsee.","Halleluja! Autuas on, joka pelkää Herraa: joka hänen käskyjänsä sangen himoitsee."],[112,2,"Hänen siemenensä on valtias maan päällä: hurskasten suku pitää siunatuksi tuleman.","Hänen siemenensä on valtias maan päällä: hurskasten suku pitää siunatuksi tuleman."],[112,3,"Rikkaus ja runsaus on hänen huoneessansa, ja hänen vanhurskautensa pysyy ijankaikkisesti.","Rikkaus ja runsaus on hänen huoneessansa, ja hänen vanhurskautensa pysyy ijankaikkisesti."],[112,4,"Hurskaille koittaa valkeus pimeässä, armolliselta, laupiaalta ja vanhurskaalta.","Hurskaille koittaa valkeus pimeässä, armolliselta, laupiaalta ja vanhurskaalta."],[112,5,"Hyvä ihminen on laupias ja mielellänsä lainaa, ja toimittaa asiansa toimellisesti.","Hyvä ihminen on laupias ja mielellänsä lainaa, ja toimittaa asiansa toimellisesti."],[112,6,"Sillä hän pysyy ijankaikkisesti: ei vanhurskas ikänä unhoteta.","Sillä hän pysyy ijankaikkisesti: ei vanhurskas ikänä unhoteta."],[112,7,"Koska rangaistus tulee, niin ei hän pelkää: hänen sydämensä uskaltaa lujasti Herran päälle.","Koska rangaistus tulee, niin ei hän pelkää: hänen sydämensä uskaltaa lujasti Herran päälle."],[112,8,"Hänen sydämensä on vahvistettu ja ei pelkää, siihenasti kuin hän näkee ilonsa vihollisistansa.","Hänen sydämensä on vahvistettu ja ei pelkää, siihenasti kuin hän näkee ilonsa vihollisistansa."],[112,9,"Hän jakaa ja antaa vaivaisille: hänen vanhurskautensa pysyy ijankaikkisesti: hänen sarvensa korotetaan kunnialla.","Hän jakaa ja antaa vaivaisille: hänen vanhurskautensa pysyy ijankaikkisesti: hänen sarvensa korotetaan kunnialla."],[112,10,"Jumalatoin näkee sen ja närkästyy: hän pureskelee hampaitansa ja nääntyy; sillä mitä jumalattomat halajavat, se tyhjäksi tulee.","Jumalatoin näkee sen ja närkästyy: hän pureskelee hampaitansa ja nääntyy; sillä mitä jumalattomat halajavat, se tyhjäksi tulee."],[113,1,"Halleluja! Kiittäkäät te, Herran palveliat, kiittäkäät Herran nimeä!","Halleluja! Kiittäkäät te, Herran palveliat, kiittäkäät Herran nimeä!"],[113,2,"Kiitetty olkoon Herran nimi, nyt ja ijankaikkisesti!","Kiitetty olkoon Herran nimi, nyt ja ijankaikkisesti!"],[113,3,"Auringon koitosta hänen laskemiseensa asti olkoon Herran nimi kiitetty!","Auringon koitosta hänen laskemiseensa asti olkoon Herran nimi kiitetty!"],[113,4,"Herra on korkia ylitse kaikkein pakanain, ja hänen kunniansa ylitse taivasten.","Herra on korkia ylitse kaikkein pakanain, ja hänen kunniansa ylitse taivasten."],[113,5,"Kuka on niinkuin Herra meidän Jumalamme, joka niin korkialla asuu?","Kuka on niinkuin Herra meidän Jumalamme, joka niin korkialla asuu?"],[113,6,"Ja kuitenkin katsoo alimmaisia taivaassa ja maassa;","Ja kuitenkin katsoo alimmaisia taivaassa ja maassa;"],[113,7,"Joka köyhän tomusta ylentää, ja vaivaisen loasta korottaa,","Joka köyhän tomusta ylentää, ja vaivaisen loasta korottaa,"],[113,8,"Istuttaaksensa häntä päämiesten sivuun, kansansa päämiesten sivuun;","Istuttaaksensa häntä päämiesten sivuun, kansansa päämiesten sivuun;"],[113,9,"Joka hedelmättömät saattaa huoneesen asumaan, että hän riemuiseksi lasten äidiksi tulee. Halleluja!","Joka hedelmättömät saattaa huoneesen asumaan, että hän riemuiseksi lasten äidiksi tulee. Halleluja!"],[114,1,"Kuin Israel Egyptistä läksi, Jakobin huone muukalaisesta kansasta,","Kuin Israel Egyptistä läksi, Jakobin huone muukalaisesta kansasta,"],[114,2,"Niin Juuda tuli hänen pyhäksensä: Israel hänen vallaksensa.","Niin Juuda tuli hänen pyhäksensä: Israel hänen vallaksensa."],[114,3,"Sen meri näki ja pakeni: Jordan palasi takaperin,","Sen meri näki ja pakeni: Jordan palasi takaperin,"],[114,4,"Vuoret hyppäsivät niinkuin oinaat, ja kukkulat niinkuin nuoret lampaat.","Vuoret hyppäsivät niinkuin oinaat, ja kukkulat niinkuin nuoret lampaat."],[114,5,"Mikä sinun oli meri, ettäs pakenit? ja sinä Jordan, ettäs palasit takaperin?","Mikä sinun oli meri, ettäs pakenit? ja sinä Jordan, ettäs palasit takaperin?"],[114,6,"Te vuoret, että te hyppäsitte niinkuin oinaat? te kukkulat niinkuin nuoret lampaat?","Te vuoret, että te hyppäsitte niinkuin oinaat? te kukkulat niinkuin nuoret lampaat?"],[114,7,"Herran edessä vapisi maa, Jakobin Jumalan edessä,","Herran edessä vapisi maa, Jakobin Jumalan edessä,"],[114,8,"Joka kalliot muuttaa vesilammiksi, ja kiven vesilähteeksi.","Joka kalliot muuttaa vesilammiksi, ja kiven vesilähteeksi."],[115,1,"Ei meille, Herra, ei meille, vaan sinun nimelles anna kunnia, sinun armos ja totuutes tähden.","Ei meille, Herra, ei meille, vaan sinun nimelles anna kunnia, sinun armos ja totuutes tähden."],[115,2,"Miksi pakanat sanovat: kussa on nyt heidän Jumalansa?","Miksi pakanat sanovat: kussa on nyt heidän Jumalansa?"],[115,3,"Mutta meidän Jumalamme on taivaissa: mitä ikänä hän tahtoo, sen hän tekee.","Mutta meidän Jumalamme on taivaissa: mitä ikänä hän tahtoo, sen hän tekee."],[115,4,"Vaan heidän epäjumalansa ovat hopia ja kulta, ihmisten käsillä tehdyt.","Vaan heidän epäjumalansa ovat hopia ja kulta, ihmisten käsillä tehdyt."],[115,5,"Heillä on suu, ja ei puhu: heillä ovat silmät, ja ei näe.","Heillä on suu, ja ei puhu: heillä ovat silmät, ja ei näe."],[115,6,"Heillä ovat korvat, ja ei kuule: heillä ovat sieraimet, ja ei haista.","Heillä ovat korvat, ja ei kuule: heillä ovat sieraimet, ja ei haista."],[115,7,"Heillä ovat kädet, ja ei rupee: heillä ovat jalat, ja ei käy; ja ei puhu kurkustansa.","Heillä ovat kädet, ja ei rupee: heillä ovat jalat, ja ei käy; ja ei puhu kurkustansa."],[115,8,"Jotka niitä tekevät, ovat niiden kaltaiset, ja kaikki, jotka heihin uskaltavat.","Jotka niitä tekevät, ovat niiden kaltaiset, ja kaikki, jotka heihin uskaltavat."],[115,9,"Mutta Israel toivokaan Herran päälle: hän on heidän apunsa ja heidän kilpensä.","Mutta Israel toivokaan Herran päälle: hän on heidän apunsa ja heidän kilpensä."],[115,10,"Aaronin huone toivokaan Herran päälle: hän on heidän apunsa ja heidän kilpensä.","Aaronin huone toivokaan Herran päälle: hän on heidän apunsa ja heidän kilpensä."],[115,11,"Jotka Herraa pelkäävät, toivokaan myös Herran päälle: hän on heidän apunsa ja heidän kilpensä.","Jotka Herraa pelkäävät, toivokaan myös Herran päälle: hän on heidän apunsa ja heidän kilpensä."],[115,12,"Herra muistaa meitä ja siunaa meitä: hän siunaa Israelin huoneen, hän siunaa Aaronin huoneen.","Herra muistaa meitä ja siunaa meitä: hän siunaa Israelin huoneen, hän siunaa Aaronin huoneen."],[115,13,"Hän siunaa ne, jotka Herraa pelkäävät, sekä pienet että suuret.","Hän siunaa ne, jotka Herraa pelkäävät, sekä pienet että suuret."],[115,14,"Herra siunatkoon teitä enemmin ja enemmin, teitä ja teidän lapsianne.","Herra siunatkoon teitä enemmin ja enemmin, teitä ja teidän lapsianne."],[115,15,"Te olette Herran siunatut, joka taivaat ja maan on tehnyt.","Te olette Herran siunatut, joka taivaat ja maan on tehnyt."],[115,16,"Taivasten taivaat ovat Herran; mutta maan on hän ihmisten lapsille antanut.","Taivasten taivaat ovat Herran; mutta maan on hän ihmisten lapsille antanut."],[115,17,"Kuolleet ei taida Herraa kiittää, eikä ne, jotka menevät alas hiljaisuuteen.","Kuolleet ei taida Herraa kiittää, eikä ne, jotka menevät alas hiljaisuuteen."],[115,18,"Mutta me kiitämme Herraa, hamasta nyt ja ijankaikkiseen, Halleluja!","Mutta me kiitämme Herraa, hamasta nyt ja ijankaikkiseen, Halleluja!"],[116,1,"Sitä minä rakastan, että Herra kuulee minun rukoukseni äänen;","Sitä minä rakastan, että Herra kuulee minun rukoukseni äänen;"],[116,2,"Että hän korvansa kallistaa minun puoleeni; sentähden minä avukseni huudan häntä elinaikanani.","Että hän korvansa kallistaa minun puoleeni; sentähden minä avukseni huudan häntä elinaikanani."],[116,3,"Kuoleman paulat ovat minun piirittäneet, ja helvetin ahdistukset ovat minun löytäneet: minä tulin vaivaan ja tuskaan.","Kuoleman paulat ovat minun piirittäneet, ja helvetin ahdistukset ovat minun löytäneet: minä tulin vaivaan ja tuskaan."],[116,4,"Mutta minä avukseni huudan Herran nimeä: o Herra, pelasta minun sieluni!","Mutta minä avukseni huudan Herran nimeä: o Herra, pelasta minun sieluni!"],[116,5,"Herra on armollinen ja vanhurskas, ja meidän Jumalamme on laupias.","Herra on armollinen ja vanhurskas, ja meidän Jumalamme on laupias."],[116,6,"Herra kätkee yksinkertaiset: kuin minä olin kovin vaivattu, niin hän minua autti.","Herra kätkee yksinkertaiset: kuin minä olin kovin vaivattu, niin hän minua autti."],[116,7,"Palaja taas, minun sieluni, sinun lepoos; sillä Herra tekee hyvästi sinulle.","Palaja taas, minun sieluni, sinun lepoos; sillä Herra tekee hyvästi sinulle."],[116,8,"Sillä sinä olet sieluni temmannut pois kuolemasta, silmäni kyynelistä, jalkani kompastuksesta.","Sillä sinä olet sieluni temmannut pois kuolemasta, silmäni kyynelistä, jalkani kompastuksesta."],[116,9,"Minä vaellan Herran edessä eläväin maassa.","Minä vaellan Herran edessä eläväin maassa."],[116,10,"Minä uskon, sentähden minä puhun; mutta minä sangen vaivataan.","Minä uskon, sentähden minä puhun; mutta minä sangen vaivataan."],[116,11,"Minä sanoin hämmästyksessä: kaikki ihmiset ovat valehteliat.","Minä sanoin hämmästyksessä: kaikki ihmiset ovat valehteliat."],[116,12,"Kuinka minä maksan Herralle kaikki hänen hyvät tekonsa, jotka hän minulle teki?","Kuinka minä maksan Herralle kaikki hänen hyvät tekonsa, jotka hän minulle teki?"],[116,13,"Minä otan sen autuaallisen kalkin, ja saarnaan Herran nimeä.","Minä otan sen autuaallisen kalkin, ja saarnaan Herran nimeä."],[116,14,"Minä maksan lupaukseni Herralle kaiken hänen kansansa edessä.","Minä maksan lupaukseni Herralle kaiken hänen kansansa edessä."],[116,15,"Hänen pyhäinsä kuolema on kallis Herran edessä.","Hänen pyhäinsä kuolema on kallis Herran edessä."],[116,16,"O Herra! minä olen sinun palvelias, minä olen sinun palvelias, sinun piikas poika: sinä olet minun siteeni vallallensa päästänyt.","O Herra! minä olen sinun palvelias, minä olen sinun palvelias, sinun piikas poika: sinä olet minun siteeni vallallensa päästänyt."],[116,17,"Minä uhraan sinulle kiitosuhria, ja Herran nimeä saarnaan.","Minä uhraan sinulle kiitosuhria, ja Herran nimeä saarnaan."],[116,18,"Minä maksan Herralle lupaukseni kaiken hänen kansansa edessä,","Minä maksan Herralle lupaukseni kaiken hänen kansansa edessä,"],[116,19,"Herran huoneen esikartanoissa, keskellä sinua, Jerusalem. Halleluja!","Herran huoneen esikartanoissa, keskellä sinua, Jerusalem. Halleluja!"],[117,1,"Kiittäkäät Herraa, kaikki pakanat: ylistäkäät häntä kaikki kansat!","Kiittäkäät Herraa, kaikki pakanat: ylistäkäät häntä kaikki kansat!"],[117,2,"Sillä hänen armonsa on voimallinen meidän päällemme, ja Herran totuus ijankaikkisesti. Halleluja!","Sillä hänen armonsa on voimallinen meidän päällemme, ja Herran totuus ijankaikkisesti. Halleluja!"],[118,1,"Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti.","Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti."],[118,2,"Sanokaan nyt Israel: hänen laupiutensa pysyy ijankaikkisesti.","Sanokaan nyt Israel: hänen laupiutensa pysyy ijankaikkisesti."],[118,3,"Sanokaan nyt Aaronin huone: hänen laupiutensa pysyy ijankaikkisesti.","Sanokaan nyt Aaronin huone: hänen laupiutensa pysyy ijankaikkisesti."],[118,4,"Sanokaan nyt kaikki, jotka Herraa pelkäävät: hänen laupiutensa pysyy ijankaikkisesti.","Sanokaan nyt kaikki, jotka Herraa pelkäävät: hänen laupiutensa pysyy ijankaikkisesti."],[118,5,"Tuskissani minä Herraa avukseni huusin, ja Herra kuuli minua, ja pelasti minun.","Tuskissani minä Herraa avukseni huusin, ja Herra kuuli minua, ja pelasti minun."],[118,6,"Herra on minun kanssani; sentähden en minä pelkää, mitä ihmiset minulle tekisivät.","Herra on minun kanssani; sentähden en minä pelkää, mitä ihmiset minulle tekisivät."],[118,7,"Herra on minun kanssani auttamassa minua, ja minä tahdon nähdä iloni minun vihollisistani.","Herra on minun kanssani auttamassa minua, ja minä tahdon nähdä iloni minun vihollisistani."],[118,8,"Parempi on uskaltaa Herran päälle, kuin luottaa ihmisiin.","Parempi on uskaltaa Herran päälle, kuin luottaa ihmisiin."],[118,9,"Parempi on uskaltaa Herran päälle, kuin luottaa päämiehiin.","Parempi on uskaltaa Herran päälle, kuin luottaa päämiehiin."],[118,10,"Kaikki pakanat piirittävät minua; mutta Herran nimeen minä heitä lyön maahan.","Kaikki pakanat piirittävät minua; mutta Herran nimeen minä heitä lyön maahan."],[118,11,"He piirittävät minua joka kulmalta; mutta Herran nimeen minä heitä lyön maahan.","He piirittävät minua joka kulmalta; mutta Herran nimeen minä heitä lyön maahan."],[118,12,"He piirittävät minua niinkuin kimalaiset, ja he sammuvat niinkuin tuli orjantappuroissa; mutta Herran nimeen minä heitä lyön maahan.","He piirittävät minua niinkuin kimalaiset, ja he sammuvat niinkuin tuli orjantappuroissa; mutta Herran nimeen minä heitä lyön maahan."],[118,13,"Minua kovin sysätään lankeemaan; mutta Herra auttaa minua.","Minua kovin sysätään lankeemaan; mutta Herra auttaa minua."],[118,14,"Herra on minun väkevyyteni, ja minun virteni, ja on minun autuuteni.","Herra on minun väkevyyteni, ja minun virteni, ja on minun autuuteni."],[118,15,"Ilon ja autuuden ääni on vanhurskasten majoissa: Herran oikia käsi saa voiton.","Ilon ja autuuden ääni on vanhurskasten majoissa: Herran oikia käsi saa voiton."],[118,16,"Herran oikia käsi on koroitettu: Herran oikia käsi saa voiton.","Herran oikia käsi on koroitettu: Herran oikia käsi saa voiton."],[118,17,"En minä kuole, vaan elän, ja Herran tekoja luettelen.","En minä kuole, vaan elän, ja Herran tekoja luettelen."],[118,18,"Kyllä Herra minua kurittaa, vaan ei hän minua kuolemalle anna.","Kyllä Herra minua kurittaa, vaan ei hän minua kuolemalle anna."],[118,19,"Avatkaat minulle vanhurskauden portit, minun käydäkseni sisälle, kiittämään Herraa.","Avatkaat minulle vanhurskauden portit, minun käydäkseni sisälle, kiittämään Herraa."],[118,20,"Tämä on Herran portti: vanhurskaat siitä käyvät sisälle.","Tämä on Herran portti: vanhurskaat siitä käyvät sisälle."],[118,21,"Minä kiitän sinua, ettäs minun rukoukseni kuulit, ja autit minua.","Minä kiitän sinua, ettäs minun rukoukseni kuulit, ja autit minua."],[118,22,"Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi.","Se kivi, jonka rakentajat hylkäsivät, on tullut kulmakiveksi."],[118,23,"Herralta se on tapahtunut, ja on ihme meidän silmäimme edessä.","Herralta se on tapahtunut, ja on ihme meidän silmäimme edessä."],[118,24,"Tämä on se päivä, jonka Herra teki: iloitkaamme ja riemuitkaamme hänessä.","Tämä on se päivä, jonka Herra teki: iloitkaamme ja riemuitkaamme hänessä."],[118,25,"O Herra, auta, o Herra, anna menestyä!","O Herra, auta, o Herra, anna menestyä!"],[118,26,"Siunattu olkoon se,joka tulee Herran nimeen! me siunaamme teitä Herran huoneesta.","Siunattu olkoon se,joka tulee Herran nimeen! me siunaamme teitä Herran huoneesta."],[118,27,"Herra on Jumala, joka meitä valistaa: kaunistakaat juhlalehdillä hamaan alttarin sarviin asti.","Herra on Jumala, joka meitä valistaa: kaunistakaat juhlalehdillä hamaan alttarin sarviin asti."],[118,28,"Sinä olet minun Jumalani, ja minä kiitän sinua; minun Jumalani! sinua minä ylistän.","Sinä olet minun Jumalani, ja minä kiitän sinua; minun Jumalani! sinua minä ylistän."],[118,29,"Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti.","Kiittäkäät Herraa; sillä hän on hyvä, ja hänen laupiutensa pysyy ijankaikkisesti."],[119,1,"Autuaat ovat ne, jotka viattomasti elävät, ja jotka Herran laissa vaeltavat.","Autuaat ovat ne, jotka viattomasti elävät, ja jotka Herran laissa vaeltavat."],[119,2,"Autuaat ovat ne, jotka hänen todistuksiansa pitävät, ja kaikesta sydämestä häntä etsivät.","Autuaat ovat ne, jotka hänen todistuksiansa pitävät, ja kaikesta sydämestä häntä etsivät."],[119,3,"Sillä, jotka hänen teissänsä vaeltavat, ei he tee mitään pahaa.","Sillä, jotka hänen teissänsä vaeltavat, ei he tee mitään pahaa."],[119,4,"Sinä olet käskenyt sangen visusti pitää sinun käskys.","Sinä olet käskenyt sangen visusti pitää sinun käskys."],[119,5,"O jospa minun tieni ojennettaisiin pitämään sinun säätyjäs!","O jospa minun tieni ojennettaisiin pitämään sinun säätyjäs!"],[119,6,"Koska minä katson kaikkia sinun käskyjäs, niin en minä tule häpiään.","Koska minä katson kaikkia sinun käskyjäs, niin en minä tule häpiään."],[119,7,"Minä kiitän sinua oikiasta sydämestä, ettäs opetat minulle vanhurskautes oikeudet.","Minä kiitän sinua oikiasta sydämestä, ettäs opetat minulle vanhurskautes oikeudet."],[119,8,"Sinun säätys minä pidän, älä minua ikänä hylkää.","Sinun säätys minä pidän, älä minua ikänä hylkää."],[119,9,"Kuinka nuorukainen tiensä puhdistais? kuin hän itsensä käyttää sinun sanas jälkeen.","Kuinka nuorukainen tiensä puhdistais? kuin hän itsensä käyttää sinun sanas jälkeen."],[119,10,"Minä etsin sinua kaikesta sydämestäni: älä salli minun eksyä sinun käskyistäs.","Minä etsin sinua kaikesta sydämestäni: älä salli minun eksyä sinun käskyistäs."],[119,11,"Minä pidän sydämessäni sinun sanas, etten minä rikkoisi sinua vastaan.","Minä pidän sydämessäni sinun sanas, etten minä rikkoisi sinua vastaan."],[119,12,"Kiitetty ole, sinä Herra: opeta minulle sinun säätyjäs!","Kiitetty ole, sinä Herra: opeta minulle sinun säätyjäs!"],[119,13,"Minä luettelen huulillani kaikki sinun suus oikeudet.","Minä luettelen huulillani kaikki sinun suus oikeudet."],[119,14,"Minä iloitsen sinun todistustes tiellä, niinkuin kaikkinaisesta rikkaudesta.","Minä iloitsen sinun todistustes tiellä, niinkuin kaikkinaisesta rikkaudesta."],[119,15,"Minä tutkistelen sinun käskyjäs, ja katselen sinun teitäs.","Minä tutkistelen sinun käskyjäs, ja katselen sinun teitäs."],[119,16,"Minä halajan sinun oikeuttas, ja en unohda sinun sanojas.","Minä halajan sinun oikeuttas, ja en unohda sinun sanojas."],[119,17,"Tee hyvästi palvelialles, että minä eläisin ja sinun sanas pitäisin.","Tee hyvästi palvelialles, että minä eläisin ja sinun sanas pitäisin."],[119,18,"Avaa minun silmäni näkemään ihmeitä sinun laistas.","Avaa minun silmäni näkemään ihmeitä sinun laistas."],[119,19,"Minä olen vieras maan päällä: älä peitä minulta käskyjäs.","Minä olen vieras maan päällä: älä peitä minulta käskyjäs."],[119,20,"Minun sieluni on muserrettu rikki ikävöitsemisestä, alati sinun oikeutes jälkeen.","Minun sieluni on muserrettu rikki ikävöitsemisestä, alati sinun oikeutes jälkeen."],[119,21,"Sinä rankaiset ylpiät kirotut, jotka sinun käskyistäs poikkeevat.","Sinä rankaiset ylpiät kirotut, jotka sinun käskyistäs poikkeevat."],[119,22,"Käännä minusta pois pilkka ja ylönkatse; sillä minä pidän sinun todistukses.","Käännä minusta pois pilkka ja ylönkatse; sillä minä pidän sinun todistukses."],[119,23,"Istuvat myös päämiehet ja puhuvat minua vastaan; mutta sinun palvelias tutkistelee sinun säätyjäs.","Istuvat myös päämiehet ja puhuvat minua vastaan; mutta sinun palvelias tutkistelee sinun säätyjäs."],[119,24,"Sinun todistukses ovat minun iloni, ne ovat minun neuvonantajani.","Sinun todistukses ovat minun iloni, ne ovat minun neuvonantajani."],[119,25,"Minun sieluni tomussa makaa: virvoita minua sanas jälkeen.","Minun sieluni tomussa makaa: virvoita minua sanas jälkeen."],[119,26,"Minä luen minun teitäni, ja sinä kuulet minua: opeta minulle sinun säätys.","Minä luen minun teitäni, ja sinä kuulet minua: opeta minulle sinun säätys."],[119,27,"Anna minun ymmärtää sinun käskyis tie, niin minä puhun sinun ihmeistäs.","Anna minun ymmärtää sinun käskyis tie, niin minä puhun sinun ihmeistäs."],[119,28,"Niin minä suren, että sydän sulaa minussa: vahvista minua sinun sanas jälkeen.","Niin minä suren, että sydän sulaa minussa: vahvista minua sinun sanas jälkeen."],[119,29,"Käännä minusta pois väärä tie, ja suo minulle sinun lakis.","Käännä minusta pois väärä tie, ja suo minulle sinun lakis."],[119,30,"Totuuden tien minä olen valinnut, oikeutes olen minä asettanut eteeni.","Totuuden tien minä olen valinnut, oikeutes olen minä asettanut eteeni."],[119,31,"Minä riipun sinun todistuksissas: Herra, älä salli minun häpiään tulla.","Minä riipun sinun todistuksissas: Herra, älä salli minun häpiään tulla."],[119,32,"Koskas minun sydämeni vahvistat, niin minä juoksen sinun käskyis tietä myöten.","Koskas minun sydämeni vahvistat, niin minä juoksen sinun käskyis tietä myöten."],[119,33,"Opeta minulle, Herra, sinun säätyis tie, että minä sen loppuun asti kätkisin.","Opeta minulle, Herra, sinun säätyis tie, että minä sen loppuun asti kätkisin."],[119,34,"Anna minulle ymmärrys, kätkeäkseni sinun lakias, ja pitääkseni sitä koko sydämestäni.","Anna minulle ymmärrys, kätkeäkseni sinun lakias, ja pitääkseni sitä koko sydämestäni."],[119,35,"Anna minun käydä sinun käskyis tietä; sillä niihin minä halajan.","Anna minun käydä sinun käskyis tietä; sillä niihin minä halajan."],[119,36,"Kallista minun sydämeni sinun todistuksiis, ja ei ahneuden puoleen.","Kallista minun sydämeni sinun todistuksiis, ja ei ahneuden puoleen."],[119,37,"Käännä minun silmäni pois katselemasta turhuutta; vaan virvoita minua sinun tiehes.","Käännä minun silmäni pois katselemasta turhuutta; vaan virvoita minua sinun tiehes."],[119,38,"Anna palvelias lujasti sinun käskys pitää, että minä sinua pelkäisin.","Anna palvelias lujasti sinun käskys pitää, että minä sinua pelkäisin."],[119,39,"Käännä minusta pois se pilkka, jota minä pelkään; sillä sinun oikeutes ovat suloiset.","Käännä minusta pois se pilkka, jota minä pelkään; sillä sinun oikeutes ovat suloiset."],[119,40,"Katso, minä pyydän sinun käskyjäs: virvoita minua vanhurskaudellas.","Katso, minä pyydän sinun käskyjäs: virvoita minua vanhurskaudellas."],[119,41,"Herra, anna armos minulle tapahtua, autuutes sinun sanas jälkeen,","Herra, anna armos minulle tapahtua, autuutes sinun sanas jälkeen,"],[119,42,"Että minä voisin vastata minun pilkkaajiani; sillä minä luotan sinun sanaas.","Että minä voisin vastata minun pilkkaajiani; sillä minä luotan sinun sanaas."],[119,43,"Älä ota totuuden sanaa peräti pois minun suustani; sillä minä toivon sinun oikeuttas.","Älä ota totuuden sanaa peräti pois minun suustani; sillä minä toivon sinun oikeuttas."],[119,44,"Minä pidän alati sinun lakis, aina ja ijankaikkisesti,","Minä pidän alati sinun lakis, aina ja ijankaikkisesti,"],[119,45,"Ja vaellan ilossa, sillä minä etsin sinun käskyjäs,","Ja vaellan ilossa, sillä minä etsin sinun käskyjäs,"],[119,46,"Ja puhun sinun todistuksistas kuningasten edessä, ja en häpee,","Ja puhun sinun todistuksistas kuningasten edessä, ja en häpee,"],[119,47,"Ja iloitsen sinun käskyistäs, joita minä rakastan,","Ja iloitsen sinun käskyistäs, joita minä rakastan,"],[119,48,"Ja nostan käsiäni sinun käskyihis, joita minä rakastan, ja puhun sinun säädyistäs.","Ja nostan käsiäni sinun käskyihis, joita minä rakastan, ja puhun sinun säädyistäs."],[119,49,"Muista sanaas sinun palvelialles, jota sinä annoit minun toivoa.","Muista sanaas sinun palvelialles, jota sinä annoit minun toivoa."],[119,50,"Tämä on minun turvani minun vaivassani, että sinun sanas virvoittaa minun.","Tämä on minun turvani minun vaivassani, että sinun sanas virvoittaa minun."],[119,51,"Ylpiät irvistelevät minua sangen; en minä sentähden sinun laistas poikkee.","Ylpiät irvistelevät minua sangen; en minä sentähden sinun laistas poikkee."],[119,52,"Herra, kuin minä ajattelen, kuinka sinä maailman alusta toiminut olet, niin minä lohdutetaan.","Herra, kuin minä ajattelen, kuinka sinä maailman alusta toiminut olet, niin minä lohdutetaan."],[119,53,"Minä hämmästyin jumalattomain tähden, jotka sinun lakis hylkäävät.","Minä hämmästyin jumalattomain tähden, jotka sinun lakis hylkäävät."],[119,54,"Sinun oikeutes ovat minun veisuni vaellukseni huoneessa.","Sinun oikeutes ovat minun veisuni vaellukseni huoneessa."],[119,55,"Herra, minä ajattelen yöllä sinun nimeäs, ja pidän sinun lakis.","Herra, minä ajattelen yöllä sinun nimeäs, ja pidän sinun lakis."],[119,56,"Se olis minun tavarani, että minä sinun käskys pitäisin.","Se olis minun tavarani, että minä sinun käskys pitäisin."],[119,57,"Minä olen sanonut: Herra, se on minun perimiseni, että minä pidän sinun sanas.","Minä olen sanonut: Herra, se on minun perimiseni, että minä pidän sinun sanas."],[119,58,"Minä rukoilen sinun kasvois edessä täydestä sydämestä: ole minulle armollinen sinun sanas jälkeen.","Minä rukoilen sinun kasvois edessä täydestä sydämestä: ole minulle armollinen sinun sanas jälkeen."],[119,59,"Minä tutkin teitäni, ja käännän jalkani sinun todistustes puoleen.","Minä tutkin teitäni, ja käännän jalkani sinun todistustes puoleen."],[119,60,"Minä riennän, ja en viivy, sinun käskyjäs pitämään.","Minä riennän, ja en viivy, sinun käskyjäs pitämään."],[119,61,"Jumalattomain joukko raatelee minua; mutta en minä unohda sinun lakias.","Jumalattomain joukko raatelee minua; mutta en minä unohda sinun lakias."],[119,62,"Puoliyöstä minä nousen sinua kiittämään, sinun vanhurskautes oikeuden tähden.","Puoliyöstä minä nousen sinua kiittämään, sinun vanhurskautes oikeuden tähden."],[119,63,"Minä olen heidän kumppaninsa, jotka sinua pelkäävät ja sinun käskyjäs pitävät,","Minä olen heidän kumppaninsa, jotka sinua pelkäävät ja sinun käskyjäs pitävät,"],[119,64,"Herra! maa on täynnä sinun hyvyyttäs: opeta minulle sinun säätyjäs.","Herra! maa on täynnä sinun hyvyyttäs: opeta minulle sinun säätyjäs."],[119,65,"Hyvästi teit sinun palveliaas kohtaan, Herra, sinun sanas jälkeen.","Hyvästi teit sinun palveliaas kohtaan, Herra, sinun sanas jälkeen."],[119,66,"Opeta minulle hyviä tapoja ja taitoa; sillä minä uskon sinun käskys.","Opeta minulle hyviä tapoja ja taitoa; sillä minä uskon sinun käskys."],[119,67,"Ennenkuin minä nöyryytettiin, eksyin minä; mutta nyt minä pidän sinun sanas.","Ennenkuin minä nöyryytettiin, eksyin minä; mutta nyt minä pidän sinun sanas."],[119,68,"Sinä olet hyvä ja teet hyvin: opeta minulle sinun säätyjäs.","Sinä olet hyvä ja teet hyvin: opeta minulle sinun säätyjäs."],[119,69,"Ylpiät ajattelevat valheen minun päälleni; mutta minä pidän täydestä sydämestä sinun käskys.","Ylpiät ajattelevat valheen minun päälleni; mutta minä pidän täydestä sydämestä sinun käskys."],[119,70,"Heidän sydämensä on lihava niinkuin rasva; mutta minä iloitsen sinun laistas.","Heidän sydämensä on lihava niinkuin rasva; mutta minä iloitsen sinun laistas."],[119,71,"Se on minulle hyvä, ettäs minun nöyryytit, että minä sinun säätyjäs oppisin.","Se on minulle hyvä, ettäs minun nöyryytit, että minä sinun säätyjäs oppisin."],[119,72,"Sinun suus laki on minulle otollisempi kuin monta tuhatta kappaletta kultaa ja hopiaa.","Sinun suus laki on minulle otollisempi kuin monta tuhatta kappaletta kultaa ja hopiaa."],[119,73,"Sinun kätes ovat minun tehneet ja valmistaneet: anna minulle ymmärrystä oppiakseni sinun käskyjäs.","Sinun kätes ovat minun tehneet ja valmistaneet: anna minulle ymmärrystä oppiakseni sinun käskyjäs."],[119,74,"Jotka sinua pelkäävät, ne minun näkevät ja iloitsevat; sillä minä toivon sinun sanaas.","Jotka sinua pelkäävät, ne minun näkevät ja iloitsevat; sillä minä toivon sinun sanaas."],[119,75,"Herra! minä tiedän sinun tuomios vanhurskaaksi, ja sinä olet minua totuudessa nöyryyttänyt.","Herra! minä tiedän sinun tuomios vanhurskaaksi, ja sinä olet minua totuudessa nöyryyttänyt."],[119,76,"Olkoon siis sinun armos minun lohdutukseni, niinkuin sinä palvelialles luvannut olet.","Olkoon siis sinun armos minun lohdutukseni, niinkuin sinä palvelialles luvannut olet."],[119,77,"Anna minulle sinun laupiutes tapahtua, että minä eläisin; sillä sinun lakis on minun iloni.","Anna minulle sinun laupiutes tapahtua, että minä eläisin; sillä sinun lakis on minun iloni."],[119,78,"Jospa ylpiät häpiään tulisivat, jotka minua painavat alas valheellansa; mutta minä ajattelen sinun käskyjäs.","Jospa ylpiät häpiään tulisivat, jotka minua painavat alas valheellansa; mutta minä ajattelen sinun käskyjäs."],[119,79,"Tulkaan ne minun tyköni, jotka sinua pelkäävät, ja sinun todistukses tuntevat.","Tulkaan ne minun tyköni, jotka sinua pelkäävät, ja sinun todistukses tuntevat."],[119,80,"Olkoon minun sydämeni toimellinen sinun säädyissäs, etten minä häväistäisi.","Olkoon minun sydämeni toimellinen sinun säädyissäs, etten minä häväistäisi."],[119,81,"Minun sieluni ikävöitsee sinun autuuttas: minä toivon sinun sanas päälle.","Minun sieluni ikävöitsee sinun autuuttas: minä toivon sinun sanas päälle."],[119,82,"Minun silmäni hiveltyvät sinun sanas jälkeen, ja sanovat: koskas minua lohdutat?","Minun silmäni hiveltyvät sinun sanas jälkeen, ja sanovat: koskas minua lohdutat?"],[119,83,"Sillä minä olen niinkuin nahka savussa: en minä unohda sinun säätyjäs.","Sillä minä olen niinkuin nahka savussa: en minä unohda sinun säätyjäs."],[119,84,"Kuinka kauvan sinun palvelias odottaa? koskas tuomitset minun vainoojani?","Kuinka kauvan sinun palvelias odottaa? koskas tuomitset minun vainoojani?"],[119,85,"Ylpiät minulle kuoppia kaivavat, jotka ei ole sinun lakis perään.","Ylpiät minulle kuoppia kaivavat, jotka ei ole sinun lakis perään."],[119,86,"Kaikki sinun käskys ovat sula totuus: he valheella minua vaivaavat: auta minua.","Kaikki sinun käskys ovat sula totuus: he valheella minua vaivaavat: auta minua."],[119,87,"He olisivat juuri lähes minun maan päällä hukuttaneet; mutta en minä sinun käskyjäs hyljännyt.","He olisivat juuri lähes minun maan päällä hukuttaneet; mutta en minä sinun käskyjäs hyljännyt."],[119,88,"Virvoita minua sinun armoillas, että minä pitäisin sinun suus todistuksen.","Virvoita minua sinun armoillas, että minä pitäisin sinun suus todistuksen."],[119,89,"Herra! sinun sanas pysyy ijankaikkisesti taivaissa.","Herra! sinun sanas pysyy ijankaikkisesti taivaissa."],[119,90,"Sinun totuutes pysyy suvusta sukuun: sinä perustit maan, ja se pysyy.","Sinun totuutes pysyy suvusta sukuun: sinä perustit maan, ja se pysyy."],[119,91,"Ne pysyvät tähän päivään asti sinun asetukses jälkeen; sillä kaikki sinua palvelevat.","Ne pysyvät tähän päivään asti sinun asetukses jälkeen; sillä kaikki sinua palvelevat."],[119,92,"Ellei sinun lakis olisi ollut minun lohdutukseni, niin minä olisin raadollisuudessani hukkunut.","Ellei sinun lakis olisi ollut minun lohdutukseni, niin minä olisin raadollisuudessani hukkunut."],[119,93,"En minä ikänä unohda sinun käskyjäs; sillä niillä sinä minua lohdutat.","En minä ikänä unohda sinun käskyjäs; sillä niillä sinä minua lohdutat."],[119,94,"Sinun minä olen: auta minua! sillä minä etsin sinun käskyjäs.","Sinun minä olen: auta minua! sillä minä etsin sinun käskyjäs."],[119,95,"Jumalattomat minua vartioitsevat hukuttaaksensa; mutta sinun todistuksistas minä otan vaarin.","Jumalattomat minua vartioitsevat hukuttaaksensa; mutta sinun todistuksistas minä otan vaarin."],[119,96,"Kaikista kappaleista minä olen lopun nähnyt; mutta sinun käskys ovat määrättömät.","Kaikista kappaleista minä olen lopun nähnyt; mutta sinun käskys ovat määrättömät."],[119,97,"Kuinka minä rakastan sinun lakias? Joka päivä minä sitä ajattelen.","Kuinka minä rakastan sinun lakias? Joka päivä minä sitä ajattelen."],[119,98,"Sinä teit minun taitavammaksi käskyilläs kuin minun viholliseni ovat; sillä se on minun ijankaikkinen tavarani.","Sinä teit minun taitavammaksi käskyilläs kuin minun viholliseni ovat; sillä se on minun ijankaikkinen tavarani."],[119,99,"Minä olen oppineempi kuin kaikki minun opettajani; sillä sinun todistukses ovat minun ajatukseni.","Minä olen oppineempi kuin kaikki minun opettajani; sillä sinun todistukses ovat minun ajatukseni."],[119,100,"Enemmän minä ymmärrän kuin vanhemmat; sillä minä pidän sinun käskys.","Enemmän minä ymmärrän kuin vanhemmat; sillä minä pidän sinun käskys."],[119,101,"Minä estän jalkani kaikista pahoista teistä, että minä sinun sanas pitäisin.","Minä estän jalkani kaikista pahoista teistä, että minä sinun sanas pitäisin."],[119,102,"En minä poikkee sinun oikeudestas; sillä sinä opetat minua.","En minä poikkee sinun oikeudestas; sillä sinä opetat minua."],[119,103,"Sinun sanas ovat minun suulleni makiammat kuin hunaja.","Sinun sanas ovat minun suulleni makiammat kuin hunaja."],[119,104,"Sinun käskys tekevät minun ymmärtäväiseksi; sentähden minä vihaan kaikkia vääriä teitä.","Sinun käskys tekevät minun ymmärtäväiseksi; sentähden minä vihaan kaikkia vääriä teitä."],[119,105,"Sinun sanas on minun jalkaini kynttilä, ja valkeus teilläni.","Sinun sanas on minun jalkaini kynttilä, ja valkeus teilläni."],[119,106,"Minä vannon, ja sen vahvana pidän, että minä sinun vanhurskautes oikeudet pitää tahdon.","Minä vannon, ja sen vahvana pidän, että minä sinun vanhurskautes oikeudet pitää tahdon."],[119,107,"Minä olen sangen kovin vaivattu: Herra, virvoita minua sinun sanas perästä.","Minä olen sangen kovin vaivattu: Herra, virvoita minua sinun sanas perästä."],[119,108,"Olkoon sinulle, Herra, otolliset minun suuni mieluiset uhrit, ja opeta minulle sinun oikeutes.","Olkoon sinulle, Herra, otolliset minun suuni mieluiset uhrit, ja opeta minulle sinun oikeutes."],[119,109,"Minun sieluni on alati minun käsissäni, ja en unohda sinun lakias.","Minun sieluni on alati minun käsissäni, ja en unohda sinun lakias."],[119,110,"Jumalattomat virittävät minulle paulan; mutta en minä eksy sinun käskyistäs.","Jumalattomat virittävät minulle paulan; mutta en minä eksy sinun käskyistäs."],[119,111,"Sinun todistukses ovat minun ijankaikkiset perimiseni; sillä ne ovat minun sydämeni ilo.","Sinun todistukses ovat minun ijankaikkiset perimiseni; sillä ne ovat minun sydämeni ilo."],[119,112,"Minä kallistan minun sydämeni tekemään sinun säätys jälkeen, aina ja ijankaikkisesti.","Minä kallistan minun sydämeni tekemään sinun säätys jälkeen, aina ja ijankaikkisesti."],[119,113,"Minä vihaan viekkaita henkiä, ja rakastan sinun lakias.","Minä vihaan viekkaita henkiä, ja rakastan sinun lakias."],[119,114,"Sinä olet minun varjelukseni ja kilpeni: minä toivon sinun sanas päälle.","Sinä olet minun varjelukseni ja kilpeni: minä toivon sinun sanas päälle."],[119,115,"Poiketkaat minusta, te pahanilkiset; ja minä pidän minun Jumalani käskyt.","Poiketkaat minusta, te pahanilkiset; ja minä pidän minun Jumalani käskyt."],[119,116,"Tue minua sanallas, että minä eläisin, ja älä anna minun toivoni häpiään tulla.","Tue minua sanallas, että minä eläisin, ja älä anna minun toivoni häpiään tulla."],[119,117,"Vahvista minua, että minä autetuksi tulisin, niin minä halajan alati sinun säätyjäs.","Vahvista minua, että minä autetuksi tulisin, niin minä halajan alati sinun säätyjäs."],[119,118,"Sinä tallaat alas kaikki, jotka sinun säädyistäs horjuvat; sillä heidän viettelyksensä on sula valhe.","Sinä tallaat alas kaikki, jotka sinun säädyistäs horjuvat; sillä heidän viettelyksensä on sula valhe."],[119,119,"Sinä heität pois kaikki jumalattomat maan päältä niinkuin loan; sentähden minä rakastan sinun todistuksias.","Sinä heität pois kaikki jumalattomat maan päältä niinkuin loan; sentähden minä rakastan sinun todistuksias."],[119,120,"Minä pelkään sinua, niin että minun ihoni värisee, ja vapisen sinun tuomioitas.","Minä pelkään sinua, niin että minun ihoni värisee, ja vapisen sinun tuomioitas."],[119,121,"Minä teen oikeuden ja vanhurskauden: älä minua hylkää niille, jotka minulle väkivaltaa tekevät.","Minä teen oikeuden ja vanhurskauden: älä minua hylkää niille, jotka minulle väkivaltaa tekevät."],[119,122,"Vastaa palvelias edestä, ja lohduta häntä, ettei ylpiät tekisi minulle väkivaltaa.","Vastaa palvelias edestä, ja lohduta häntä, ettei ylpiät tekisi minulle väkivaltaa."],[119,123,"Minun silmäni hiveltyvät sinun autuutes perään, ja sinun vanhurskautes sanan jälkeen.","Minun silmäni hiveltyvät sinun autuutes perään, ja sinun vanhurskautes sanan jälkeen."],[119,124,"Tee palvelias kanssa sinun armos jälkeen, ja opeta minulle sinun säätyjäs.","Tee palvelias kanssa sinun armos jälkeen, ja opeta minulle sinun säätyjäs."],[119,125,"Sinun palvelias minä olen: anna minulle ymmärrystä, että minä tuntisin sinun todistukses.","Sinun palvelias minä olen: anna minulle ymmärrystä, että minä tuntisin sinun todistukses."],[119,126,"Jopa aika on, että Herra siihen jotakin tekis: he ovat sinun lakis särkeneet.","Jopa aika on, että Herra siihen jotakin tekis: he ovat sinun lakis särkeneet."],[119,127,"Sentähden minä rakastan sinun käskyjäs, enempi kuin kultaa ja parasta kultaa.","Sentähden minä rakastan sinun käskyjäs, enempi kuin kultaa ja parasta kultaa."],[119,128,"Sentähden minä pidän visusti kaikkia sinun käskyjäs: minä vihaan kaikkia vääriä teitä.","Sentähden minä pidän visusti kaikkia sinun käskyjäs: minä vihaan kaikkia vääriä teitä."],[119,129,"Ihmeelliset ovat sinun todistukses; sentähden minun sieluni ne pitää.","Ihmeelliset ovat sinun todistukses; sentähden minun sieluni ne pitää."],[119,130,"Kuin sinun sanas julistetaan, niin se valistaa ja antaa yksinkertaisille ymmärryksen.","Kuin sinun sanas julistetaan, niin se valistaa ja antaa yksinkertaisille ymmärryksen."],[119,131,"Minä avaan suuni ja huokaan; sillä minä halajan sinun käskys.","Minä avaan suuni ja huokaan; sillä minä halajan sinun käskys."],[119,132,"Käännä sinuas minun puoleeni, ja ole minulle armollinen, niinkuin sinä olet niille tottunut tekemään, jotka sinun nimeäs rakastavat.","Käännä sinuas minun puoleeni, ja ole minulle armollinen, niinkuin sinä olet niille tottunut tekemään, jotka sinun nimeäs rakastavat."],[119,133,"Vahvista minun käymiseni sinun sanassas, ja älä anna väkivallan minua vallita.","Vahvista minun käymiseni sinun sanassas, ja älä anna väkivallan minua vallita."],[119,134,"Lunasta minua ihmisten väkivallasta, niin minä pidän sinun käskys.","Lunasta minua ihmisten väkivallasta, niin minä pidän sinun käskys."],[119,135,"Valista sinun kasvos palvelias päälle, ja opeta minulle sinun säätys.","Valista sinun kasvos palvelias päälle, ja opeta minulle sinun säätys."],[119,136,"Minun silmäni vettä vuotavat, niinkuin virta, ettei sinun käskyjäs pidetä.","Minun silmäni vettä vuotavat, niinkuin virta, ettei sinun käskyjäs pidetä."],[119,137,"Herra! sinä olet vanhurskas ja sinun tuomios ovat oikiat.","Herra! sinä olet vanhurskas ja sinun tuomios ovat oikiat."],[119,138,"Sinä olet vanhurskautes todistukset ja totuuden visusti käskenyt.","Sinä olet vanhurskautes todistukset ja totuuden visusti käskenyt."],[119,139,"Minä olen lähes surmakseni kiivannut, että minun viholliseni ovat sinun sanas unohtaneet.","Minä olen lähes surmakseni kiivannut, että minun viholliseni ovat sinun sanas unohtaneet."],[119,140,"Sinun puhees on sangen koeteltu, ja sinun palvelias sen rakkaana pitää.","Sinun puhees on sangen koeteltu, ja sinun palvelias sen rakkaana pitää."],[119,141,"Minä olen halpa ja ylönkatsottu, mutta en minä unohda sinun käskyjäs.","Minä olen halpa ja ylönkatsottu, mutta en minä unohda sinun käskyjäs."],[119,142,"Sinun vanhurskautes on ijankaikkinen vanhurskaus, ja sinun lakis on totuus.","Sinun vanhurskautes on ijankaikkinen vanhurskaus, ja sinun lakis on totuus."],[119,143,"Ahdistus ja tuska ovat minun saavuttaneet; mutta minä iloitsen sinun käskyistäs.","Ahdistus ja tuska ovat minun saavuttaneet; mutta minä iloitsen sinun käskyistäs."],[119,144,"Sinun todistustes vanhurskaus pysyy ijankaikkisesti: anna minulle ymmärrys, niin minä elän.","Sinun todistustes vanhurskaus pysyy ijankaikkisesti: anna minulle ymmärrys, niin minä elän."],[119,145,"Minä huudan kaikesta sydämestäni: kuule, Herra, minua, että minä sinun säätys pitäisin.","Minä huudan kaikesta sydämestäni: kuule, Herra, minua, että minä sinun säätys pitäisin."],[119,146,"Sinua minä huudan, auta minua, että minä sinun todistukses pitäisin.","Sinua minä huudan, auta minua, että minä sinun todistukses pitäisin."],[119,147,"Varhain minä ennätän, ja huudan: sinun sanas päälle minä toivon.","Varhain minä ennätän, ja huudan: sinun sanas päälle minä toivon."],[119,148,"Varhain minä herään, tutkistelemaan sinun sanojas.","Varhain minä herään, tutkistelemaan sinun sanojas."],[119,149,"Kuule minun ääneni sinun armos jälkeen: Herra, virvoita minua sinun oikeutes jälkeen.","Kuule minun ääneni sinun armos jälkeen: Herra, virvoita minua sinun oikeutes jälkeen."],[119,150,"Pahanilkiset vainoojat karkaavat minun päälleni, ja ovat kaukana sinun laistas.","Pahanilkiset vainoojat karkaavat minun päälleni, ja ovat kaukana sinun laistas."],[119,151,"Herra, sinä olet läsnä, ja sinun käskys ovat sula totuus.","Herra, sinä olet läsnä, ja sinun käskys ovat sula totuus."],[119,152,"Mutta minä sen aikaa tiesin, että sinä olet todistukses ijankaikkisesti perustanut.","Mutta minä sen aikaa tiesin, että sinä olet todistukses ijankaikkisesti perustanut."],[119,153,"Katso minun raadollisuuttani, ja pelasta minua; sillä enpä minä unohda sinun lakias.","Katso minun raadollisuuttani, ja pelasta minua; sillä enpä minä unohda sinun lakias."],[119,154,"Toimita minun asiani ja päästä minua: virvoita minua sinun sanas kautta.","Toimita minun asiani ja päästä minua: virvoita minua sinun sanas kautta."],[119,155,"Autuus on kaukana jumalattomista, sillä ei he tottele säätyjäs.","Autuus on kaukana jumalattomista, sillä ei he tottele säätyjäs."],[119,156,"Herra, sinun laupiutes on suuri: virvoita minua sinun oikeutes jälkeen.","Herra, sinun laupiutes on suuri: virvoita minua sinun oikeutes jälkeen."],[119,157,"Minun vainoojaani ja vihollistani on monta; mutta en minä poikkee sinun todistuksistas.","Minun vainoojaani ja vihollistani on monta; mutta en minä poikkee sinun todistuksistas."],[119,158,"Minä näen ylönkatsojat, ja siihen suutun, ettei he sinun sanaas pidä.","Minä näen ylönkatsojat, ja siihen suutun, ettei he sinun sanaas pidä."],[119,159,"Katso, minä rakastan sinun käskyjäs: Herra, virvoita minua sinun armos jälkeen.","Katso, minä rakastan sinun käskyjäs: Herra, virvoita minua sinun armos jälkeen."],[119,160,"Sinun sanas on alusta totuus ollut: kaikki sinun vanhurskautes oikeudet pysyvät ijankaikkisesti.","Sinun sanas on alusta totuus ollut: kaikki sinun vanhurskautes oikeudet pysyvät ijankaikkisesti."],[119,161,"Päämiehet vainoovat minua ilman syytä; mutta minun sydämeni pelkää sinun sanojas.","Päämiehet vainoovat minua ilman syytä; mutta minun sydämeni pelkää sinun sanojas."],[119,162,"Minä iloitsen sinun puheestas, niinkuin se joka suuren saaliin löytänyt on.","Minä iloitsen sinun puheestas, niinkuin se joka suuren saaliin löytänyt on."],[119,163,"Valhetta minä vihaan ja kauhistun; mutta sinun lakias minä rakastan.","Valhetta minä vihaan ja kauhistun; mutta sinun lakias minä rakastan."],[119,164,"Seitsemästi päivässä minä kiitän sinua sinun vanhurskautes oikeuden tähden.","Seitsemästi päivässä minä kiitän sinua sinun vanhurskautes oikeuden tähden."],[119,165,"Suuri rauha on niillä, jotka sinun lakias rakastavat, ja ei he itsiänsä loukkaa.","Suuri rauha on niillä, jotka sinun lakias rakastavat, ja ei he itsiänsä loukkaa."],[119,166,"Herra! minä odotan sinun autuuttas, ja teen sinun käskys.","Herra! minä odotan sinun autuuttas, ja teen sinun käskys."],[119,167,"Minun sieluni pitää sinun todistukses, ja minä rakastan niitä sangen suuresti.","Minun sieluni pitää sinun todistukses, ja minä rakastan niitä sangen suuresti."],[119,168,"Minä pidän sinun käskys ja todistukses; sillä kaikki minun tieni ovat edessäs.","Minä pidän sinun käskys ja todistukses; sillä kaikki minun tieni ovat edessäs."],[119,169,"Herra! anna minun huutoni tulla sinun etees: anna minulle ymmärrystä sinun sanas jälkeen.","Herra! anna minun huutoni tulla sinun etees: anna minulle ymmärrystä sinun sanas jälkeen."],[119,170,"Anna minun rukoukseni tulla sinun etees: pelasta minua sinun sanas jälkeen.","Anna minun rukoukseni tulla sinun etees: pelasta minua sinun sanas jälkeen."],[119,171,"Minun huuleni kiittävät, koskas minulle opetat sinun säätys.","Minun huuleni kiittävät, koskas minulle opetat sinun säätys."],[119,172,"Minun kieleni puhuu sinun sanastas; sillä kaikki sinun käskys ovat vanhurskaat.","Minun kieleni puhuu sinun sanastas; sillä kaikki sinun käskys ovat vanhurskaat."],[119,173,"Olkoon sinun kätes minulle avullinen; sillä minä olen valinnut sinun käskys.","Olkoon sinun kätes minulle avullinen; sillä minä olen valinnut sinun käskys."],[119,174,"Herra, minä ikävöitsen sinun autuuttas, ja halajan sinun lakias.","Herra, minä ikävöitsen sinun autuuttas, ja halajan sinun lakias."],[119,175,"Anna minun sieluni elää, että hän sinua kiittäis, ja sinun oikeutes auttakoon minua!","Anna minun sieluni elää, että hän sinua kiittäis, ja sinun oikeutes auttakoon minua!"],[119,176,"Minä olen eksyvä niinkuin kadotettu lammas, etsi sinun palveliaas; sillä en minä unohda sinun käskyjäs.","Minä olen eksyvä niinkuin kadotettu lammas, etsi sinun palveliaas; sillä en minä unohda sinun käskyjäs."],[120,1,"Veisu korkeimmassa Kuorissa. Minä huudan Herraa minun tuskissani, ja hän kuulee minun rukoukseni.","Veisu korkeimmassa Kuorissa. Minä huudan Herraa minun tuskissani, ja hän kuulee minun rukoukseni."],[120,2,"Herra, pelasta minun sieluni valhettelevista suista ja vääristä kielistä?","Herra, pelasta minun sieluni valhettelevista suista ja vääristä kielistä?"],[120,3,"Mitä väärä kieli taitaa sinulle tehdä? ja mitä se taitaa toimittaa?","Mitä väärä kieli taitaa sinulle tehdä? ja mitä se taitaa toimittaa?"],[120,4,"Se on niinkuin väkevän terävät nuolet, niinkuin tuli katajissa.","Se on niinkuin väkevän terävät nuolet, niinkuin tuli katajissa."],[120,5,"Voi minua, että minä olen muukalainen Mesekin seassa! minun täytyy asua Kedarin majain seassa.","Voi minua, että minä olen muukalainen Mesekin seassa! minun täytyy asua Kedarin majain seassa."],[120,6,"Se tulee minun sielulleni ikäväksi, asua niiden tykönä, jotka rauhaa vihaavat.","Se tulee minun sielulleni ikäväksi, asua niiden tykönä, jotka rauhaa vihaavat."],[120,7,"Minä pidän rauhan, mutta kuin minä puhun, niin he sodan nostavat.","Minä pidän rauhan, mutta kuin minä puhun, niin he sodan nostavat."],[121,1,"Veisu korkeimmassa Kuorissa. Minä nostan silmäni mäkiin päin, joista minulle apu tulee.","Veisu korkeimmassa Kuorissa. Minä nostan silmäni mäkiin päin, joista minulle apu tulee."],[121,2,"Minun apuni tulee Herralta, joka taivaan ja maan tehnyt on.","Minun apuni tulee Herralta, joka taivaan ja maan tehnyt on."],[121,3,"Ei hän salli jalkas horjua; eikä se torku, joka sinua kätkee.","Ei hän salli jalkas horjua; eikä se torku, joka sinua kätkee."],[121,4,"Katso, joka Israelia varjelee, ei se torku eli makaa.","Katso, joka Israelia varjelee, ei se torku eli makaa."],[121,5,"Herra kätkeköön sinua: Herra on sinun varjos, sinun oikialla kädelläs,","Herra kätkeköön sinua: Herra on sinun varjos, sinun oikialla kädelläs,"],[121,6,"Ettei aurinko sinua polttaisi päivällä, eikä kuu yöllä.","Ettei aurinko sinua polttaisi päivällä, eikä kuu yöllä."],[121,7,"Herra kätkeköön sinun kaikesta pahasta: hän kätkeköön sinun sielus!","Herra kätkeköön sinun kaikesta pahasta: hän kätkeköön sinun sielus!"],[121,8,"Herra kätkeköön sinun uloskäymises ja sisällekäymises, hamasta nyt ja ijankaikkiseen!","Herra kätkeköön sinun uloskäymises ja sisällekäymises, hamasta nyt ja ijankaikkiseen!"],[122,1,"Davidin veisu korkeimmassa Kuorissa. Minä iloitsen niistä, jotka minulle sanovat: että me menemme Herran huoneeseen,","Davidin veisu korkeimmassa Kuorissa. Minä iloitsen niistä, jotka minulle sanovat: että me menemme Herran huoneeseen,"],[122,2,"Ja että meidän jalkamme pitää seisoman sinun porteissas, Jerusalem.","Ja että meidän jalkamme pitää seisoman sinun porteissas, Jerusalem."],[122,3,"Jerusalem on rakennettu kaupungiksi, johon on tuleminen kokoon,","Jerusalem on rakennettu kaupungiksi, johon on tuleminen kokoon,"],[122,4,"Että sukukunnat astuisivat sinne ylös, Herran sukukunnat, Israelille todistukseksi, kiittämään Herran nimeä.","Että sukukunnat astuisivat sinne ylös, Herran sukukunnat, Israelille todistukseksi, kiittämään Herran nimeä."],[122,5,"Sillä siellä ovat istuimet rakennetut tuomittaa, Davidin huoneen istuimet.","Sillä siellä ovat istuimet rakennetut tuomittaa, Davidin huoneen istuimet."],[122,6,"Toivottakaat Jerusalemille rauhaa: he menestyköön, jotka sinua rakastavat!","Toivottakaat Jerusalemille rauhaa: he menestyköön, jotka sinua rakastavat!"],[122,7,"Rauha olkoon sinun muureis sisällä, ja onni sinun huoneissas!","Rauha olkoon sinun muureis sisällä, ja onni sinun huoneissas!"],[122,8,"Minun veljieni ja ystäväini tähden minä toivotan nyt sinulle rauhaa!","Minun veljieni ja ystäväini tähden minä toivotan nyt sinulle rauhaa!"],[122,9,"Herran meidän Jumalamme huoneen tähden etsin minä sinun parastas.","Herran meidän Jumalamme huoneen tähden etsin minä sinun parastas."],[123,1,"Veisu korkeimmassa Kuorissa. Minä nostan silmäni sinun tykös, joka asut taivaissa.","Veisu korkeimmassa Kuorissa. Minä nostan silmäni sinun tykös, joka asut taivaissa."],[123,2,"Katso, niinkuin palveliain silmät katsovat isäntänsä käsiin, niinkuin piikain silmät katsovat emäntäinsä käsiin, niin meidänkin silmämme katsovat Herraa meidän Jumalaamme, siihenasti että hän meitä armahtaa.","Katso, niinkuin palveliain silmät katsovat isäntänsä käsiin, niinkuin piikain silmät katsovat emäntäinsä käsiin, niin meidänkin silmämme katsovat Herraa meidän Jumalaamme, siihenasti että hän meitä armahtaa."],[123,3,"Ole meille armollinen, Herra, ole meille armollinen! sillä me olemme sangen täytetyt ylönkatseesta;","Ole meille armollinen, Herra, ole meille armollinen! sillä me olemme sangen täytetyt ylönkatseesta;"],[123,4,"Sangen täynnä on meidän sielumme rikasten pilkkaa ja ylpeiden ylönkatsetta.","Sangen täynnä on meidän sielumme rikasten pilkkaa ja ylpeiden ylönkatsetta."],[124,1,"Davidin veisu korkeimmassa Kuorissa. Ellei Herra olisi meidän kanssamme, niin sanokaan Israel:","Davidin veisu korkeimmassa Kuorissa. Ellei Herra olisi meidän kanssamme, niin sanokaan Israel:"],[124,2,"Ellei Herra olisi meidän kanssamme, koska ihmiset karkaavat meitä vastaan,","Ellei Herra olisi meidän kanssamme, koska ihmiset karkaavat meitä vastaan,"],[124,3,"Niin he nielisivät meidät elävältä, kuin heidän vihansa julmistuu meidän päällemme;","Niin he nielisivät meidät elävältä, kuin heidän vihansa julmistuu meidän päällemme;"],[124,4,"Niin vesi meitä upottais: kosket kävisivät sieluimme ylitse:","Niin vesi meitä upottais: kosket kävisivät sieluimme ylitse:"],[124,5,"Niin ylpiät veden aallot kävisivät sielumme ylitse.","Niin ylpiät veden aallot kävisivät sielumme ylitse."],[124,6,"Kiitetty olkoon Herra, joka ei meitä anna raatelukseksi heidän hampaillensa!","Kiitetty olkoon Herra, joka ei meitä anna raatelukseksi heidän hampaillensa!"],[124,7,"Meidän sielumme pääsi niinkuin lintu lintumiehen paulasta. Paula on särjetty, ja me olemme päästetyt.","Meidän sielumme pääsi niinkuin lintu lintumiehen paulasta. Paula on särjetty, ja me olemme päästetyt."],[124,8,"Meidän apumme on Herran nimessä, joka taivaan ja maan tehnyt on.","Meidän apumme on Herran nimessä, joka taivaan ja maan tehnyt on."],[125,1,"Veisu korkeimmassa Kuorissa. Jotka Herran päälle uskaltavat, ei he lankee, vaan pysyvät ijankaikkisesti niinkuin Zionin vuori.","Veisu korkeimmassa Kuorissa. Jotka Herran päälle uskaltavat, ei he lankee, vaan pysyvät ijankaikkisesti niinkuin Zionin vuori."],[125,2,"Jerusalemin ympäri ovat vuoret, ja Herra on kansansa ympärillä, hamasta nyt ja ijankaikkiseen.","Jerusalemin ympäri ovat vuoret, ja Herra on kansansa ympärillä, hamasta nyt ja ijankaikkiseen."],[125,3,"Sillä jumalattomain valtikka ei pidä pysymän vanhurskasten joukon päällä, ettei vanhurskaat ojentaisi käsiänsä vääryyteen.","Sillä jumalattomain valtikka ei pidä pysymän vanhurskasten joukon päällä, ettei vanhurskaat ojentaisi käsiänsä vääryyteen."],[125,4,"Herra, tee hyvästi hyville ja hurskaille sydämille.","Herra, tee hyvästi hyville ja hurskaille sydämille."],[125,5,"Mutta jotka poikkeevat vääriin teihinsä, niitä Herra ajaa pois pahantekiäin kanssa; mutta rauha olkoon Israelille!","Mutta jotka poikkeevat vääriin teihinsä, niitä Herra ajaa pois pahantekiäin kanssa; mutta rauha olkoon Israelille!"],[126,1,"Veisu korkeimmassa Kuorissa. Koska Herra päästää Zionin vangit, niin me olemme niinkuin unta näkeväiset.","Veisu korkeimmassa Kuorissa. Koska Herra päästää Zionin vangit, niin me olemme niinkuin unta näkeväiset."],[126,2,"Silloin meidän suumme naurulla täytetään, ja kielemme on täynnä riemua; silloin sanotaan pakanoissa: Herra on suuria heidän kohtaansa tehnyt.","Silloin meidän suumme naurulla täytetään, ja kielemme on täynnä riemua; silloin sanotaan pakanoissa: Herra on suuria heidän kohtaansa tehnyt."],[126,3,"Herra on suuria tehnyt meidän kohtaamme: siitä me olemme iloiset.","Herra on suuria tehnyt meidän kohtaamme: siitä me olemme iloiset."],[126,4,"Herra! käännä meidän vankiutemme, niinkuin virrat etelässä.","Herra! käännä meidän vankiutemme, niinkuin virrat etelässä."],[126,5,"Jotka kyyneleillä kylvävät, ne ilolla niittävät.","Jotka kyyneleillä kylvävät, ne ilolla niittävät."],[126,6,"He menevät matkaan ja itkevät, ja vievät ulos kalliin siemenen, ja tulevat riemulla, ja tuovat lyhteensä.","He menevät matkaan ja itkevät, ja vievät ulos kalliin siemenen, ja tulevat riemulla, ja tuovat lyhteensä."],[127,1,"Salomon veisu korkeimmassa Kuorissa. Jos ei Herra huonetta rakenna, niin hukkaan työtä tekevät, jotka sitä rakentavat: jos ei Herra kaupunkia varjele, niin vartiat hukkaan valvovat.","Salomon veisu korkeimmassa Kuorissa. Jos ei Herra huonetta rakenna, niin hukkaan työtä tekevät, jotka sitä rakentavat: jos ei Herra kaupunkia varjele, niin vartiat hukkaan valvovat."],[127,2,"Se on turha, että te varhain nousette ja hiljain maata menette, ja syötte leipänne surulla; sillä hän antaa ystävillensä heidän maatessansa.","Se on turha, että te varhain nousette ja hiljain maata menette, ja syötte leipänne surulla; sillä hän antaa ystävillensä heidän maatessansa."],[127,3,"Katso, lapset ovat Herran lahja, ja kohdun hedelmä on anto.","Katso, lapset ovat Herran lahja, ja kohdun hedelmä on anto."],[127,4,"Kuin nuolet väkevän kädessä, niin ovat nuorukaiset.","Kuin nuolet väkevän kädessä, niin ovat nuorukaiset."],[127,5,"Autuas on se, jonka viini on niitä täynnänsä: ei ne häväistä, kuin heillä vihollistensa kanssa portissa tekemistä on.","Autuas on se, jonka viini on niitä täynnänsä: ei ne häväistä, kuin heillä vihollistensa kanssa portissa tekemistä on."],[128,1,"Veisu korkeimmassa Kuorissa. Autuas on jokainen, joka Herraa pelkää, ja hänen tiellänsä vaeltaa.","Veisu korkeimmassa Kuorissa. Autuas on jokainen, joka Herraa pelkää, ja hänen tiellänsä vaeltaa."],[128,2,"Sillä sinä elätät itses kättes töistä: autuas sinä olet, ja sinulle käy hyvästi.","Sillä sinä elätät itses kättes töistä: autuas sinä olet, ja sinulle käy hyvästi."],[128,3,"Sinun emäntäs on niinkuin hedelmällinen viinapuu huonees sisimmäisissä loukkaissa: sinun lapses niinkuin öljypuun vesat, pöytäs ympärillä.","Sinun emäntäs on niinkuin hedelmällinen viinapuu huonees sisimmäisissä loukkaissa: sinun lapses niinkuin öljypuun vesat, pöytäs ympärillä."],[128,4,"Katsos, näin se mies siunataan, joka Herraa pelkää.","Katsos, näin se mies siunataan, joka Herraa pelkää."],[128,5,"Herra siunaa sinua Zionista, ettäs näet Jerusalemin onnen kaikkena elinaikanas,","Herra siunaa sinua Zionista, ettäs näet Jerusalemin onnen kaikkena elinaikanas,"],[128,6,"Ja saat nähdä lastes lapset: rauha olkoon Israelille!","Ja saat nähdä lastes lapset: rauha olkoon Israelille!"],[129,1,"Veisu korkeimmassa Kuorissa. He ovat usein minua ahdistaneet, hamasta nuoruudestani, sanokaan nyt Israel;","Veisu korkeimmassa Kuorissa. He ovat usein minua ahdistaneet, hamasta nuoruudestani, sanokaan nyt Israel;"],[129,2,"He ovat usein minua ahdistaneet, hamasta nuoruudestani; mutta ei he minua voittaneet.","He ovat usein minua ahdistaneet, hamasta nuoruudestani; mutta ei he minua voittaneet."],[129,3,"Kyntäjät ovat minun selkäni päällä kyntäneet, ja vakonsa pitkäksi vetäneet.","Kyntäjät ovat minun selkäni päällä kyntäneet, ja vakonsa pitkäksi vetäneet."],[129,4,"Herra, joka vanhurskas on, on jumalattomain köydet katkonut.","Herra, joka vanhurskas on, on jumalattomain köydet katkonut."],[129,5,"Tulkoon häpiään ja kääntyköön takaperin kaikki, jotka Zionia vihaavat.","Tulkoon häpiään ja kääntyköön takaperin kaikki, jotka Zionia vihaavat."],[129,6,"Olkoon niinkuin ruoho kattojen päällä, joka kuivettuu ennen kuin se reväistään ylös,","Olkoon niinkuin ruoho kattojen päällä, joka kuivettuu ennen kuin se reväistään ylös,"],[129,7,"Joista niittäjä ei kättänsä täytä, eikä lyhteensitoja syliänsä;","Joista niittäjä ei kättänsä täytä, eikä lyhteensitoja syliänsä;"],[129,8,"Eikä yksikään ohitsekäypä sano: olkoon Herran siunaus teidän päällänne: me siunaamme teitä Herran nimeen.","Eikä yksikään ohitsekäypä sano: olkoon Herran siunaus teidän päällänne: me siunaamme teitä Herran nimeen."],[130,1,"Veisu korkeimmassa Kuorissa. Syvyydessä minä huudan sinua, Herra.","Veisu korkeimmassa Kuorissa. Syvyydessä minä huudan sinua, Herra."],[130,2,"Herra, kuule minun ääneni: vaarinottakaan korvas rukousteni äänestä.","Herra, kuule minun ääneni: vaarinottakaan korvas rukousteni äänestä."],[130,3,"Jos sinä, Herra, soimaat syntiä: Herra, kuka siis pysyy?","Jos sinä, Herra, soimaat syntiä: Herra, kuka siis pysyy?"],[130,4,"Sillä sinun tykönäs on anteeksi antamus, että sinua peljättäisiin.","Sillä sinun tykönäs on anteeksi antamus, että sinua peljättäisiin."],[130,5,"Minä odotan Herraa: sieluni odottaa, ja minä toivon hänen sanansa päälle.","Minä odotan Herraa: sieluni odottaa, ja minä toivon hänen sanansa päälle."],[130,6,"Sieluni vartioitsee Herraa huomenvartiosta toiseen huomenvartioon asti.","Sieluni vartioitsee Herraa huomenvartiosta toiseen huomenvartioon asti."],[130,7,"Israel toivokaan Herran päälle; sillä Herralla on armo, ja runsas lunastus hänellä.","Israel toivokaan Herran päälle; sillä Herralla on armo, ja runsas lunastus hänellä."],[130,8,"Ja hän lunastaa Israelin kaikista synneistänsä.","Ja hän lunastaa Israelin kaikista synneistänsä."],[131,1,"Davidin veisu korkeimmassa Kuorissa. Herra! ei minun sydämeni ole paisunut, eikä minun silmäni ole ylpiät; enkä minä vaella suurissa asioissa, jotka minulle työläät ovat.","Davidin veisu korkeimmassa Kuorissa. Herra! ei minun sydämeni ole paisunut, eikä minun silmäni ole ylpiät; enkä minä vaella suurissa asioissa, jotka minulle työläät ovat."],[131,2,"Kuin en minä sieluani asettanut ja vaikittanut, niin minun sieluni tuli vieroitetuksi, niinkuin lapsi äidistänsä vieroitetaan.","Kuin en minä sieluani asettanut ja vaikittanut, niin minun sieluni tuli vieroitetuksi, niinkuin lapsi äidistänsä vieroitetaan."],[131,3,"Israel toivokaan Herran päälle, hamasta nyt ja ijankaikkiseen.","Israel toivokaan Herran päälle, hamasta nyt ja ijankaikkiseen."],[132,1,"Veisu korkeimmassa Kuorissa. Muista, Herra, Davidia, ja kaikkia hänen vaivojansa,","Veisu korkeimmassa Kuorissa. Muista, Herra, Davidia, ja kaikkia hänen vaivojansa,"],[132,2,"Joka Herralle vannoi, ja lupasi lupauksen Jakobin väkevälle:","Joka Herralle vannoi, ja lupasi lupauksen Jakobin väkevälle:"],[132,3,"En mene huoneeni majaan, enkä vuoteeseeni pane maata;","En mene huoneeni majaan, enkä vuoteeseeni pane maata;"],[132,4,"En anna silmäini unta saada, enkä silmälautaini torkkua,","En anna silmäini unta saada, enkä silmälautaini torkkua,"],[132,5,"Siihenasti kuin minä löydän sian Herralle, Jakobin väkevän asumiseksi.","Siihenasti kuin minä löydän sian Herralle, Jakobin väkevän asumiseksi."],[132,6,"Katso, me kuulimme hänestä Ephratassa: me olemme sen löytäneet metsän kedoilla.","Katso, me kuulimme hänestä Ephratassa: me olemme sen löytäneet metsän kedoilla."],[132,7,"Me tahdomme hänen asuinsioihinsa mennä, ja kumartaa hänen jalkainsa astinlaudan edessä.","Me tahdomme hänen asuinsioihinsa mennä, ja kumartaa hänen jalkainsa astinlaudan edessä."],[132,8,"Nouse, Herra, sinun lepoos, sinä ja sinun väkevyytes arkki.","Nouse, Herra, sinun lepoos, sinä ja sinun väkevyytes arkki."],[132,9,"Anna pappis pukea heitänsä vanhurskaudella ja sinun pyhäs riemuitkaan.","Anna pappis pukea heitänsä vanhurskaudella ja sinun pyhäs riemuitkaan."],[132,10,"Älä käännä pois voideltus kasvoja, sinun palvelias Davidin tähden.","Älä käännä pois voideltus kasvoja, sinun palvelias Davidin tähden."],[132,11,"Herra on vannonut Davidille totisen valan, ja ei hän siitä vilpistele: sinun ruumiis hedelmästä minä istutan istuimelles.","Herra on vannonut Davidille totisen valan, ja ei hän siitä vilpistele: sinun ruumiis hedelmästä minä istutan istuimelles."],[132,12,"Jos sinun lapses minun liittoni pitävät, ja minun todistukseni, jotka minä heille opetan, niin heidän lapsensa myös pitää sinun istuimellas istuman ijankaikkisesti.","Jos sinun lapses minun liittoni pitävät, ja minun todistukseni, jotka minä heille opetan, niin heidän lapsensa myös pitää sinun istuimellas istuman ijankaikkisesti."],[132,13,"Sillä Herra on Zionin valinnut, ja tahtoo sitä asuinsiaksensa.","Sillä Herra on Zionin valinnut, ja tahtoo sitä asuinsiaksensa."],[132,14,"Tämä on minun leponi ijankaikkisesti: tässä minä tahdon asua; sillä se minulle kelpaa.","Tämä on minun leponi ijankaikkisesti: tässä minä tahdon asua; sillä se minulle kelpaa."],[132,15,"Minä hyvästi siunaan hänen elatuksensa, ja hänen köyhillensä kyllä annan leipää.","Minä hyvästi siunaan hänen elatuksensa, ja hänen köyhillensä kyllä annan leipää."],[132,16,"Hänen pappinsa minä puetan autuudella; ja hänen pyhänsä pitää ilolla riemuitseman.","Hänen pappinsa minä puetan autuudella; ja hänen pyhänsä pitää ilolla riemuitseman."],[132,17,"Siellä minä annan puhjeta Davidin sarven: minä valmistan kynttilän voidellulleni.","Siellä minä annan puhjeta Davidin sarven: minä valmistan kynttilän voidellulleni."],[132,18,"Hänen vihollisensa minä häpiällä puetan; mutta hänen päällänsä pitää hänen kruununsa kukoistaman.","Hänen vihollisensa minä häpiällä puetan; mutta hänen päällänsä pitää hänen kruununsa kukoistaman."],[133,1,"Davidin veisu korkeimmassa Kuorissa. Katsos kuinka hyvä ja kuinka suloinen se on, että veljekset sovinnossa keskenänsä asuvat.","Davidin veisu korkeimmassa Kuorissa. Katsos kuinka hyvä ja kuinka suloinen se on, että veljekset sovinnossa keskenänsä asuvat."],[133,2,"Niinkuin kallis voide, joka Aaronin päästä vuotaa koko hänen partaansa, joka vuotaa hänen vaatettensa liepeesen;","Niinkuin kallis voide, joka Aaronin päästä vuotaa koko hänen partaansa, joka vuotaa hänen vaatettensa liepeesen;"],[133,3,"Niinkuin Hermonin kaste, joka tulee alas Zionin vuorelle; sillä siellä lupaa Herra siunauksen ja elämän alati ja ijankaikkisesti.","Niinkuin Hermonin kaste, joka tulee alas Zionin vuorelle; sillä siellä lupaa Herra siunauksen ja elämän alati ja ijankaikkisesti."],[134,1,"Veisu korkeimmassa Kuorissa. Katso, kiittäkäät Herraa, kaikki Herran palveliat, jotka yöllä seisotte Herran huoneessa!","Veisu korkeimmassa Kuorissa. Katso, kiittäkäät Herraa, kaikki Herran palveliat, jotka yöllä seisotte Herran huoneessa!"],[134,2,"Nostakaat kätenne pyhään päin, ja kiittäkäät Herraa.","Nostakaat kätenne pyhään päin, ja kiittäkäät Herraa."],[134,3,"Herra siunatkoon sinua Zionista, joka taivaan ja maan tehnyt on.","Herra siunatkoon sinua Zionista, joka taivaan ja maan tehnyt on."],[135,1,"Halleluja! Ylistäkäät Herran nimeä, kiittäkäät, Herran palveliat.","Halleluja! Ylistäkäät Herran nimeä, kiittäkäät, Herran palveliat."],[135,2,"Te kuin seisotte Herran huoneessa, meidän Jumalamme esihuoneissa.","Te kuin seisotte Herran huoneessa, meidän Jumalamme esihuoneissa."],[135,3,"Kiittäkäät Herraa, sillä Herra on hyvä, ja veisatkaat kiitosta hänen nimellensä; sillä se on suloinen.","Kiittäkäät Herraa, sillä Herra on hyvä, ja veisatkaat kiitosta hänen nimellensä; sillä se on suloinen."],[135,4,"Sillä Herra on itsellensä valinnut Jakobin, Israelin omaksensa.","Sillä Herra on itsellensä valinnut Jakobin, Israelin omaksensa."],[135,5,"Minä tiedän, että Herra on suuri, ja meidän Jumalamme kaikkein jumalain ylitse.","Minä tiedän, että Herra on suuri, ja meidän Jumalamme kaikkein jumalain ylitse."],[135,6,"Kaikki, mitä Herra tahtoo, niin hän tekee, taivaassa ja maassa, meressä ja kaikessa syvyydessä;","Kaikki, mitä Herra tahtoo, niin hän tekee, taivaassa ja maassa, meressä ja kaikessa syvyydessä;"],[135,7,"Joka pilvet nostaa maan ääristä, joka pitkäisen leimauksesta sateen saattaa, ja tuulen tuo ulos tavaroistansa;","Joka pilvet nostaa maan ääristä, joka pitkäisen leimauksesta sateen saattaa, ja tuulen tuo ulos tavaroistansa;"],[135,8,"Joka esikoiset Egyptissä löi, sekä ihmisistä että karjasta,","Joka esikoiset Egyptissä löi, sekä ihmisistä että karjasta,"],[135,9,"Ja antoi merkkinsä ja ihmeensä tulla Egyptin keskelle, Pharaolle ja kaikille hänen palvelioillensa;","Ja antoi merkkinsä ja ihmeensä tulla Egyptin keskelle, Pharaolle ja kaikille hänen palvelioillensa;"],[135,10,"Joka monet pakanat löi, ja tappoi väkevät kuninkaat:","Joka monet pakanat löi, ja tappoi väkevät kuninkaat:"],[135,11,"Sihonin Amorilaisten kuninkaan, ja Ogin Basanin kuninkaan, ja kaikki Kanaanin valtakunnat,","Sihonin Amorilaisten kuninkaan, ja Ogin Basanin kuninkaan, ja kaikki Kanaanin valtakunnat,"],[135,12,"Ja antoi heidän maansa perimiseksi, Israelille kansallensa perimiseksi.","Ja antoi heidän maansa perimiseksi, Israelille kansallensa perimiseksi."],[135,13,"Herra, sinun nimes pysyy ijankaikkisesti: Herra, sinun muistos pysyy suvusta sukuun.","Herra, sinun nimes pysyy ijankaikkisesti: Herra, sinun muistos pysyy suvusta sukuun."],[135,14,"Sillä Herra tuomitsee kansansa, ja on palvelioillensa armollinen.","Sillä Herra tuomitsee kansansa, ja on palvelioillensa armollinen."],[135,15,"Pakanain epäjumalat ovat hopia ja kulta, ihmisten käsillä tehdyt.","Pakanain epäjumalat ovat hopia ja kulta, ihmisten käsillä tehdyt."],[135,16,"Heillä on suu, ja ei puhu: heillä ovat silmät, ja ei näe;","Heillä on suu, ja ei puhu: heillä ovat silmät, ja ei näe;"],[135,17,"Heillä ovat korvat, ja ei kuule: eikä ole henkeä heidän suussansa.","Heillä ovat korvat, ja ei kuule: eikä ole henkeä heidän suussansa."],[135,18,"Jotka niitä tekevät, he ovat niiden kaltaiset, ja kaikki, jotka heihin uskaltavat.","Jotka niitä tekevät, he ovat niiden kaltaiset, ja kaikki, jotka heihin uskaltavat."],[135,19,"Te Israelin huoneesta, kiittäkäät Herraa! te Aaronin huoneesta, kiittäkäät Herraa!","Te Israelin huoneesta, kiittäkäät Herraa! te Aaronin huoneesta, kiittäkäät Herraa!"],[135,20,"Te Levin huoneesta, kiittäkäät Herraa! te jotka Herraa pelkäätte, kiittäkäät Herraa!","Te Levin huoneesta, kiittäkäät Herraa! te jotka Herraa pelkäätte, kiittäkäät Herraa!"],[135,21,"Kiitetty olkoon Herra Zionista, joka Jerusalemissa asuu! Halleluja!","Kiitetty olkoon Herra Zionista, joka Jerusalemissa asuu! Halleluja!"],[136,1,"Kiittäkäät Herraa, sillä hän on hyvä; sillä hänen laupiutensa pysyy ijankaikkisesti.","Kiittäkäät Herraa, sillä hän on hyvä; sillä hänen laupiutensa pysyy ijankaikkisesti."],[136,2,"Kiittäkäät kaikkein jumalain Jumalaa; sillä hänen laupiutensa pysyy ijankaikkisesti.","Kiittäkäät kaikkein jumalain Jumalaa; sillä hänen laupiutensa pysyy ijankaikkisesti."],[136,3,"Kiittäkäät kaikkein herrain Herraa; sillä hänen laupiutensa pysyy ijankaikkisesti,","Kiittäkäät kaikkein herrain Herraa; sillä hänen laupiutensa pysyy ijankaikkisesti,"],[136,4,"Joka yksinänsä suuret ihmeet tekee; sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka yksinänsä suuret ihmeet tekee; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,5,"Joka taivaat toimellisesti on tehnyt; sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka taivaat toimellisesti on tehnyt; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,6,"Joka maan on levittänyt veden päälle; sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka maan on levittänyt veden päälle; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,7,"Joka suuret valkeudet on tehnyt; sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka suuret valkeudet on tehnyt; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,8,"Auringon päivää hallitsemaan; sillä hänen laupiutensa pysyy ijankaikkisesti;","Auringon päivää hallitsemaan; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,9,"Kuun ja tähdet yötä hallitsemaan; sillä hänen laupiutensa pysyy ijankaikkisesti;","Kuun ja tähdet yötä hallitsemaan; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,10,"Joka Egyptin esikoiset löi: sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka Egyptin esikoiset löi: sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,11,"Ja vei Israelin ulos heidän keskeltänsä; sillä hänen laupiutensa pysyy ijankaikkisesti;","Ja vei Israelin ulos heidän keskeltänsä; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,12,"Väkevällä kädellä ja ojennetulla käsivarrella; sillä hänen laupiutensa pysyy ijankaikkisesti.","Väkevällä kädellä ja ojennetulla käsivarrella; sillä hänen laupiutensa pysyy ijankaikkisesti."],[136,13,"Joka Punaisen meren jakoi kahtia; sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka Punaisen meren jakoi kahtia; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,14,"Ja antoi Israelin käydä sen keskeltä; sillä hänen laupiutensa pysyy ijankaikkisesti;","Ja antoi Israelin käydä sen keskeltä; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,15,"Joka Pharaon sotaväkinensä Punaiseen mereen upotti; sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka Pharaon sotaväkinensä Punaiseen mereen upotti; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,16,"Joka johdatti kansansa korven lävitse; sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka johdatti kansansa korven lävitse; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,17,"Joka suuret kuninkaat löi; sillä hänen laupiutensa pysyy ijankaikkisesti;","Joka suuret kuninkaat löi; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,18,"Ja tappoi väkevät kuninkaat; sillä hänen laupiutensa pysyy ijankaikkisesti;","Ja tappoi väkevät kuninkaat; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,19,"Sihonin Amorilaisten kuninkaan; sillä hänen laupiutensa pysyy ijankaikkisesti;","Sihonin Amorilaisten kuninkaan; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,20,"Ja Ogin Basanin kuninkaan; sillä hänen laupiutensa pysyy ijankaikkisesti;","Ja Ogin Basanin kuninkaan; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,21,"Ja antoi heidän maansa perimiseksi; sillä hänen laupiutensa pysyy ijankaikkisesti;","Ja antoi heidän maansa perimiseksi; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,22,"Perimiseksi palveliallensa Israelille; sillä hänen laupiutensa pysyy ijankaikkisesti.","Perimiseksi palveliallensa Israelille; sillä hänen laupiutensa pysyy ijankaikkisesti."],[136,23,"Hän muisti meitä, kuin me olimme painetut alas; sillä hänen laupiutensa pysyy ijankaikkisesti;","Hän muisti meitä, kuin me olimme painetut alas; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,24,"Ja lunasti meitä vihollisistamme; sillä hänen laupiutensa pysyy ijankaikkisesti;","Ja lunasti meitä vihollisistamme; sillä hänen laupiutensa pysyy ijankaikkisesti;"],[136,25,"Joka antaa kaikelle lihalle ruan; sillä hänen laupiutensa pysyy ijankaikkisesti.","Joka antaa kaikelle lihalle ruan; sillä hänen laupiutensa pysyy ijankaikkisesti."],[136,26,"Kiittäkäät taivaan Jumalaa! sillä hänen laupiutensa pysyy ijankaikkisesti.","Kiittäkäät taivaan Jumalaa! sillä hänen laupiutensa pysyy ijankaikkisesti."],[137,1,"Babelin virtain tykönä me istuimme ja itkimme, kuin me Zionin muistimme.","Babelin virtain tykönä me istuimme ja itkimme, kuin me Zionin muistimme."],[137,2,"Kanteleemme me ripustimme pajuihin, jotka siellä olivat.","Kanteleemme me ripustimme pajuihin, jotka siellä olivat."],[137,3,"Siellä he käskivät meidän veisata, jotka meitä vankina pitivät, ja iloita meidän itkussamme: Veisatkaat meille Zionin virsiä.","Siellä he käskivät meidän veisata, jotka meitä vankina pitivät, ja iloita meidän itkussamme: Veisatkaat meille Zionin virsiä."],[137,4,"Kuinka me veisaisimme Herran veisun vieraalla maalla?","Kuinka me veisaisimme Herran veisun vieraalla maalla?"],[137,5,"Jos minä unohdan sinua, Jerusalem, niin olkoon oikia käteni unohdettu.","Jos minä unohdan sinua, Jerusalem, niin olkoon oikia käteni unohdettu."],[137,6,"Tarttukoon kieleni suuni lakeen, ellen minä sinua muista, ellen minä tee Jerusalemia ylimmäiseksi ilokseni.","Tarttukoon kieleni suuni lakeen, ellen minä sinua muista, ellen minä tee Jerusalemia ylimmäiseksi ilokseni."],[137,7,"Herra, muista Edomin lapsia Jerusalemin päivänä, jotka sanovat: repikäät maahan hamaan hänen perustukseensa asti.","Herra, muista Edomin lapsia Jerusalemin päivänä, jotka sanovat: repikäät maahan hamaan hänen perustukseensa asti."],[137,8,"Sinä hävitetty tytär, Babel; autuas on, se joka sinulle kostaa, niinkuin sinä meille tehnyt olet.","Sinä hävitetty tytär, Babel; autuas on, se joka sinulle kostaa, niinkuin sinä meille tehnyt olet."],[137,9,"Autuas on se, joka piskuiset lapses ottaa ja paiskaa kiviin.","Autuas on se, joka piskuiset lapses ottaa ja paiskaa kiviin."],[138,1,"Davidin. Minä kiitän sinua kaikesta sydämestäni: jumalain edessä minä sinulle kiitosta veisaan.","Davidin. Minä kiitän sinua kaikesta sydämestäni: jumalain edessä minä sinulle kiitosta veisaan."],[138,2,"Minä tahdon kumartaen rukoilla sinun pyhän templis puoleen, ja kiittää sinun nimeäs, sinun armos ja totuutes tähden; sillä sinä teit nimes ja sanas suureksi kaikkein ylitse.","Minä tahdon kumartaen rukoilla sinun pyhän templis puoleen, ja kiittää sinun nimeäs, sinun armos ja totuutes tähden; sillä sinä teit nimes ja sanas suureksi kaikkein ylitse."],[138,3,"Koska minä sinua avukseni huudan, niin sinä kuulet minua, ja annat sielulleni suuren väkevyyden.","Koska minä sinua avukseni huudan, niin sinä kuulet minua, ja annat sielulleni suuren väkevyyden."],[138,4,"Herra! sinua kiittävät kaikki kuninkaat maan päällä, että he kuulevat sinun suus sanoja,","Herra! sinua kiittävät kaikki kuninkaat maan päällä, että he kuulevat sinun suus sanoja,"],[138,5,"Ja veisaavat Herran teille, että Herran kunnia on suuri.","Ja veisaavat Herran teille, että Herran kunnia on suuri."],[138,6,"Sillä Herra on korkia, ja katselee nöyriä, ja ylpiät tuntee kaukaa.","Sillä Herra on korkia, ja katselee nöyriä, ja ylpiät tuntee kaukaa."],[138,7,"Jos minä vaeltaisin ahdistuksen keskellä, niin sinä virvoitat minua, ja lähetät kätes vihollisteni vihan päälle: sinun oikia kätes varjelee minua.","Jos minä vaeltaisin ahdistuksen keskellä, niin sinä virvoitat minua, ja lähetät kätes vihollisteni vihan päälle: sinun oikia kätes varjelee minua."],[138,8,"Herra tekee siihen lopun minun tähteni: Herra, sinun laupiutes on ijankaikkinen, älä käsialaas hylkää!","Herra tekee siihen lopun minun tähteni: Herra, sinun laupiutes on ijankaikkinen, älä käsialaas hylkää!"],[139,1,"Davidin Psalmi, edelläveisaajalle. Herra! sinä tutkit minua, ja tunnet minun.","Davidin Psalmi, edelläveisaajalle. Herra! sinä tutkit minua, ja tunnet minun."],[139,2,"Joko minä istun eli nousen, niin sinä sen tiedät: sinä ymmärrät taampaa ajatukseni.","Joko minä istun eli nousen, niin sinä sen tiedät: sinä ymmärrät taampaa ajatukseni."],[139,3,"Joko minä käyn eli makaan, niin sinä olet ympärilläni, ja näet kaikki tieni.","Joko minä käyn eli makaan, niin sinä olet ympärilläni, ja näet kaikki tieni."],[139,4,"Sillä katso, ei ole sanaakaan kieleni päällä, joita et sinä Herra kaikkia tiedä.","Sillä katso, ei ole sanaakaan kieleni päällä, joita et sinä Herra kaikkia tiedä."],[139,5,"Sinä olet tehnyt jälkimäiseni ja ensimäiseni, ja pidät sinun kätes minun päälläni.","Sinä olet tehnyt jälkimäiseni ja ensimäiseni, ja pidät sinun kätes minun päälläni."],[139,6,"Senkaltainen tieto on minulle ylen ihmeellinen ja ylen korkia, etten minä voi sitä käsittää.","Senkaltainen tieto on minulle ylen ihmeellinen ja ylen korkia, etten minä voi sitä käsittää."],[139,7,"Kuhunka minä menen sinun hengestäs? ja kuhunka minä sinun kasvois edestä pakenen?","Kuhunka minä menen sinun hengestäs? ja kuhunka minä sinun kasvois edestä pakenen?"],[139,8,"Jos minä astuisin ylös taivaaseen, niin sinä siellä olet: jos minä vuoteeni helvetissä rakentaisin, katso, sinä myös siellä olet.","Jos minä astuisin ylös taivaaseen, niin sinä siellä olet: jos minä vuoteeni helvetissä rakentaisin, katso, sinä myös siellä olet."],[139,9,"Jos minä ottaisin aamuruskon siivet, ja asuisin meren äärissä,","Jos minä ottaisin aamuruskon siivet, ja asuisin meren äärissä,"],[139,10,"Niin sinun kätes sielläkin minua johdattais, ja sinun oikia kätes pitäis minun.","Niin sinun kätes sielläkin minua johdattais, ja sinun oikia kätes pitäis minun."],[139,11,"Jos minä sanoisin: pimeys kuitenkin peittää minun, niin on myös yö valkeus minun ympärilläni.","Jos minä sanoisin: pimeys kuitenkin peittää minun, niin on myös yö valkeus minun ympärilläni."],[139,12,"Sillä ei pimeys sinun edessäs pimitä, ja yö valistaa niinkuin päivä; pimeys on niinkuin valkeus.","Sillä ei pimeys sinun edessäs pimitä, ja yö valistaa niinkuin päivä; pimeys on niinkuin valkeus."],[139,13,"Sinun hallussas ovat minun munaskuuni: sinä peitit minun äitini kohdussa.","Sinun hallussas ovat minun munaskuuni: sinä peitit minun äitini kohdussa."],[139,14,"Minä kiitän sinua sen edestä, että minä niin aivan ihmeellisesti tehty olen: ihmeelliset ovat sinun tekos, ja sen minun sieluni kyllä tietää.","Minä kiitän sinua sen edestä, että minä niin aivan ihmeellisesti tehty olen: ihmeelliset ovat sinun tekos, ja sen minun sieluni kyllä tietää."],[139,15,"Ei minun luuni olleet sinulta salatut, kuin minä siinä salaisesti tehty olin, kuin minä maan sisällä niin taitavasti koottu olin.","Ei minun luuni olleet sinulta salatut, kuin minä siinä salaisesti tehty olin, kuin minä maan sisällä niin taitavasti koottu olin."],[139,16,"Sinun silmäs näkivät minun, kuin en vielä valmistettu ollut, ja kaikki päivät sinun kirjaas olivat kirjoitetut, jotka vielä oleman piti, joista ei yksikään silloin vielä tullut ollut.","Sinun silmäs näkivät minun, kuin en vielä valmistettu ollut, ja kaikki päivät sinun kirjaas olivat kirjoitetut, jotka vielä oleman piti, joista ei yksikään silloin vielä tullut ollut."],[139,17,"Mutta kuinka kalliit ovat minun edessäni, Jumala, sinun ajatukses? kuinka suuri on heidän lukunsa?","Mutta kuinka kalliit ovat minun edessäni, Jumala, sinun ajatukses? kuinka suuri on heidän lukunsa?"],[139,18,"Jos minä heitä lukisin, niin ne olisivat usiammat kuin santa: kuin minä herään, olen minä vielä tykönäs.","Jos minä heitä lukisin, niin ne olisivat usiammat kuin santa: kuin minä herään, olen minä vielä tykönäs."],[139,19,"Jumala, jospa tappaisit jumalattomat, ja verikoirat minusta poikkeisivat.","Jumala, jospa tappaisit jumalattomat, ja verikoirat minusta poikkeisivat."],[139,20,"Sillä he puhuvat sinusta häpiällisesti, ja sinun vihollises turhaan lausuvat (sinun nimes).","Sillä he puhuvat sinusta häpiällisesti, ja sinun vihollises turhaan lausuvat (sinun nimes)."],[139,21,"Herra, minä tosin vihaan niitä, jotka sinua vihaavat, ja minä närkästyn heistä, jotka karkaavat sinua vastaan.","Herra, minä tosin vihaan niitä, jotka sinua vihaavat, ja minä närkästyn heistä, jotka karkaavat sinua vastaan."],[139,22,"Täydestä todesta minä heitä vihaan; sentähden ovat he minulle viholliset.","Täydestä todesta minä heitä vihaan; sentähden ovat he minulle viholliset."],[139,23,"Tutki minua, Jumala, ja koettele sydämeni: kiusaa minua, ja ymmärrä, kuinka minä ajattelen.","Tutki minua, Jumala, ja koettele sydämeni: kiusaa minua, ja ymmärrä, kuinka minä ajattelen."],[139,24,"Ja katsos, jos minä pahalla tiellä lienen, niin saata minua ijankaikkiselle tielle.","Ja katsos, jos minä pahalla tiellä lienen, niin saata minua ijankaikkiselle tielle."],[140,1,"Davidin Psalmi, edelläveisaajalle. (H140:2) Herra, pelasta minua pahoista ihmisistä: varjele minua vääristä miehistä,","Davidin Psalmi, edelläveisaajalle. (H140:2) Herra, pelasta minua pahoista ihmisistä: varjele minua vääristä miehistä,"],[140,2,"Jotka pahaa ajattelevat sydämissänsä, ja joka päivä sotaan hankitsevat.","Jotka pahaa ajattelevat sydämissänsä, ja joka päivä sotaan hankitsevat."],[140,3,"He hiovat kieltänsä niinkuin kärme: kyykärmeen myrkky on heidän huultensa alla, Sela!","He hiovat kieltänsä niinkuin kärme: kyykärmeen myrkky on heidän huultensa alla, Sela!"],[140,4,"Varjele minua, Herra, jumalattomain käsistä, varjele minua vääristä ihmisistä, jotka ajattelevat minun käymiseni kukistaa.","Varjele minua, Herra, jumalattomain käsistä, varjele minua vääristä ihmisistä, jotka ajattelevat minun käymiseni kukistaa."],[140,5,"Ylpiät asettavat paulat ja nuorat minun eteeni, ja venyttävät verkot tien viereen: minun eteeni panevat he paulan, Sela!","Ylpiät asettavat paulat ja nuorat minun eteeni, ja venyttävät verkot tien viereen: minun eteeni panevat he paulan, Sela!"],[140,6,"Mutta minä sanoin Herralle: sinä olet minun Jumalani: Herra, kuule minun rukoukseni ääni.","Mutta minä sanoin Herralle: sinä olet minun Jumalani: Herra, kuule minun rukoukseni ääni."],[140,7,"Herra, Herra, väkevä apuni! sinä varjelet minun pääni sodan aikana.","Herra, Herra, väkevä apuni! sinä varjelet minun pääni sodan aikana."],[140,8,"Herra, älä salli jumalattomalle hänen himoansa: älä vahvista hänen pahaa tahtoansa, ettei hän ylpeytyisi, Sela!","Herra, älä salli jumalattomalle hänen himoansa: älä vahvista hänen pahaa tahtoansa, ettei hän ylpeytyisi, Sela!"],[140,9,"Heidän sappensa, jotka minua piirittävät, ja heidän huultensa vaiva langetkoon heidän päällensä.","Heidän sappensa, jotka minua piirittävät, ja heidän huultensa vaiva langetkoon heidän päällensä."],[140,10,"Tuliset hiilet pitää heidän päällensä putooman: hän antaa heidän langeta tuleen ja syvään kuoppaan, ettei heidän pidä nouseman ylös.","Tuliset hiilet pitää heidän päällensä putooman: hän antaa heidän langeta tuleen ja syvään kuoppaan, ettei heidän pidä nouseman ylös."],[140,11,"Kielilakkarin ei pidä menestymän maan päällä: häijy väärä ihminen karkoitetaan ja kukistetaan.","Kielilakkarin ei pidä menestymän maan päällä: häijy väärä ihminen karkoitetaan ja kukistetaan."],[140,12,"Sillä minä tiedän, että Herra raadollisen asian ja köyhän oikeuden toimittaa.","Sillä minä tiedän, että Herra raadollisen asian ja köyhän oikeuden toimittaa."],[140,13,"Tosin vanhurskaat kiittävät sinun nimeäs, ja vakaat asuvat sinun kasvois edessä.","Tosin vanhurskaat kiittävät sinun nimeäs, ja vakaat asuvat sinun kasvois edessä."],[141,1,"Davidin Psalmi. Herra, minä avukseni huudan sinua: riennä minun puoleeni: ota korviis minun ääneni, koska minä sinua huudan.","Davidin Psalmi. Herra, minä avukseni huudan sinua: riennä minun puoleeni: ota korviis minun ääneni, koska minä sinua huudan."],[141,2,"Kelvatkoon minun rukoukseni sinun edessäs niinkuin savu-uhri, minun kätteni ylennys niinkuin ehtoo-uhri.","Kelvatkoon minun rukoukseni sinun edessäs niinkuin savu-uhri, minun kätteni ylennys niinkuin ehtoo-uhri."],[141,3,"Herra, varjele minun suuni ja varjele minun huuleni.","Herra, varjele minun suuni ja varjele minun huuleni."],[141,4,"Älä kallista minun sydäntäni mihinkään pahuuteen, pitämään jumalatointa menoa pahointekiäin kanssa, etten minä söisi niitä, mitkä heille kelpaavat.","Älä kallista minun sydäntäni mihinkään pahuuteen, pitämään jumalatointa menoa pahointekiäin kanssa, etten minä söisi niitä, mitkä heille kelpaavat."],[141,5,"Vanhurskas lyökään minua ystävällisesti, ja nuhdelkaan minua, se olkoon niinkuin öljy minun pääni päällä; sillä minä vielä rukoilen heidän pahuuttansa vastaan.","Vanhurskas lyökään minua ystävällisesti, ja nuhdelkaan minua, se olkoon niinkuin öljy minun pääni päällä; sillä minä vielä rukoilen heidän pahuuttansa vastaan."],[141,6,"Heidän opettajansa sysättäköön kiveen, niin sitte kuullaan minun opetukseni suloiseksi.","Heidän opettajansa sysättäköön kiveen, niin sitte kuullaan minun opetukseni suloiseksi."],[141,7,"Meidän luumme ovat hajoitetut haudan reunalle, niinkuin joku maan repis ja kaivais.","Meidän luumme ovat hajoitetut haudan reunalle, niinkuin joku maan repis ja kaivais."],[141,8,"Sillä sinua, Herra, Herra, minun silmäni katsovat: minä uskallan sinuun, älä minun sieluani hylkää.","Sillä sinua, Herra, Herra, minun silmäni katsovat: minä uskallan sinuun, älä minun sieluani hylkää."],[141,9,"Varjele minua siitä paulasta, jonka he asettivat eteeni, ja pahointekiäin ansasta.","Varjele minua siitä paulasta, jonka he asettivat eteeni, ja pahointekiäin ansasta."],[141,10,"Jumalattomat lankeevat toinen toisensa kanssa omiin verkkoihinsa, siihenasti kuin minä pääsen ohitse.","Jumalattomat lankeevat toinen toisensa kanssa omiin verkkoihinsa, siihenasti kuin minä pääsen ohitse."],[142,1,"Davidin oppi ja rukous, kuin hän luolassa oli. (H142:2) Minä huudan Herran tykö äänelläni, ja rukoilen Herraa äänelläni.","Davidin oppi ja rukous, kuin hän luolassa oli. (H142:2) Minä huudan Herran tykö äänelläni, ja rukoilen Herraa äänelläni."],[142,2,"Minä vuodatan ajatukseni hänen edessänsä, ja osoitan hänelle hätäni,","Minä vuodatan ajatukseni hänen edessänsä, ja osoitan hänelle hätäni,"],[142,3,"Koska henkeni on ahdistuksessa, niin sinä tiedät käymiseni: tielle, jota minä vaellan, asettavat he paulat eteeni.","Koska henkeni on ahdistuksessa, niin sinä tiedät käymiseni: tielle, jota minä vaellan, asettavat he paulat eteeni."],[142,4,"Katsele oikialle puolelle ja näe, siellä ei yksikään tahdo minua tuta: en minä taida paeta, ei tottele kenkään minun sieluani.","Katsele oikialle puolelle ja näe, siellä ei yksikään tahdo minua tuta: en minä taida paeta, ei tottele kenkään minun sieluani."],[142,5,"Herra, sinua minä huudan ja sanon: sinä olet minun toivoni ja minun osani elävien maalla.","Herra, sinua minä huudan ja sanon: sinä olet minun toivoni ja minun osani elävien maalla."],[142,6,"Ota vaari minun rukouksestani, sillä minua vaivataan sangen: pelasta minua vainollisistani; sillä he ovat minua väkevämmät.","Ota vaari minun rukouksestani, sillä minua vaivataan sangen: pelasta minua vainollisistani; sillä he ovat minua väkevämmät."],[142,7,"Vie minun sieluni vankeudesta ulos kiittämään sinun nimeäs: vanhurskaat kokoontuvat minun tyköni, koskas minulle hyvästi teet.","Vie minun sieluni vankeudesta ulos kiittämään sinun nimeäs: vanhurskaat kokoontuvat minun tyköni, koskas minulle hyvästi teet."],[143,1,"Davidin Psalmi. Herra! kuule minun rukoukseni, ota anomiseni korviis, sinun totuutes tähden, kuule minua sinun vanhurskautes tähden,","Davidin Psalmi. Herra! kuule minun rukoukseni, ota anomiseni korviis, sinun totuutes tähden, kuule minua sinun vanhurskautes tähden,"],[143,2,"Ja älä käy tuomiolle palvelias kanssa; sillä ei yksikään elävä ole vakaa sinun edessäs.","Ja älä käy tuomiolle palvelias kanssa; sillä ei yksikään elävä ole vakaa sinun edessäs."],[143,3,"Sillä vihollinen vainoo minun sieluani, ja lyö minun elämäni rikki maahan asti: hän panee minun pimeyteen, niinkuin kuolleet maailmassa.","Sillä vihollinen vainoo minun sieluani, ja lyö minun elämäni rikki maahan asti: hän panee minun pimeyteen, niinkuin kuolleet maailmassa."],[143,4,"Minun henkeni on minussa ahdistettu: sydämeni on minussa kulutettu.","Minun henkeni on minussa ahdistettu: sydämeni on minussa kulutettu."],[143,5,"Minä muistelen entisiä aikoja: minä ajattelen kaikkia sinun tekojas, ja tutkistelen sinun kättes töitä.","Minä muistelen entisiä aikoja: minä ajattelen kaikkia sinun tekojas, ja tutkistelen sinun kättes töitä."],[143,6,"Minä levitän käteni sinun puolees: minun sieluni janoo sinua, niinkuin karkia maa, Sela!","Minä levitän käteni sinun puolees: minun sieluni janoo sinua, niinkuin karkia maa, Sela!"],[143,7,"Herra, kuule minua nopiasti, henkeni katoo: älä kasvojas minulta kätke, etten minä niiden kaltaiseksi tulisi, jotka hautaan menevät.","Herra, kuule minua nopiasti, henkeni katoo: älä kasvojas minulta kätke, etten minä niiden kaltaiseksi tulisi, jotka hautaan menevät."],[143,8,"Suo minun varhain kuulla sinun armojas, sillä sinuun minä toivon: ilmoita minulle tie, jota minä käyn; sillä minä ylennän sieluni sinun tykös.","Suo minun varhain kuulla sinun armojas, sillä sinuun minä toivon: ilmoita minulle tie, jota minä käyn; sillä minä ylennän sieluni sinun tykös."],[143,9,"Pelasta minua, Herra, vihollisistani! sinun tykös minä pakenen.","Pelasta minua, Herra, vihollisistani! sinun tykös minä pakenen."],[143,10,"Opeta minua tekemään sinun suosios jälkeen; sillä sinä olet minun Jumalani: sinun hyvä henkes viekään minua tasaista tietä.","Opeta minua tekemään sinun suosios jälkeen; sillä sinä olet minun Jumalani: sinun hyvä henkes viekään minua tasaista tietä."],[143,11,"Herra, virvoita minua nimes tähden: vie sieluni hädästä ulos sinun vanhurskautes tähden.","Herra, virvoita minua nimes tähden: vie sieluni hädästä ulos sinun vanhurskautes tähden."],[143,12,"Ja teloita viholliseni sinun laupiutes tähden, ja kadota kaikki, jotka minun sieluani ahdistavat, sillä minä olen palvelias.","Ja teloita viholliseni sinun laupiutes tähden, ja kadota kaikki, jotka minun sieluani ahdistavat, sillä minä olen palvelias."],[144,1,"Davidin Psalmi. Kiitetty olkoon Herra, minun turvani, joka käteni opettaa sotimaan, ja sormeni tappelemaan,","Davidin Psalmi. Kiitetty olkoon Herra, minun turvani, joka käteni opettaa sotimaan, ja sormeni tappelemaan,"],[144,2,"Minun laupiuteni ja minun linnani, minun varjelukseni ja minun vapahtajani, minun kilpeni, johon minä uskallan, joka minun kansani minun alleni vaatii.","Minun laupiuteni ja minun linnani, minun varjelukseni ja minun vapahtajani, minun kilpeni, johon minä uskallan, joka minun kansani minun alleni vaatii."],[144,3,"Herra, mikä on ihminen, ettäs häntä korjaat? eli ihmisen poika, ettäs hänestä otat vaarin?","Herra, mikä on ihminen, ettäs häntä korjaat? eli ihmisen poika, ettäs hänestä otat vaarin?"],[144,4,"On sittekin ihminen tyhjän verta: hänen aikansa katoo niinkuin varjo.","On sittekin ihminen tyhjän verta: hänen aikansa katoo niinkuin varjo."],[144,5,"Herra, kallista sinun taivaas, ja astu alas: rupee vuoriin, että he suitsisivat.","Herra, kallista sinun taivaas, ja astu alas: rupee vuoriin, että he suitsisivat."],[144,6,"Anna leimaukset iskeä, ja hajoita heitä: ammu nuolias ja kauhistuta heitä.","Anna leimaukset iskeä, ja hajoita heitä: ammu nuolias ja kauhistuta heitä."],[144,7,"Lähetä kätes ylhäältä, ja kirvota minua, ja pelasta minua suurista vesistä ja muukalaisten lasten käsistä,","Lähetä kätes ylhäältä, ja kirvota minua, ja pelasta minua suurista vesistä ja muukalaisten lasten käsistä,"],[144,8,"Joiden suu puhuu valhetta, ja heidän oikia kätensä on petollinen oikia käsi.","Joiden suu puhuu valhetta, ja heidän oikia kätensä on petollinen oikia käsi."],[144,9,"Jumala, minä veisaan sinulle uuden virren: minä soitan sinulle kymmenkielisellä psaltarilla,","Jumala, minä veisaan sinulle uuden virren: minä soitan sinulle kymmenkielisellä psaltarilla,"],[144,10,"Sinä joka kuninkaille voiton annat, ja palvelias Davidin vapahdat murhamiekasta.","Sinä joka kuninkaille voiton annat, ja palvelias Davidin vapahdat murhamiekasta."],[144,11,"Päästä myös minua ja pelasta minua muukalaisten kädestä, joiden suu puhuu valhetta, ja heidän oikia kätensä on petollinen oikia käsi,","Päästä myös minua ja pelasta minua muukalaisten kädestä, joiden suu puhuu valhetta, ja heidän oikia kätensä on petollinen oikia käsi,"],[144,12,"Että meidän pojat kasvaisivat nuoruudessansa niinkuin vesat, ja meidän tyttäret, niinkuin templin kaunistetut seinät.","Että meidän pojat kasvaisivat nuoruudessansa niinkuin vesat, ja meidän tyttäret, niinkuin templin kaunistetut seinät."],[144,13,"Meidän aittamme olkoon täynnä, jotka runsaat elatukset antaisivat toinen toisensa perästä, että meidän lampaamme poikisivat tuhannen, ja sata tuhatta, kylissämme;","Meidän aittamme olkoon täynnä, jotka runsaat elatukset antaisivat toinen toisensa perästä, että meidän lampaamme poikisivat tuhannen, ja sata tuhatta, kylissämme;"],[144,14,"Että härkämme olisivat vahvat työhön; ettei yhtään vahinkoa, eikä valitusta eli kannetta olisi kaduillamme.","Että härkämme olisivat vahvat työhön; ettei yhtään vahinkoa, eikä valitusta eli kannetta olisi kaduillamme."],[144,15,"Autuas on se kansa, jolle niin käy; vaan autuas on se kansa, jonka Jumalana Herra on.","Autuas on se kansa, jolle niin käy; vaan autuas on se kansa, jonka Jumalana Herra on."],[145,1,"Davidin kiitos. Minä ylistän sinua, Jumalani, sinä kuningas, ja kiitän sinun nimeäs aina ja ijankaikkiseti.","Davidin kiitos. Minä ylistän sinua, Jumalani, sinä kuningas, ja kiitän sinun nimeäs aina ja ijankaikkiseti."],[145,2,"Joka päivä minä kunnioitan sinua, ja kiitän sinun nimeäs aina ja ijankaikkisesti.","Joka päivä minä kunnioitan sinua, ja kiitän sinun nimeäs aina ja ijankaikkisesti."],[145,3,"Suuri on Herra, ja sangen kunniallinen, ja hänen suuruutensa on sanomatoin.","Suuri on Herra, ja sangen kunniallinen, ja hänen suuruutensa on sanomatoin."],[145,4,"Suku pitää suvulle jutteleman sinun töitäs, ja sinun voimastas puhuman.","Suku pitää suvulle jutteleman sinun töitäs, ja sinun voimastas puhuman."],[145,5,"Minä ajattelen sinun suuren kunnias kauneutta ja sinun ihmeitäs;","Minä ajattelen sinun suuren kunnias kauneutta ja sinun ihmeitäs;"],[145,6,"Että puhuttaisiin sinun ihmeellisten töittes voimasta: ja sinun suurta herrauttas minä juttelen;","Että puhuttaisiin sinun ihmeellisten töittes voimasta: ja sinun suurta herrauttas minä juttelen;"],[145,7,"Että sinun suuren hyvyytes muisto ylistettäisiin, ja sinun vanhurskautes kiitettäisiin.","Että sinun suuren hyvyytes muisto ylistettäisiin, ja sinun vanhurskautes kiitettäisiin."],[145,8,"Armollinen ja laupias on Herra, hidas vihaan ja sangen hyvä.","Armollinen ja laupias on Herra, hidas vihaan ja sangen hyvä."],[145,9,"Suloinen on Herra kaikille, ja armahtaa kaikkia tekojansa.","Suloinen on Herra kaikille, ja armahtaa kaikkia tekojansa."],[145,10,"Kiittäkään sinua, Herra, kaikki sinun tekos, ja sinun pyhäs kiittäkään sinua;","Kiittäkään sinua, Herra, kaikki sinun tekos, ja sinun pyhäs kiittäkään sinua;"],[145,11,"Julistakaan sinun valtakuntas kunniaa, ja puhukaa sinun voimastas.","Julistakaan sinun valtakuntas kunniaa, ja puhukaa sinun voimastas."],[145,12,"Että sinun voimas tulis ihmisten lapsille tiettäväksi, ja sinun valtakuntas suuri kunnia.","Että sinun voimas tulis ihmisten lapsille tiettäväksi, ja sinun valtakuntas suuri kunnia."],[145,13,"Sinun valtakuntas on ijankaikkinen valtakunta, ja sinun herrautes pysyy suvusta sukuun.","Sinun valtakuntas on ijankaikkinen valtakunta, ja sinun herrautes pysyy suvusta sukuun."],[145,14,"Herra tukee kaikkia kaatuvaisia, ja nostaa kaikkia sullotuita.","Herra tukee kaikkia kaatuvaisia, ja nostaa kaikkia sullotuita."],[145,15,"Kaikkein silmät vartioitsevat sinua, ja sinä annat heille ruan ajallansa.","Kaikkein silmät vartioitsevat sinua, ja sinä annat heille ruan ajallansa."],[145,16,"Sinä avaat kätes, ja ravitset kaikki, kuin elävät, suosiolla.","Sinä avaat kätes, ja ravitset kaikki, kuin elävät, suosiolla."],[145,17,"Vanhurskas on Herra kaikissa teissänsä, ja laupias kaikissa töissänsä.","Vanhurskas on Herra kaikissa teissänsä, ja laupias kaikissa töissänsä."],[145,18,"Läsnä on Herra kaikkia, jotka häntä avuksensa huutavat, kaikkia, jotka totuudessa häntä avuksensa huutavat.","Läsnä on Herra kaikkia, jotka häntä avuksensa huutavat, kaikkia, jotka totuudessa häntä avuksensa huutavat."],[145,19,"Hän tekee, mitä häntä pelkääväiset halajavat, ja kuulee heidän huutonsa, ja auttaa heitä.","Hän tekee, mitä häntä pelkääväiset halajavat, ja kuulee heidän huutonsa, ja auttaa heitä."],[145,20,"Herra varjelee kaikkia, jotka häntä rakastavat, ja hukuttaa kaikki jumalattomat.","Herra varjelee kaikkia, jotka häntä rakastavat, ja hukuttaa kaikki jumalattomat."],[145,21,"Minun suuni pitää puhuman Herran kiitoksen, ja kaikki liha kunnioittakaan hänen pyhää nimeänsä, aina ja ijankaikkisesti.","Minun suuni pitää puhuman Herran kiitoksen, ja kaikki liha kunnioittakaan hänen pyhää nimeänsä, aina ja ijankaikkisesti."],[146,1,"Halleluja! Kiitä Herraa, minun sieluni.","Halleluja! Kiitä Herraa, minun sieluni."],[146,2,"Minä kiitän Herraa niinkauvan kuin minä elän, ja Jumalalleni kiitoksen veisaan, niinkauvan kuin minä täällä olen.","Minä kiitän Herraa niinkauvan kuin minä elän, ja Jumalalleni kiitoksen veisaan, niinkauvan kuin minä täällä olen."],[146,3,"Älkäät uskaltako päämiehiin; ihmiset he ovat, ei he voi mitään auttaa.","Älkäät uskaltako päämiehiin; ihmiset he ovat, ei he voi mitään auttaa."],[146,4,"Sillä ihmisen henki pitää erkaneman, ja hänen täytyy maaksi tulla jälleen: silloin ovat kaikki hänen aivoituksensa hukassa.","Sillä ihmisen henki pitää erkaneman, ja hänen täytyy maaksi tulla jälleen: silloin ovat kaikki hänen aivoituksensa hukassa."],[146,5,"Autuas on se, jonka apu Jakobin Jumala on, jonka toivo Herrassa hänen Jumalassansa on;","Autuas on se, jonka apu Jakobin Jumala on, jonka toivo Herrassa hänen Jumalassansa on;"],[146,6,"Joka taivaan ja maan, meren ja kaikki, jotka niissä ovat, tehnyt on, joka totuuden pitää ijankaikkisesti;","Joka taivaan ja maan, meren ja kaikki, jotka niissä ovat, tehnyt on, joka totuuden pitää ijankaikkisesti;"],[146,7,"Joka oikeuden saattaa niille, jotka väkivaltaa kärsivät, joka isoovaiset ravitsee. Herra kirvottaa vangitut:","Joka oikeuden saattaa niille, jotka väkivaltaa kärsivät, joka isoovaiset ravitsee. Herra kirvottaa vangitut:"],[146,8,"Herra avaa sokian silmät: Herra nostaa kukistetut: Herra rakastaa vanhurskaita.","Herra avaa sokian silmät: Herra nostaa kukistetut: Herra rakastaa vanhurskaita."],[146,9,"Herra varjelee vieraat, ja holhoo orpoja ja leskiä, ja jumalattomain tien hajoittaa.","Herra varjelee vieraat, ja holhoo orpoja ja leskiä, ja jumalattomain tien hajoittaa."],[146,10,"Herra on kuningas ijankaikkisesti, sinun Jumalas, Zion, suvusta sukuun, Halleluja!","Herra on kuningas ijankaikkisesti, sinun Jumalas, Zion, suvusta sukuun, Halleluja!"],[147,1,"Kiittäkäät Herraa! sillä Jumalaamme kiittää on kallis asia: kiitos on suloinen ja kaunis.","Kiittäkäät Herraa! sillä Jumalaamme kiittää on kallis asia: kiitos on suloinen ja kaunis."],[147,2,"Herra rakentaa Jerusalemin, ja kokoo hajoitetut Israelilaiset.","Herra rakentaa Jerusalemin, ja kokoo hajoitetut Israelilaiset."],[147,3,"Hän parantaa murretut sydämet, ja sitoo heidän kipunsa.","Hän parantaa murretut sydämet, ja sitoo heidän kipunsa."],[147,4,"Hän lukee tähdet, ja kutsuu heitä kaikkia nimeltänsä.","Hän lukee tähdet, ja kutsuu heitä kaikkia nimeltänsä."],[147,5,"Suuri on meidän Herramme, ja suuri hänen voimansa, ja hänen viisautensa on määrätöin.","Suuri on meidän Herramme, ja suuri hänen voimansa, ja hänen viisautensa on määrätöin."],[147,6,"Herra ojentaa raadolliset, ja jumalattomat maahan paiskaa.","Herra ojentaa raadolliset, ja jumalattomat maahan paiskaa."],[147,7,"Vuoroin veisatkaat Herralle kiitossanalla, ja veisatkaat meidän Herrallemme kanteleella;","Vuoroin veisatkaat Herralle kiitossanalla, ja veisatkaat meidän Herrallemme kanteleella;"],[147,8,"Joka taivaan pilvillä peittää ja antaa sateen maan päälle; joka ruohot vuorilla kasvattaa;","Joka taivaan pilvillä peittää ja antaa sateen maan päälle; joka ruohot vuorilla kasvattaa;"],[147,9,"Joka eläimille antaa heidän ruokansa, ja kaarneen pojille, jotka häntä avuksensa huutavat.","Joka eläimille antaa heidän ruokansa, ja kaarneen pojille, jotka häntä avuksensa huutavat."],[147,10,"Ei hän mielisty hevosten väkevyyteen, eikä hänelle kelpaa miehen sääriluut.","Ei hän mielisty hevosten väkevyyteen, eikä hänelle kelpaa miehen sääriluut."],[147,11,"Herralle kelpaavat ne, jotka häntä pelkäävät, ja jotka hänen laupiuteensa uskaltavat.","Herralle kelpaavat ne, jotka häntä pelkäävät, ja jotka hänen laupiuteensa uskaltavat."],[147,12,"Ylistä, Jerusalem, Herraa: kiitä, Zion, sinun Jumalaas!","Ylistä, Jerusalem, Herraa: kiitä, Zion, sinun Jumalaas!"],[147,13,"Sillä hän vahvistaa sinun porttis salvat, ja siunaa sinussa sinun lapses.","Sillä hän vahvistaa sinun porttis salvat, ja siunaa sinussa sinun lapses."],[147,14,"Hän saattaa rauhan sinun ääriis, ja ravitsee sinua parhailla nisuilla.","Hän saattaa rauhan sinun ääriis, ja ravitsee sinua parhailla nisuilla."],[147,15,"Hän lähettää puheensa maan päälle: hänen sanansa nopiasti juoksee.","Hän lähettää puheensa maan päälle: hänen sanansa nopiasti juoksee."],[147,16,"Hän antaa lumen niinkuin villan; hän hajoittaa härmän niinkuin tuhan.","Hän antaa lumen niinkuin villan; hän hajoittaa härmän niinkuin tuhan."],[147,17,"Hän heittää rakeensa niinkuin palat; kuka hänen pakkasensa edessä kestää?","Hän heittää rakeensa niinkuin palat; kuka hänen pakkasensa edessä kestää?"],[147,18,"Hän lähettää sanansa, ja sulaa ne; hän antaa tuulen puhaltaa, niin vedet juoksevat.","Hän lähettää sanansa, ja sulaa ne; hän antaa tuulen puhaltaa, niin vedet juoksevat."],[147,19,"Hän ilmoittaa Jakobille sanansa, ja Israelille säätynsä ja oikeutensa.","Hän ilmoittaa Jakobille sanansa, ja Israelille säätynsä ja oikeutensa."],[147,20,"Ei hän niin tehnyt kaikille pakanoille; eikä he tiedä hänen oikeuttansa, Halleluja!","Ei hän niin tehnyt kaikille pakanoille; eikä he tiedä hänen oikeuttansa, Halleluja!"],[148,1,"Halleluja! Kiittäkäät Herraa taivaissa, kiittäkäät häntä korkeudessa.","Halleluja! Kiittäkäät Herraa taivaissa, kiittäkäät häntä korkeudessa."],[148,2,"Kiittäkäät häntä kaikki hänen enkelinsä: kiittäkäät häntä kaikki hänen sotaväkensä.","Kiittäkäät häntä kaikki hänen enkelinsä: kiittäkäät häntä kaikki hänen sotaväkensä."],[148,3,"Kiittäkäät häntä aurinko ja kuu: kiittäkäät häntä kaikki kirkkaat tähdet.","Kiittäkäät häntä aurinko ja kuu: kiittäkäät häntä kaikki kirkkaat tähdet."],[148,4,"Kiittäkäät häntä, te taivasten taivaat, ja vedet, jotka taivasten päällä ovat.","Kiittäkäät häntä, te taivasten taivaat, ja vedet, jotka taivasten päällä ovat."],[148,5,"Heidän pitää Herran nimeä kiittämän; sillä hän käski, ja ne luoduksi tulivat.","Heidän pitää Herran nimeä kiittämän; sillä hän käski, ja ne luoduksi tulivat."],[148,6,"Hän pitää ylös ne aina ja ijankaikkisesti: hän asettaa heitä, ettei heidän toisin käymän pitäisi.","Hän pitää ylös ne aina ja ijankaikkisesti: hän asettaa heitä, ettei heidän toisin käymän pitäisi."],[148,7,"Kiittäkäät Herraa maan päällä, te valaskalat ja kaikki syvyydet;","Kiittäkäät Herraa maan päällä, te valaskalat ja kaikki syvyydet;"],[148,8,"Tuli ja rakeet, lumi ja sumu, tuulispää, jotka hänen sanansa toimittavat,","Tuli ja rakeet, lumi ja sumu, tuulispää, jotka hänen sanansa toimittavat,"],[148,9,"Vuoret ja kaikki kukkulat, hedelmälliset puut ja kaikki sedripuut;","Vuoret ja kaikki kukkulat, hedelmälliset puut ja kaikki sedripuut;"],[148,10,"Pedot ja kaikki eläimet, madot ja siivelliset linnut;","Pedot ja kaikki eläimet, madot ja siivelliset linnut;"],[148,11,"Maan kuninkaat ja kaikki kansat, päämiehet ja kaikki tuomarit maan päällä;","Maan kuninkaat ja kaikki kansat, päämiehet ja kaikki tuomarit maan päällä;"],[148,12,"Nuorukaiset ja neitseet, vanhat nuorten kanssa:","Nuorukaiset ja neitseet, vanhat nuorten kanssa:"],[148,13,"Kiittäkään Herran nimeä; sillä hänen ainoan nimensä on korotettu, ja hänen suuri kunniansa ylitse maan ja taivaan.","Kiittäkään Herran nimeä; sillä hänen ainoan nimensä on korotettu, ja hänen suuri kunniansa ylitse maan ja taivaan."],[148,14,"Ja hän korottaa sarven kansallensa: kaikki hänen pyhänsä kiittäkäät, Israelin lapset, kansa joka häntä lähin on, Halleluja!","Ja hän korottaa sarven kansallensa: kaikki hänen pyhänsä kiittäkäät, Israelin lapset, kansa joka häntä lähin on, Halleluja!"],[149,1,"Halleluja! Veisatkaat Herralle uusi veisu: pyhäin seurakunnan pitää häntä kiittämän.","Halleluja! Veisatkaat Herralle uusi veisu: pyhäin seurakunnan pitää häntä kiittämän."],[149,2,"Iloitkaan Israel tekiässänsä: Zionin lapset riemuitkaan Kuninkaastansa.","Iloitkaan Israel tekiässänsä: Zionin lapset riemuitkaan Kuninkaastansa."],[149,3,"Heidän pitää tanssissa hänen nimeänsä kiittämän: harpuilla ja kanteleilla pitää heidän soittaman.","Heidän pitää tanssissa hänen nimeänsä kiittämän: harpuilla ja kanteleilla pitää heidän soittaman."],[149,4,"Sillä Herra rakastaa kansaansa: hän kunnioittaa nöyriä autuudella.","Sillä Herra rakastaa kansaansa: hän kunnioittaa nöyriä autuudella."],[149,5,"Pyhäin pitää iloitseman kunnialla, ja kiittämän vuoteissansa.","Pyhäin pitää iloitseman kunnialla, ja kiittämän vuoteissansa."],[149,6,"Heidän suussansa pitää Jumalan ylistys oleman, ja kaksiteräiset miekat heidän käsissänsä,","Heidän suussansa pitää Jumalan ylistys oleman, ja kaksiteräiset miekat heidän käsissänsä,"],[149,7,"Kostamaan pakanoille, ja rankaisemaan kansoja,","Kostamaan pakanoille, ja rankaisemaan kansoja,"],[149,8,"Heidän kuninkaitansa sitomaan kahleisiin, ja heidän jaloimpiansa rautakahleisiin,","Heidän kuninkaitansa sitomaan kahleisiin, ja heidän jaloimpiansa rautakahleisiin,"],[149,9,"Ja tekemään heille kirjoitetun oikeuden: tämä kunnia pitää kaikille hänen pyhillensä oleman, Halleluja!","Ja tekemään heille kirjoitetun oikeuden: tämä kunnia pitää kaikille hänen pyhillensä oleman, Halleluja!"],[150,1,"Halleluja! Kiittäkäät Herraa hänen pyhässänsä: kiittäkäät häntä hänen väkevyytensä avaruudessa!","Halleluja! Kiittäkäät Herraa hänen pyhässänsä: kiittäkäät häntä hänen väkevyytensä avaruudessa!"],[150,2,"Kiittäkäät häntä hänen voimallisten tekoinsa tähden: kiittäkäät häntä ylenpalttisen suuruutensa tähden!","Kiittäkäät häntä hänen voimallisten tekoinsa tähden: kiittäkäät häntä ylenpalttisen suuruutensa tähden!"],[150,3,"Kiittäkäät häntä basunilla: kiittäkäät häntä psaltareilla ja kanteleilla!","Kiittäkäät häntä basunilla: kiittäkäät häntä psaltareilla ja kanteleilla!"],[150,4,"Kiittäkäät häntä harpuilla ja tanssilla: kiittäkäät häntä harpun kielillä ja huiluilla!","Kiittäkäät häntä harpuilla ja tanssilla: kiittäkäät häntä harpun kielillä ja huiluilla!"],[150,5,"Kiittäkäät häntä kilisevillä symbaleilla!","Kiittäkäät häntä kilisevillä symbaleilla!"],[150,6,"Kaikki, joilla henki on, kiittäkään Herraa, Halleluja!","Kaikki, joilla henki on, kiittäkään Herraa, Halleluja!"]]}};